{"command":"mkdir -p /workspace/src && cat > /workspace/src/types.h <<'EOF'
// Core type system and value representation
#pragma once
#include <string>
#include <vector>
#include <memory>
#include <cstdint>
#include <stdexcept>
#include <functional>
#include <map>

typedef __int128 int128_t;
typedef unsigned __int128 uint128_t;

enum class TypeId : uint8_t {
  INVALID, SQLNULL, BOOLEAN, TINYINT, SMALLINT, INTEGER, BIGINT, HUGEINT,
  UTINYINT, USMALLINT, UINTEGER, UBIGINT, UHUGEINT, FLOAT, DOUBLE, DECIMAL,
  VARCHAR, BLOB, DATE, TIME, TIMESTAMP, TIMESTAMP_TZ, TIMESTAMP_S, TIMESTAMP_MS, TIMESTAMP_NS, TIME_TZ,
  INTERVAL, UUID, BIT, LIST, ARRAY, STRUCT, MAP, UNION, ENUM, ANY,
  STRING_LITERAL, INTEGER_LITERAL, UNKNOWN, TABLE, LAMBDA
};

struct LogicalType;
struct TypeInfo {
  std::vector<LogicalType> children;         // list: 1 child; struct: fields; map: key, value
  std::vector<std::string> names;            // struct field names / enum values
  std::string alias;                         // user type alias
  int64_t array_size = 0;
};

struct LogicalType {
  TypeId id = TypeId::INVALID;
  uint8_t width = 0, scale = 0;
  std::shared_ptr<TypeInfo> info;
  LogicalType() {}
  LogicalType(TypeId i) : id(i) {}
  LogicalType(TypeId i, uint8_t w, uint8_t s) : id(i), width(w), scale(s) {}
  static LogicalType Decimal(int w, int s) { return LogicalType(TypeId::DECIMAL, (uint8_t)w, (uint8_t)s); }
  static LogicalType List(const LogicalType &child);
  static LogicalType Array(const LogicalType &child, int64_t size);
  static LogicalType Struct(const std::vector<std::string> &names, const std::vector<LogicalType> &types);
  static LogicalType Map(const LogicalType &k, const LogicalType &v);
  static LogicalType Union(const std::vector<std::string> &names, const std::vector<LogicalType> &types);
  static LogicalType Enum(const std::vector<std::string> &values);
  const LogicalType &child() const { return info->children[0]; }
  bool operator==(const LogicalType &o) const;
  bool operator!=(const LogicalType &o) const { return !(*this == o); }
  bool IsNumeric() const;
  bool IsInteger() const;
  bool IsSigned() const;
  bool IsUnsigned() const;
  bool IsFloating() const { return id == TypeId::FLOAT || id == TypeId::DOUBLE; }
  bool IsTemporal() const;
  bool IsNested() const { return id == TypeId::LIST || id == TypeId::STRUCT || id == TypeId::MAP || id == TypeId::ARRAY || id == TypeId::UNION; }
  bool IsStringLike() const { return id == TypeId::VARCHAR || id == TypeId::STRING_LITERAL; }
  bool IsTimestamp() const { return id == TypeId::TIMESTAMP || id == TypeId::TIMESTAMP_TZ || id == TypeId::TIMESTAMP_S || id == TypeId::TIMESTAMP_MS || id == TypeId::TIMESTAMP_NS; }
  std::string ToString() const;        // SQL name, uppercase: INTEGER, DECIMAL(3,2), INTEGER[]
  std::string ToStringLower() const;   // duckbox name: int32, decimal(3,2), int32[]
  std::string ToStringInternal() const;// error-message name: INT32, VARCHAR
  // numeric helpers
  int DecimalWidth() const { return width; }
  int DecimalScale() const { return scale; }
};

LogicalType NamedType(const std::string &name);  // parse type name ("INT", "VARCHAR", ...), returns INVALID if unknown

struct Interval {
  int32_t months = 0;
  int32_t days = 0;
  int64_t micros = 0;
  bool operator==(const Interval &o) const { return months == o.months && days == o.days && micros == o.micros; }
};

struct Value;
typedef std::shared_ptr<std::vector<Value>> ValueList;

struct Value {
  LogicalType type;
  bool is_null = true;
  int128_t ival = 0;      // all integer kinds, boolean, decimal (scaled), date (days), time (micros), timestamp (micros), enum index
  double dval = 0;        // float / double
  std::string str;        // varchar / blob / bit / uuid-as-string? (uuid stored as int128 in ival)
  Interval interval;
  ValueList children;     // list / struct / map (list of struct(key,value)) / union (tag in ival + children[0])

  Value() : type(TypeId::SQLNULL) {}
  explicit Value(const LogicalType &t) : type(t), is_null(true) {}
  static Value Null(const LogicalType &t = LogicalType(TypeId::SQLNULL)) { Value v(t); return v; }
  static Value Boolean(bool b) { Value v(TypeId::BOOLEAN); v.is_null = false; v.ival = b ? 1 : 0; return v; }
  static Value Int(int128_t i, TypeId t = TypeId::INTEGER) { Value v(t); v.is_null = false; v.ival = i; return v; }
  static Value Integer(int32_t i) { return Int(i, TypeId::INTEGER); }
  static Value BigInt(int64_t i) { return Int(i, TypeId::BIGINT); }
  static Value HugeInt(int128_t i) { return Int(i, TypeId::HUGEINT); }
  static Value Double(double d) { Value v(TypeId::DOUBLE); v.is_null = false; v.dval = d; return v; }
  static Value Float(float d) { Value v(TypeId::FLOAT); v.is_null = false; v.dval = d; return v; }
  static Value Decimal(int128_t scaled, int w, int s) { Value v(LogicalType::Decimal(w, s)); v.is_null = false; v.ival = scaled; return v; }
  static Value Varchar(const std::string &s) { Value v(TypeId::VARCHAR); v.is_null = false; v.str = s; return v; }
  static Value StringLiteral(const std::string &s) { Value v(TypeId::STRING_LITERAL); v.is_null = false; v.str = s; return v; }
  static Value Blob(const std::string &s) { Value v(TypeId::BLOB); v.is_null = false; v.str = s; return v; }
  static Value Date(int32_t days) { Value v(TypeId::DATE); v.is_null = false; v.ival = days; return v; }
  static Value Time(int64_t micros) { Value v(TypeId::TIME); v.is_null = false; v.ival = micros; return v; }
  static Value Timestamp(int64_t micros, TypeId t = TypeId::TIMESTAMP) { Value v(t); v.is_null = false; v.ival = micros; return v; }
  static Value IntervalV(const Interval &i) { Value v(TypeId::INTERVAL); v.is_null = false; v.interval = i; return v; }
  static Value List(const LogicalType &child, std::vector<Value> vals);
  static Value Struct(const std::vector<std::string> &names, std::vector<Value> vals);
  static Value Map(const LogicalType &k, const LogicalType &v, std::vector<Value> keys, std::vector<Value> vals);
  static Value Enum(const LogicalType &t, int64_t idx) { Value v(t); v.is_null = false; v.ival = idx; return v; }
  static Value UUID(int128_t u) { Value v(TypeId::UUID); v.is_null = false; v.ival = u; return v; }

  bool IsNull() const { return is_null; }
  bool GetBool() const { return ival != 0; }
  int64_t GetInt64() const { return (int64_t)ival; }
  double GetDouble() const;    // numeric to double
  std::string ToString() const;   // DuckDB string representation (varchar cast)
  std::string ToSQLString() const; // SQL literal
  const std::vector<Value> &ListValues() const { return *children; }
  // comparison (SQL semantics, NULLs compare equal to NULL and greater than anything for sorting)
  static int Compare(const Value &a, const Value &b);  // -1, 0, 1 ; NULL sorts last
  bool operator==(const Value &o) const { return Compare(*this, o) == 0; }
  bool operator<(const Value &o) const { return Compare(*this, o) < 0; }
  size_t Hash() const;
};

// exceptions
struct DBException : public std::runtime_error {
  std::string kind;  // "Parser", "Binder", "Catalog", "Conversion", ...
  int64_t position = -1;  // error position in query (byte offset), -1 if none
  DBException(const std::string &k, const std::string &msg) : std::runtime_error(msg), kind(k) {}
  std::string Format() const { return kind + " Error: " + what(); }
};
struct ParserException : DBException { ParserException(const std::string &m) : DBException("Parser", m) {} };
struct BinderException : DBException { BinderException(const std::string &m) : DBException("Binder", m) {} };
struct CatalogException : DBException { CatalogException(const std::string &m) : DBException("Catalog", m) {} };
struct ConversionException : DBException { ConversionException(const std::string &m) : DBException("Conversion", m) {} };
struct OutOfRangeException : DBException { OutOfRangeException(const std::string &m) : DBException("Out of Range", m) {} };
struct InvalidInputException : DBException { InvalidInputException(const std::string &m) : DBException("Invalid Input", m) {} };
struct ConstraintException : DBException { ConstraintException(const std::string &m) : DBException("Constraint", m) {} };
struct IOException : DBException { IOException(const std::string &m) : DBException("IO", m) {} };
struct NotImplementedException : DBException { NotImplementedException(const std::string &m) : DBException("Not implemented", m) {} };
struct InvalidTypeException : DBException { InvalidTypeException(const std::string &m) : DBException("Invalid type", m) {} };
struct SyntaxException : DBException { SyntaxException(const std::string &m) : DBException("Syntax", m) {} };
struct InternalException : DBException { InternalException(const std::string &m) : DBException("INTERNAL", m) {} };
struct TransactionException : DBException { TransactionException(const std::string &m) : DBException("TransactionContext", m) {} };
struct DependencyException : DBException { DependencyException(const std::string &m) : DBException("Dependency", m) {} };
struct PermissionException : DBException { PermissionException(const std::string &m) : DBException("Permission", m) {} };
struct ParameterNotAllowedException : DBException { ParameterNotAllowedException(const std::string &m) : DBException("Parameter Not Allowed", m) {} };
struct SerializationException : DBException { SerializationException(const std::string &m) : DBException("Serialization", m) {} };
struct ExecutorException : DBException { ExecutorException(const std::string &m) : DBException("Executor", m) {} };

// casting
Value CastValue(const Value &v, const LogicalType &target, bool try_cast = false);
bool TryCastValue(const Value &v, const LogicalType &target, Value &result);
LogicalType MaxLogicalType(const LogicalType &a, const LogicalType &b);
bool CanImplicitCast(const LogicalType &from, const LogicalType &to);
int ImplicitCastCost(const LogicalType &from, const LogicalType &to);

// numeric helpers
std::string Int128ToString(int128_t v);
std::string UInt128ToString(uint128_t v);
int128_t Pow10(int n);
std::string DoubleToString(double d);
std::string FloatToString(float f);
std::string DecimalToString(int128_t v, int width, int scale);
bool ParseInt128(const std::string &s, int128_t &out, bool strict = true);
bool ParseDouble(const std::string &s, double &out);
int128_t NumericMin(TypeId t);
int128_t NumericMax(TypeId t);
int128_t MaxInt128();
int128_t MinInt128();

// date/time helpers (micros since epoch; days since epoch)
struct DateParts { int32_t year, month, day; };
int32_t DateFromYMD(int32_t y, int32_t m, int32_t d);
DateParts DateToYMD(int32_t days);
bool IsValidYMD(int32_t y, int32_t m, int32_t d);
std::string DateToString(int32_t days);
std::string TimeToString(int64_t micros);
std::string TimestampToString(int64_t micros, TypeId t = TypeId::TIMESTAMP);
std::string IntervalToString(const Interval &i);
bool ParseDate(const std::string &s, int32_t &days, bool strict = true, size_t *consumed = nullptr);
bool ParseTime(const std::string &s, int64_t &micros, bool strict = true, size_t *consumed = nullptr);
bool ParseTimestamp(const std::string &s, int64_t &micros, bool strict = true);
bool ParseInterval(const std::string &s, Interval &out);
std::string UUIDToString(int128_t u);
bool ParseUUID(const std::string &s, int128_t &out);
int DayOfWeek(int32_t days);   // 0 = Sunday
int DayOfYear(int32_t days);
bool IsLeapYear(int32_t y);
int DaysInMonth(int32_t y, int32_t m);
int64_t DateToTimestampMicros(int32_t days);
int32_t TimestampToDate(int64_t micros);
std::string BlobToString(const std::string &bytes);
std::string BitToString(const std::string &bits);
int128_t UuidFromString(const std::string &s);

// string utilities
std::string ToLower(const std::string &s);
std::string ToUpper(const std::string &s);
std::string Trim(const std::string &s);
bool StartsWith(const std::string &s, const std::string &p);
bool EndsWith(const std::string &s, const std::string &p);
bool IEquals(const std::string &a, const std::string &b);
std::string EscapeSQLString(const std::string &s);   // 'abc' -> 'abc' with quotes doubled, wrapped in quotes
std::string QuoteIdentifierIfNeeded(const std::string &s);
std::vector<std::string> SplitString(const std::string &s, char sep);
std::string JoinStrings(const std::vector<std::string> &v, const std::string &sep);
size_t Utf8Length(const std::string &s);
size_t Utf8DisplayWidth(const std::string &s);
std::string Utf8Substr(const std::string &s, int64_t start, int64_t len); // 1-based
int Utf8CharLen(unsigned char c);
std::string ReplaceAll(const std::string &s, const std::string &from, const std::string &to);
bool IsKeyword(const std::string &s);
EOF
echo done"}

