  if (len == 1) cp = c;
  else if (len == 2) cp = c & 0x1F;
  else if (len == 3) cp = c & 0x0F;
  else cp = c & 0x07;
  for (int k = 1; k < len && i + k < s.size(); k++) cp = (cp << 6) | (s[i + k] & 0x3F);
