}

std::string QuoteIdentifierIfNeeded(const std::string &s) {
  bool need = s.empty();
  if (!need) {
    if (!(isalpha((unsigned char)s[0]) || s[0] == '_' || (unsigned char)s[0] >= 0x80)) need = true;
    for (char c : s) if (!(isalnum((unsigned char)c) || c == '_' || (unsigned char)c >= 0x80)) { need = true; break; }
