  uint128_t u = neg ? (uint128_t)(-(v + 1)) + 1 : (uint128_t)v;
  std::string digits = UInt128ToString(u);
  std::string out;
  if (neg) out += "-";
  if (scale == 0) { out += digits; return out; }
  if ((int)digits.size() <= scale) {
    digits = std::string(scale - digits.size() + 1, '0') + digits;
  }
  std::string ip = digits.substr(0, digits.size() - scale);
  std::string fp = digits.substr(digits.size() - scale);
  if (width == scale) {
    // no leading integer digits (DuckDB quirk)
    if (ip == "0") ip = "";
  }
  out += ip + "." + fp;
  return out;
}

bool ParseInt128(const std::string &s_in, int128_t &out, bool strict) {
  const char *s = s_in.c_str();
  size_t n = s_in.size();
  size_t i = 0;
  while (i < n && isspace((unsigned char)s[i])) i++;
  bool neg = false;
  if (i < n && (s[i] == '-' || s[i] == '+')) { neg = s[i] == '-'; i++; }
  if (i >= n || !isdigit((unsigned char)s[i])) return false;
  uint128_t v = 0;
  uint128_t limit = (uint128_t)MaxInt128() + (neg ? 1 : 0);
  bool any = false;
  while (i < n && isdigit((unsigned char)s[i])) {
    int d = s[i] - '0';
    if (v > (limit - d) / 10) return false;
    v = v * 10 + d;
    i++; any = true;
  }
  if (!any) return false;
  // allow decimal part if it is all zeros? DuckDB rounds strings like "1.5" -> 2 when casting to int
  if (i < n && s[i] == '.') {
    i++;
    // round half away from zero
    bool round_up = false;
    if (i < n && isdigit((unsigned char)s[i])) {
      round_up = s[i] >= '5';
    }
    while (i < n && isdigit((unsigned char)s[i])) i++;
    if (round_up) v += 1;
  }
  if (i < n && (s[i] == 'e' || s[i] == 'E')) {
    // exponent
    i++;
    bool eneg = false;
    if (i < n && (s[i] == '-' || s[i] == '+')) { eneg = s[i] == '-'; i++; }
    if (i >= n || !isdigit((unsigned char)s[i])) return false;
    int e = 0;
    while (i < n && isdigit((unsigned char)s[i])) { e = e * 10 + (s[i] - '0'); if (e > 100) return false; i++; }
    if (eneg) { for (int k = 0; k < e; k++) v /= 10; }
    else { for (int k = 0; k < e; k++) { if (v > limit / 10) return false; v *= 10; } }
  }
  while (i < n && isspace((unsigned char)s[i])) i++;
  if (i != n) return false;
  if (v > limit) return false;
  if (neg) out = -(int128_t)(v - 1) - 1; else out = (int128_t)v;
  if (neg && v == 0) out = 0;
  return true;
}

bool ParseDouble(const std::string &s_in, double &out) {
  std::string s = Trim(s_in);
  if (s.empty()) return false;
  std::string l = ToLower(s);
  if (l == "nan" || l == "+nan") { out = NAN; return true; }
  if (l == "-nan") { out = -NAN; return true; }
  if (l == "inf" || l == "+inf" || l == "infinity" || l == "+infinity") { out = INFINITY; return true; }
  if (l == "-inf" || l == "-infinity") { out = -INFINITY; return true; }
  // must be numeric characters
  for (char c : s) {
    if (!(isdigit((unsigned char)c) || c == '.' || c == 'e' || c == 'E' || c == '-' || c == '+' || c == '_')) return false;
  }
  std::string t;
  for (char c : s) if (c != '_') t += c;
  char *end;
  out = strtod(t.c_str(), &end);
  if (*end != 0) return false;
  return true;
}

// ---------------------------------------------------------------- date/time
bool IsLeapYear(int32_t y) { return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0; }
int DaysInMonth(int32_t y, int32_t m) {
  static const int d[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
  if (m == 2 && IsLeapYear(y)) return 29;
  return d[m - 1];
}
bool IsValidYMD(int32_t y, int32_t m, int32_t d) {
  if (m < 1 || m > 12) return false;
  if (d < 1 || d > DaysInMonth(y, m)) return false;
  return true;
}
// days from civil (Howard Hinnant)
int32_t DateFromYMD(int32_t y, int32_t m, int32_t d) {
  y -= m <= 2;
  int64_t era = (y >= 0 ? y : y - 399) / 400;
  unsigned yoe = (unsigned)(y - era * 400);
  unsigned doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
  unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
  return (int32_t)(era * 146097 + (int64_t)doe - 719468);
}
DateParts DateToYMD(int32_t z) {
  int64_t zz = (int64_t)z + 719468;
  int64_t era = (zz >= 0 ? zz : zz - 146096) / 146097;
  unsigned doe = (unsigned)(zz - era * 146097);
  unsigned yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
  int64_t y = (int64_t)yoe + era * 400;
  unsigned doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
  unsigned mp = (5 * doy + 2) / 153;
  unsigned d = doy - (153 * mp + 2) / 5 + 1;
  unsigned m = mp + (mp < 10 ? 3 : -9);
  DateParts p;
  p.year = (int32_t)(y + (m <= 2));
  p.month = (int32_t)m;
  p.day = (int32_t)d;
  return p;
}
int DayOfWeek(int32_t days) {
  // 1970-01-01 was a Thursday (4)
  int64_t d = ((int64_t)days + 4) % 7;
  if (d < 0) d += 7;
  return (int)d;
}
int DayOfYear(int32_t days) {
  DateParts p = DateToYMD(days);
  return days - DateFromYMD(p.year, 1, 1) + 1;
}
int64_t DateToTimestampMicros(int32_t days) { return (int64_t)days * 86400000000LL; }
int32_t TimestampToDate(int64_t micros) {
  int64_t d = micros / 86400000000LL;
  if (micros < 0 && micros % 86400000000LL != 0) d--;
  return (int32_t)d;
}

static const int32_t DATE_INFINITY = INT32_MAX;
static const int32_t DATE_NINFINITY = -INT32_MAX;
static const int64_t TS_INFINITY = INT64_MAX;
static const int64_t TS_NINFINITY = -INT64_MAX;

static std::string Pad(int64_t v, int width) {
  std::string s = std::to_string(v);
  while ((int)s.size() < width) s = "0" + s;
  return s;
}

std::string DateToString(int32_t days) {
  if (days == DATE_INFINITY) return "infinity";
  if (days == DATE_NINFINITY) return "-infinity";
  DateParts p = DateToYMD(days);
  std::string s;
  int32_t y = p.year;
  bool bc = false;
  if (y <= 0) { bc = true; y = -y + 1; }
  s = Pad(y, 4) + "-" + Pad(p.month, 2) + "-" + Pad(p.day, 2);
  if (bc) s += " (BC)";
  return s;
}
std::string TimeToString(int64_t micros) {
  int64_t h = micros / 3600000000LL;
  int64_t rem = micros % 3600000000LL;
  int64_t m = rem / 60000000LL;
  rem %= 60000000LL;
  int64_t s = rem / 1000000LL;
  int64_t us = rem % 1000000LL;
  std::string out = Pad(h, 2) + ":" + Pad(m, 2) + ":" + Pad(s, 2);
  if (us) {
    std::string f = Pad(us, 6);
    while (!f.empty() && f.back() == '0') f.pop_back();
    out += "." + f;
  }
  return out;
}
std::string TimestampToString(int64_t micros, TypeId t) {
  if (micros == TS_INFINITY) return "infinity";
  if (micros == TS_NINFINITY) return "-infinity";
  int32_t days = TimestampToDate(micros);
  int64_t tod = micros - DateToTimestampMicros(days);
  std::string s = DateToString(days);
  // put (BC) at end
  bool bc = false;
  if (EndsWith(s, " (BC)")) { bc = true; s = s.substr(0, s.size() - 5); }
  s += " " + TimeToString(tod);
  if (t == TypeId::TIMESTAMP_TZ) s += "+00";
  if (bc) s += " (BC)";
  return s;
}
std::string IntervalToString(const Interval &iv) {
  std::vector<std::string> parts;
  int32_t years = iv.months / 12;
  int32_t months = iv.months % 12;
  if (years) parts.push_back(std::to_string(years) + (std::abs(years) == 1 ? " year" : " years"));
  if (months) parts.push_back(std::to_string(months) + (std::abs(months) == 1 ? " month" : " months"));
  if (iv.days) parts.push_back(std::to_string(iv.days) + (std::abs(iv.days) == 1 ? " day" : " days"));
  if (iv.micros || parts.empty()) {
    int64_t micros = iv.micros;
    std::string t;
    if (micros < 0) { t = "-"; micros = -micros; }
    int64_t h = micros / 3600000000LL;
    int64_t rem = micros % 3600000000LL;
    int64_t m = rem / 60000000LL;
    rem %= 60000000LL;
    int64_t s = rem / 1000000LL;
    int64_t us = rem % 1000000LL;
    t += Pad(h, 2) + ":" + Pad(m, 2) + ":" + Pad(s, 2);
    if (us) {
      std::string f = Pad(us, 6);
      while (!f.empty() && f.back() == '0') f.pop_back();
      t += "." + f;
    }
    parts.push_back(t);
  }
  return JoinStrings(parts, " ");
}

static bool ParseDateInternal(const char *s, size_t n, size_t &pos, int32_t &days, bool strict) {
  size_t i = pos;
  while (i < n && isspace((unsigned char)s[i])) i++;
  // special values
  if (i < n && (s[i] == 'i' || s[i] == '-' || s[i] == '+' || s[i] == 'e')) {
    const char *rest = s + i;
    size_t remaining = n - i;
    auto match = [&](const char *word, int32_t val) {
      size_t L = strlen(word);
      if (remaining >= L && strncasecmp(rest, word, L) == 0) {
        size_t j = i + L;
        while (j < n && isspace((unsigned char)s[j])) j++;
        if (j == n || !strict) { days = val; pos = i + L; return true; }
      }
      return false;
    };
    if (match("infinity", DATE_INFINITY)) return true;
    if (match("-infinity", DATE_NINFINITY)) return true;
    if (match("epoch", 0)) return true;
  }
  bool neg = false;
  if (i < n && s[i] == '-') { neg = true; i++; }
  if (i >= n || !isdigit((unsigned char)s[i])) return false;
  int64_t y = 0;
  int digits = 0;
  while (i < n && isdigit((unsigned char)s[i])) { y = y * 10 + (s[i] - '0'); i++; digits++; if (digits > 7) return false; }
  if (i >= n || (s[i] != '-' && s[i] != '/' && s[i] != ' ')) return false;
  char sep = s[i];
  i++;
  if (i >= n || !isdigit((unsigned char)s[i])) return false;
  int m = 0; digits = 0;
  while (i < n && isdigit((unsigned char)s[i])) { m = m * 10 + (s[i] - '0'); i++; if (++digits > 2) return false; }
  if (i >= n || s[i] != sep) return false;
  i++;
  if (i >= n || !isdigit((unsigned char)s[i])) return false;
  int d = 0; digits = 0;
  while (i < n && isdigit((unsigned char)s[i])) { d = d * 10 + (s[i] - '0'); i++; if (++digits > 2) return false; }
  // optional (BC)
  size_t j = i;
  while (j < n && s[j] == ' ') j++;
  bool bc = false;
  if (j + 4 <= n && strncasecmp(s + j, "(BC)", 4) == 0) { bc = true; i = j + 4; }
  if (neg) y = -y;
  if (bc) y = -y + 1;
  if (!IsValidYMD((int32_t)y, m, d)) return false;
  if (y < -290307 || y > 294247) return false;
  days = DateFromYMD((int32_t)y, m, d);
  pos = i;
  return true;
}

bool ParseDate(const std::string &str, int32_t &days, bool strict, size_t *consumed) {
  size_t pos = 0;
  if (!ParseDateInternal(str.c_str(), str.size(), pos, days, strict)) return false;
  if (consumed) *consumed = pos;
  if (strict) {
    while (pos < str.size() && isspace((unsigned char)str[pos])) pos++;
    if (pos != str.size()) return false;
  }
  return true;
}

static bool ParseTimeInternal(const char *s, size_t n, size_t &pos, int64_t &micros, bool allow_24 = false) {
  size_t i = pos;
  while (i < n && isspace((unsigned char)s[i])) i++;
  if (i >= n || !isdigit((unsigned char)s[i])) return false;
  int64_t h = 0; int digits = 0;
  while (i < n && isdigit((unsigned char)s[i])) { h = h * 10 + (s[i] - '0'); i++; if (++digits > 2) return false; }
  if (i >= n || s[i] != ':') return false;
  i++;
  if (i >= n || !isdigit((unsigned char)s[i])) return false;
  int64_t m = 0; digits = 0;
  while (i < n && isdigit((unsigned char)s[i])) { m = m * 10 + (s[i] - '0'); i++; if (++digits > 2) return false; }
  int64_t sec = 0, us = 0;
  if (i < n && s[i] == ':') {
    i++;
    if (i >= n || !isdigit((unsigned char)s[i])) return false;
    digits = 0;
    while (i < n && isdigit((unsigned char)s[i])) { sec = sec * 10 + (s[i] - '0'); i++; if (++digits > 2) return false; }
    if (i < n && s[i] == '.') {
      i++;
      int fd = 0;
      while (i < n && isdigit((unsigned char)s[i])) {
        if (fd < 6) { us = us * 10 + (s[i] - '0'); fd++; }
        i++;
      }
      while (fd < 6) { us *= 10; fd++; }
    }
  }
  if (h > 24 || m > 59 || sec > 59) return false;
  if (h == 24 && (m || sec || us) && !allow_24) return false;
  if (h == 24 && !allow_24) return false;
  micros = h * 3600000000LL + m * 60000000LL + sec * 1000000LL + us;
  pos = i;
  return true;
}

bool ParseTime(const std::string &str, int64_t &micros, bool strict, size_t *consumed) {
  size_t pos = 0;
  if (!ParseTimeInternal(str.c_str(), str.size(), pos, micros)) return false;
  if (consumed) *consumed = pos;
  if (strict) {
    while (pos < str.size() && isspace((unsigned char)str[pos])) pos++;
    if (pos != str.size()) return false;
  }
  return true;
}

bool ParseTimestamp(const std::string &str, int64_t &micros, bool strict) {
  const char *s = str.c_str();
  size_t n = str.size();
  size_t pos = 0;
  int32_t days;
  if (!ParseDateInternal(s, n, pos, days, false)) return false;
  if (days == DATE_INFINITY) { micros = TS_INFINITY; return true; }
  if (days == DATE_NINFINITY) { micros = TS_NINFINITY; return true; }
  size_t i = pos;
  int64_t tod = 0;
  if (i < n && (s[i] == ' ' || s[i] == 'T')) {
    i++;
    size_t p2 = i;
    if (!ParseTimeInternal(s, n, p2, tod, true)) return false;
    i = p2;
    // timezone
    while (i < n && isspace((unsigned char)s[i])) i++;
    if (i < n && (s[i] == '+' || s[i] == '-' || s[i] == 'Z' || s[i] == 'z')) {
      if (s[i] == 'Z' || s[i] == 'z') { i++; }
      else {
        bool neg = s[i] == '-';
        i++;
        int64_t th = 0, tm = 0;
        int dg = 0;
        while (i < n && isdigit((unsigned char)s[i])) { th = th * 10 + (s[i] - '0'); i++; dg++; }
        if (dg == 4) { tm = th % 100; th /= 100; }
        else if (dg != 2) return false;
        if (i < n && s[i] == ':') {
          i++;
          dg = 0;
          while (i < n && isdigit((unsigned char)s[i])) { tm = tm * 10 + (s[i] - '0'); i++; dg++; }
          if (dg != 2) return false;
        }
        int64_t off = th * 3600000000LL + tm * 60000000LL;
        tod += neg ? off : -off;
      }
    }
  } else if (i < n && s[i] == '(') {
    // handled in date parse
  }
  while (i < n && isspace((unsigned char)s[i])) i++;
  if (i != n) return false;
  int64_t limit = 9223372036854775807LL;
  int64_t daymicros;
  if (__builtin_mul_overflow((int64_t)days, 86400000000LL, &daymicros)) return false;
  if (__builtin_add_overflow(daymicros, tod, &micros)) return false;
  if (micros == limit || micros == -limit) return false;
  return true;
}

bool ParseInterval(const std::string &str_in, Interval &out) {
  std::string str = Trim(str_in);
  if (str.empty()) return false;
  out = Interval();
  // ISO 8601? P1Y2M3DT4H5M6S
  if (str[0] == 'P' || str[0] == 'p') {
    size_t i = 1;
    bool time_part = false;
    bool any = false;
    while (i < str.size()) {
      if (str[i] == 'T' || str[i] == 't') { time_part = true; i++; continue; }
      bool neg = false;
      if (str[i] == '-') { neg = true; i++; }
      size_t start = i;
      while (i < str.size() && (isdigit((unsigned char)str[i]) || str[i] == '.')) i++;
      if (start == i || i >= str.size()) return false;
      double v = atof(str.substr(start, i - start).c_str());
      if (neg) v = -v;
      char u = toupper(str[i]); i++;
      any = true;
      if (!time_part) {
        if (u == 'Y') out.months += (int32_t)(v * 12);
        else if (u == 'M') out.months += (int32_t)v;
        else if (u == 'W') out.days += (int32_t)(v * 7);
        else if (u == 'D') out.days += (int32_t)v;
        else return false;
      } else {
        if (u == 'H') out.micros += (int64_t)(v * 3600000000.0);
        else if (u == 'M') out.micros += (int64_t)(v * 60000000.0);
        else if (u == 'S') out.micros += (int64_t)std::llround(v * 1000000.0);
        else return false;
      }
    }
    return any;
  }
  // tokens: number [unit] | HH:MM[:SS[.ffff]]
  size_t i = 0, n = str.size();
  bool any = false;
  bool global_neg = false;
  while (i < n) {
    while (i < n && isspace((unsigned char)str[i])) i++;
    if (i >= n) break;
    if (str[i] == '@') { i++; continue; }
    if (str[i] == 'a' && str.compare(i, 3, "ago") == 0) { global_neg = true; i += 3; continue; }
    bool neg = false;
    if (str[i] == '-' || str[i] == '+') { neg = str[i] == '-'; i++; }
    if (i >= n || !(isdigit((unsigned char)str[i]) || str[i] == '.')) return false;
    size_t start = i;
    while (i < n && isdigit((unsigned char)str[i])) i++;
    // time format?
    if (i < n && str[i] == ':') {
      int64_t h = atoll(str.substr(start, i - start).c_str());
      i++;
      size_t ms = i;
      while (i < n && isdigit((unsigned char)str[i])) i++;
      if (ms == i) return false;
      int64_t m = atoll(str.substr(ms, i - ms).c_str());
      int64_t sec = 0, us = 0;
      if (i < n && str[i] == ':') {
        i++;
        size_t ss = i;
        while (i < n && isdigit((unsigned char)str[i])) i++;
        if (ss == i) return false;
        sec = atoll(str.substr(ss, i - ss).c_str());
        if (i < n && str[i] == '.') {
          i++;
          int fd = 0;
          while (i < n && isdigit((unsigned char)str[i])) { if (fd < 6) { us = us * 10 + (str[i] - '0'); fd++; } i++; }
          while (fd < 6) { us *= 10; fd++; }
        }
      }
      int64_t total = h * 3600000000LL + m * 60000000LL + sec * 1000000LL + us;
      out.micros += neg ? -total : total;
      any = true;
      continue;
    }
    bool has_frac = false;
    double frac = 0;
    if (i < n && str[i] == '.') {
      has_frac = true;
      i++;
      while (i < n && isdigit((unsigned char)str[i])) i++;
    }
    std::string numstr = str.substr(start, i - start);
    double dv = atof(numstr.c_str());
    int64_t iv = has_frac ? (int64_t)dv : atoll(numstr.c_str());
    frac = dv - (double)iv;
    if (neg) { iv = -iv; frac = -frac; dv = -dv; }
    while (i < n && isspace((unsigned char)str[i])) i++;
    size_t us = i;
    while (i < n && isalpha((unsigned char)str[i])) i++;
    std::string unit = ToLower(str.substr(us, i - us));
    if (unit.empty()) {
      // bare number: seconds? DuckDB fails on bare numbers
      return false;
    }
    any = true;
    auto is = [&](const char *a, const char *b, const char *c = nullptr, const char *d = nullptr) {
      return unit == a || unit == b || (c && unit == c) || (d && unit == d);
    };
    if (is("year", "years", "y", "yr") || unit == "yrs") { out.months += (int32_t)(iv * 12); out.months += (int32_t)(frac * 12); }
    else if (is("month", "months", "mon", "mons")) { out.months += (int32_t)iv; out.days += (int32_t)(frac * 30); }
    else if (is("week", "weeks", "w")) { out.days += (int32_t)(iv * 7); out.micros += (int64_t)(frac * 7 * 86400000000.0); }
    else if (is("day", "days", "d")) { out.days += (int32_t)iv; out.micros += (int64_t)(frac * 86400000000.0); }
    else if (is("hour", "hours", "h", "hr") || unit == "hrs") { out.micros += (int64_t)std::llround(dv * 3600000000.0); }
    else if (is("minute", "minutes", "m", "min") || unit == "mins") { out.micros += (int64_t)std::llround(dv * 60000000.0); }
    else if (is("second", "seconds", "s", "sec") || unit == "secs") { out.micros += (int64_t)std::llround(dv * 1000000.0); }
    else if (is("millisecond", "milliseconds", "ms", "msec") || unit == "msecs" || unit == "millis") { out.micros += (int64_t)std::llround(dv * 1000.0); }
    else if (is("microsecond", "microseconds", "us", "usec") || unit == "usecs" || unit == "micros") { out.micros += (int64_t)std::llround(dv); }
    else if (is("decade", "decades", "dec") || unit == "decs") { out.months += (int32_t)(dv * 120); }
    else if (is("century", "centuries", "c")) { out.months += (int32_t)(dv * 1200); }
    else if (is("millennium", "millennia", "millenniums")) { out.months += (int32_t)(dv * 12000); }
    else return false;
  }
  if (!any) return false;
  if (global_neg) { out.months = -out.months; out.days = -out.days; out.micros = -out.micros; }
  return true;
}

std::string UUIDToString(int128_t u) {
  uint128_t v = (uint128_t)u;
  // DuckDB flips the MSB for ordering; the stored value has msb flipped
  v ^= ((uint128_t)1 << 127);
  char buf[40];
  uint64_t hi = (uint64_t)(v >> 64), lo = (uint64_t)v;
  snprintf(buf, sizeof(buf), "%08x-%04x-%04x-%04x-%012llx", (unsigned)(hi >> 32), (unsigned)((hi >> 16) & 0xFFFF),
           (unsigned)(hi & 0xFFFF), (unsigned)(lo >> 48), (unsigned long long)(lo & 0xFFFFFFFFFFFFULL));
  return buf;
}
bool ParseUUID(const std::string &s_in, int128_t &out) {
  std::string s = Trim(s_in);
  if (StartsWith(ToLower(s), "urn:uuid:")) s = s.substr(9);
  if (!s.empty() && s[0] == '{' && s.back() == '}') s = s.substr(1, s.size() - 2);
  uint128_t v = 0;
  int digits = 0;
  for (char c : s) {
    if (c == '-') continue;
    int d;
    if (c >= '0' && c <= '9') d = c - '0';
    else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
    else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
    else return false;
    v = (v << 4) | d;
    digits++;
  }
  if (digits != 32) return false;
  v ^= ((uint128_t)1 << 127);
