  }
}

static bool NeedsQuotes(const std::string &s) {
  if (s.empty()) return true;
  if (IEquals(s, "null")) return true;
  if (s.front() == ' ' || s.back() == ' ') return true;
  for (char c : s) {
    if (c == '[' || c == ']' || c == '{' || c == '}' || c == '"' || c == '\'' || c == ',' || c == ':' || c == '(' || c == ')') return true;
  }
  return false;
}
static std::string QuoteNested(const std::string &s) {
  std::string r = "'";
  for (char c : s) {
    if (c == '\'') r += "\\'";
    else if (c == '\\') r += "\\\\";
    else r += c;
  }
  return r + "'";
}
static std::string NestedElementString(const Value &v, bool is_key = false) {
  if (v.is_null) return "NULL";
  std::string s = v.ToString();
  bool stringy = false;
  switch (v.type.id) {
  case TypeId::VARCHAR: case TypeId::STRING_LITERAL: case TypeId::TIME: case TypeId::TIMESTAMP: case TypeId::TIMESTAMP_TZ:
  case TypeId::TIMESTAMP_S: case TypeId::TIMESTAMP_MS: case TypeId::TIMESTAMP_NS: case TypeId::TIME_TZ: case TypeId::ENUM:
    stringy = true; break;
  default: break;
  }
  if (is_key) return QuoteNested(s);
  if (stringy && NeedsQuotes(s)) return QuoteNested(s);
  return s;
}

std::string Value::ToString() const {
  if (is_null) return "NULL";
  switch (type.id) {
  case TypeId::BOOLEAN: return ival ? "true" : "false";
  case TypeId::TINYINT: case TypeId::SMALLINT: case TypeId::INTEGER: case TypeId::BIGINT: case TypeId::HUGEINT:
  case TypeId::UTINYINT: case TypeId::USMALLINT: case TypeId::UINTEGER: case TypeId::UBIGINT: case TypeId::INTEGER_LITERAL:
    return Int128ToString(ival);
  case TypeId::UHUGEINT: return UInt128ToString((uint128_t)ival);
  case TypeId::FLOAT: return FloatToString((float)dval);
  case TypeId::DOUBLE: return DoubleToString(dval);
  case TypeId::DECIMAL: return DecimalToString(ival, type.width, type.scale);
  case TypeId::VARCHAR: case TypeId::STRING_LITERAL: return str;
  case TypeId::BLOB: return BlobToString(str);
  case TypeId::BIT: return str;
  case TypeId::DATE: return DateToString((int32_t)ival);
  case TypeId::TIME: return TimeToString((int64_t)ival);
  case TypeId::TIME_TZ: return TimeToString((int64_t)ival) + "+00";
  case TypeId::TIMESTAMP: return TimestampToString((int64_t)ival);
  case TypeId::TIMESTAMP_TZ: return TimestampToString((int64_t)ival, TypeId::TIMESTAMP_TZ);
  case TypeId::TIMESTAMP_S: return TimestampToString((int64_t)ival * 1000000);
  case TypeId::TIMESTAMP_MS: return TimestampToString((int64_t)ival * 1000);
  case TypeId::TIMESTAMP_NS: {
    int64_t ns = (int64_t)ival;
    int64_t us = ns / 1000; int64_t rem = ns % 1000;
    if (rem < 0) { rem += 1000; us--; }
    std::string s = TimestampToString(us);
    if (rem) {
      // append extra nanosecond digits
      size_t dot = s.find('.');
      std::string frac;
      if (dot == std::string::npos) { s += ".000000"; }
      else { while (s.size() - dot - 1 < 6) s += "0"; }
      char buf[8]; snprintf(buf, sizeof(buf), "%03d", (int)rem);
      s += buf;
      while (s.back() == '0') s.pop_back();
    }
    return s;
  }
  case TypeId::INTERVAL: return IntervalToString(interval);
  case TypeId::UUID: return UUIDToString(ival);
  case TypeId::ENUM: return (size_t)ival < type.info->names.size() ? type.info->names[(size_t)ival] : "";
  case TypeId::LIST: case TypeId::ARRAY: {
    std::string r = "[";
    for (size_t i = 0; i < children->size(); i++) {
      if (i) r += ", ";
      r += NestedElementString((*children)[i]);
    }
    return r + "]";
  }
  case TypeId::STRUCT: {
    std::string r = "{";
    for (size_t i = 0; i < children->size(); i++) {
      if (i) r += ", ";
      r += QuoteNested(type.info->names[i]) + ": " + NestedElementString((*children)[i]);
    }
    return r + "}";
  }
  case TypeId::MAP: {
    std::string r = "{";
    for (size_t i = 0; i < children->size(); i++) {
      if (i) r += ", ";
      auto &kv = (*children)[i];
      r += NestedElementString((*kv.children)[0]) + "=" + NestedElementString((*kv.children)[1]);
    }
    return r + "}";
  }
  case TypeId::UNION: {
    if (children && !children->empty()) return (*children)[0].ToString();
    return "NULL";
  }
  default: return "";
  }
}

std::string Value::ToSQLString() const {
  if (is_null) return "NULL";
  switch (type.id) {
  case TypeId::BOOLEAN: case TypeId::TINYINT: case TypeId::SMALLINT: case TypeId::INTEGER: case TypeId::BIGINT: case TypeId::HUGEINT:
  case TypeId::UTINYINT: case TypeId::USMALLINT: case TypeId::UINTEGER: case TypeId::UBIGINT: case TypeId::UHUGEINT:
  case TypeId::FLOAT: case TypeId::DOUBLE: case TypeId::DECIMAL: case TypeId::INTEGER_LITERAL:
    return ToString();
  case TypeId::VARCHAR: case TypeId::STRING_LITERAL: return EscapeSQLString(str);
  case TypeId::BLOB: return EscapeSQLString(BlobToString(str)) + "::BLOB";
  case TypeId::DATE: return EscapeSQLString(ToString()) + "::DATE";
  case TypeId::TIME: return EscapeSQLString(ToString()) + "::TIME";
  case TypeId::TIMESTAMP: return EscapeSQLString(ToString()) + "::TIMESTAMP";
  case TypeId::INTERVAL: return EscapeSQLString(ToString()) + "::INTERVAL";
  case TypeId::LIST: {
    std::string r = "[";
    for (size_t i = 0; i < children->size(); i++) { if (i) r += ", "; r += (*children)[i].ToSQLString(); }
    return r + "]";
  }
  case TypeId::STRUCT: {
    std::string r = "{";
    for (size_t i = 0; i < children->size(); i++) {
      if (i) r += ", ";
      r += EscapeSQLString(type.info->names[i]) + ": " + (*children)[i].ToSQLString();
    }
    return r + "}";
  }
  default: return EscapeSQLString(ToString()) + "::" + type.ToString();
  }
}

static int CmpInt128(int128_t a, int128_t b) { return a < b ? -1 : (a > b ? 1 : 0); }
static int CmpDouble(double a, double b) {
  // NaN sorts greater than everything
  bool an = std::isnan(a), bn = std::isnan(b);
  if (an && bn) return 0;
  if (an) return 1;
  if (bn) return -1;
  return a < b ? -1 : (a > b ? 1 : 0);
}

int Value::Compare(const Value &a, const Value &b) {
  if (a.is_null && b.is_null) return 0;
  if (a.is_null) return 1;
  if (b.is_null) return -1;
  TypeId ta = a.type.id, tb = b.type.id;
  auto numeric = [](TypeId t) { return LogicalType(t).IsNumeric() || t == TypeId::BOOLEAN; };
  if (numeric(ta) && numeric(tb)) {
    if (ta == TypeId::DECIMAL || tb == TypeId::DECIMAL) {
      if (ta == TypeId::DECIMAL && tb == TypeId::DECIMAL) {
        int s = std::max(a.type.scale, b.type.scale);
        return CmpInt128(a.ival * Pow10(s - a.type.scale), b.ival * Pow10(s - b.type.scale));
      }
      if (a.type.IsFloating() || b.type.IsFloating()) return CmpDouble(a.GetDouble(), b.GetDouble());
      // decimal vs integer
      if (ta == TypeId::DECIMAL) return CmpInt128(a.ival, b.ival * Pow10(a.type.scale));
      return CmpInt128(a.ival * Pow10(b.type.scale), b.ival);
    }
    if (a.type.IsFloating() || b.type.IsFloating()) return CmpDouble(a.GetDouble(), b.GetDouble());
    if (ta == TypeId::UHUGEINT || tb == TypeId::UHUGEINT) {
      uint128_t ua = (uint128_t)a.ival, ub = (uint128_t)b.ival;
      if (ta != TypeId::UHUGEINT && a.ival < 0) return -1;
      if (tb != TypeId::UHUGEINT && b.ival < 0) return 1;
      return ua < ub ? -1 : (ua > ub ? 1 : 0);
    }
    return CmpInt128(a.ival, b.ival);
  }
  switch (ta) {
  case TypeId::VARCHAR: case TypeId::STRING_LITERAL: case TypeId::BLOB: case TypeId::BIT: {
    if (b.type.id == TypeId::ENUM) return a.str.compare(b.ToString()) < 0 ? -1 : (a.str == b.ToString() ? 0 : 1);
    int c = a.str.compare(b.str);
    return c < 0 ? -1 : (c > 0 ? 1 : 0);
  }
  case TypeId::ENUM:
    if (b.type.id == TypeId::ENUM && a.type == b.type) return CmpInt128(a.ival, b.ival);
    { std::string sa = a.ToString(), sb = b.ToString(); int c = sa.compare(sb); return c < 0 ? -1 : (c > 0 ? 1 : 0); }
  case TypeId::INTERVAL: {
    // normalize: months*30 days + days, then micros
    int64_t da = (int64_t)a.interval.months * 30 + a.interval.days;
    int64_t db = (int64_t)b.interval.months * 30 + b.interval.days;
    int128_t ma = (int128_t)da * 86400000000LL + a.interval.micros;
    int128_t mb = (int128_t)db * 86400000000LL + b.interval.micros;
    return CmpInt128(ma, mb);
  }
  case TypeId::LIST: case TypeId::ARRAY: case TypeId::STRUCT: case TypeId::MAP: {
    if (!b.children) return 1;
    size_t n = std::min(a.children->size(), b.children->size());
    for (size_t i = 0; i < n; i++) {
      // for nested comparisons NULL sorts last but equal to NULL
      int c = Compare((*a.children)[i], (*b.children)[i]);
      if (c) return c;
    }
    return a.children->size() < b.children->size() ? -1 : (a.children->size() > b.children->size() ? 1 : 0);
  }
  case TypeId::UNION: {
    int c = CmpInt128(a.ival, b.ival);
    if (c) return c;
    return Compare((*a.children)[0], (*b.children)[0]);
  }
  default:
    return CmpInt128(a.ival, b.ival);
  }
}

size_t Value::Hash() const {
  if (is_null) return 0x9e3779b9;
  std::hash<std::string> hs;
  switch (type.id) {
  case TypeId::VARCHAR: case TypeId::STRING_LITERAL: case TypeId::BLOB: case TypeId::BIT: return hs(str);
  case TypeId::FLOAT: case TypeId::DOUBLE: { double d = dval; if (d == 0) d = 0; return std::hash<double>()(d); }
  case TypeId::DECIMAL: { return std::hash<double>()(GetDouble()); }
  case TypeId::INTERVAL: return std::hash<int64_t>()((int64_t)interval.months * 30 * 86400000000LL + (int64_t)interval.days * 86400000000LL + interval.micros);
  case TypeId::LIST: case TypeId::ARRAY: case TypeId::STRUCT: case TypeId::MAP: case TypeId::UNION: {
    size_t h = 17;
    for (auto &c : *children) h = h * 31 + c.Hash();
    return h;
  }
  case TypeId::ENUM: return hs(ToString());
  default: return std::hash<int64_t>()((int64_t)ival) ^ std::hash<int64_t>()((int64_t)(ival >> 64));
  }
}

// ---------------------------------------------------------------- casting
static bool FitsIn(int128_t v, TypeId t) {
  if (t == TypeId::UHUGEINT) return v >= 0;
  if (t == TypeId::HUGEINT) return true;
  return v >= NumericMin(t) && v <= NumericMax(t);
}

static std::string CastErrorMsg(const Value &v, const LogicalType &target) {
  return "Could not convert string '" + v.str + "' to " + target.ToStringInternal();
}

static int128_t RoundDoubleToInt128(double d) {
  double r = std::round(d);
  return (int128_t)r;
}

static bool TryCastInternal(const Value &v, const LogicalType &target, Value &out, std::string &err) {
  const LogicalType &st = v.type;
  if (v.is_null) { out = Value::Null(target); return true; }
  if (st.id == target.id && (target.id != TypeId::DECIMAL) && !target.IsNested() && target.id != TypeId::ENUM) {
    out = v; out.type = target; return true;
  }
  if (st == target) { out = v; return true; }
  TypeId tid = target.id;
  out = Value(target);
  out.is_null = false;
  // --- from string
  if (st.id == TypeId::VARCHAR || st.id == TypeId::STRING_LITERAL) {
    const std::string &s = v.str;
    switch (tid) {
    case TypeId::VARCHAR: case TypeId::STRING_LITERAL: out.str = s; return true;
    case TypeId::BOOLEAN: {
      std::string l = ToLower(Trim(s));
      if (l == "true" || l == "t" || l == "1" || l == "yes" || l == "y") { out.ival = 1; return true; }
      if (l == "false" || l == "f" || l == "0" || l == "no" || l == "n") { out.ival = 0; return true; }
      err = "Could not convert string '" + s + "' to BOOL"; return false;
    }
    case TypeId::TINYINT: case TypeId::SMALLINT: case TypeId::INTEGER: case TypeId::BIGINT: case TypeId::HUGEINT:
    case TypeId::UTINYINT: case TypeId::USMALLINT: case TypeId::UINTEGER: case TypeId::UBIGINT: case TypeId::UHUGEINT: {
      int128_t iv;
      if (!ParseInt128(s, iv)) { err = CastErrorMsg(v, target); return false; }
      if (!FitsIn(iv, tid)) { err = CastErrorMsg(v, target); return false; }
      out.ival = iv; return true;
    }
    case TypeId::FLOAT: case TypeId::DOUBLE: {
      double d;
      if (!ParseDouble(s, d)) { err = "Could not convert string '" + s + "' to " + target.ToString(); return false; }
      if (tid == TypeId::FLOAT) d = (float)d;
      out.dval = d; return true;
    }
    case TypeId::DECIMAL: {
      // parse decimal string
      std::string t = Trim(s);
      bool neg = false;
      size_t i = 0;
      if (i < t.size() && (t[i] == '-' || t[i] == '+')) { neg = t[i] == '-'; i++; }
      std::string ip, fp;
      bool any = false;
      while (i < t.size() && isdigit((unsigned char)t[i])) { ip += t[i]; i++; any = true; }
      if (i < t.size() && t[i] == '.') { i++; while (i < t.size() && isdigit((unsigned char)t[i])) { fp += t[i]; i++; any = true; } }
      int exp = 0;
      if (i < t.size() && (t[i] == 'e' || t[i] == 'E')) {
        i++;
        bool eneg = false;
        if (i < t.size() && (t[i] == '-' || t[i] == '+')) { eneg = t[i] == '-'; i++; }
        if (i >= t.size()) { err = CastErrorMsg(v, target); return false; }
        while (i < t.size() && isdigit((unsigned char)t[i])) { exp = exp * 10 + (t[i] - '0'); i++; }
        if (eneg) exp = -exp;
      }
      if (!any || i != t.size()) {
        // maybe double parse (nan etc.)
        err = "Could not convert string \"" + s + "\" to DECIMAL(" + std::to_string(target.width) + "," + std::to_string(target.scale) + ")";
        return false;
      }
      // apply exponent by shifting digits
      std::string digits = ip + fp;
      int scale = (int)fp.size() - exp;
      // value = digits * 10^-scale; want scale = target.scale
      int128_t val = 0;
      for (char c : digits) {
        if (val > (MaxInt128() - 9) / 10) { err = "Could not convert string \"" + s + "\" to DECIMAL(" + std::to_string(target.width) + "," + std::to_string(target.scale) + ")"; return false; }
        val = val * 10 + (c - '0');
      }
      if (scale < target.scale) {
        for (int k = scale; k < target.scale; k++) {
          if (val > MaxInt128() / 10) { err = "Could not convert string \"" + s + "\" to DECIMAL(" + std::to_string(target.width) + "," + std::to_string(target.scale) + ")"; return false; }
          val *= 10;
        }
      } else if (scale > target.scale) {
        int diff = scale - target.scale;
        int128_t div = Pow10(diff);
        int128_t rem = val % div;
        val /= div;
        if (rem >= div / 2) val++;
      }
      if (val >= Pow10(target.width)) {
        err = "Could not convert string \"" + s + "\" to DECIMAL(" + std::to_string(target.width) + "," + std::to_string(target.scale) + ")";
        return false;
      }
      out.ival = neg ? -val : val;
      return true;
    }
    case TypeId::DATE: {
      int32_t d;
      if (!ParseDate(s, d)) {
        // determine error: format or range
        err = "date field value out of range: \"" + s + "\", expected format is (YYYY-MM-DD)";
        // check if format is valid but range invalid
        std::string t = Trim(s);
        int y, m, dd;
        if (sscanf(t.c_str(), "%d-%d-%d", &y, &m, &dd) == 3 && !IsValidYMD(y, m, dd)) err = "date field value out of range: \"" + s + "\"";
        return false;
      }
      out.ival = d; return true;
    }
    case TypeId::TIME: case TypeId::TIME_TZ: {
      int64_t t;
      if (!ParseTime(s, t)) {
        // try timestamp then take time part
        int64_t ts;
        if (ParseTimestamp(s, ts)) { int32_t days = TimestampToDate(ts); out.ival = ts - DateToTimestampMicros(days); return true; }
        err = "time field value out of range: \"" + s + "\", expected format is ([YYYY-MM-DD ]HH:MM:SS[.MS])"; return false;
      }
      out.ival = t; return true;
    }
    case TypeId::TIMESTAMP: case TypeId::TIMESTAMP_TZ: case TypeId::TIMESTAMP_S: case TypeId::TIMESTAMP_MS: case TypeId::TIMESTAMP_NS: {
      int64_t ts;
      if (!ParseTimestamp(s, ts)) {
        std::string t = Trim(s);
        int y, m, dd;
        if (sscanf(t.c_str(), "%d-%d-%d", &y, &m, &dd) == 3 && !IsValidYMD(y, m, dd)) err = "timestamp field value out of range: \"" + s + "\"";
        else err = "timestamp field value out of range: \"" + s + "\", expected format is (YYYY-MM-DD HH:MM:SS[.US][±HH:MM| ZONE])";
        return false;
      }
      if (tid == TypeId::TIMESTAMP_S) ts /= 1000000;
      else if (tid == TypeId::TIMESTAMP_MS) ts /= 1000;
      else if (tid == TypeId::TIMESTAMP_NS) ts *= 1000;
      out.ival = ts; return true;
    }
    case TypeId::INTERVAL: {
      Interval iv;
      if (!ParseInterval(s, iv)) { err = "Could not convert string '" + s + "' to INTERVAL"; return false; }
      out.interval = iv; return true;
    }
    case TypeId::BLOB: {
      std::string r;
      for (size_t i = 0; i < s.size(); i++) {
        unsigned char c = s[i];
        if (c == '\\') {
          if (i + 3 < s.size() + 0 && i + 3 <= s.size() - 1 && s[i + 1] == 'x' && isxdigit((unsigned char)s[i + 2]) && isxdigit((unsigned char)s[i + 3])) {
            r += (char)strtol(s.substr(i + 2, 2).c_str(), nullptr, 16);
            i += 3;
          } else {
            err = "Invalid hex escape code encountered in string -> blob conversion of string \"" + s + "\": " + s.substr(i, 4);
            return false;
          }
        } else if (c >= 0x80) {
          err = "Invalid byte encountered in STRING -> BLOB conversion of string \"" + s + "\". All non-ascii characters must be escaped with hex codes (e.g. \\xAA)";
          return false;
        } else r += (char)c;
      }
      out.str = r; return true;
    }
    case TypeId::BIT: {
      for (char c : s) if (c != '0' && c != '1') { err = std::string("Invalid character encountered in string -> bit conversion: '") + c + "'"; return false; }
      if (s.empty()) { err = "Cannot cast empty string to BIT"; return false; }
      out.str = s; return true;
    }
    case TypeId::UUID: {
      int128_t u;
      if (!ParseUUID(s, u)) { err = "Could not convert string '" + s + "' to UUID"; return false; }
      out.ival = u; return true;
    }
    case TypeId::ENUM: {
      auto &names = target.info->names;
      for (size_t i = 0; i < names.size(); i++) if (names[i] == s) { out.ival = (int64_t)i; return true; }
      err = "Could not convert string '" + s + "' to " + target.ToString(); return false;
    }
    case TypeId::LIST: case TypeId::STRUCT: case TypeId::MAP: case TypeId::ARRAY: {
      // parse nested literal from string: minimal support
      extern bool ParseNestedFromString(const std::string &s, const LogicalType &target, Value &out, std::string &err);
      return ParseNestedFromString(s, target, out, err);
    }
    case TypeId::SQLNULL: out = Value::Null(target); return true;
    default: break;
    }
    err = "Unimplemented type for cast (" + st.ToString() + " -> " + target.ToString() + ")";
    return false;
  }
  // --- to string
  if (tid == TypeId::VARCHAR || tid == TypeId::STRING_LITERAL) {
    out.str = v.ToString();
    return true;
  }
  // --- numeric conversions
  if (st.IsNumeric() || st.id == TypeId::BOOLEAN) {
    if (tid == TypeId::BOOLEAN) {
      if (st.IsFloating()) out.ival = v.dval != 0;
      else out.ival = v.ival != 0;
      return true;
    }
    if (LogicalType(tid).IsInteger()) {
      int128_t iv;
      if (st.IsFloating()) {
        double d = v.dval;
        if (std::isnan(d) || std::isinf(d)) { err = "Could not convert " + std::string(st.id == TypeId::FLOAT ? "float" : "double") + " value '" + v.ToString() + "' to " + target.ToStringInternal(); return false; }
        double r = std::round(d);
        if (r < -1.7e38 || r > 1.7e38) { err = "Could not convert " + std::string(st.id == TypeId::FLOAT ? "float" : "double") + " value '" + v.ToString() + "' to " + target.ToStringInternal(); return false; }
        iv = RoundDoubleToInt128(d);
        if (!FitsIn(iv, tid)) {
          err = "Could not convert " + std::string(st.id == TypeId::FLOAT ? "float" : "double") + " value '" + v.ToString() + "' to " + target.ToStringInternal();
          return false;
        }
      } else if (st.id == TypeId::DECIMAL) {
        int128_t div = Pow10(st.scale);
        iv = v.ival / div;
        int128_t rem = v.ival % div;
        if (rem >= (div + 1) / 2 && div > 1) iv++;
        else if (rem <= -(div + 1) / 2 && div > 1) iv--;
        if (div == 1) iv = v.ival;
        if (!FitsIn(iv, tid)) {
          err = "Failed to cast decimal value " + v.ToString() + " to type " + target.ToStringInternal(); return false;
        }
      } else {
        iv = v.ival;
        if (st.id == TypeId::UHUGEINT && tid != TypeId::UHUGEINT) {
          if (iv < 0) { err = "Type UINT128 with value " + v.ToString() + " can't be cast because the value is out of range for the destination type " + target.ToStringInternal(); return false; }
        }
        if (!FitsIn(iv, tid)) {
          err = "Type " + st.ToStringInternal() + " with value " + v.ToString() + " can't be cast because the value is out of range for the destination type " + target.ToStringInternal();
          return false;
        }
      }
      out.ival = iv; return true;
    }
    if (tid == TypeId::FLOAT || tid == TypeId::DOUBLE) {
      double d = v.GetDouble();
      if (st.id == TypeId::UHUGEINT) d = (double)(uint128_t)v.ival;
      if (tid == TypeId::FLOAT) {
        if (std::isfinite(d) && std::fabs(d) > 3.4028235e38) { err = "Type DOUBLE with value " + v.ToString() + " can't be cast because the value is out of range for the destination type FLOAT"; return false; }
        d = (float)d;
      }
      out.dval = d; return true;
    }
    if (tid == TypeId::DECIMAL) {
      int128_t val;
      if (st.IsFloating()) {
        double d = v.dval;
        if (std::isnan(d) || std::isinf(d)) { err = "Could not cast value " + v.ToString() + " to DECIMAL(" + std::to_string(target.width) + "," + std::to_string(target.scale) + ")"; return false; }
        double scaled = d * (double)Pow10(target.scale);
        double r = std::round(scaled);
        if (std::fabs(r) >= (double)Pow10(target.width)) {
          err = "Could not cast value " + v.ToString() + " to DECIMAL(" + std::to_string(target.width) + "," + std::to_string(target.scale) + ")"; return false;
        }
        val = (int128_t)r;
      } else if (st.id == TypeId::DECIMAL) {
        if (target.scale >= st.scale) {
          int diff = target.scale - st.scale;
          // check fits
          int128_t limit = Pow10(target.width - diff > 0 ? target.width - diff : 0);
          if (target.width - diff <= 0 || v.ival >= limit || v.ival <= -limit) {
            err = "Casting value \"" + v.ToString() + "\" to type DECIMAL(" + std::to_string(target.width) + "," + std::to_string(target.scale) + ") failed: value is out of range!"; return false;
          }
          val = v.ival * Pow10(diff);
        } else {
          int diff = st.scale - target.scale;
          int128_t div = Pow10(diff);
          // DuckDB quirk: check that value rounded to integer fits in (width - scale) digits
          int128_t src_scale_div = Pow10(st.scale);
          int128_t absv = v.ival < 0 ? -v.ival : v.ival;
          int128_t rounded_int = (absv + src_scale_div / 2) / src_scale_div;
          if (rounded_int >= Pow10(target.width - target.scale)) {
            err = "Casting value \"" + v.ToString() + "\" to type DECIMAL(" + std::to_string(target.width) + "," + std::to_string(target.scale) + ") failed: value is out of range!"; return false;
          }
          int128_t q = absv / div;
          int128_t rem = absv % div;
          if (rem >= (div + 1) / 2) q++;
          val = v.ival < 0 ? -q : q;
        }
      } else {
        // integer -> decimal
        int128_t iv = v.ival;
        int128_t limit = Pow10(target.width - target.scale);
        if (iv >= limit || iv <= -limit) {
          err = "Type " + st.ToStringInternal() + " with value " + v.ToString() + " can't be cast because the value is out of range for the destination type DECIMAL(" + std::to_string(target.width) + "," + std::to_string(target.scale) + ")";
          // DuckDB message
          err = "Casting value \"" + v.ToString() + "\" to type DECIMAL(" + std::to_string(target.width) + "," + std::to_string(target.scale) + ") failed: value is out of range!";
          return false;
        }
        val = iv * Pow10(target.scale);
      }
      out.ival = val; return true;
    }
    // integer -> temporal? (e.g. epoch) not implicit
    if (st.IsInteger() && (tid == TypeId::TIMESTAMP_S || tid == TypeId::TIMESTAMP_MS || tid == TypeId::TIMESTAMP_NS || tid == TypeId::TIMESTAMP)) {
      // DuckDB doesn't allow int -> timestamp cast directly
    }
    if (st.id == TypeId::BOOLEAN && tid == TypeId::VARCHAR) { out.str = v.ToString(); return true; }
    if (st.IsInteger() && tid == TypeId::BIT) {
      err = "Unimplemented type for cast (" + st.ToString() + " -> BIT)"; return false;
    }
    if (st.IsInteger() && tid == TypeId::ENUM) {
      err = "Unimplemented type for cast (" + st.ToString() + " -> " + target.ToString() + ")"; return false;
    }
  }
  // --- temporal conversions
  if (st.id == TypeId::DATE) {
    if (target.IsTimestamp()) {
      int32_t d = (int32_t)v.ival;
      if (d == INT32_MAX) { out.ival = INT64_MAX; return true; }
      if (d == -INT32_MAX) { out.ival = -INT64_MAX; return true; }
      int64_t us;
      if (__builtin_mul_overflow((int64_t)d, 86400000000LL, &us)) { err = "Could not convert DATE (" + v.ToString() + ") to TIMESTAMP"; return false; }
      if (tid == TypeId::TIMESTAMP_S) us /= 1000000;
      else if (tid == TypeId::TIMESTAMP_MS) us /= 1000;
      else if (tid == TypeId::TIMESTAMP_NS) { if (__builtin_mul_overflow(us, 1000LL, &us)) { err = "Could not convert DATE (" + v.ToString() + ") to TIMESTAMP"; return false; } }
      out.ival = us; return true;
    }
  }
  if (st.IsTimestamp()) {
    int64_t us = (int64_t)v.ival;
    if (st.id == TypeId::TIMESTAMP_S) us *= 1000000;
    else if (st.id == TypeId::TIMESTAMP_MS) us *= 1000;
    else if (st.id == TypeId::TIMESTAMP_NS) us /= 1000;
    if (tid == TypeId::DATE) { out.ival = (us == INT64_MAX) ? INT32_MAX : (us == -INT64_MAX ? -INT32_MAX : TimestampToDate(us)); return true; }
    if (tid == TypeId::TIME || tid == TypeId::TIME_TZ) { out.ival = us - DateToTimestampMicros(TimestampToDate(us)); return true; }
    if (target.IsTimestamp()) {
      if (tid == TypeId::TIMESTAMP_S) us /= 1000000;
      else if (tid == TypeId::TIMESTAMP_MS) us /= 1000;
      else if (tid == TypeId::TIMESTAMP_NS) us *= 1000;
      out.ival = us; return true;
    }
  }
  if (st.id == TypeId::TIME && tid == TypeId::TIME_TZ) { out.ival = v.ival; return true; }
  if (st.id == TypeId::TIME_TZ && tid == TypeId::TIME) { out.ival = v.ival; return true; }
  // --- blob <-> varchar handled; blob -> bit etc.
  if (st.id == TypeId::BLOB && tid == TypeId::BIT) { out.str = v.str; return true; }
  if (st.id == TypeId::UUID && tid == TypeId::HUGEINT) { out.ival = v.ival; return true; }
  if (st.id == TypeId::HUGEINT && tid == TypeId::UUID) { out.ival = v.ival; return true; }
  if (st.id == TypeId::ENUM) {
    std::string s = v.ToString();
    return TryCastInternal(Value::Varchar(s), target, out, err);
  }
  // --- nested
  if ((st.id == TypeId::LIST || st.id == TypeId::ARRAY) && (tid == TypeId::LIST || tid == TypeId::ARRAY)) {
    std::vector<Value> vals;
    for (auto &c : *v.children) {
      Value cv;
      if (!TryCastInternal(c, target.child(), cv, err)) return false;
      vals.push_back(cv);
    }
    if (tid == TypeId::ARRAY && (int64_t)vals.size() != target.info->array_size) {
      err = "Cannot cast list with length " + std::to_string(vals.size()) + " to array with length " + std::to_string(target.info->array_size);
      return false;
    }
    out.children = std::make_shared<std::vector<Value>>(std::move(vals));
    return true;
  }
  if (st.id == TypeId::STRUCT && tid == TypeId::STRUCT) {
    std::vector<Value> vals;
    auto &snames = st.info->names;
    auto &tnames = target.info->names;
    if (snames.size() != tnames.size()) {
      err = "Cannot cast STRUCTs of different size"; return false;
    }
    // match by name if names match, else positional
    bool by_name = true;
    for (auto &tn : tnames) {
      bool found = false;
      for (auto &sn : snames) if (IEquals(sn, tn)) found = true;
      if (!found) { by_name = false; break; }
    }
    for (size_t i = 0; i < tnames.size(); i++) {
      size_t src = i;
      if (by_name) { for (size_t j = 0; j < snames.size(); j++) if (IEquals(snames[j], tnames[i])) src = j; }
      Value cv;
      if (!TryCastInternal((*v.children)[src], target.info->children[i], cv, err)) return false;
      vals.push_back(cv);
    }
    out.children = std::make_shared<std::vector<Value>>(std::move(vals));
    return true;
  }
  if (st.id == TypeId::MAP && tid == TypeId::MAP) {
    std::vector<Value> vals;
    for (auto &c : *v.children) {
      Value k, val;
      if (!TryCastInternal((*c.children)[0], target.info->children[0], k, err)) return false;
      if (!TryCastInternal((*c.children)[1], target.info->children[1], val, err)) return false;
      vals.push_back(Value::Struct({"key", "value"}, {k, val}));
    }
    out.children = std::make_shared<std::vector<Value>>(std::move(vals));
    return true;
  }
  if (st.id == TypeId::STRUCT && tid == TypeId::MAP) {
    err = "Unimplemented type for cast (" + st.ToString() + " -> " + target.ToString() + ")"; return false;
  }
  if (tid == TypeId::UNION) {
    // find matching member
    for (size_t i = 0; i < target.info->children.size(); i++) {
      if (target.info->children[i] == st) {
        out.ival = (int64_t)i;
        out.children = std::make_shared<std::vector<Value>>(std::vector<Value>{v});
        return true;
      }
    }
    for (size_t i = 0; i < target.info->children.size(); i++) {
      Value cv;
      std::string e2;
      if (TryCastInternal(v, target.info->children[i], cv, e2)) {
        out.ival = (int64_t)i;
        out.children = std::make_shared<std::vector<Value>>(std::vector<Value>{cv});
        return true;
      }
    }
  }
  if (st.id == TypeId::UNION) {
    return TryCastInternal((*v.children)[0], target, out, err);
  }
  if (st.id == TypeId::SQLNULL) { out = Value::Null(target); return true; }
  err = "Unimplemented type for cast (" + st.ToString() + " -> " + target.ToString() + ")";
  return false;
}

bool TryCastValue(const Value &v, const LogicalType &target, Value &result) {
  std::string err;
  if (TryCastInternal(v, target, result, err)) return true;
  result = Value::Null(target);
  return false;
}

Value CastValue(const Value &v, const LogicalType &target, bool try_cast) {
  Value result;
  std::string err;
  if (TryCastInternal(v, target, result, err)) return result;
  if (try_cast) return Value::Null(target);
  if (v.type.id == TypeId::STRING_LITERAL || v.type.id == TypeId::VARCHAR) {
    throw ConversionException(err);
  }
  throw ConversionException(err);
}

// nested from string parsing (basic)
static void SkipWs(const std::string &s, size_t &i) { while (i < s.size() && isspace((unsigned char)s[i])) i++; }
static bool ParseNestedElement(const std::string &s, size_t &i, std::string &out, bool &quoted) {
  SkipWs(s, i);
  quoted = false;
  if (i >= s.size()) return false;
  if (s[i] == '\'' || s[i] == '"') {
    char q = s[i]; i++;
    quoted = true;
    while (i < s.size() && s[i] != q) {
      if (s[i] == '\\' && i + 1 < s.size()) { i++; }
      out += s[i]; i++;
    }
    if (i >= s.size()) return false;
    i++;
    return true;
  }
  int depth = 0;
  size_t start = i;
  while (i < s.size()) {
    char c = s[i];
    if (c == '[' || c == '{' || c == '(') depth++;
    else if (c == ']' || c == '}' || c == ')') { if (depth == 0) break; depth--; }
    else if ((c == ',' || c == ':' || c == '=') && depth == 0) break;
    i++;
  }
  out = Trim(s.substr(start, i - start));
  return true;
}
bool ParseNestedFromString(const std::string &s, const LogicalType &target, Value &out, std::string &err) {
  std::string t = Trim(s);
  out = Value(target);
  out.is_null = false;
  if (target.id == TypeId::LIST || target.id == TypeId::ARRAY) {
    if (t.size() < 2 || t.front() != '[' || t.back() != ']') { err = "Type VARCHAR with value '" + s + "' can't be cast to the destination type " + target.ToString(); return false; }
    std::vector<Value> vals;
    size_t i = 1;
    std::string inner = t.substr(0, t.size() - 1);
    SkipWs(inner, i);
    while (i < inner.size()) {
      std::string el; bool quoted;
      if (!ParseNestedElement(inner, i, el, quoted)) { err = "Type VARCHAR with value '" + s + "' can't be cast to the destination type " + target.ToString(); return false; }
      Value cv;
      if (!quoted && IEquals(el, "null")) cv = Value::Null(target.child());
      else if (!TryCastInternal(Value::Varchar(el), target.child(), cv, err)) return false;
      vals.push_back(cv);
      SkipWs(inner, i);
      if (i < inner.size() && inner[i] == ',') i++;
    }
    out.children = std::make_shared<std::vector<Value>>(std::move(vals));
    return true;
  }
  if (target.id == TypeId::STRUCT) {
    if (t.size() < 2 || t.front() != '{' || t.back() != '}') { err = "Type VARCHAR with value '" + s + "' can't be cast to the destination type " + target.ToString(); return false; }
    std::vector<Value> vals(target.info->children.size());
    std::vector<bool> set(vals.size(), false);
    size_t i = 1;
    std::string inner = t.substr(0, t.size() - 1);
    SkipWs(inner, i);
    while (i < inner.size()) {
      std::string key; bool q;
      if (!ParseNestedElement(inner, i, key, q)) break;
      SkipWs(inner, i);
      if (i < inner.size() && inner[i] == ':') i++;
      std::string val; bool vq;
      if (!ParseNestedElement(inner, i, val, vq)) break;
      for (size_t k = 0; k < target.info->names.size(); k++) {
        if (IEquals(target.info->names[k], key)) {
          Value cv;
          if (!vq && IEquals(val, "null")) cv = Value::Null(target.info->children[k]);
          else if (!TryCastInternal(Value::Varchar(val), target.info->children[k], cv, err)) return false;
          vals[k] = cv; set[k] = true;
        }
      }
      SkipWs(inner, i);
      if (i < inner.size() && inner[i] == ',') i++;
    }
    for (size_t k = 0; k < vals.size(); k++) if (!set[k]) vals[k] = Value::Null(target.info->children[k]);
    out.children = std::make_shared<std::vector<Value>>(std::move(vals));
    return true;
  }
  if (target.id == TypeId::MAP) {
    if (t.size() < 2 || t.front() != '{' || t.back() != '}') { err = "Type VARCHAR with value '" + s + "' can't be cast to the destination type " + target.ToString(); return false; }
    std::vector<Value> vals;
    size_t i = 1;
    std::string inner = t.substr(0, t.size() - 1);
    SkipWs(inner, i);
    while (i < inner.size()) {
      std::string key; bool q;
      if (!ParseNestedElement(inner, i, key, q)) break;
      SkipWs(inner, i);
      if (i < inner.size() && (inner[i] == '=' || inner[i] == ':')) i++;
      std::string val; bool vq;
      if (!ParseNestedElement(inner, i, val, vq)) break;
      Value kv, vv;
      if (!TryCastInternal(Value::Varchar(key), target.info->children[0], kv, err)) return false;
      if (!vq && IEquals(val, "null")) vv = Value::Null(target.info->children[1]);
      else if (!TryCastInternal(Value::Varchar(val), target.info->children[1], vv, err)) return false;
      vals.push_back(Value::Struct({"key", "value"}, {kv, vv}));
      SkipWs(inner, i);
      if (i < inner.size() && inner[i] == ',') i++;
    }
    out.children = std::make_shared<std::vector<Value>>(std::move(vals));
    return true;
  }
  err = "Unimplemented cast";
  return false;
}

// ---------------------------------------------------------------- type promotion
static int NumericRank(TypeId t) {
  switch (t) {
  case TypeId::BOOLEAN: return 0;
  case TypeId::TINYINT: return 1;
  case TypeId::UTINYINT: return 2;
  case TypeId::SMALLINT: return 3;
  case TypeId::USMALLINT: return 4;
  case TypeId::INTEGER: return 5;
  case TypeId::UINTEGER: return 6;
  case TypeId::BIGINT: return 7;
  case TypeId::UBIGINT: return 8;
  case TypeId::HUGEINT: return 9;
  case TypeId::UHUGEINT: return 10;
  case TypeId::DECIMAL: return 11;
  case TypeId::FLOAT: return 12;
  case TypeId::DOUBLE: return 13;
  default: return -1;
  }
}

static LogicalType DecimalForInteger(TypeId t) {
  switch (t) {
  case TypeId::TINYINT: return LogicalType::Decimal(3, 0);
  case TypeId::UTINYINT: return LogicalType::Decimal(3, 0);
  case TypeId::SMALLINT: return LogicalType::Decimal(5, 0);
  case TypeId::USMALLINT: return LogicalType::Decimal(5, 0);
  case TypeId::INTEGER: return LogicalType::Decimal(10, 0);
  case TypeId::UINTEGER: return LogicalType::Decimal(10, 0);
  case TypeId::BIGINT: return LogicalType::Decimal(19, 0);
  case TypeId::UBIGINT: return LogicalType::Decimal(20, 0);
  case TypeId::HUGEINT: return LogicalType::Decimal(38, 0);
  case TypeId::UHUGEINT: return LogicalType::Decimal(38, 0);
  default: return LogicalType::Decimal(18, 3);
  }
}

LogicalType MaxLogicalType(const LogicalType &a, const LogicalType &b) {
  if (a.id == TypeId::SQLNULL || a.id == TypeId::UNKNOWN) return b;
  if (b.id == TypeId::SQLNULL || b.id == TypeId::UNKNOWN) return a;
  if (a == b) return a;
  if (a.id == TypeId::STRING_LITERAL) {
    if (b.id == TypeId::STRING_LITERAL) return LogicalType(TypeId::VARCHAR);
    return b;
  }
  if (b.id == TypeId::STRING_LITERAL) return a;
  if (a.id == TypeId::INTEGER_LITERAL) return MaxLogicalType(LogicalType(TypeId::INTEGER), b);
  if (b.id == TypeId::INTEGER_LITERAL) return MaxLogicalType(a, LogicalType(TypeId::INTEGER));
  if (a.id == TypeId::ANY) return b;
  if (b.id == TypeId::ANY) return a;
  if (a.IsNumeric() && b.IsNumeric()) {
    if (a.id == TypeId::DOUBLE || b.id == TypeId::DOUBLE) return LogicalType(TypeId::DOUBLE);
    if (a.id == TypeId::FLOAT || b.id == TypeId::FLOAT) return LogicalType(TypeId::FLOAT);
    if (a.id == TypeId::DECIMAL || b.id == TypeId::DECIMAL) {
      LogicalType da = a.id == TypeId::DECIMAL ? a : DecimalForInteger(a.id);
      LogicalType db = b.id == TypeId::DECIMAL ? b : DecimalForInteger(b.id);
      int scale = std::max(da.scale, db.scale);
      int width = std::max(da.width - da.scale, db.width - db.scale) + scale;
      if (width > 38) { width = 38; }
      if (scale > width) scale = width;
      return LogicalType::Decimal(width, scale);
    }
    // both integers
    if (a.IsSigned() == b.IsSigned()) {
      return NumericRank(a.id) > NumericRank(b.id) ? a : b;
    }
    // mixed signed / unsigned
    const LogicalType &s = a.IsSigned() ? a : b;
    const LogicalType &u = a.IsSigned() ? b : a;
    // need signed type that fits both
    auto rank = [](TypeId t) {
      switch (t) {
      case TypeId::TINYINT: case TypeId::UTINYINT: return 1;
      case TypeId::SMALLINT: case TypeId::USMALLINT: return 2;
      case TypeId::INTEGER: case TypeId::UINTEGER: return 3;
      case TypeId::BIGINT: case TypeId::UBIGINT: return 4;
      default: return 5;
      }
    };
    int ru = rank(u.id), rs = rank(s.id);
    if (u.id == TypeId::UHUGEINT) return LogicalType(TypeId::DOUBLE);
    if (rs > ru) return s;
    // unsigned is >= signed: promote to next signed
    switch (u.id) {
    case TypeId::UTINYINT: return LogicalType(TypeId::SMALLINT);
    case TypeId::USMALLINT: return LogicalType(TypeId::INTEGER);
    case TypeId::UINTEGER: return LogicalType(TypeId::BIGINT);
    case TypeId::UBIGINT: return LogicalType(TypeId::HUGEINT);
    default: return LogicalType(TypeId::HUGEINT);
    }
  }
  if (a.id == TypeId::BOOLEAN && b.IsNumeric()) return b;
  if (b.id == TypeId::BOOLEAN && a.IsNumeric()) return a;
  // temporal
  if (a.id == TypeId::DATE && b.IsTimestamp()) return b;
  if (b.id == TypeId::DATE && a.IsTimestamp()) return a;
  if (a.IsTimestamp() && b.IsTimestamp()) {
    if (a.id == TypeId::TIMESTAMP_NS || b.id == TypeId::TIMESTAMP_NS) return LogicalType(TypeId::TIMESTAMP_NS);
    if (a.id == TypeId::TIMESTAMP_TZ || b.id == TypeId::TIMESTAMP_TZ) return LogicalType(TypeId::TIMESTAMP_TZ);
    return LogicalType(TypeId::TIMESTAMP);
  }
  if (a.id == TypeId::TIME && b.id == TypeId::TIME_TZ) return b;
  if (b.id == TypeId::TIME && a.id == TypeId::TIME_TZ) return a;
  // nested
  if (a.id == TypeId::LIST && b.id == TypeId::LIST) return LogicalType::List(MaxLogicalType(a.child(), b.child()));
  if (a.id == TypeId::ARRAY && b.id == TypeId::ARRAY && a.info->array_size == b.info->array_size)
    return LogicalType::Array(MaxLogicalType(a.child(), b.child()), a.info->array_size);
  if ((a.id == TypeId::ARRAY && b.id == TypeId::LIST) || (a.id == TypeId::LIST && b.id == TypeId::ARRAY))
    return LogicalType::List(MaxLogicalType(a.child(), b.child()));
  if (a.id == TypeId::STRUCT && b.id == TypeId::STRUCT && a.info->children.size() == b.info->children.size()) {
    std::vector<LogicalType> types;
    for (size_t i = 0; i < a.info->children.size(); i++) types.push_back(MaxLogicalType(a.info->children[i], b.info->children[i]));
    return LogicalType::Struct(a.info->names, types);
  }
  if (a.id == TypeId::MAP && b.id == TypeId::MAP)
    return LogicalType::Map(MaxLogicalType(a.info->children[0], b.info->children[0]), MaxLogicalType(a.info->children[1], b.info->children[1]));
  if (a.id == TypeId::ENUM && b.id == TypeId::VARCHAR) return b;
  if (b.id == TypeId::ENUM && a.id == TypeId::VARCHAR) return a;
  if (a.id == TypeId::ENUM && b.id == TypeId::ENUM) return LogicalType(TypeId::VARCHAR);
  if (a.id == TypeId::VARCHAR) return a;
  if (b.id == TypeId::VARCHAR) return b;
  // fallback: varchar
  return LogicalType(TypeId::VARCHAR);
}

int ImplicitCastCost(const LogicalType &from, const LogicalType &to) {
  // returns -1 if not possible
  if (from == to) return 0;
  if (to.id == TypeId::ANY) return 10;
  if (from.id == TypeId::SQLNULL || from.id == TypeId::UNKNOWN) return 1;
  if (from.id == TypeId::STRING_LITERAL) {
    if (to.id == TypeId::VARCHAR) return 1;
    if (to.IsNested() || to.id == TypeId::BLOB || to.id == TypeId::BIT) return -1;
    return 20;  // string literals can be cast to most things
  }
  if (from.id == TypeId::INTEGER_LITERAL) {
    if (to.IsNumeric()) return 1;
    return -1;
  }
  if (to.id == TypeId::VARCHAR && from.id == TypeId::STRING_LITERAL) return 1;
  if (from.IsNumeric() && to.IsNumeric()) {
    int rf = NumericRank(from.id), rt = NumericRank(to.id);
    if (from.id == TypeId::DECIMAL) { if (to.IsFloating()) return 1 + (to.id == TypeId::DOUBLE ? 1 : 2); return -1; }
    if (to.id == TypeId::DECIMAL) return from.IsFloating() ? -1 : 10;
    if (from.IsSigned() && to.IsUnsigned()) return -1;
    if (from.IsUnsigned() && to.IsSigned()) {
      // allowed if to is strictly larger
      if (rt > rf + 1) return rt - rf;
      return -1;
    }
    if (rt > rf) return rt - rf;
    return -1;
  }
  if (from.id == TypeId::BOOLEAN && to.IsNumeric()) return -1;
  if (from.id == TypeId::DATE && to.IsTimestamp()) return 10;
  if (from.id == TypeId::TIMESTAMP && to.id == TypeId::TIMESTAMP_TZ) return 10;
  if (from.id == TypeId::TIME && to.id == TypeId::TIME_TZ) return 10;
  if (from.id == TypeId::LIST && to.id == TypeId::LIST) return ImplicitCastCost(from.child(), to.child());
  if (from.id == TypeId::ARRAY && to.id == TypeId::LIST) { int c = ImplicitCastCost(from.child(), to.child()); return c < 0 ? -1 : c + 1; }
  if (from.id == TypeId::ENUM && to.id == TypeId::VARCHAR) return 5;
  if (from.id == TypeId::STRUCT && to.id == TypeId::STRUCT && from.info->children.size() == to.info->children.size()) {
    int total = 0;
    for (size_t i = 0; i < from.info->children.size(); i++) {
      int c = ImplicitCastCost(from.info->children[i], to.info->children[i]);
      if (c < 0) return -1;
      total += c;
    }
    return total;
  }
  if (from.id == TypeId::MAP && to.id == TypeId::MAP) {
    int c1 = ImplicitCastCost(from.info->children[0], to.info->children[0]);
    int c2 = ImplicitCastCost(from.info->children[1], to.info->children[1]);
    if (c1 < 0 || c2 < 0) return -1;
    return c1 + c2;
  }
  return -1;
}
bool CanImplicitCast(const LogicalType &from, const LogicalType &to) { return ImplicitCastCost(from, to) >= 0; }
