// AST definitions
#pragma once
#include "types.h"
#include <memory>
#include <vector>
#include <string>

struct Expr;
struct TableRef;
struct QueryNode;
struct SelectStatement;
typedef std::unique_ptr<Expr> ExprPtr;
typedef std::unique_ptr<TableRef> TableRefPtr;
typedef std::unique_ptr<QueryNode> QueryNodePtr;

enum class ExprKind {
  CONSTANT, COLUMN_REF, STAR, FUNCTION, OPERATOR, COMPARISON, CONJUNCTION, CASE, CAST, SUBQUERY, BETWEEN, COLLATE,
  LAMBDA, WINDOW, POSITIONAL_REF, PARAMETER, DEFAULT, LAMBDA_REF
};

enum class SubqueryType { SCALAR, EXISTS, NOT_EXISTS, ANY, ALL };
enum class OrderType { ASC, DESC, DEFAULT };
enum class NullOrder { NULLS_FIRST, NULLS_LAST, DEFAULT };

struct OrderByNode {
  ExprPtr expr;
  OrderType type = OrderType::DEFAULT;
  NullOrder null_order = NullOrder::DEFAULT;
};

struct WindowFrame {
  enum Bound { UNBOUNDED_PRECEDING, EXPR_PRECEDING, CURRENT_ROW, EXPR_FOLLOWING, UNBOUNDED_FOLLOWING };
  bool rows = true;   // ROWS vs RANGE (false) ; groups
  bool groups = false;
  Bound start = UNBOUNDED_PRECEDING, end = CURRENT_ROW;
  ExprPtr start_expr, end_expr;
  bool specified = false;
  enum Exclude { EXCLUDE_NONE, EXCLUDE_CURRENT_ROW, EXCLUDE_GROUP, EXCLUDE_TIES } exclude = EXCLUDE_NONE;
};

struct WindowSpec {
  std::string name;  // reference to named window
  std::vector<ExprPtr> partitions;
  std::vector<OrderByNode> orders;
  WindowFrame frame;
};

struct Expr {
  ExprKind kind;
  std::string alias;
  int64_t position = -1;  // query position for error messages
  // constant
  Value value;
  // column ref / function name / operator
  std::vector<std::string> names;   // column ref parts; for function: [schema?, name]
  std::string op;                   // operator / function name
  std::string schema;               // function schema
  std::vector<ExprPtr> children;    // args / operands
  bool distinct = false;            // aggregate DISTINCT
  ExprPtr filter;                   // aggregate FILTER
  std::vector<OrderByNode> order_bys; // aggregate ORDER BY
  bool is_operator = false;
  bool export_state = false;
  // star
  std::vector<std::string> exclude_list;
  std::vector<std::pair<std::string, ExprPtr>> replace_list;
  std::vector<std::pair<std::string, ExprPtr>> rename_list;
  std::string relation_name;        // t.*
  ExprPtr columns_expr;             // COLUMNS(regex) or COLUMNS(lambda)
  bool columns_star = false;
  std::string columns_regex;
  // case
  struct CaseCheck { ExprPtr when; ExprPtr then; };
  std::vector<CaseCheck> case_checks;
  ExprPtr else_expr;
  // cast
  LogicalType cast_type;
  bool try_cast = false;
  // subquery
  std::unique_ptr<SelectStatement> subquery;
  SubqueryType subquery_type = SubqueryType::SCALAR;
  std::string comparison_type;       // for ANY/ALL
  // between: children[0] BETWEEN children[1] AND children[2]
  // collate
  std::string collation;
  // lambda: children[0] = params expr (column ref or row), children[1] = body
  std::vector<std::string> lambda_params;
  // window
  std::unique_ptr<WindowSpec> window;
  bool ignore_nulls = false;
  // positional
  int64_t index = 0;
  // parameter
  std::string param_name;

  Expr(ExprKind k) : kind(k) {}
  std::string ToString() const;
  ExprPtr Copy() const;
  bool IsAggregate() const;
  // helpers
  static ExprPtr Constant(const Value &v) { auto e = std::make_unique<Expr>(ExprKind::CONSTANT); e->value = v; return e; }
  static ExprPtr ColumnRef(const std::vector<std::string> &names) { auto e = std::make_unique<Expr>(ExprKind::COLUMN_REF); e->names = names; return e; }
  static ExprPtr Function(const std::string &name, std::vector<ExprPtr> args) {
    auto e = std::make_unique<Expr>(ExprKind::FUNCTION); e->op = name; e->children = std::move(args); return e;
  }
  static ExprPtr Operator(const std::string &op, std::vector<ExprPtr> args) {
    auto e = std::make_unique<Expr>(ExprKind::OPERATOR); e->op = op; e->children = std::move(args); return e;
  }
  static ExprPtr Comparison(const std::string &op, ExprPtr l, ExprPtr r) {
    auto e = std::make_unique<Expr>(ExprKind::COMPARISON); e->op = op; e->children.push_back(std::move(l)); e->children.push_back(std::move(r)); return e;
  }
  static ExprPtr Conjunction(const std::string &op, ExprPtr l, ExprPtr r) {
    auto e = std::make_unique<Expr>(ExprKind::CONJUNCTION); e->op = op; e->children.push_back(std::move(l)); e->children.push_back(std::move(r)); return e;
  }
  static ExprPtr Cast(ExprPtr child, const LogicalType &t, bool try_c = false) {
    auto e = std::make_unique<Expr>(ExprKind::CAST); e->children.push_back(std::move(child)); e->cast_type = t; e->try_cast = try_c; return e;
  }
};

std::string OrderByToString(const OrderByNode &o);
std::string WindowSpecToString(const WindowSpec &w, const std::string &fname);

// ---------------------------------------------------------------- table refs
enum class TableRefKind { BASE_TABLE, SUBQUERY, JOIN, TABLE_FUNCTION, EXPRESSION_LIST, EMPTY, PIVOT, SHOW_REF, COLUMN_DATA };
enum class JoinType { INNER, LEFT, RIGHT, FULL, CROSS, SEMI, ANTI, POSITIONAL, ASOF, MARK, SINGLE };
enum class JoinRefType { REGULAR, NATURAL, CROSS, POSITIONAL, ASOF, DEPENDENT };

struct TableRef {
  TableRefKind kind;
  std::string alias;
  std::vector<std::string> column_aliases;
  std::string sample;
  int64_t position = -1;
  // base table
  std::string catalog, schema, table_name;
  // subquery
  std::unique_ptr<SelectStatement> subquery;
  // join
  TableRefPtr left, right;
  JoinType join_type = JoinType::INNER;
  JoinRefType ref_type = JoinRefType::REGULAR;
  ExprPtr condition;
  std::vector<std::string> using_columns;
  bool lateral = false;
  // table function
  std::string function_name;
  std::vector<ExprPtr> function_args;
  std::vector<std::pair<std::string, ExprPtr>> named_args;
  // expression list (VALUES)
  std::vector<std::vector<ExprPtr>> values;
  std::vector<std::string> expected_names;
  // pivot
  struct PivotColumn {
    std::vector<ExprPtr> pivot_exprs;   // columns to pivot on
    std::vector<ExprPtr> entries;       // IN values
    std::string unpivot_name;
    std::vector<std::vector<std::string>> unpivot_cols;  // unpivot: list of column groups
    std::vector<std::string> entry_aliases;
    std::unique_ptr<SelectStatement> subquery; // IN (subquery)
  };
  TableRefPtr source;
  std::vector<PivotColumn> pivots;
  std::vector<ExprPtr> aggregates;
  std::vector<std::string> unpivot_names;
  std::vector<ExprPtr> groups;
  bool include_nulls = false;
  bool is_unpivot = false;
  std::vector<std::string> pivot_column_names;  // for simplified pivot syntax: ON/USING/GROUP BY

  TableRef(TableRefKind k) : kind(k) {}
  std::string ToString() const;
};

// ---------------------------------------------------------------- query nodes
enum class QueryNodeKind { SELECT, SET_OPERATION, RECURSIVE_CTE, CTE, VALUES };
enum class SetOpType { UNION, UNION_ALL, EXCEPT, EXCEPT_ALL, INTERSECT, INTERSECT_ALL, UNION_BY_NAME, UNION_ALL_BY_NAME };

struct CTE {
  std::string name;
  std::vector<std::string> aliases;
  std::unique_ptr<SelectStatement> query;
  bool materialized = false;
  bool recursive = false;
  std::string key_target;
};

struct SampleOptions {
  bool specified = false;
  double value = 0;
  bool is_percentage = false;
  std::string method;
  int64_t seed = -1;
};

struct QueryNode {
  QueryNodeKind kind;
  std::vector<std::unique_ptr<CTE>> ctes;
  bool recursive_ctes = false;
  // modifiers (apply to all nodes)
  std::vector<OrderByNode> orders;
