  while (i < n) {
    char c = sql[i];
    if (c == '\'' || c == '"') { i = SkipQuoted(sql, i); continue; }
    if (c == '$' && i + 1 < n && !isdigit((unsigned char)sql[i + 1])) {
      size_t j = SkipQuoted(sql, i);
      if (j > i + 1) { i = j; continue; }
    }
    if (c == '-' && i + 1 < n && sql[i + 1] == '-') { while (i < n && sql[i] != '\n') i++; continue; }
    if (c == '/' && i + 1 < n && sql[i + 1] == '*') {
      size_t e = sql.find("*/", i + 2);
      i = e == std::string::npos ? n : e + 2;
      continue;
    }
    if (c == ';') {
      out.push_back({sql.substr(start, i - start), start});
      i++;
      start = i;
      continue;
    }
    i++;
  }
  if (start < n) {
    std::string rest = sql.substr(start);
    bool all_ws = true;
    for (char ch : rest) if (!isspace((unsigned char)ch)) { all_ws = false; break; }
    if (!all_ws) out.push_back({rest, start});
  }
  return out;
}

bool SqlIsComplete(const std::string &sql) {
  // complete if last non-whitespace/comment char is ';' and we're not inside quotes
  size_t n = sql.size();
  size_t i = 0;
  bool last_semicolon = false;
  while (i < n) {
    char c = sql[i];
    if (c == '\'' || c == '"') { size_t j = SkipQuoted(sql, i); if (j >= n && (j == n && !(sql.back() == c && j > i + 1))) { /* possibly unterminated */ } i = j; last_semicolon = false; continue; }
    if (c == '$' && i + 1 < n && !isdigit((unsigned char)sql[i + 1])) {
      size_t j = SkipQuoted(sql, i);
      if (j > i + 1) { i = j; last_semicolon = false; continue; }
    }
    if (c == '-' && i + 1 < n && sql[i + 1] == '-') { while (i < n && sql[i] != '\n') i++; continue; }
    if (c == '/' && i + 1 < n && sql[i + 1] == '*') { size_t e = sql.find("*/", i + 2); i = e == std::string::npos ? n : e + 2; continue; }
    if (isspace((unsigned char)c)) { i++; continue; }
    last_semicolon = c == ';';
    i++;
  }
  return last_semicolon;
}
