Parser::Parser(const std::string &sql_in) : sql(sql_in) { tokens = Tokenize(sql); }

void Parser::SyntaxError(const Token &t) {
  if (t.type == TokenType::EOI) {
    ParserException e("syntax error at end of input");
    e.position = t.pos;
    throw e;
  }
  std::string text = sql.substr(t.pos, t.end - t.pos);
  ParserException e("syntax error at or near \"" + text + "\"");
  e.position = t.pos;
  throw e;
}
void Parser::ExpectKeyword(const char *kw) { if (!MatchKeyword(kw)) SyntaxErrorHere(); }
void Parser::ExpectOp(const char *op) { if (!MatchOp(op)) SyntaxErrorHere(); }

bool Parser::PeekIdentifier(size_t ahead) {
  const Token &t = Peek(ahead);
  return t.type == TokenType::IDENT || t.type == TokenType::QUOTED_IDENT;
}

std::string Parser::ParseIdentifier() {
  const Token &t = Peek();
  if (t.type == TokenType::QUOTED_IDENT) { Next(); return t.text; }
  if (t.type == TokenType::IDENT) {
    if (kReserved.count(ToLower(t.text))) SyntaxErrorHere();
    Next();
    return ToLower(t.text);
  }
  SyntaxErrorHere();
}

std::string Parser::ParseColumnAlias() {
  const Token &t = Peek();
  if (t.type == TokenType::QUOTED_IDENT) { Next(); return t.text; }
  if (t.type == TokenType::IDENT) { Next(); return ToLower(t.text); }
  if (t.type == TokenType::STRING) { Next(); return t.text; }
  SyntaxErrorHere();
}

std::vector<std::string> Parser::ParseQualifiedName() {
  std::vector<std::string> names;
  names.push_back(ParseIdentifier());
  while (PeekOp(".")) {
    Next();
    const Token &t = Peek();
    if (t.type == TokenType::QUOTED_IDENT) { Next(); names.push_back(t.text); }
    else if (t.type == TokenType::IDENT) { Next(); names.push_back(ToLower(t.text)); }
    else SyntaxErrorHere();
  }
  return names;
}

std::string Parser::ParseStringLiteral() {
  const Token &t = Peek();
  if (t.type == TokenType::STRING || t.type == TokenType::ESCAPE_STRING || t.type == TokenType::DOLLAR_STRING) { Next(); return t.text; }
  SyntaxErrorHere();
}

