std::string TypeToCastDisplay(const LogicalType &t) {
  switch (t.id) {
  case TypeId::TINYINT: case TypeId::UTINYINT: case TypeId::USMALLINT: case TypeId::UINTEGER: case TypeId::UBIGINT: case TypeId::HUGEINT:
  case TypeId::UHUGEINT: case TypeId::DOUBLE: case TypeId::DATE: case TypeId::BLOB: case TypeId::TIMESTAMP_TZ: case TypeId::TIMESTAMP_S:
  case TypeId::TIMESTAMP_MS: case TypeId::TIMESTAMP_NS: case TypeId::TIME_TZ: case TypeId::UUID:
    return "\"" + t.ToString() + "\"";
  case TypeId::ENUM: {
    std::string r = "\"ENUM\"(";
    for (size_t i = 0; i < t.info->names.size(); i++) { if (i) r += ", "; r += EscapeSQLString(t.info->names[i]); }
    return r + ")";
  }
  case TypeId::DECIMAL: return "DECIMAL(" + std::to_string(t.width) + ", " + std::to_string(t.scale) + ")";
  case TypeId::LIST: return TypeToCastDisplay(t.child()) + "[]";
  case TypeId::ARRAY: return TypeToCastDisplay(t.child()) + "[" + std::to_string(t.info->array_size) + "]";
  case TypeId::STRUCT: {
    std::string r = "STRUCT(";
    for (size_t i = 0; i < t.info->children.size(); i++) { if (i) r += ", "; r += QuoteIdentifierIfNeeded(t.info->names[i]) + " " + TypeToCastDisplay(t.info->children[i]); }
    return r + ")";
  }
  case TypeId::UNION: {
    std::string r = "UNION(";
    for (size_t i = 0; i < t.info->children.size(); i++) { if (i) r += ", "; r += QuoteIdentifierIfNeeded(t.info->names[i]) + " " + TypeToCastDisplay(t.info->children[i]); }
    return r + ")";
  }
  case TypeId::MAP: return "MAP(" + TypeToCastDisplay(t.info->children[0]) + ", " + TypeToCastDisplay(t.info->children[1]) + ")";
  case TypeId::INVALID: if (t.info && !t.info->alias.empty()) return "\"" + t.info->alias + "\""; return "INVALID";
  default: return t.ToString();
  }
}

TypeDisplay Parser::ParseType() {
  TypeDisplay result;
  const Token &t = Peek();
  std::string name;
  bool quoted = false;
  if (t.type == TokenType::QUOTED_IDENT) { name = t.text; quoted = true; Next(); }
  else if (t.type == TokenType::IDENT) { name = ToLower(t.text); Next(); }
  else SyntaxErrorHere();
  std::string lname = ToLower(name);
  std::string display;
  LogicalType type;
  // multi-word types
  if (lname == "double" && PeekKeyword("precision")) { Next(); }
  if (lname == "timestamp" || lname == "time") {
    if (PeekKeyword("with")) {
      Next(); ExpectKeyword("time"); ExpectKeyword("zone");
      lname = lname == "timestamp" ? "timestamptz" : "timetz";
    } else if (PeekKeyword("without")) {
      Next(); ExpectKeyword("time"); ExpectKeyword("zone");
    }
  }
  if (lname == "character" && PeekKeyword("varying")) { Next(); lname = "varchar"; }
  if (lname == "struct" || lname == "row") {
    ExpectOp("(");
    std::vector<std::string> names; std::vector<LogicalType> types; std::vector<std::string> disp;
    do {
      std::string fname = ParseColumnAlias();
      TypeDisplay ft = ParseType();
      names.push_back(fname); types.push_back(ft.type); disp.push_back(QuoteIdentifierIfNeeded(fname) + " " + ft.display);
    } while (MatchOp(","));
    ExpectOp(")");
    type = LogicalType::Struct(names, types);
    display = "STRUCT(" + JoinStrings(disp, ", ") + ")";
  } else if (lname == "map") {
    ExpectOp("(");
    TypeDisplay k = ParseType(); ExpectOp(","); TypeDisplay v = ParseType(); ExpectOp(")");
    type = LogicalType::Map(k.type, v.type);
    display = "MAP(" + k.display + ", " + v.display + ")";
  } else if (lname == "union") {
    ExpectOp("(");
    std::vector<std::string> names; std::vector<LogicalType> types; std::vector<std::string> disp;
    do {
      std::string fname = ParseColumnAlias();
      TypeDisplay ft = ParseType();
      names.push_back(fname); types.push_back(ft.type); disp.push_back(QuoteIdentifierIfNeeded(fname) + " " + ft.display);
    } while (MatchOp(","));
    ExpectOp(")");
    type = LogicalType::Union(names, types);
    display = "UNION(" + JoinStrings(disp, ", ") + ")";
  } else if (lname == "enum") {
    ExpectOp("(");
    std::vector<std::string> vals;
    if (!PeekOp(")")) {
      do { vals.push_back(ParseStringLiteral()); } while (MatchOp(","));
    }
    ExpectOp(")");
    type = LogicalType::Enum(vals);
    std::string r = "\"ENUM\"(";
    for (size_t i = 0; i < vals.size(); i++) { if (i) r += ", "; r += EscapeSQLString(vals[i]); }
    display = r + ")";
  } else if (!quoted && kParseTimeTypes.count(lname)) {
    auto &entry = kParseTimeTypes.at(lname);
    type = LogicalType(entry.first);
    display = entry.second;
    // modifiers
    if (PeekOp("(")) {
      Next();
      std::vector<std::string> mods;
      do {
        const Token &m = Peek();
        if (m.type == TokenType::NUMBER) { mods.push_back(m.text); Next(); }
        else SyntaxErrorHere();
      } while (MatchOp(","));
      ExpectOp(")");
      if (type.id == TypeId::DECIMAL) {
        int w = atoi(mods[0].c_str());
        int s = mods.size() > 1 ? atoi(mods[1].c_str()) : 0;
        if (w < 1 || w > 38) { ParserException e("Width must be between 1 and 38!"); e.position = t.pos; throw e; }
        if (s > w) { ParserException e("Scale cannot be bigger than width"); e.position = t.pos; throw e; }
        type = LogicalType::Decimal(w, s);
        display = "DECIMAL(" + mods[0] + (mods.size() > 1 ? ", " + mods[1] : "") + ")";
      } else if (type.id == TypeId::VARCHAR) {
        display = "VARCHAR(" + mods[0] + ")";
      } else if (type.id == TypeId::BIT) {
        display = "BIT(" + mods[0] + ")";
      } else if (type.id == TypeId::FLOAT) {
        int p = atoi(mods[0].c_str());
        if (p > 24) { type = LogicalType(TypeId::DOUBLE); display = "\"DOUBLE\""; }
      }
    } else {
      if (type.id == TypeId::DECIMAL) type = LogicalType::Decimal(18, 3);
      if (lname == "char" || lname == "character") display = "VARCHAR(1)";
      if (type.id == TypeId::BIT) display = "BIT(1)";
    }
  } else if (!quoted && kDeferredTypes.count(lname)) {
    auto &entry = kDeferredTypes.at(lname);
    type = LogicalType(entry.first);
    display = "\"" + std::string(entry.second) + "\"";
    if (PeekOp("(")) {  // ignore modifiers
      Next();
      while (!PeekOp(")") && Peek().type != TokenType::EOI) Next();
      ExpectOp(")");
    }
  } else {
    // user type: resolve later
    type = LogicalType(TypeId::INVALID);
    type.info = std::make_shared<TypeInfo>();
    type.info->alias = quoted ? name : name;
    display = "\"" + name + "\"";
    if (PeekOp("(")) {
      Next();
      std::vector<std::string> mods;
      while (!PeekOp(")") && Peek().type != TokenType::EOI) { mods.push_back(Peek().text); Next(); }
      ExpectOp(")");
    }
  }
  // array suffixes
  while (PeekOp("[")) {
    Next();
    if (PeekOp("]")) { Next(); type = LogicalType::List(type); display += "[]"; }
    else {
      const Token &n = Peek();
      if (n.type != TokenType::NUMBER) SyntaxErrorHere();
      Next();
      ExpectOp("]");
      type = LogicalType::Array(type, atoll(n.text.c_str()));
      display += "[" + n.text + "]";
    }
  }
  if (MatchKeyword("array")) { type = LogicalType::List(type); display += "[]"; }
  result.type = type;
  result.display = display;
  return result;
}

// ---------------------------------------------------------------- expressions
// precedence levels
enum Prec { P_OR = 1, P_AND = 2, P_NOT = 3, P_IS = 4, P_CMP = 5, P_LIKE = 6, P_OTHER = 7, P_ADD = 8, P_MUL = 9, P_POW = 10, P_UNARY = 11, P_POSTFIX = 12 };

static bool IsComparisonOp(const std::string &op) {
  return op == "=" || op == "==" || op == "<>" || op == "!=" || op == "<" || op == ">" || op == "<=" || op == ">=";
}

ExprPtr Parser::MakeNot(ExprPtr e) {
  // DuckDB simplifies NOT (a = b) into a != b etc.
  if (e->kind == ExprKind::COMPARISON) {
    std::string neg;
    if (e->op == "=") neg = "!="; else if (e->op == "!=") neg = "="; else if (e->op == "<") neg = ">="; else if (e->op == ">") neg = "<=";
    else if (e->op == "<=") neg = ">"; else if (e->op == ">=") neg = "<";
    else if (e->op == "IS DISTINCT FROM") neg = "IS NOT DISTINCT FROM"; else if (e->op == "IS NOT DISTINCT FROM") neg = "IS DISTINCT FROM";
    if (!neg.empty()) { e->op = neg; return e; }
  }
  if (e->kind == ExprKind::OPERATOR) {
    if (e->op == "IS NULL") { e->op = "IS NOT NULL"; return e; }
    if (e->op == "IS NOT NULL") { e->op = "IS NULL"; return e; }
    if (e->op == "IN") { e->op = "NOT IN"; return e; }
    if (e->op == "NOT IN") { e->op = "IN"; return e; }
    if (e->op == "NOT") { return std::move(e->children[0]); }
  }
  if (e->kind == ExprKind::CONSTANT && e->value.type.id == TypeId::BOOLEAN && !e->value.is_null) {
    // keep as NOT for display fidelity
  }
  return Expr::Operator("NOT", [&]{ std::vector<ExprPtr> v; v.push_back(std::move(e)); return v; }());
}

std::vector<ExprPtr> Parser::ParseExpressionList() {
  std::vector<ExprPtr> list;
  do { list.push_back(ParseExpression()); } while (MatchOp(","));
  return list;
}

ExprPtr Parser::ParseExpression(int min_prec) {
  ExprPtr left = ParseUnary();
  while (true) {
    const Token &t = Peek();
    int64_t pos = t.pos;
    // keyword operators
    if (t.type == TokenType::IDENT) {
      std::string kw = ToLower(t.text);
      if (kw == "or") {
        if (min_prec > P_OR) break;
        Next();
        ExprPtr right = ParseExpression(P_OR + 1);
        left = Expr::Conjunction("OR", std::move(left), std::move(right));
        continue;
      }
      if (kw == "and") {
        if (min_prec > P_AND) break;
        Next();
        ExprPtr right = ParseExpression(P_AND + 1);
        left = Expr::Conjunction("AND", std::move(left), std::move(right));
        continue;
      }
      if (kw == "is") {
        if (min_prec > P_IS) break;
        Next();
        bool negate = MatchKeyword("not");
        if (MatchKeyword("null")) {
          std::vector<ExprPtr> c; c.push_back(std::move(left));
          left = Expr::Operator(negate ? "IS NOT NULL" : "IS NULL", std::move(c));
        } else if (MatchKeyword("distinct")) {
          ExpectKeyword("from");
          ExprPtr right = ParseExpression(P_IS + 1);
          left = Expr::Comparison(negate ? "IS NOT DISTINCT FROM" : "IS DISTINCT FROM", std::move(left), std::move(right));
        } else if (PeekKeyword("true") || PeekKeyword("false")) {
          bool val = PeekKeyword("true");
          Next();
          // x IS TRUE => CAST(x AS BOOLEAN) IS NOT DISTINCT FROM true
          ExprPtr casted = Expr::Cast(std::move(left), LogicalType(TypeId::BOOLEAN));
          ExprPtr cst = Expr::Constant(Value::Boolean(val));
          cst->position = -2;  // marker: print as true/false literally
          left = Expr::Comparison(negate ? "IS DISTINCT FROM" : "IS NOT DISTINCT FROM", std::move(casted), std::move(cst));
        } else if (MatchKeyword("unknown")) {
          std::vector<ExprPtr> c; c.push_back(std::move(left));
          left = Expr::Operator(negate ? "IS NOT NULL" : "IS NULL", std::move(c));
        } else SyntaxErrorHere();
        left->position = pos;
        continue;
      }
      if (kw == "isnull" || kw == "notnull") {
        if (min_prec > P_IS) break;
        Next();
        std::vector<ExprPtr> c; c.push_back(std::move(left));
        left = Expr::Operator(kw == "isnull" ? "IS NULL" : "IS NOT NULL", std::move(c));
        continue;
      }
      bool negate = false;
      size_t save = idx;
      if (kw == "not") {
        // NOT BETWEEN / NOT IN / NOT LIKE ...
        const Token &n = Peek(1);
        if (n.type == TokenType::IDENT) {
          std::string nk = ToLower(n.text);
          if (nk == "between" || nk == "in" || nk == "like" || nk == "ilike" || nk == "similar" || nk == "glob") {
            if (min_prec > P_LIKE) break;
            Next();
            negate = true;
            kw = nk;
          } else break;
        } else break;
      }
      if (kw == "between") {
        if (min_prec > P_LIKE) break;
        Next();
        bool symmetric = false;
        if (MatchKeyword("symmetric")) symmetric = true; else MatchKeyword("asymmetric");
        ExprPtr lo = ParseExpression(P_LIKE + 1);
        ExpectKeyword("and");
        ExprPtr hi = ParseExpression(P_LIKE + 1);
        auto e = std::make_unique<Expr>(ExprKind::BETWEEN);
        e->children.push_back(std::move(left)); e->children.push_back(std::move(lo)); e->children.push_back(std::move(hi));
        e->position = pos;
        (void)symmetric;
        left = negate ? MakeNot(std::move(e)) : std::move(e);
        continue;
      }
      if (kw == "in") {
        if (min_prec > P_LIKE) break;
        Next();
        ExpectOp("(");
        if (IsSelectStart()) {
          auto sq = std::make_unique<Expr>(ExprKind::SUBQUERY);
          sq->subquery = ParseSelectStatement();
          sq->subquery_type = SubqueryType::ANY;
          sq->comparison_type = "=";
          sq->children.push_back(std::move(left));
          ExpectOp(")");
          sq->position = pos;
          left = negate ? MakeNot(std::move(sq)) : std::move(sq);
        } else {
          std::vector<ExprPtr> c;
          c.push_back(std::move(left));
          if (!PeekOp(")")) {
            auto list = ParseExpressionList();
            for (auto &x : list) c.push_back(std::move(x));
          }
          ExpectOp(")");
          left = Expr::Operator(negate ? "NOT IN" : "IN", std::move(c));
          left->position = pos;
        }
        continue;
      }
      if (kw == "like" || kw == "ilike" || kw == "glob" || kw == "similar") {
        if (min_prec > P_LIKE) break;
        Next();
        if (kw == "similar") ExpectKeyword("to");
        ExprPtr right = ParseExpression(P_LIKE + 1);
        ExprPtr escape;
        if (MatchKeyword("escape")) escape = ParseExpression(P_LIKE + 1);
        ExprPtr e;
        if (kw == "similar") {
          std::vector<ExprPtr> args; args.push_back(std::move(left)); args.push_back(std::move(right));
          if (escape) args.push_back(std::move(escape));
          e = Expr::Function("regexp_full_match", std::move(args));
          e->position = pos;
          left = negate ? MakeNot(std::move(e)) : std::move(e);
        } else if (escape) {
          std::vector<ExprPtr> args; args.push_back(std::move(left)); args.push_back(std::move(right)); args.push_back(std::move(escape));
          std::string fname = kw == "like" ? (negate ? "not_like_escape" : "like_escape") : (negate ? "not_ilike_escape" : "ilike_escape");
          e = Expr::Function(fname, std::move(args));
          e->schema = "main";
          e->position = pos;
          left = std::move(e);
        } else {
          std::string op = kw == "like" ? (negate ? "!~~" : "~~") : kw == "ilike" ? (negate ? "!~~*" : "~~*") : (negate ? "!~~~" : "~~~");
          std::vector<ExprPtr> args; args.push_back(std::move(left)); args.push_back(std::move(right));
          e = Expr::Function(op, std::move(args));
          e->is_operator = true;
          e->position = pos;
          left = std::move(e);
        }
        continue;
      }
      if (kw == "collate") {
        if (min_prec > P_POSTFIX) break;
        Next();
        auto e = std::make_unique<Expr>(ExprKind::COLLATE);
        e->collation = ParseColumnAlias();
        e->children.push_back(std::move(left));
        left = std::move(e);
        continue;
      }
      if (kw == "at") {
        // AT TIME ZONE
        if (min_prec > P_OTHER) break;
        Next();
        ExpectKeyword("time"); ExpectKeyword("zone");
        ExprPtr tz = ParseExpression(P_OTHER + 1);
        std::vector<ExprPtr> args; args.push_back(std::move(tz)); args.push_back(std::move(left));
        left = Expr::Function("timezone", std::move(args));
        left->position = pos;
        continue;
      }
      idx = save;
      break;
    }
    if (t.type != TokenType::OPERATOR) break;
    std::string op = t.text;
    if (op == "::") {
      Next();
      TypeDisplay td = ParseType();
      left = Expr::Cast(std::move(left), td.type);
      left->op = td.display;
      left->position = pos;
      continue;
    }
    if (op == "[" ) {
      // index / slice
      Next();
      ExprPtr lo, hi;
      bool is_slice = false;
      if (PeekOp(":")) { is_slice = true; }
      else lo = ParseExpression();
      if (MatchOp(":")) {
        is_slice = true;
        if (!PeekOp("]") && !PeekOp(":")) hi = ParseExpression();
        if (MatchOp(":")) { ParseExpression(); /* step: ignored */ }
      }
      ExpectOp("]");
      std::vector<ExprPtr> args;
      args.push_back(std::move(left));
      if (is_slice) {
        if (!lo) { lo = Expr::Constant(Value::BigInt(1)); lo->position = -3; }
        if (!hi) { hi = Expr::Constant(Value::BigInt(-1)); hi->position = -3; }
        args.push_back(std::move(lo)); args.push_back(std::move(hi));
        left = Expr::Function("array_slice", std::move(args));
      } else {
        args.push_back(std::move(lo));
        left = Expr::Function("array_extract", std::move(args));
      }
      left->is_operator = true;
      left->position = pos;
      continue;
    }
    if (op == ".") {
      // struct field access or function call on expr (dot syntax)
      Next();
      const Token &n = Peek();
      std::string fname;
      if (n.type == TokenType::IDENT) { fname = ToLower(n.text); Next(); }
      else if (n.type == TokenType::QUOTED_IDENT) { fname = n.text; Next(); }
      else SyntaxErrorHere();
      if (PeekOp("(")) {
        // method-call syntax: expr.func(args) => func(expr, args)
        Next();
        std::vector<ExprPtr> args;
        args.push_back(std::move(left));
        if (!PeekOp(")")) {
          auto rest = ParseExpressionList();
          for (auto &a : rest) args.push_back(std::move(a));
        }
        ExpectOp(")");
        left = Expr::Function(fname, std::move(args));
        left->position = pos;
      } else {
        std::vector<ExprPtr> args;
        args.push_back(std::move(left));
        args.push_back(Expr::Constant(Value::Varchar(fname)));
        left = Expr::Function("struct_extract", std::move(args));
        left->is_operator = true;
        left->op = "struct_extract";
        left->position = pos;
      }
      continue;
    }
    int prec;
    bool right_assoc = false;
    if (IsComparisonOp(op)) prec = P_CMP;
    else if (op == "+" || op == "-") prec = P_ADD;
    else if (op == "*" || op == "/" || op == "%" || op == "//") prec = P_MUL;
    else if (op == "^" || op == "**") prec = P_POW;
    else if (op == "->") {
      // lambda arrow (deprecated) when left is a column ref or row of refs
      if (left->kind == ExprKind::COLUMN_REF && left->names.size() == 1) {
        if (min_prec > P_OTHER) break;
        Next();
        std::vector<std::string> params = {left->names[0]};
        left = ParseLambdaBody(params, pos);
        left->op = "->";
        continue;
      }
      if (left->kind == ExprKind::FUNCTION && left->op == "row" && left->distinct == false) {
        bool all_refs = true;
        std::vector<std::string> params;
        for (auto &c : left->children) { if (c->kind != ExprKind::COLUMN_REF || c->names.size() != 1) all_refs = false; else params.push_back(c->names[0]); }
        if (all_refs) {
          if (min_prec > P_OTHER) break;
          Next();
          left = ParseLambdaBody(params, pos);
          left->op = "->";
          continue;
        }
      }
      prec = P_OTHER;
    }
    else if (op == "||" || op == "&" || op == "|" || op == "<<" || op == ">>" || op == "#" || op == "~~" || op == "!~~" || op == "~~*" || op == "!~~*" || op == "~~~" || op == "~" || op == "!~" || op == "~*" || op == "@>" || op == "<@" || op == "&&" || op == "->>" || op == "<->") prec = P_OTHER;
    else break;
    if (min_prec > prec) break;
    Next();
    if (IsComparisonOp(op) && (PeekKeyword("any") || PeekKeyword("all") || PeekKeyword("some"))) {
      bool is_all = PeekKeyword("all");
      Next();
      ExpectOp("(");
      std::string cmp = op == "<>" ? "!=" : (op == "==" ? "=" : op);
      ExprPtr result;
      if (IsSelectStart()) {
        auto sq = std::make_unique<Expr>(ExprKind::SUBQUERY);
        sq->subquery = ParseSelectStatement();
        sq->subquery_type = is_all ? SubqueryType::ALL : SubqueryType::ANY;
        sq->comparison_type = cmp;
        sq->children.push_back(std::move(left));
        ExpectOp(")");
        result = std::move(sq);
      } else {
        // x = ANY(list) => x = ANY(SELECT unnest(list))
        ExprPtr list = ParseExpression();
        ExpectOp(")");
        auto sq = std::make_unique<Expr>(ExprKind::SUBQUERY);
        auto sel = std::make_unique<SelectStatement>();
        auto node = std::make_unique<QueryNode>(QueryNodeKind::SELECT);
        std::vector<ExprPtr> uargs; uargs.push_back(std::move(list));
        node->select_list.push_back(Expr::Function("unnest", std::move(uargs)));
        sel->node = std::move(node);
        sq->subquery = std::move(sel);
        sq->subquery_type = is_all ? SubqueryType::ALL : SubqueryType::ANY;
        sq->comparison_type = cmp;
        sq->children.push_back(std::move(left));
        result = std::move(sq);
      }
      result->position = pos;
      left = std::move(result);
      continue;
    }
    ExprPtr right = ParseExpression(right_assoc ? prec : prec + 1);
    if (IsComparisonOp(op)) {
      if (op == "<>") op = "!=";
      if (op == "==") op = "=";
      left = Expr::Comparison(op, std::move(left), std::move(right));
      left->position = pos;
      // non-associative: a < b = c is a syntax error
      if (Peek().type == TokenType::OPERATOR && IsComparisonOp(Peek().text)) SyntaxErrorHere();
      continue;
    }
    std::vector<ExprPtr> args;
    args.push_back(std::move(left));
    args.push_back(std::move(right));
    if (op == "~~" || op == "!~~" || op == "~~*" || op == "!~~*" || op == "~~~" || op == "~" || op == "!~" || op == "~*" || op == "@>" || op == "<@" || op == "&&" || op == "->>" || op == "<->") {
      left = Expr::Function(op, std::move(args));
      left->is_operator = true;
    } else {
      left = Expr::Operator(op, std::move(args));
    }
    left->position = pos;
  }
  return left;
}

ExprPtr Parser::ParseLambdaBody(std::vector<std::string> params, int64_t pos) {
  auto lam = std::make_unique<Expr>(ExprKind::LAMBDA);
  lam->lambda_params = params;
  lam->children.push_back(ParseExpression(P_OR));
  lam->position = pos;
  return lam;
}

ExprPtr Parser::ParseUnary() {
  const Token &t = Peek();
  int64_t pos = t.pos;
  if (t.type == TokenType::IDENT && IEquals(t.text, "not")) {
    Next();
    ExprPtr e = ParseExpression(P_NOT);
    e = MakeNot(std::move(e));
    e->position = pos;
    return e;
  }
  if (t.type == TokenType::OPERATOR && (t.text == "-" || t.text == "+" || t.text == "~")) {
    std::string op = t.text;
    Next();
    ExprPtr e = ParseExpression(P_UNARY);
    if (op == "-") {
      if (e->kind == ExprKind::CONSTANT && e->value.type.IsNumeric() && !e->value.is_null) {
        Value &v = e->value;
        if (v.type.IsFloating()) v.dval = -v.dval;
        else {
          v.ival = -v.ival;
          // -2147483648 fits in INTEGER
          if (v.type.id == TypeId::BIGINT && v.ival >= INT32_MIN) v.type = LogicalType(TypeId::INTEGER);
          if (v.type.id == TypeId::HUGEINT && v.ival >= INT64_MIN) v.type = LogicalType(TypeId::BIGINT);
        }
        e->position = pos;
        return e;
      }
      std::vector<ExprPtr> args; args.push_back(std::move(e));
      auto r = Expr::Operator("-", std::move(args));
      r->position = pos;
      return r;
    }
    if (op == "+") {
      std::vector<ExprPtr> args; args.push_back(std::move(e));
      auto r = Expr::Operator("+", std::move(args));
      r->position = pos;
      return r;
    }
    std::vector<ExprPtr> args; args.push_back(std::move(e));
    auto r = Expr::Operator("~", std::move(args));
    r->position = pos;
    return r;
  }
  if (t.type == TokenType::OPERATOR && t.text == "@") {
    Next();
    ExprPtr e = ParseExpression(P_UNARY);
    std::vector<ExprPtr> args; args.push_back(std::move(e));
    auto r = Expr::Operator("@", std::move(args));
    r->position = pos;
    return r;
  }
  ExprPtr prim = ParsePrimary();
  return prim;
}

bool Parser::IsSelectStart(size_t ahead) {
  const Token &t = Peek(ahead);
  if (t.type != TokenType::IDENT) {
    if (t.Is("(")) return IsSelectStart(ahead + 1);
    return false;
  }
  return IEquals(t.text, "select") || IEquals(t.text, "with") || IEquals(t.text, "values") || IEquals(t.text, "from") ||
         IEquals(t.text, "pivot") || IEquals(t.text, "unpivot") || IEquals(t.text, "show") || IEquals(t.text, "describe") || IEquals(t.text, "summarize");
}

ExprPtr Parser::ParseSubqueryExpr(SubqueryType type) {
  auto sq = std::make_unique<Expr>(ExprKind::SUBQUERY);
  sq->subquery = ParseSelectStatement();
  sq->subquery_type = type;
  return sq;
}

ExprPtr Parser::ParseTypedLiteral(const std::string &tname) {
  // DATE '...', TIMESTAMP '...', INTERVAL ..., etc.
  const Token &t = Peek();
  int64_t pos = t.pos;
  std::string s = ParseStringLiteral();
  std::string ln = ToLower(tname);
  if (ln == "interval") {
    // INTERVAL 'str' [unit]
    auto cst = Expr::Constant(Value::StringLiteral(s));
    cst->position = pos;
    return ParseInterval(std::move(cst));
  }
  LogicalType type;
  std::string display;
  if (kParseTimeTypes.count(ln)) { type = LogicalType(kParseTimeTypes.at(ln).first); display = kParseTimeTypes.at(ln).second; }
  else if (kDeferredTypes.count(ln)) { type = LogicalType(kDeferredTypes.at(ln).first); display = "\"" + std::string(kDeferredTypes.at(ln).second) + "\""; }
  else { type = LogicalType(TypeId::INVALID); type.info = std::make_shared<TypeInfo>(); type.info->alias = tname; display = "\"" + tname + "\""; }
  if (ln == "timestamp" || ln == "time") {
    // could be TIMESTAMP WITH TIME ZONE 'x' handled before string? rare
  }
  auto cst = Expr::Constant(Value::StringLiteral(s));
  cst->position = pos;
  auto e = Expr::Cast(std::move(cst), type);
  e->op = display;
  e->position = pos;
  return e;
}

ExprPtr Parser::ParseInterval(ExprPtr value) {
  // value followed by optional unit keyword(s)
  const Token &t = Peek();
  static const std::set<std::string> units = {"year", "years", "month", "months", "day", "days", "hour", "hours", "minute", "minutes",
    "second", "seconds", "millisecond", "milliseconds", "microsecond", "microseconds", "week", "weeks", "decade", "decades", "century", "centuries",
    "millennium", "millennia", "quarter", "quarters"};
  if (t.type == TokenType::IDENT && units.count(ToLower(t.text))) {
    std::string unit = ToLower(t.text);
    Next();
    if (unit == "millennium") unit = "millennia";
    // INTERVAL 1 DAY -> to_days(CAST(trunc(CAST(1 AS DOUBLE)) AS INTEGER)) ; string literal: to_days(CAST(trunc(CAST('1' AS DOUBLE)) AS INTEGER))
    std::string fname;
    if (unit == "year" || unit == "years") fname = "to_years";
    else if (unit == "month" || unit == "months") fname = "to_months";
    else if (unit == "day" || unit == "days") fname = "to_days";
    else if (unit == "hour" || unit == "hours") fname = "to_hours";
    else if (unit == "minute" || unit == "minutes") fname = "to_minutes";
    else if (unit == "second" || unit == "seconds") fname = "to_seconds";
    else if (unit == "millisecond" || unit == "milliseconds") fname = "to_milliseconds";
    else if (unit == "microsecond" || unit == "microseconds") fname = "to_microseconds";
    else if (unit == "week" || unit == "weeks") fname = "to_weeks";
    else if (unit == "decade" || unit == "decades") fname = "to_decades";
    else if (unit == "century" || unit == "centuries") fname = "to_centuries";
    else if (unit == "millennia") fname = "to_millennia";
    else if (unit == "quarter" || unit == "quarters") fname = "to_quarters";
    ExprPtr arg;
    bool is_time_unit = (fname == "to_seconds" || fname == "to_milliseconds" || fname == "to_microseconds");
    if (is_time_unit) {
      // to_seconds(CAST(x AS DOUBLE))
      ExprPtr casted = Expr::Cast(std::move(value), LogicalType(TypeId::DOUBLE));
      casted->op = "\"DOUBLE\"";
      arg = std::move(casted);
    } else if (fname == "to_hours" || fname == "to_minutes") {
      ExprPtr casted = Expr::Cast(std::move(value), LogicalType(TypeId::BIGINT));
      casted->op = "BIGINT";
      arg = std::move(casted);
    } else {
      ExprPtr casted = Expr::Cast(std::move(value), LogicalType(TypeId::DOUBLE));
      casted->op = "\"DOUBLE\"";
      std::vector<ExprPtr> targs; targs.push_back(std::move(casted));
      ExprPtr tr = Expr::Function("trunc", std::move(targs));
      ExprPtr c2 = Expr::Cast(std::move(tr), LogicalType(TypeId::INTEGER));
      c2->op = "INTEGER";
      arg = std::move(c2);
    }
    std::vector<ExprPtr> args; args.push_back(std::move(arg));
    auto e = Expr::Function(fname, std::move(args));
    return e;
  }
  // plain INTERVAL 'string'
  auto e = Expr::Cast(std::move(value), LogicalType(TypeId::INTERVAL));
  e->op = "INTERVAL";
  return e;
}

ExprPtr Parser::ParseCaseExpression() {
  auto e = std::make_unique<Expr>(ExprKind::CASE);
  ExprPtr operand;
  if (!PeekKeyword("when")) operand = ParseExpression();
  while (MatchKeyword("when")) {
    Expr::CaseCheck cc;
    ExprPtr cond = ParseExpression();
    if (operand) cond = Expr::Comparison("=", operand->Copy(), std::move(cond));
    ExpectKeyword("then");
    cc.when = std::move(cond);
    cc.then = ParseExpression();
    e->case_checks.push_back(std::move(cc));
  }
  if (MatchKeyword("else")) e->else_expr = ParseExpression();
  else e->else_expr = Expr::Constant(Value());
  ExpectKeyword("end");
  return e;
}

ExprPtr Parser::ParseCastExpression(bool try_cast) {
  ExpectOp("(");
  ExprPtr child = ParseExpression();
  ExpectKeyword("as");
  TypeDisplay td = ParseType();
  ExpectOp(")");
  auto e = Expr::Cast(std::move(child), td.type, try_cast);
  e->op = td.display;
  return e;
}

ExprPtr Parser::ParseStarExpression(const std::string &relation) {
  auto e = std::make_unique<Expr>(ExprKind::STAR);
  e->relation_name = relation;
  while (true) {
    if (MatchKeyword("exclude")) {
      bool paren = MatchOp("(");
      do {
        auto names = ParseQualifiedName();
        e->exclude_list.push_back(JoinStrings(names, "."));
      } while (paren && MatchOp(","));
      if (paren) ExpectOp(")");
    } else if (MatchKeyword("replace")) {
      bool paren = MatchOp("(");
      do {
        ExprPtr ex = ParseExpression();
        ExpectKeyword("as");
        std::string name = ParseColumnAlias();
        e->replace_list.push_back({name, std::move(ex)});
      } while (paren && MatchOp(","));
      if (paren) ExpectOp(")");
    } else if (MatchKeyword("rename")) {
      bool paren = MatchOp("(");
      do {
        std::string name = ParseColumnAlias();
        ExpectKeyword("as");
        std::string newname = ParseColumnAlias();
        e->rename_list.push_back({name, Expr::Constant(Value::Varchar(newname))});
      } while (paren && MatchOp(","));
      if (paren) ExpectOp(")");
    } else break;
  }
  return e;
}

std::unique_ptr<WindowSpec> Parser::ParseWindowSpec() {
  auto w = std::make_unique<WindowSpec>();
  if (PeekIdentifier() && !PeekKeyword("partition") && !PeekKeyword("order") && !PeekKeyword("rows") && !PeekKeyword("range") && !PeekKeyword("groups")) {
    w->name = ParseIdentifier();
  }
  if (MatchKeyword("partition")) {
    ExpectKeyword("by");
    w->partitions = ParseExpressionList();
  }
  if (MatchKeyword("order")) {
    ExpectKeyword("by");
    bool all = false;
    ParseOrderBy(w->orders, all);
  }
  ParseWindowFrame(w->frame);
  return w;
}

void Parser::ParseWindowFrame(WindowFrame &frame) {
  if (PeekKeyword("rows") || PeekKeyword("range") || PeekKeyword("groups")) {
    frame.specified = true;
    frame.rows = PeekKeyword("rows");
    frame.groups = PeekKeyword("groups");
    Next();
    auto parse_bound = [&](WindowFrame::Bound &b, ExprPtr &ex) {
      if (MatchKeyword("unbounded")) {
        if (MatchKeyword("preceding")) b = WindowFrame::UNBOUNDED_PRECEDING;
        else { ExpectKeyword("following"); b = WindowFrame::UNBOUNDED_FOLLOWING; }
      } else if (MatchKeyword("current")) {
        ExpectKeyword("row");
        b = WindowFrame::CURRENT_ROW;
      } else {
        ex = ParseExpression();
        if (MatchKeyword("preceding")) b = WindowFrame::EXPR_PRECEDING;
        else { ExpectKeyword("following"); b = WindowFrame::EXPR_FOLLOWING; }
      }
    };
    if (MatchKeyword("between")) {
      parse_bound(frame.start, frame.start_expr);
      ExpectKeyword("and");
      parse_bound(frame.end, frame.end_expr);
    } else {
      parse_bound(frame.start, frame.start_expr);
      frame.end = WindowFrame::CURRENT_ROW;
    }
    if (MatchKeyword("exclude")) {
      if (MatchKeyword("current")) { ExpectKeyword("row"); frame.exclude = WindowFrame::EXCLUDE_CURRENT_ROW; }
      else if (MatchKeyword("group")) frame.exclude = WindowFrame::EXCLUDE_GROUP;
      else if (MatchKeyword("ties")) frame.exclude = WindowFrame::EXCLUDE_TIES;
      else if (MatchKeyword("no")) { ExpectKeyword("others"); }
      else SyntaxErrorHere();
    }
  }
}

ExprPtr Parser::ParseFunctionCall(std::vector<std::string> names, int64_t pos) {
  // '(' already consumed? no: we are at '('
  ExpectOp("(");
  auto e = std::make_unique<Expr>(ExprKind::FUNCTION);
  e->position = pos;
  std::string fname = names.back();
  if (names.size() == 2) e->schema = names[0];
  else if (names.size() == 3) { e->schema = names[1]; }
  e->op = fname;
  std::string lname = ToLower(fname);
  if (MatchKeyword("distinct")) e->distinct = true;
  else MatchKeyword("all");
  if (PeekOp("*") && Peek(1).Is(")")) {
    Next();
    // count(*)
    if (lname == "count") { e->op = "count_star"; }
    else { auto star = std::make_unique<Expr>(ExprKind::STAR); e->children.push_back(std::move(star)); }
  } else if (!PeekOp(")")) {
    do {
      // named argument: name := expr  or name => expr
      if (PeekIdentifier() && (Peek(1).Is(":=") || Peek(1).Is("=>"))) {
        std::string pname = ParseColumnAlias();
        Next();
        ExprPtr arg = ParseExpression();
        arg->alias = pname;
        e->children.push_back(std::move(arg));
        continue;
      }
      ExprPtr arg = ParseExpression();
      e->children.push_back(std::move(arg));
    } while (MatchOp(","));
    if (MatchKeyword("order")) {
      ExpectKeyword("by");
      bool all = false;
      ParseOrderBy(e->order_bys, all);
    }
    if (MatchKeyword("ignore")) { ExpectKeyword("nulls"); e->ignore_nulls = true; }
    else if (MatchKeyword("respect")) { ExpectKeyword("nulls"); }
  }
  ExpectOp(")");
  // WITHIN GROUP (ORDER BY ...)
  if (MatchKeyword("within")) {
    ExpectKeyword("group");
    ExpectOp("(");
    ExpectKeyword("order"); ExpectKeyword("by");
    bool all = false;
    std::vector<OrderByNode> orders;
    ParseOrderBy(orders, all);
    ExpectOp(")");
    // quantile_cont(0.5) WITHIN GROUP (ORDER BY x) => quantile_cont(x, 0.5)
    std::vector<ExprPtr> newargs;
    newargs.push_back(std::move(orders[0].expr));
    for (auto &c : e->children) newargs.push_back(std::move(c));
    e->children = std::move(newargs);
    if (lname == "percentile_cont") e->op = "quantile_cont";
    else if (lname == "percentile_disc") e->op = "quantile_disc";
    else if (lname == "mode") e->op = "mode";
  }
  if (MatchKeyword("filter")) {
    ExpectOp("(");
    ExpectKeyword("where");
    e->filter = ParseExpression();
    ExpectOp(")");
  }
  if (MatchKeyword("ignore")) { ExpectKeyword("nulls"); e->ignore_nulls = true; }
  else if (MatchKeyword("respect")) { ExpectKeyword("nulls"); }
  if (MatchKeyword("export_state")) e->export_state = true;
  if (MatchKeyword("over")) {
    auto w = std::make_unique<Expr>(ExprKind::WINDOW);
    w->op = e->op;
    w->schema = e->schema;
    w->children = std::move(e->children);
    w->distinct = e->distinct;
    w->filter = std::move(e->filter);
    w->order_bys = std::move(e->order_bys);
    w->ignore_nulls = e->ignore_nulls;
    w->position = pos;
    if (MatchOp("(")) {
      w->window = ParseWindowSpec();
      ExpectOp(")");
    } else {
      w->window = std::make_unique<WindowSpec>();
      w->window->name = ParseIdentifier();
    }
    return w;
  }
  return e;
}

ExprPtr Parser::ParseParenExpression() {
  // '(' consumed
  if (IsSelectStart()) {
    auto sq = ParseSubqueryExpr(SubqueryType::SCALAR);
    ExpectOp(")");
    return sq;
  }
  ExprPtr e = ParseExpression();
  if (PeekOp(",")) {
    // row constructor (a, b)
    std::vector<ExprPtr> args;
    args.push_back(std::move(e));
    while (MatchOp(",")) args.push_back(ParseExpression());
    ExpectOp(")");
    auto r = Expr::Function("row", std::move(args));
    r->schema = "main";
    return r;
  }
  ExpectOp(")");
  // mark parenthesized (for display of e.g. (SELECT ...))
  return e;
}

ExprPtr Parser::ParsePrimary() {
  const Token &t = Peek();
  int64_t pos = t.pos;
  ExprPtr result;
  switch (t.type) {
  case TokenType::NUMBER: {
    Next();
    const std::string &txt = t.text;
    Value v;
    if (txt.find_first_of(".eE") != std::string::npos) {
      // decimal or double
      size_t epos = txt.find_first_of("eE");
      if (epos != std::string::npos) {
        double d = strtod(txt.c_str(), nullptr);
        v = Value::Double(d);
      } else {
        // decimal: count digits
        std::string digits;
        size_t dot = txt.find('.');
        std::string ip = txt.substr(0, dot), fp = txt.substr(dot + 1);
        int scale = (int)fp.size();
        int width = (int)(ip.size() + fp.size());
        if (width == 0) width = 1;
        if (width > 38) {
          v = Value::Double(strtod(txt.c_str(), nullptr));
        } else {
          int128_t val = 0;
          for (char c : ip + fp) val = val * 10 + (c - '0');
          if (width < scale) width = scale;
          if (width == 0) width = 1;
          v = Value::Decimal(val, width, scale);
        }
      }
    } else {
      int128_t iv;
      if (!ParseInt128(txt, iv)) {
        v = Value::Double(strtod(txt.c_str(), nullptr));
      } else if (iv <= INT32_MAX) v = Value::Integer((int32_t)iv);
      else if (iv <= INT64_MAX) v = Value::BigInt((int64_t)iv);
      else v = Value::HugeInt(iv);
    }
    result = Expr::Constant(v);
    result->position = pos;
    return result;
  }
  case TokenType::STRING: case TokenType::ESCAPE_STRING: case TokenType::DOLLAR_STRING: {
    Next();
    result = Expr::Constant(Value::StringLiteral(t.text));
    result->position = pos;
    return result;
  }
  case TokenType::HEX_STRING: {
    Next();
    std::string bytes;
    std::string hex = t.text;
    if (hex.size() % 2) hex = "0" + hex;
    for (size_t i = 0; i + 1 < hex.size(); i += 2) bytes += (char)strtol(hex.substr(i, 2).c_str(), nullptr, 16);
    result = Expr::Constant(Value::Blob(bytes));
    result->position = pos;
    return result;
  }
  case TokenType::BIT_STRING: {
    Next();
    Value v(TypeId::BIT); v.is_null = false; v.str = t.text;
    result = Expr::Constant(v);
    result->position = pos;
    return result;
  }
  case TokenType::PARAM: {
    Next();
    auto e = std::make_unique<Expr>(ExprKind::PARAMETER);
    e->param_name = t.text;
    e->position = pos;
    return e;
  }
  case TokenType::OPERATOR: {
    if (t.text == "(") {
      Next();
      result = ParseParenExpression();
      return result;
    }
    if (t.text == "[") {
      // list literal or list comprehension
      Next();
      std::vector<ExprPtr> items;
      if (!PeekOp("]")) {
        ExprPtr first = ParseExpression();
        if (MatchKeyword("for")) {
          // list comprehension: [expr FOR x IN list IF cond]
          std::vector<std::string> params;
          params.push_back(ParseIdentifier());
          while (MatchOp(",")) params.push_back(ParseIdentifier());
          ExpectKeyword("in");
          ExprPtr list = ParseExpression();
          ExprPtr cond;
          if (MatchKeyword("if")) cond = ParseExpression();
          ExpectOp("]");
          // build list_transform(list_filter(list, lambda), lambda)
          ExprPtr src = std::move(list);
          if (cond) {
            auto lam = std::make_unique<Expr>(ExprKind::LAMBDA);
            lam->lambda_params = params;
            lam->children.push_back(std::move(cond));
            std::vector<ExprPtr> fa; fa.push_back(std::move(src)); fa.push_back(std::move(lam));
            src = Expr::Function("list_filter", std::move(fa));
          }
          auto lam2 = std::make_unique<Expr>(ExprKind::LAMBDA);
          lam2->lambda_params = params;
          lam2->children.push_back(std::move(first));
          std::vector<ExprPtr> ta; ta.push_back(std::move(src)); ta.push_back(std::move(lam2));
          result = Expr::Function("list_transform", std::move(ta));
          result->position = pos;
          result->alias = "";
          result->schema = "comprehension";
          return result;
        }
        items.push_back(std::move(first));
        while (MatchOp(",")) items.push_back(ParseExpression());
      }
      ExpectOp("]");
      result = Expr::Function("list_value", std::move(items));
      result->schema = "main";
      result->position = pos;
      return result;
    }
    if (t.text == "{") {
      Next();
      std::vector<ExprPtr> items;
      if (!PeekOp("}")) {
