std::unique_ptr<Statement> Parser::ParseStatement() {
  const Token &t = Peek();
  if (t.type != TokenType::IDENT && !t.Is("(")) SyntaxErrorHere();
  std::string kw = ToLower(t.text);
  if (t.Is("(")) return ParseSelectStatement();
