    ParseCTEs(ctes, recursive);
    if (PeekKeyword("insert")) return ParseInsert(std::move(ctes));
    if (PeekKeyword("update")) return ParseUpdate(std::move(ctes));
    if (PeekKeyword("delete")) return ParseDelete(std::move(ctes));
    idx = save;
    return ParseSelectStatement();
  }
  if (kw == "create") return ParseCreate();
  if (kw == "drop") return ParseDrop();
  if (kw == "alter") return ParseAlter();
  if (kw == "insert") return ParseInsert({});
  if (kw == "update") return ParseUpdate({});
  if (kw == "delete") return ParseDelete({});
  if (kw == "truncate") {
    Next();
    MatchKeyword("table");
    auto s = std::make_unique<TruncateStatement>();
    auto names = ParseQualifiedName();
    s->table = names.back();
    if (names.size() > 1) s->schema = names[names.size() - 2];
    return s;
  }
  if (kw == "begin" || kw == "start") {
    Next();
    if (kw == "start") ExpectKeyword("transaction"); else { MatchKeyword("transaction"); MatchKeyword("work"); }
    if (MatchKeyword("read")) { if (!MatchKeyword("only")) ExpectKeyword("write"); }
    auto s = std::make_unique<TransactionStatement>();
    s->kind = "BEGIN";
    return s;
  }
  if (kw == "commit" || kw == "end") {
    Next(); MatchKeyword("transaction"); MatchKeyword("work");
    auto s = std::make_unique<TransactionStatement>();
    s->kind = "COMMIT";
    return s;
  }
  if (kw == "rollback" || kw == "abort") {
    Next(); MatchKeyword("transaction"); MatchKeyword("work");
    auto s = std::make_unique<TransactionStatement>();
    s->kind = "ROLLBACK";
    return s;
  }
  if (kw == "copy") return ParseCopy();
  if (kw == "pragma") return ParsePragma();
  if (kw == "set") return ParseSet(false);
  if (kw == "reset") return ParseSet(true);
  if (kw == "show") return ParseShow();
  if (kw == "describe" || kw == "desc") return ParseDescribe();
  if (kw == "summarize") {
    Next();
    auto s = std::make_unique<ShowStatement>();
    s->kind = "SUMMARIZE";
    s->summarize = true;
    if (IsSelectStart()) s->query = ParseSelectStatement();
    else { auto names = ParseQualifiedName(); s->name = JoinStrings(names, "."); }
    return s;
  }
  if (kw == "explain") return ParseExplain();
  if (kw == "attach") return ParseAttach();
  if (kw == "detach") {
    Next();
    MatchKeyword("database");
    auto s = std::make_unique<DetachStatement>();
    if (MatchKeyword("if")) { ExpectKeyword("exists"); s->if_exists = true; }
    s->name = ParseIdentifier();
    return s;
  }
  if (kw == "use") {
    Next();
    auto s = std::make_unique<UseStatement>();
    auto names = ParseQualifiedName();
    s->name = JoinStrings(names, ".");
    return s;
  }
  if (kw == "export") return ParseExport(false);
  if (kw == "import") return ParseExport(true);
  if (kw == "call") return ParseCall();
  if (kw == "prepare") return ParsePrepare();
  if (kw == "execute") return ParseExecute();
  if (kw == "deallocate") {
    Next(); MatchKeyword("prepare");
    auto s = std::make_unique<SimpleStatement>(StatementType::DEALLOCATE);
    s->name = ParseIdentifier();
    return s;
  }
  if (kw == "checkpoint" || kw == "force") {
    Next();
    if (kw == "force") ExpectKeyword("checkpoint");
    auto s = std::make_unique<SimpleStatement>(StatementType::CHECKPOINT);
    if (PeekIdentifier()) s->name = ParseIdentifier();
    return s;
  }
  if (kw == "vacuum") {
    Next();
    auto s = std::make_unique<SimpleStatement>(StatementType::VACUUM);
    MatchKeyword("analyze");
    if (PeekIdentifier()) { auto n = ParseQualifiedName(); s->name = JoinStrings(n, "."); if (MatchOp("(")) { ParseQualifiedName(); while (MatchOp(",")) ParseQualifiedName(); ExpectOp(")"); } }
    return s;
  }
  if (kw == "analyze") {
    Next();
    auto s = std::make_unique<SimpleStatement>(StatementType::ANALYZE);
    if (PeekIdentifier()) { auto n = ParseQualifiedName(); s->name = JoinStrings(n, "."); }
    return s;
  }
  if (kw == "load") {
    Next();
    auto s = std::make_unique<SimpleStatement>(StatementType::LOAD);
    if (Peek().type == TokenType::STRING) s->name = ParseStringLiteral(); else s->name = ParseIdentifier();
    return s;
  }
  if (kw == "install" || kw == "force") {
    Next();
    auto s = std::make_unique<SimpleStatement>(StatementType::INSTALL);
    if (Peek().type == TokenType::STRING) s->name = ParseStringLiteral(); else s->name = ParseIdentifier();
    if (MatchKeyword("from")) { if (Peek().type == TokenType::STRING) ParseStringLiteral(); else ParseIdentifier(); }
    return s;
  }
  if (kw == "comment") return ParseComment();
  if (kw == "update_extensions" ) { Next(); return std::make_unique<SimpleStatement>(StatementType::UPDATE_EXTENSIONS); }
  SyntaxErrorHere();
}

// ---------------------------------------------------------------- SELECT
std::unique_ptr<SelectStatement> Parser::ParseSelectStatement() {
  auto stmt = std::make_unique<SelectStatement>();
  stmt->node = ParseQueryNode();
  return stmt;
}

void Parser::ParseCTEs(std::vector<std::unique_ptr<CTE>> &ctes, bool &recursive) {
  // 'WITH' consumed
  recursive = MatchKeyword("recursive");
  do {
    auto cte = std::make_unique<CTE>();
    cte->name = ParseIdentifier();
    if (MatchOp("(")) {
      do { cte->aliases.push_back(ParseColumnAlias()); } while (MatchOp(","));
      ExpectOp(")");
    }
    if (MatchKeyword("using")) { ExpectKeyword("key"); ExpectOp("("); do { ParseIdentifier(); } while (MatchOp(",")); ExpectOp(")"); }
    ExpectKeyword("as");
    if (MatchKeyword("materialized")) cte->materialized = true;
    else if (MatchKeyword("not")) { ExpectKeyword("materialized"); }
    ExpectOp("(");
    cte->query = ParseSelectStatement();
    ExpectOp(")");
    cte->recursive = recursive;
    ctes.push_back(std::move(cte));
  } while (MatchOp(","));
}

static int SetOpPrec(SetOpType t) {
  switch (t) {
  case SetOpType::INTERSECT: case SetOpType::INTERSECT_ALL: return 2;
  default: return 1;
  }
}

QueryNodePtr Parser::ParseQueryNode(bool allow_setops) {
  std::vector<std::unique_ptr<CTE>> ctes;
  bool recursive = false;
  if (MatchKeyword("with")) ParseCTEs(ctes, recursive);
  // parse set operation chain with precedence (INTERSECT binds tighter)
  std::vector<QueryNodePtr> operands;
  std::vector<SetOpType> ops;
  operands.push_back(ParseQueryNodeNoModifiers());
  while (allow_setops) {
    SetOpType op;
    if (PeekKeyword("union")) {
      Next();
      bool all = MatchKeyword("all");
      if (!all) MatchKeyword("distinct");
      bool by_name = false;
      if (MatchKeyword("by")) { ExpectKeyword("name"); by_name = true; }
      op = by_name ? (all ? SetOpType::UNION_ALL_BY_NAME : SetOpType::UNION_BY_NAME) : (all ? SetOpType::UNION_ALL : SetOpType::UNION);
    } else if (PeekKeyword("except")) {
      Next(); bool all = MatchKeyword("all"); if (!all) MatchKeyword("distinct");
      op = all ? SetOpType::EXCEPT_ALL : SetOpType::EXCEPT;
    } else if (PeekKeyword("intersect")) {
      Next(); bool all = MatchKeyword("all"); if (!all) MatchKeyword("distinct");
      op = all ? SetOpType::INTERSECT_ALL : SetOpType::INTERSECT;
    } else break;
    ops.push_back(op);
    operands.push_back(ParseQueryNodeNoModifiers());
  }
  // build tree: left-assoc with INTERSECT higher precedence
  // first fold INTERSECTs
  std::vector<QueryNodePtr> ops2;
  std::vector<SetOpType> ops2_types;
  ops2.push_back(std::move(operands[0]));
  for (size_t i = 0; i < ops.size(); i++) {
    if (SetOpPrec(ops[i]) == 2) {
      auto n = std::make_unique<QueryNode>(QueryNodeKind::SET_OPERATION);
      n->setop = ops[i];
      n->left = std::move(ops2.back());
      n->right = std::move(operands[i + 1]);
      ops2.back() = std::move(n);
    } else {
      ops2_types.push_back(ops[i]);
      ops2.push_back(std::move(operands[i + 1]));
    }
  }
  QueryNodePtr result = std::move(ops2[0]);
  for (size_t i = 0; i < ops2_types.size(); i++) {
    auto n = std::make_unique<QueryNode>(QueryNodeKind::SET_OPERATION);
    n->setop = ops2_types[i];
    n->left = std::move(result);
    n->right = std::move(ops2[i + 1]);
    result = std::move(n);
  }
  // modifiers at the end (ORDER BY / LIMIT) apply to whole set operation
  if (result->kind == QueryNodeKind::SET_OPERATION || result->orders.empty()) ParseModifiers(*result);
  result->ctes = std::move(ctes);
  result->recursive_ctes = recursive;
  return result;
}

void Parser::ParseOrderBy(std::vector<OrderByNode> &orders, bool &order_by_all) {
  // 'ORDER BY' consumed
  if (PeekKeyword("all") && !Peek(1).Is("(") && !Peek(1).Is(".")) {
    Next();
    order_by_all = true;
    OrderByNode o;
    o.expr = Expr::ColumnRef({"ALL"});
    if (MatchKeyword("asc")) o.type = OrderType::ASC; else if (MatchKeyword("desc")) o.type = OrderType::DESC;
    if (MatchKeyword("nulls")) { if (MatchKeyword("first")) o.null_order = NullOrder::NULLS_FIRST; else { ExpectKeyword("last"); o.null_order = NullOrder::NULLS_LAST; } }
    orders.push_back(std::move(o));
    return;
  }
  do {
    OrderByNode o;
    o.expr = ParseExpression();
    if (MatchKeyword("asc")) o.type = OrderType::ASC;
    else if (MatchKeyword("desc")) o.type = OrderType::DESC;
    if (MatchKeyword("nulls")) {
      if (MatchKeyword("first")) o.null_order = NullOrder::NULLS_FIRST;
      else { ExpectKeyword("last"); o.null_order = NullOrder::NULLS_LAST; }
    }
    orders.push_back(std::move(o));
  } while (MatchOp(","));
}

void Parser::ParseModifiers(QueryNode &node) {
  if (MatchKeyword("order")) {
    ExpectKeyword("by");
    ParseOrderBy(node.orders, node.order_by_all);
  }
  while (true) {
    if (MatchKeyword("limit")) {
      if (MatchKeyword("all")) { node.limit = nullptr; }
      else {
        node.limit = ParseExpression();
        if (MatchOp("%")) node.limit_percent = true;
        else if (MatchKeyword("percent")) node.limit_percent = true;
      }
      // LIMIT x, y (mysql style) not supported
    } else if (MatchKeyword("offset")) {
      node.offset = ParseExpression();
      if (MatchKeyword("rows") || MatchKeyword("row")) {}
    } else if (MatchKeyword("fetch")) {
      if (!MatchKeyword("first")) ExpectKeyword("next");
      if (!PeekKeyword("rows") && !PeekKeyword("row")) node.limit = ParseExpression();
      else node.limit = Expr::Constant(Value::Integer(1));
      if (!MatchKeyword("rows")) ExpectKeyword("row");
      ExpectKeyword("only");
    } else break;
  }
}

QueryNodePtr Parser::ParseQueryNodeNoModifiers() {
  if (PeekOp("(")) {
    Next();
    QueryNodePtr inner = ParseQueryNode();
    ExpectOp(")");
    // parenthesized query may be followed by its own modifiers (apply to inner)
    ParseModifiers(*inner);
    return inner;
  }
  if (PeekKeyword("values")) return ParseValuesNode();
  if (PeekKeyword("select") || PeekKeyword("from") || PeekKeyword("pivot") || PeekKeyword("unpivot") || PeekKeyword("pivot_wider") || PeekKeyword("pivot_longer")) return ParseSelectNode();
  if (PeekKeyword("show") || PeekKeyword("describe") || PeekKeyword("summarize")) {
    // DESCRIBE as a subquery source: treat as table function
    auto stmt = PeekKeyword("summarize") ? nullptr : (PeekKeyword("show") ? ParseShow() : ParseDescribe());
    auto node = std::make_unique<QueryNode>(QueryNodeKind::SELECT);
    auto star = std::make_unique<Expr>(ExprKind::STAR);
    node->select_list.push_back(std::move(star));
    auto ref = std::make_unique<TableRef>(TableRefKind::SHOW_REF);
    ShowStatement *show = dynamic_cast<ShowStatement *>(stmt.get());
    if (show) {
      ref->function_name = show->kind;
      ref->table_name = show->name;
      if (show->query) ref->subquery = std::move(show->query);
    }
    node->from = std::move(ref);
    return node;
  }
  if (PeekKeyword("with")) {
    return ParseQueryNode();
  }
  SyntaxErrorHere();
}

QueryNodePtr Parser::ParseValuesNode() {
  ExpectKeyword("values");
  auto node = std::make_unique<QueryNode>(QueryNodeKind::VALUES);
  do {
    ExpectOp("(");
    std::vector<ExprPtr> row = ParseExpressionList();
    ExpectOp(")");
    node->values.push_back(std::move(row));
  } while (MatchOp(","));
  // DuckDB: VALUES -> SELECT * FROM (VALUES ...) valueslist
  auto sel = std::make_unique<QueryNode>(QueryNodeKind::SELECT);
  sel->select_list.push_back(std::make_unique<Expr>(ExprKind::STAR));
  auto ref = std::make_unique<TableRef>(TableRefKind::EXPRESSION_LIST);
  ref->values = std::move(node->values);
  ref->alias = "valueslist";
  sel->from = std::move(ref);
  ParseModifiers(*sel);
  return sel;
}

bool Parser::PeekReservedForAlias() {
  const Token &t = Peek();
  if (t.type != TokenType::IDENT) return true;
  return IsReservedKeyword(t.text);
}

QueryNodePtr Parser::ParseSelectNode() {
  auto node = std::make_unique<QueryNode>(QueryNodeKind::SELECT);
  bool from_first = false;
  if (PeekKeyword("from")) {
    from_first = true;
    node->from_first = true;
    Next();
    node->from = ParseFromClause();
    if (PeekKeyword("pivot") || PeekKeyword("unpivot")) {
      node->from = ParsePivot(std::move(node->from));
    }
  }
  if (PeekKeyword("pivot") || PeekKeyword("unpivot") || PeekKeyword("pivot_wider") || PeekKeyword("pivot_longer")) {
    node->from = ParsePivot(nullptr);
    node->select_list.push_back(std::make_unique<Expr>(ExprKind::STAR));
    if (MatchKeyword("where")) node->where = ParseExpression();
    ParseModifiers(*node);
    return node;
  }
  if (MatchKeyword("select")) {
    if (MatchKeyword("distinct")) {
      node->distinct = true;
      if (MatchKeyword("on")) {
        ExpectOp("(");
        node->distinct_on = ParseExpressionList();
        ExpectOp(")");
      }
    } else MatchKeyword("all");
    // select list
    if (!PeekKeyword("from") && !PeekKeyword("where") && Peek().type != TokenType::EOI && !PeekOp(";") && !PeekOp(")") && !PeekKeyword("order") && !PeekKeyword("limit") && !PeekKeyword("group") && !PeekKeyword("having") && !PeekKeyword("union") && !PeekKeyword("except") && !PeekKeyword("intersect")) {
      do {
        // prefix alias: name: expr
        if ((Peek().type == TokenType::IDENT || Peek().type == TokenType::QUOTED_IDENT) && Peek(1).Is(":") && !Peek(2).Is(":")) {
          std::string alias = ParseColumnAlias();
          Next();
          ExprPtr e = ParseExpression();
          e->alias = alias;
          node->select_list.push_back(std::move(e));
          continue;
        }
        ExprPtr e = ParseExpression();
        if (MatchKeyword("as")) {
          e->alias = ParseColumnAlias();
        } else if ((Peek().type == TokenType::IDENT && !PeekReservedForAlias()) || Peek().type == TokenType::QUOTED_IDENT) {
          e->alias = ParseColumnAlias();
        }
        node->select_list.push_back(std::move(e));
      } while (MatchOp(","));
    }
  } else if (from_first) {
    node->select_list.push_back(std::make_unique<Expr>(ExprKind::STAR));
  } else SyntaxErrorHere();
  if (!from_first && MatchKeyword("from")) {
    node->from = ParseFromClause();
  }
  if (MatchKeyword("where")) node->where = ParseExpression();
  if (MatchKeyword("group")) {
    ExpectKeyword("by");
    if (PeekKeyword("all") && !Peek(1).Is("(") && !Peek(1).Is(".")) { Next(); node->group_by_all = true; }
    else {
      do {
        if (MatchKeyword("grouping")) {
          ExpectKeyword("sets");
          ExpectOp("(");
          do {
            std::vector<int> set;
            ExpectOp("(");
            if (!PeekOp(")")) {
              do {
                node->groups.push_back(ParseExpression());
                set.push_back((int)node->groups.size() - 1);
              } while (MatchOp(","));
            }
            ExpectOp(")");
            node->grouping_sets.push_back(set);
          } while (MatchOp(","));
          ExpectOp(")");
        } else if (PeekKeyword("rollup") || PeekKeyword("cube")) {
          bool rollup = PeekKeyword("rollup");
          Next();
          ExpectOp("(");
          std::vector<int> idxs;
          do { node->groups.push_back(ParseExpression()); idxs.push_back((int)node->groups.size() - 1); } while (MatchOp(","));
          ExpectOp(")");
          if (rollup) {
            for (size_t n = idxs.size() + 1; n-- > 0;) { std::vector<int> s(idxs.begin(), idxs.begin() + n); node->grouping_sets.push_back(s); }
          } else {
            size_t total = 1u << idxs.size();
            for (size_t mask = total; mask-- > 0;) {
              std::vector<int> s;
              for (size_t b = 0; b < idxs.size(); b++) if (mask & (1u << b)) s.push_back(idxs[b]);
              node->grouping_sets.push_back(s);
            }
          }
        } else {
          node->groups.push_back(ParseExpression());
        }
      } while (MatchOp(","));
    }
  }
  if (MatchKeyword("having")) node->having = ParseExpression();
  if (MatchKeyword("window")) {
    do {
      std::string name = ParseIdentifier();
      ExpectKeyword("as");
      ExpectOp("(");
      auto spec = ParseWindowSpec();
      ExpectOp(")");
      node->named_windows.push_back({name, std::move(spec)});
    } while (MatchOp(","));
  }
  if (MatchKeyword("qualify")) node->qualify = ParseExpression();
  ParseModifiers(*node);
  return node;
}

// ---------------------------------------------------------------- FROM
TableRefPtr Parser::ParseFromClause() {
  TableRefPtr ref = ParseTableRef();
  while (MatchOp(",")) {
    TableRefPtr right = ParseTableRef();
    auto join = std::make_unique<TableRef>(TableRefKind::JOIN);
    join->join_type = JoinType::CROSS;
    join->ref_type = JoinRefType::CROSS;
    join->left = std::move(ref);
    join->right = std::move(right);
    join->lateral = true;  // comma joins allow lateral references to earlier tables
    ref = std::move(join);
  }
  return ref;
}

void Parser::ParseTableAlias(TableRef &ref) {
  if (MatchKeyword("as")) {
    ref.alias = ParseColumnAlias();
  } else if ((Peek().type == TokenType::IDENT && !PeekReservedForAlias() && !PeekKeyword("pivot") && !PeekKeyword("unpivot")) || Peek().type == TokenType::QUOTED_IDENT) {
    // make sure it's not a keyword starting the next clause
    ref.alias = ParseColumnAlias();
  } else return;
  if (PeekOp("(")) {
    Next();
    do { ref.column_aliases.push_back(ParseColumnAlias()); } while (MatchOp(","));
    ExpectOp(")");
  }
}

TableRefPtr Parser::ParseTableRefBase() {
  const Token &t = Peek();
  int64_t pos = t.pos;
  if (t.Is("(")) {
    Next();
    if (IsSelectStart()) {
      auto ref = std::make_unique<TableRef>(TableRefKind::SUBQUERY);
      ref->subquery = ParseSelectStatement();
      ExpectOp(")");
      ref->position = pos;
      ParseTableAlias(*ref);
      return ref;
    }
    // parenthesized join
    TableRefPtr inner = ParseTableRef();
    ExpectOp(")");
    ParseTableAlias(*inner);
    return inner;
  }
  if (t.type == TokenType::STRING) {
    // file name: SELECT * FROM 'file.csv'
    Next();
    auto ref = std::make_unique<TableRef>(TableRefKind::BASE_TABLE);
    ref->table_name = t.text;
    ref->position = pos;
    ParseTableAlias(*ref);
    return ref;
  }
  if (t.KeywordIs("lateral")) {
    Next();
    TableRefPtr r = ParseTableRefBase();
    r->lateral = true;
    return r;
  }
  if (t.KeywordIs("values")) {
    auto node = ParseValuesNode();
    auto ref = std::make_unique<TableRef>(TableRefKind::SUBQUERY);
    auto stmt = std::make_unique<SelectStatement>();
    stmt->node = std::move(node);
    ref->subquery = std::move(stmt);
    ref->position = pos;
    ParseTableAlias(*ref);
    return ref;
  }
  if (t.type == TokenType::IDENT || t.type == TokenType::QUOTED_IDENT) {
    std::vector<std::string> names = ParseQualifiedName();
    if (PeekOp("(")) {
      // table function
      Next();
      auto ref = std::make_unique<TableRef>(TableRefKind::TABLE_FUNCTION);
      ref->function_name = names.back();
      if (names.size() > 1) ref->schema = names[names.size() - 2];
      if (!PeekOp(")")) {
        do {
          if (PeekIdentifier() && (Peek(1).Is(":=") || Peek(1).Is("=>") || Peek(1).Is("="))) {
            std::string pname = ParseColumnAlias();
            Next();
            ref->named_args.push_back({pname, ParseExpression()});
          } else ref->function_args.push_back(ParseExpression());
        } while (MatchOp(","));
      }
      ExpectOp(")");
      ref->position = pos;
      if (MatchKeyword("with")) { ExpectKeyword("ordinality"); }
      ParseTableAlias(*ref);
      return ref;
    }
    auto ref = std::make_unique<TableRef>(TableRefKind::BASE_TABLE);
    ref->table_name = names.back();
    if (names.size() >= 2) ref->schema = names[names.size() - 2];
    if (names.size() >= 3) ref->catalog = names[names.size() - 3];
    ref->position = pos;
    ParseTableAlias(*ref);
    if (MatchKeyword("at")) {
      // AT (VERSION => x) time travel: skip
      ExpectOp("("); while (!PeekOp(")")) Next(); ExpectOp(")");
    }
    return ref;
  }
  SyntaxErrorHere();
}

TableRefPtr Parser::ParseTableRef() {
  TableRefPtr left = ParseTableRefBase();
  while (true) {
    // sample clause
    if (PeekKeyword("tablesample") || (PeekKeyword("using") && Peek(1).KeywordIs("sample"))) {
      if (PeekKeyword("using")) Next();
      Next();
      // skip sample spec
      int depth = 0;
      while (Peek().type != TokenType::EOI) {
        if (PeekOp("(")) depth++;
        else if (PeekOp(")")) { if (depth == 0) break; depth--; }
        else if (depth == 0 && (PeekKeyword("where") || PeekKeyword("join") || PeekKeyword("inner") || PeekKeyword("left") || PeekKeyword("right") || PeekKeyword("full") || PeekKeyword("cross") || PeekKeyword("group") || PeekKeyword("order") || PeekKeyword("limit") || PeekOp(",") || PeekOp(";"))) break;
        Next();
      }
      continue;
    }
    if (PeekKeyword("pivot") || PeekKeyword("unpivot")) {
      left = ParsePivot(std::move(left));
      continue;
    }
    JoinType jt = JoinType::INNER;
    JoinRefType rt = JoinRefType::REGULAR;
    bool natural = false;
    bool is_join = false;
    size_t save = idx;
    if (MatchKeyword("natural")) { natural = true; rt = JoinRefType::NATURAL; }
    if (MatchKeyword("asof")) { rt = JoinRefType::ASOF; jt = JoinType::ASOF; }
    if (MatchKeyword("positional")) { rt = JoinRefType::POSITIONAL; jt = JoinType::POSITIONAL; }
    if (MatchKeyword("cross")) { ExpectKeyword("join"); jt = JoinType::CROSS; rt = JoinRefType::CROSS; is_join = true; }
    else if (MatchKeyword("inner")) { ExpectKeyword("join"); is_join = true; }
    else if (MatchKeyword("left")) { MatchKeyword("outer"); ExpectKeyword("join"); if (jt != JoinType::ASOF) jt = JoinType::LEFT; else jt = JoinType::ASOF; rt = rt == JoinRefType::ASOF ? rt : rt; is_join = true; if (rt == JoinRefType::ASOF) jt = JoinType::LEFT; }
    else if (MatchKeyword("right")) { MatchKeyword("outer"); ExpectKeyword("join"); jt = JoinType::RIGHT; is_join = true; }
    else if (MatchKeyword("full")) { MatchKeyword("outer"); ExpectKeyword("join"); jt = JoinType::FULL; is_join = true; }
    else if (MatchKeyword("semi")) { ExpectKeyword("join"); jt = JoinType::SEMI; is_join = true; }
    else if (MatchKeyword("anti")) { ExpectKeyword("join"); jt = JoinType::ANTI; is_join = true; }
    else if (MatchKeyword("join")) { is_join = true; }
    if (!is_join) { idx = save; break; }
    auto join = std::make_unique<TableRef>(TableRefKind::JOIN);
    join->join_type = jt;
    join->ref_type = rt;
    join->position = tokens[save].pos;
    join->left = std::move(left);
    join->right = ParseTableRefBase();
    if (join->right->lateral) join->lateral = true;
    if (!natural && jt != JoinType::CROSS && rt != JoinRefType::POSITIONAL) {
      if (MatchKeyword("on")) join->condition = ParseExpression();
      else if (MatchKeyword("using")) {
        ExpectOp("(");
        do { join->using_columns.push_back(ParseColumnAlias()); } while (MatchOp(","));
        ExpectOp(")");
      } else {
        // no condition: cross-join like (DuckDB allows JOIN without ON for inner join => cross product)
        if (jt == JoinType::INNER) { join->join_type = JoinType::CROSS; join->ref_type = JoinRefType::CROSS; }
        else SyntaxErrorHere();
      }
    }
    left = std::move(join);
  }
  return left;
}

TableRefPtr Parser::ParsePivot(TableRefPtr source) {
  bool unpivot = PeekKeyword("unpivot") || PeekKeyword("pivot_longer");
  Next();
  auto ref = std::make_unique<TableRef>(TableRefKind::PIVOT);
  ref->is_unpivot = unpivot;
  if (!source) {
    ref->source = ParseTableRefBase();
  } else ref->source = std::move(source);
  if (!unpivot) {
    // PIVOT source ON cols [IN (...)] USING aggs GROUP BY groups
    if (MatchKeyword("on")) {
      do {
        TableRef::PivotColumn pc;
        pc.pivot_exprs.push_back(ParseExpression());
        if (MatchKeyword("in")) {
          ExpectOp("(");
          if (IsSelectStart()) pc.subquery = ParseSelectStatement();
          else {
            do {
              ExprPtr e = ParseExpression();
              std::string alias;
              if (MatchKeyword("as")) alias = ParseColumnAlias();
              pc.entry_aliases.push_back(alias);
              pc.entries.push_back(std::move(e));
            } while (MatchOp(","));
          }
          ExpectOp(")");
        }
        ref->pivots.push_back(std::move(pc));
      } while (MatchOp(","));
    }
    if (MatchKeyword("using")) {
      do {
        ExprPtr e = ParseExpression();
        if (MatchKeyword("as")) e->alias = ParseColumnAlias();
        ref->aggregates.push_back(std::move(e));
      } while (MatchOp(","));
    }
    if (MatchKeyword("group")) { ExpectKeyword("by"); ref->groups = ParseExpressionList(); }
  } else {
    // UNPIVOT source ON cols INTO NAME n VALUE v
    if (MatchKeyword("include")) { ExpectKeyword("nulls"); ref->include_nulls = true; }
    else if (MatchKeyword("exclude")) { ExpectKeyword("nulls"); }
    ExpectKeyword("on");
    TableRef::PivotColumn pc;
    do {
      std::vector<std::string> group;
      if (MatchOp("(")) {
        do { group.push_back(ParseColumnAlias()); } while (MatchOp(","));
        ExpectOp(")");
      } else {
        // could be a star expression or column
        ExprPtr e = ParseExpression();
        if (e->kind == ExprKind::STAR) { pc.pivot_exprs.push_back(std::move(e)); group.clear(); }
        else if (e->kind == ExprKind::COLUMN_REF) group.push_back(e->names.back());
        else pc.pivot_exprs.push_back(std::move(e));
      }
      std::string alias;
      if (MatchKeyword("as")) alias = ParseColumnAlias();
      if (!group.empty()) { pc.unpivot_cols.push_back(group); pc.entry_aliases.push_back(alias); }
    } while (MatchOp(","));
    ref->pivots.push_back(std::move(pc));
    if (MatchKeyword("into")) {
      ExpectKeyword("name");
      ref->unpivot_names.push_back(ParseColumnAlias());
      ExpectKeyword("value");
      do { ref->unpivot_names.push_back(ParseColumnAlias()); } while (MatchOp(","));
    }
  }
  ParseTableAlias(*ref);
  return ref;
}

// ---------------------------------------------------------------- CREATE
OnCreateConflict Parser::ParseIfNotExists(bool or_replace) {
  if (MatchKeyword("if")) {
    ExpectKeyword("not"); ExpectKeyword("exists");
    return OnCreateConflict::IGNORE;
  }
  return or_replace ? OnCreateConflict::REPLACE : OnCreateConflict::ERROR;
}

void Parser::ParseColumnDef(ColumnDef &col, std::vector<Constraint> &constraints) {
  col.name = ParseColumnAlias();
  size_t type_start = Peek().pos;
  TypeDisplay td = ParseType();
  col.type = td.type;
  col.type_name = sql.substr(type_start, Peek().pos - type_start);
  while (true) {
    if (MatchKeyword("not")) { ExpectKeyword("null"); col.not_null = true; }
    else if (MatchKeyword("null")) {}
    else if (MatchKeyword("primary")) { ExpectKeyword("key"); col.primary_key = true; }
    else if (MatchKeyword("unique")) { col.unique = true; }
    else if (MatchKeyword("default")) { col.default_value = ParseExpression(P_OTHER_FOR_DEFAULT_PLACEHOLDER()); }
    else if (MatchKeyword("check")) { ExpectOp("("); col.check = ParseExpression(); ExpectOp(")"); }
    else if (MatchKeyword("references")) {
      Constraint c; c.kind = Constraint::FOREIGN_KEY;
      c.columns.push_back(col.name);
      c.fk_table = JoinStrings(ParseQualifiedName(), ".");
      if (MatchOp("(")) { do { c.fk_columns.push_back(ParseColumnAlias()); } while (MatchOp(",")); ExpectOp(")"); }
      constraints.push_back(std::move(c));
    }
    else if (MatchKeyword("collate")) { col.collation = ParseColumnAlias(); }
    else if (MatchKeyword("generated")) {
      ExpectKeyword("always"); ExpectKeyword("as");
      ExpectOp("("); col.generated = ParseExpression(); ExpectOp(")");
      if (MatchKeyword("virtual") || MatchKeyword("stored")) {}
    }
    else if (PeekKeyword("as") || PeekOp("(")) {
      // generated column shorthand: name type AS (expr) or name AS (expr)
      MatchKeyword("as");
      ExpectOp("("); col.generated = ParseExpression(); ExpectOp(")");
      if (MatchKeyword("virtual") || MatchKeyword("stored")) {}
    }
    else if (MatchKeyword("constraint")) { ParseIdentifier(); }
    else if (MatchKeyword("using")) { ExpectKeyword("compression"); col.compression = ParseIdentifier(); }
    else break;
  }
}

void Parser::ParseTableConstraint(std::vector<Constraint> &constraints) {
  Constraint c;
  if (MatchKeyword("constraint")) c.name = ParseIdentifier();
  if (MatchKeyword("primary")) {
    ExpectKeyword("key");
    c.kind = Constraint::PRIMARY_KEY;
    ExpectOp("(");
    do { c.columns.push_back(ParseColumnAlias()); } while (MatchOp(","));
    ExpectOp(")");
  } else if (MatchKeyword("unique")) {
    c.kind = Constraint::UNIQUE;
    ExpectOp("(");
    do { c.columns.push_back(ParseColumnAlias()); } while (MatchOp(","));
    ExpectOp(")");
  } else if (MatchKeyword("check")) {
    c.kind = Constraint::CHECK;
    ExpectOp("(");
    c.check = ParseExpression();
    ExpectOp(")");
  } else if (MatchKeyword("foreign")) {
    ExpectKeyword("key");
    c.kind = Constraint::FOREIGN_KEY;
    ExpectOp("(");
    do { c.columns.push_back(ParseColumnAlias()); } while (MatchOp(","));
    ExpectOp(")");
    ExpectKeyword("references");
    c.fk_table = JoinStrings(ParseQualifiedName(), ".");
    if (MatchOp("(")) { do { c.fk_columns.push_back(ParseColumnAlias()); } while (MatchOp(",")); ExpectOp(")"); }
  } else SyntaxErrorHere();
  constraints.push_back(std::move(c));
}

std::unique_ptr<Statement> Parser::ParseCreate() {
  ExpectKeyword("create");
  bool or_replace = false;
  bool temporary = false;
  if (MatchKeyword("or")) { ExpectKeyword("replace"); or_replace = true; }
  if (MatchKeyword("temporary") || MatchKeyword("temp")) temporary = true;
  if (MatchKeyword("persistent")) {}
  if (MatchKeyword("table")) {
    auto s = std::make_unique<CreateTableStatement>();
    s->temporary = temporary;
    s->on_conflict = ParseIfNotExists(or_replace);
    auto names = ParseQualifiedName();
    s->table = names.back();
    if (names.size() >= 2) s->schema = names[names.size() - 2];
    if (names.size() >= 3) s->catalog = names[names.size() - 3];
    if (MatchKeyword("as")) {
      s->query = ParseSelectStatement();
      return s;
    }
    if (MatchOp("(")) {
      if (!PeekOp(")")) {
        do {
          if (PeekKeyword("primary") || PeekKeyword("unique") || PeekKeyword("check") || PeekKeyword("foreign") || PeekKeyword("constraint")) {
            ParseTableConstraint(s->constraints);
          } else {
            ColumnDef col;
            ParseColumnDef(col, s->constraints);
            s->columns.push_back(std::move(col));
          }
        } while (MatchOp(","));
      }
      ExpectOp(")");
      if (MatchKeyword("as")) s->query = ParseSelectStatement();
      return s;
    }
    SyntaxErrorHere();
  }
  if (MatchKeyword("view")) {
    auto s = std::make_unique<CreateViewStatement>();
    s->temporary = temporary;
    s->on_conflict = ParseIfNotExists(or_replace);
    auto names = ParseQualifiedName();
    s->view = names.back();
    if (names.size() >= 2) s->schema = names[names.size() - 2];
    if (names.size() >= 3) s->catalog = names[names.size() - 3];
    if (MatchOp("(")) {
      do { s->aliases.push_back(ParseColumnAlias()); } while (MatchOp(","));
      ExpectOp(")");
    }
    ExpectKeyword("as");
    s->query = ParseSelectStatement();
    return s;
  }
  if (MatchKeyword("schema")) {
    auto s = std::make_unique<CreateSchemaStatement>();
    s->on_conflict = ParseIfNotExists(or_replace);
    auto names = ParseQualifiedName();
    s->schema = names.back();
    return s;
  }
  if (MatchKeyword("sequence")) {
    auto s = std::make_unique<CreateSequenceStatement>();
    s->temporary = temporary;
    s->on_conflict = ParseIfNotExists(or_replace);
    auto names = ParseQualifiedName();
    s->name = names.back();
    if (names.size() >= 2) s->schema = names[names.size() - 2];
    while (true) {
      if (MatchKeyword("increment")) { MatchKeyword("by"); ExprPtr e = ParseExpression(); s->increment = e->value.GetInt64(); }
      else if (MatchKeyword("start")) { MatchKeyword("with"); ExprPtr e = ParseExpression(); s->start = e->value.GetInt64(); }
      else if (MatchKeyword("minvalue")) { ExprPtr e = ParseExpression(); s->min_value = e->value.GetInt64(); s->has_min = true; }
      else if (MatchKeyword("maxvalue")) { ExprPtr e = ParseExpression(); s->max_value = e->value.GetInt64(); s->has_max = true; }
      else if (MatchKeyword("no")) { if (MatchKeyword("cycle")) {} else if (MatchKeyword("minvalue")) {} else if (MatchKeyword("maxvalue")) {} else SyntaxErrorHere(); }
      else if (MatchKeyword("cycle")) s->cycle = true;
      else break;
    }
    return s;
  }
  bool is_unique = false;
  if (MatchKeyword("unique")) { is_unique = true; }
  if (MatchKeyword("index")) {
    auto s = std::make_unique<CreateIndexStatement>();
    s->unique = is_unique;
    s->on_conflict = ParseIfNotExists(or_replace);
    s->index_name = ParseIdentifier();
    ExpectKeyword("on");
    auto names = ParseQualifiedName();
    s->table = names.back();
    if (names.size() >= 2) s->schema = names[names.size() - 2];
    if (MatchKeyword("using")) ParseIdentifier();
    ExpectOp("(");
    s->expressions = ParseExpressionList();
    ExpectOp(")");
    if (MatchKeyword("with")) { ExpectOp("("); while (!PeekOp(")")) Next(); ExpectOp(")"); }
    return s;
  }
  if (MatchKeyword("type")) {
    auto s = std::make_unique<CreateTypeStatement>();
    s->on_conflict = ParseIfNotExists(or_replace);
    auto names = ParseQualifiedName();
    s->name = names.back();
    if (names.size() >= 2) s->schema = names[names.size() - 2];
    ExpectKeyword("as");
    if (PeekKeyword("enum") && Peek(1).Is("(") && IsSelectStart(2)) {
      Next(); Next();
      s->query = ParseSelectStatement();
      ExpectOp(")");
      return s;
    }
    s->type = ParseType().type;
    return s;
  }
  if (MatchKeyword("macro") || MatchKeyword("function")) {
    auto s = std::make_unique<CreateMacroStatement>();
    s->temporary = temporary;
    s->on_conflict = ParseIfNotExists(or_replace);
    auto names = ParseQualifiedName();
    s->name = names.back();
    if (names.size() >= 2) s->schema = names[names.size() - 2];
    do {
      CreateMacroStatement::Overload ov;
      ExpectOp("(");
      if (!PeekOp(")")) {
        do {
          std::string pname = ParseColumnAlias();
          if (MatchOp(":=") || MatchOp("=")) {
            ov.defaults.push_back({pname, ParseExpression()});
          } else ov.params.push_back(pname);
        } while (MatchOp(","));
      }
      ExpectOp(")");
      ExpectKeyword("as");
      if (MatchKeyword("table")) {
        s->is_table = true;
        ov.query = ParseSelectStatement();
      } else {
        ov.expr = ParseExpression();
      }
      s->overloads.push_back(std::move(ov));
    } while (MatchOp(","));
    return s;
  }
  if (MatchKeyword("secret")) {
    auto s = std::make_unique<SimpleStatement>(StatementType::CREATE_SECRET);
    while (Peek().type != TokenType::EOI && !PeekOp(";")) Next();
    return s;
  }
  SyntaxErrorHere();
}

std::unique_ptr<Statement> Parser::ParseDrop() {
  ExpectKeyword("drop");
  auto s = std::make_unique<DropStatement>();
  if (MatchKeyword("table")) s->entry_type = "TABLE";
  else if (MatchKeyword("view")) s->entry_type = "VIEW";
  else if (MatchKeyword("index")) s->entry_type = "INDEX";
  else if (MatchKeyword("schema")) s->entry_type = "SCHEMA";
  else if (MatchKeyword("sequence")) s->entry_type = "SEQUENCE";
  else if (MatchKeyword("macro") || MatchKeyword("function")) { s->entry_type = "MACRO"; if (MatchKeyword("table")) s->entry_type = "MACRO TABLE"; }
  else if (MatchKeyword("type")) s->entry_type = "TYPE";
  else if (MatchKeyword("secret")) { s->entry_type = "SECRET"; }
  else if (MatchKeyword("temporary") || MatchKeyword("temp")) { return ParseDrop(); }
  else SyntaxErrorHere();
  if (MatchKeyword("if")) { ExpectKeyword("exists"); s->if_exists = true; }
  auto names = ParseQualifiedName();
  s->name = names.back();
  if (names.size() >= 2) s->schema = names[names.size() - 2];
  if (names.size() >= 3) s->catalog = names[names.size() - 3];
  if (MatchKeyword("cascade")) s->cascade = true;
  else MatchKeyword("restrict");
  return s;
}

std::unique_ptr<Statement> Parser::ParseAlter() {
  ExpectKeyword("alter");
  auto s = std::make_unique<AlterStatement>();
  if (MatchKeyword("view")) s->entry_type = "VIEW";
  else if (MatchKeyword("sequence")) s->entry_type = "SEQUENCE";
  else ExpectKeyword("table");
  if (MatchKeyword("if")) { ExpectKeyword("exists"); s->if_exists = true; }
  auto names = ParseQualifiedName();
  s->table = names.back();
  if (names.size() >= 2) s->schema = names[names.size() - 2];
  if (names.size() >= 3) s->catalog = names[names.size() - 3];
  if (MatchKeyword("add")) {
    if (MatchKeyword("primary")) { ExpectKeyword("key"); ExpectOp("("); s->kind = AlterStatement::ADD_PK; do { s->constraint.columns.push_back(ParseColumnAlias()); } while (MatchOp(",")); ExpectOp(")"); return s; }
    if (PeekKeyword("constraint") || PeekKeyword("unique") || PeekKeyword("check") || PeekKeyword("foreign")) {
      std::vector<Constraint> cs;
      ParseTableConstraint(cs);
      s->kind = AlterStatement::ADD_CONSTRAINT;
      s->constraint = std::move(cs[0]);
      return s;
    }
    MatchKeyword("column");
    s->kind = AlterStatement::ADD_COLUMN;
    if (MatchKeyword("if")) { ExpectKeyword("not"); ExpectKeyword("exists"); s->if_not_exists = true; }
    std::vector<Constraint> cs;
    ParseColumnDef(s->column, cs);
    return s;
  }
  if (MatchKeyword("drop")) {
    MatchKeyword("column");
    s->kind = AlterStatement::DROP_COLUMN;
    if (MatchKeyword("if")) { ExpectKeyword("exists"); s->if_column_exists = true; }
    s->column_name = ParseColumnAlias();
    if (MatchKeyword("cascade")) s->cascade = true; else MatchKeyword("restrict");
    return s;
  }
  if (MatchKeyword("rename")) {
    if (MatchKeyword("to")) { s->kind = AlterStatement::RENAME_TABLE; s->new_name = ParseColumnAlias(); return s; }
    MatchKeyword("column");
    s->kind = AlterStatement::RENAME_COLUMN;
    s->column_name = ParseColumnAlias();
    ExpectKeyword("to");
    s->new_name = ParseColumnAlias();
    return s;
  }
  if (MatchKeyword("alter")) {
    MatchKeyword("column");
    s->column_name = ParseColumnAlias();
    if (MatchKeyword("set")) {
      if (MatchKeyword("data")) { ExpectKeyword("type"); s->kind = AlterStatement::ALTER_TYPE; s->new_type = ParseType().type; if (MatchKeyword("using")) s->expression = ParseExpression(); return s; }
      if (MatchKeyword("type")) { s->kind = AlterStatement::ALTER_TYPE; s->new_type = ParseType().type; if (MatchKeyword("using")) s->expression = ParseExpression(); return s; }
      if (MatchKeyword("default")) { s->kind = AlterStatement::SET_DEFAULT; s->expression = ParseExpression(); return s; }
      if (MatchKeyword("not")) { ExpectKeyword("null"); s->kind = AlterStatement::SET_NOT_NULL; return s; }
      SyntaxErrorHere();
    }
    if (MatchKeyword("type")) { s->kind = AlterStatement::ALTER_TYPE; s->new_type = ParseType().type; if (MatchKeyword("using")) s->expression = ParseExpression(); return s; }
    if (MatchKeyword("drop")) {
      if (MatchKeyword("default")) { s->kind = AlterStatement::DROP_DEFAULT; return s; }
      if (MatchKeyword("not")) { ExpectKeyword("null"); s->kind = AlterStatement::DROP_NOT_NULL; return s; }
      SyntaxErrorHere();
    }
    SyntaxErrorHere();
  }
  if (MatchKeyword("set")) {
    if (MatchKeyword("partitioned")) { ExpectKeyword("by"); s->kind = AlterStatement::SET_PARTITIONED_BY; ExpectOp("("); ParseExpressionList(); ExpectOp(")"); return s; }
    if (MatchKeyword("sorted")) { ExpectKeyword("by"); s->kind = AlterStatement::SET_SORTED_BY; ExpectOp("("); bool a; std::vector<OrderByNode> o; ParseOrderBy(o, a); ExpectOp(")"); return s; }
  }
  if (MatchKeyword("reset")) {
    if (MatchKeyword("partitioned")) { ExpectKeyword("by"); s->kind = AlterStatement::RESET_PARTITIONED_BY; return s; }
    if (MatchKeyword("sorted")) { ExpectKeyword("by"); s->kind = AlterStatement::RESET_SORTED_BY; return s; }
  }
  SyntaxErrorHere();
}

void Parser::ParseReturning(std::vector<ExprPtr> &out) {
  if (MatchKeyword("returning")) {
    do {
      ExprPtr e = ParseExpression();
      if (MatchKeyword("as")) e->alias = ParseColumnAlias();
      else if ((Peek().type == TokenType::IDENT && !PeekReservedForAlias()) || Peek().type == TokenType::QUOTED_IDENT) e->alias = ParseColumnAlias();
      out.push_back(std::move(e));
    } while (MatchOp(","));
  }
}

std::unique_ptr<Statement> Parser::ParseInsert(std::vector<std::unique_ptr<CTE>> ctes) {
  ExpectKeyword("insert");
  auto s = std::make_unique<InsertStatement>();
  s->ctes = std::move(ctes);
  if (MatchKeyword("or")) {
    if (MatchKeyword("replace")) s->or_replace = true;
    else { ExpectKeyword("ignore"); s->or_ignore = true; }
  }
  ExpectKeyword("into");
  auto names = ParseQualifiedName();
  s->table = names.back();
  if (names.size() >= 2) s->schema = names[names.size() - 2];
  if (names.size() >= 3) s->catalog = names[names.size() - 3];
  if (MatchKeyword("as")) ParseColumnAlias();
  if (MatchKeyword("by")) {
    if (MatchKeyword("name")) s->by_name = true;
    else { ExpectKeyword("position"); s->by_position = true; }
  }
  if (PeekOp("(") && !IsSelectStart(1)) {
    Next();
    do { s->columns.push_back(ParseColumnAlias()); } while (MatchOp(","));
    ExpectOp(")");
  }
  if (MatchKeyword("by")) {
    if (MatchKeyword("name")) s->by_name = true;
    else { ExpectKeyword("position"); s->by_position = true; }
  }
  if (MatchKeyword("default")) { ExpectKeyword("values"); s->default_values = true; }
  else s->select = ParseSelectStatement();
  if (MatchKeyword("on")) {
    ExpectKeyword("conflict");
    s->on_conflict = std::make_unique<OnConflictInfo>();
    if (MatchOp("(")) {
      do { s->on_conflict->indexed_columns.push_back(ParseColumnAlias()); } while (MatchOp(","));
      ExpectOp(")");
      if (MatchKeyword("where")) s->on_conflict->condition = ParseExpression();
    }
    ExpectKeyword("do");
    if (MatchKeyword("nothing")) s->on_conflict->action = OnConflictInfo::NOTHING;
    else {
      ExpectKeyword("update");
      ExpectKeyword("set");
      s->on_conflict->action = OnConflictInfo::UPDATE;
      do {
        s->on_conflict->set_columns.push_back(ParseColumnAlias());
        ExpectOp("=");
        s->on_conflict->set_exprs.push_back(ParseExpression());
      } while (MatchOp(","));
      if (MatchKeyword("where")) s->on_conflict->where = ParseExpression();
    }
  }
  ParseReturning(s->returning);
  return s;
}

std::unique_ptr<Statement> Parser::ParseUpdate(std::vector<std::unique_ptr<CTE>> ctes) {
  ExpectKeyword("update");
  auto s = std::make_unique<UpdateStatement>();
  s->ctes = std::move(ctes);
  auto names = ParseQualifiedName();
  s->table = names.back();
  if (names.size() >= 2) s->schema = names[names.size() - 2];
  if (MatchKeyword("as")) s->alias = ParseColumnAlias();
  else if (PeekIdentifier() && !PeekKeyword("set")) s->alias = ParseColumnAlias();
  ExpectKeyword("set");
  do {
    if (MatchOp("(")) {
      std::vector<std::string> cols;
      do { cols.push_back(ParseColumnAlias()); } while (MatchOp(","));
      ExpectOp(")");
      ExpectOp("=");
      ExpectOp("(");
      std::vector<ExprPtr> exprs = ParseExpressionList();
      ExpectOp(")");
      for (size_t i = 0; i < cols.size(); i++) { s->columns.push_back(cols[i]); s->expressions.push_back(std::move(exprs[i])); }
    } else {
      s->columns.push_back(ParseColumnAlias());
      ExpectOp("=");
      s->expressions.push_back(ParseExpression());
    }
  } while (MatchOp(","));
  if (MatchKeyword("from")) s->from = ParseFromClause();
  if (MatchKeyword("where")) s->where = ParseExpression();
  ParseReturning(s->returning);
  return s;
}

std::unique_ptr<Statement> Parser::ParseDelete(std::vector<std::unique_ptr<CTE>> ctes) {
  ExpectKeyword("delete");
  ExpectKeyword("from");
  auto s = std::make_unique<DeleteStatement>();
  s->ctes = std::move(ctes);
  auto names = ParseQualifiedName();
  s->table = names.back();
  if (names.size() >= 2) s->schema = names[names.size() - 2];
  if (MatchKeyword("as")) s->alias = ParseColumnAlias();
  else if (PeekIdentifier() && !PeekKeyword("using") && !PeekKeyword("where") && !PeekKeyword("returning")) s->alias = ParseColumnAlias();
  if (MatchKeyword("using")) {
    do { s->using_clauses.push_back(ParseTableRef()); } while (MatchOp(","));
  }
  if (MatchKeyword("where")) s->where = ParseExpression();
  ParseReturning(s->returning);
  return s;
}

void Parser::ParseCopyOptions(std::map<std::string, std::vector<Value>> &options) {
  // (opt val, opt val ...) or legacy WITH options
  if (MatchOp("(")) {
    if (!PeekOp(")")) {
      do {
        std::string name = ToLower(Peek().text);
        Next();
        std::vector<Value> vals;
        if (PeekOp(",") || PeekOp(")")) { vals.push_back(Value::Boolean(true)); }
        else if (MatchOp("(")) {
          do { ExprPtr e = ParseExpression(); vals.push_back(e->kind == ExprKind::CONSTANT ? e->value : Value::Varchar(e->ToString())); } while (MatchOp(","));
          ExpectOp(")");
        } else {
          if (PeekOp("=")) Next();
          if (PeekOp("*")) { Next(); vals.push_back(Value::Varchar("*")); }
          else {
            ExprPtr e = ParseExpression();
            if (e->kind == ExprKind::CONSTANT) vals.push_back(e->value);
            else if (e->kind == ExprKind::COLUMN_REF) vals.push_back(Value::Varchar(e->names.back()));
            else if (e->kind == ExprKind::FUNCTION && e->op == "list_value") { for (auto &c : e->children) vals.push_back(c->value); }
            else vals.push_back(Value::Varchar(e->ToString()));
          }
        }
        options[name] = vals;
      } while (MatchOp(","));
    }
    ExpectOp(")");
  } else {
    MatchKeyword("with");
    while (PeekIdentifier() && !PeekOp(";")) {
      std::string name = ToLower(Peek().text);
      Next();
      std::vector<Value> vals;
      if (name == "header") { vals.push_back(Value::Boolean(true)); }
      else if (name == "delimiter" || name == "quote" || name == "escape" || name == "null" || name == "format") {
        MatchKeyword("as");
        ExprPtr e = ParseExpression();
        vals.push_back(e->kind == ExprKind::CONSTANT ? e->value : Value::Varchar(e->ToString()));
      } else if (name == "csv" || name == "binary") { options["format"] = {Value::Varchar(name)}; continue; }
      else { ExprPtr e = ParseExpression(); vals.push_back(e->kind == ExprKind::CONSTANT ? e->value : Value::Varchar(e->ToString())); }
      options[name] = vals;
    }
  }
}

std::unique_ptr<Statement> Parser::ParseCopy() {
  ExpectKeyword("copy");
  auto s = std::make_unique<CopyStatement>();
  if (MatchKeyword("from")) {
    // COPY FROM DATABASE a TO b
    ExpectKeyword("database");
    ParseIdentifier(); ExpectKeyword("to"); ParseIdentifier();
    s->format = "database";
    return s;
  }
  if (PeekOp("(")) {
    Next();
    s->select = ParseSelectStatement();
    ExpectOp(")");
  } else {
    auto names = ParseQualifiedName();
    s->table = names.back();
    if (names.size() >= 2) s->schema = names[names.size() - 2];
    if (MatchOp("(")) {
      do { s->columns.push_back(ParseColumnAlias()); } while (MatchOp(","));
      ExpectOp(")");
    }
  }
  if (MatchKeyword("from")) s->is_from = true;
  else ExpectKeyword("to");
  if (Peek().type == TokenType::STRING) s->file = ParseStringLiteral();
  else if (PeekKeyword("stdout") || PeekKeyword("stdin")) { s->file = "/dev/" + ToLower(Peek().text); Next(); }
  else SyntaxErrorHere();
  ParseCopyOptions(s->options);
  if (s->options.count("format")) s->format = ToLower(s->options["format"][0].ToString());
  return s;
}

std::unique_ptr<Statement> Parser::ParsePragma() {
  ExpectKeyword("pragma");
  auto s = std::make_unique<PragmaStatement>();
  s->name = ToLower(ParseColumnAlias());
  if (MatchOp("=")) {
    s->has_assignment = true;
    s->params.push_back(ParseExpression());
  } else if (MatchOp("(")) {
    if (!PeekOp(")")) {
      do {
        if (PeekIdentifier() && (Peek(1).Is(":=") || Peek(1).Is("="))) {
          std::string n = ParseColumnAlias(); Next();
          s->named_params.push_back({n, ParseExpression()});
        } else s->params.push_back(ParseExpression());
      } while (MatchOp(","));
    }
    ExpectOp(")");
  }
  return s;
}

std::unique_ptr<Statement> Parser::ParseSet(bool reset) {
  Next();
  auto s = std::make_unique<SetStatement>();
  s->is_reset = reset;
  if (MatchKeyword("local")) s->scope = "LOCAL";
  else if (MatchKeyword("session")) s->scope = "SESSION";
  else if (MatchKeyword("global")) s->scope = "GLOBAL";
  if (MatchKeyword("variable")) {
    s->is_variable = true;
    s->name = ParseColumnAlias();
    if (!reset) { if (!MatchOp("=")) ExpectKeyword("to"); s->value = ParseExpression(); }
    return s;
  }
  if (PeekKeyword("schema") || PeekKeyword("search_path")) {
    s->name = ToLower(Peek().text); Next();
    if (!reset) { if (!MatchOp("=")) ExpectKeyword("to"); s->value = ParseExpression(); }
    return s;
  }
  auto names = ParseQualifiedName();
  s->name = JoinStrings(names, ".");
  if (!reset) {
    if (!MatchOp("=")) ExpectKeyword("to");
    if (MatchKeyword("default")) { s->is_reset = true; return s; }
    s->value = ParseExpression();
  }
  return s;
}

std::unique_ptr<Statement> Parser::ParseShow() {
  ExpectKeyword("show");
  auto s = std::make_unique<ShowStatement>();
  if (MatchKeyword("tables")) { s->kind = "TABLES"; if (MatchKeyword("from")) { ParseQualifiedName(); } return s; }
  if (MatchKeyword("all")) {
    if (MatchKeyword("tables")) { s->kind = "ALL TABLES"; return s; }
    SyntaxErrorHere();
  }
  if (MatchKeyword("databases")) { s->kind = "DATABASES"; return s; }
  if (MatchKeyword("schemas")) { s->kind = "SCHEMAS"; return s; }
  if (MatchKeyword("variables")) { s->kind = "VARIABLES"; return s; }
  if (MatchKeyword("table")) { auto names = ParseQualifiedName(); s->kind = "DESCRIBE"; s->name = JoinStrings(names, "."); return s; }
  if (IsSelectStart()) { s->kind = "DESCRIBE"; s->query = ParseSelectStatement(); return s; }
  // SHOW name => describe table / setting
  auto names = ParseQualifiedName();
  s->kind = "DESCRIBE";
  s->name = JoinStrings(names, ".");
  return s;
}

std::unique_ptr<Statement> Parser::ParseDescribe() {
  Next();
  auto s = std::make_unique<ShowStatement>();
  s->kind = "DESCRIBE";
  if (MatchKeyword("table")) { auto names = ParseQualifiedName(); s->name = JoinStrings(names, "."); return s; }
  if (IsSelectStart()) { s->query = ParseSelectStatement(); return s; }
  if (Peek().type == TokenType::EOI || PeekOp(";")) { s->kind = "TABLES"; return s; }
  auto names = ParseQualifiedName();
  s->name = JoinStrings(names, ".");
  return s;
}

std::unique_ptr<Statement> Parser::ParseExplain() {
  ExpectKeyword("explain");
  auto s = std::make_unique<ExplainStatement>();
  if (MatchKeyword("analyze")) s->analyze = true;
  if (MatchOp("(")) { while (!PeekOp(")")) Next(); ExpectOp(")"); }
  s->stmt = ParseStatement();
  return s;
}

std::unique_ptr<Statement> Parser::ParseAttach() {
  ExpectKeyword("attach");
  auto s = std::make_unique<AttachStatement>();
  if (MatchKeyword("or")) { ExpectKeyword("replace"); s->or_replace = true; }
  MatchKeyword("database");
  if (MatchKeyword("if")) { ExpectKeyword("not"); ExpectKeyword("exists"); s->if_not_exists = true; }
  if (Peek().type == TokenType::STRING) s->path = ParseStringLiteral();
  else s->path = ParseIdentifier();
  if (MatchKeyword("as")) s->name = ParseIdentifier();
  if (MatchOp("(")) {
    if (!PeekOp(")")) {
      do {
        std::string n = ToLower(Peek().text); Next();
        if (PeekOp(",") || PeekOp(")")) s->options.push_back({n, Expr::Constant(Value::Boolean(true))});
        else s->options.push_back({n, ParseExpression()});
      } while (MatchOp(","));
    }
    ExpectOp(")");
  }
  return s;
}

std::unique_ptr<Statement> Parser::ParseExport(bool is_import) {
  Next();
  ExpectKeyword("database");
  auto s = std::make_unique<ExportStatement>();
  s->is_import = is_import;
  if (PeekIdentifier() && Peek(1).KeywordIs("to")) { ParseIdentifier(); ExpectKeyword("to"); }
  s->path = ParseStringLiteral();
  if (PeekOp("(") || PeekKeyword("with")) ParseCopyOptions(s->options);
  return s;
}

std::unique_ptr<Statement> Parser::ParseCall() {
  ExpectKeyword("call");
  auto s = std::make_unique<CallStatement>();
  s->function = ParseExpression();
  return s;
}

std::unique_ptr<Statement> Parser::ParsePrepare() {
  ExpectKeyword("prepare");
  auto s = std::make_unique<PrepareStatement>();
  s->name = ParseIdentifier();
  if (MatchOp("(")) { while (!PeekOp(")")) Next(); ExpectOp(")"); }
  ExpectKeyword("as");
  s->stmt = ParseStatement();
  return s;
}

std::unique_ptr<Statement> Parser::ParseExecute() {
  ExpectKeyword("execute");
  auto s = std::make_unique<ExecuteStatement>();
  s->name = ParseIdentifier();
  if (MatchOp("(")) {
    if (!PeekOp(")")) {
      do {
        if (PeekIdentifier() && (Peek(1).Is(":=") || Peek(1).Is("=>"))) {
          std::string n = ParseColumnAlias(); Next();
          s->named_params.push_back({n, ParseExpression()});
        } else s->params.push_back(ParseExpression());
      } while (MatchOp(","));
    }
    ExpectOp(")");
  }
  return s;
}

std::unique_ptr<Statement> Parser::ParseComment() {
  ExpectKeyword("comment");
  ExpectKeyword("on");
  auto s = std::make_unique<CommentStatement>();
  if (MatchKeyword("column")) {
    s->entry_type = "COLUMN";
    auto names = ParseQualifiedName();
    s->column = names.back();
    names.pop_back();
    s->name = JoinStrings(names, ".");
  } else {
    s->entry_type = ToUpper(Peek().text);
    Next();
    if (s->entry_type == "MACRO" && MatchKeyword("table")) s->entry_type = "MACRO TABLE";
    s->name = JoinStrings(ParseQualifiedName(), ".");
  }
  ExpectKeyword("is");
  if (MatchKeyword("null")) s->comment = Value();
  else s->comment = Value::Varchar(ParseStringLiteral());
  return s;
}
