static std::string ConstantToString(const Value &v, int64_t marker) {
  if (v.is_null) return "NULL";
  switch (v.type.id) {
  case TypeId::BOOLEAN:
    if (marker == -2) return v.ival ? "true" : "false";
    return v.ival ? "CAST('t' AS BOOLEAN)" : "CAST('f' AS BOOLEAN)";
  case TypeId::VARCHAR: case TypeId::STRING_LITERAL: return EscapeSQLString(v.str);
  case TypeId::BLOB: return EscapeSQLString(BlobToString(v.str)) + "::BLOB";
  case TypeId::BIT: return "'" + v.str + "'::BIT";
  case TypeId::INTERVAL: return "INTERVAL '" + v.ToString() + "'";
  case TypeId::DATE: return "DATE '" + v.ToString() + "'";
  case TypeId::TIMESTAMP: return "TIMESTAMP '" + v.ToString() + "'";
  case TypeId::TIME: return "TIME '" + v.ToString() + "'";
  case TypeId::DECIMAL: case TypeId::FLOAT: case TypeId::DOUBLE: return v.ToString();
  case TypeId::LIST: {
    std::string r = "[";
    for (size_t i = 0; i < v.children->size(); i++) { if (i) r += ", "; r += ConstantToString((*v.children)[i], 0); }
    return r + "]";
  }
  case TypeId::STRUCT: {
    std::string r = "{";
    for (size_t i = 0; i < v.children->size(); i++) { if (i) r += ", "; r += EscapeSQLString(v.type.info->names[i]) + ": " + ConstantToString((*v.children)[i], 0); }
    return r + "}";
  }
  default: return v.ToString();
  }
}

static std::string ChildrenToString(const std::vector<ExprPtr> &children, size_t start = 0) {
  std::string r;
  for (size_t i = start; i < children.size(); i++) {
    if (i > start) r += ", ";
    if (!children[i]->alias.empty() && children[i]->kind != ExprKind::STAR) r += QuoteIdentifierIfNeeded(children[i]->alias) + " := ";
    r += children[i]->ToString();
  }
  return r;
}

std::string OrderByToString(const OrderByNode &o) {
  std::string r = o.expr->ToString();
  if (o.type == OrderType::ASC) r += " ASC";
  else if (o.type == OrderType::DESC) r += " DESC";
  if (o.null_order == NullOrder::NULLS_FIRST) r += " NULLS FIRST";
  else if (o.null_order == NullOrder::NULLS_LAST) r += " NULLS LAST";
  return r;
}

static std::string FrameBoundToString(WindowFrame::Bound b, const ExprPtr &e, bool start) {
  switch (b) {
  case WindowFrame::UNBOUNDED_PRECEDING: return "UNBOUNDED PRECEDING";
  case WindowFrame::UNBOUNDED_FOLLOWING: return "UNBOUNDED FOLLOWING";
  case WindowFrame::CURRENT_ROW: return "CURRENT ROW";
  case WindowFrame::EXPR_PRECEDING: return e->ToString() + " PRECEDING";
  case WindowFrame::EXPR_FOLLOWING: return e->ToString() + " FOLLOWING";
  }
  return "";
}

std::string WindowSpecToString(const WindowSpec &w, const std::string &fname) {
  std::string r = "(";
  if (!w.name.empty()) r += w.name;
  bool first = true;
  if (!w.partitions.empty()) {
    r += "PARTITION BY ";
    for (size_t i = 0; i < w.partitions.size(); i++) { if (i) r += ", "; r += w.partitions[i]->ToString(); }
    first = false;
  }
  if (!w.orders.empty()) {
    if (!first) r += " ";
    r += "ORDER BY ";
    for (size_t i = 0; i < w.orders.size(); i++) { if (i) r += ", "; r += OrderByToString(w.orders[i]); }
    first = false;
  }
  if (w.frame.specified) {
    if (!first) r += " ";
    r += w.frame.rows ? "ROWS" : (w.frame.groups ? "GROUPS" : "RANGE");
    r += " BETWEEN " + FrameBoundToString(w.frame.start, w.frame.start_expr, true) + " AND " + FrameBoundToString(w.frame.end, w.frame.end_expr, false);
  }
  return r + ")";
}

std::string Expr::ToString() const {
  switch (kind) {
  case ExprKind::CONSTANT: return ConstantToString(value, position);
  case ExprKind::COLUMN_REF: {
    std::string r;
    for (size_t i = 0; i < names.size(); i++) { if (i) r += "."; r += QuoteIdentifierIfNeeded(names[i]); }
    return r;
  }
  case ExprKind::STAR: {
    if (columns_star) {
      std::string r = "COLUMNS(";
      if (columns_expr) r += columns_expr->ToString(); else r += "*";
      return r + ")";
    }
    std::string r = relation_name.empty() ? "*" : relation_name + ".*";
    if (!exclude_list.empty()) {
      r += " EXCLUDE (";
      for (size_t i = 0; i < exclude_list.size(); i++) { if (i) r += ", "; r += exclude_list[i]; }
      r += ")";
    }
    if (!replace_list.empty()) {
      r += " REPLACE (";
      for (size_t i = 0; i < replace_list.size(); i++) { if (i) r += ", "; r += replace_list[i].second->ToString() + " AS " + replace_list[i].first; }
      r += ")";
    }
    return r;
  }
  case ExprKind::FUNCTION: {
    std::string lname = ToLower(op);
    if (is_operator) {
      if (op == "array_extract") return children[0]->ToString() + "[" + children[1]->ToString() + "]";
      if (op == "array_slice") {
        std::string lo = children[1]->position == -3 ? "" : children[1]->ToString();
        std::string hi = children[2]->position == -3 ? "" : children[2]->ToString();
        return children[0]->ToString() + "[" + lo + ":" + hi + "]";
      }
      if (op == "struct_extract") return "(" + children[0]->ToString() + ")." + QuoteIdentifierIfNeeded(children[1]->value.str);
      if (op == "list_value") return "(ARRAY[" + ChildrenToString(children) + "])";
      if (children.size() == 2) return "(" + children[0]->ToString() + " " + op + " " + children[1]->ToString() + ")";
    }
    std::string r;
    if (!schema.empty() && schema != "comprehension") r += schema + ".";
    if (lname == "count_star") return "count_star()";
    // functions whose names are keywords get quoted
    std::string fn = IsKeyword(lname) && lname != "coalesce" ? "\"" + lname + "\"" : lname;
    if (lname == "coalesce") fn = "COALESCE";
    if (lname == "nullif") fn = "\"nullif\"";
    if (lname == "first" || lname == "last" || lname == "row" || lname == "version" || lname == "any_value") fn = (lname == "first" || lname == "row" || lname == "version") ? "\"" + lname + "\"" : lname;
    r += fn + "(";
    if (distinct) r += "DISTINCT ";
    r += ChildrenToString(children);
    if (!order_bys.empty()) {
      r += " ORDER BY ";
      for (size_t i = 0; i < order_bys.size(); i++) { if (i) r += ", "; r += OrderByToString(order_bys[i]); }
    }
    r += ")";
    if (filter) r += " FILTER (WHERE " + filter->ToString() + ")";
    return r;
  }
  case ExprKind::OPERATOR: {
    if (op == "IS NULL" || op == "IS NOT NULL") return "(" + children[0]->ToString() + " " + op + ")";
    if (op == "NOT") return "(NOT " + children[0]->ToString() + ")";
    if (op == "IN" || op == "NOT IN") {
      std::string r = "(" + children[0]->ToString() + " " + op + " (";
      r += ChildrenToString(children, 1);
      return r + "))";
    }
    if (children.size() == 1) return op + "(" + children[0]->ToString() + ")";
    return "(" + children[0]->ToString() + " " + op + " " + children[1]->ToString() + ")";
  }
  case ExprKind::COMPARISON: return "(" + children[0]->ToString() + " " + op + " " + children[1]->ToString() + ")";
  case ExprKind::CONJUNCTION: {
    std::string r = "(";
    for (size_t i = 0; i < children.size(); i++) { if (i) r += " " + op + " "; r += children[i]->ToString(); }
    return r + ")";
  }
  case ExprKind::CASE: {
    std::string r = "CASE ";
    for (auto &cc : case_checks) r += " WHEN (" + cc.when->ToString() + ") THEN (" + cc.then->ToString() + ")";
    r += " ELSE " + (else_expr ? else_expr->ToString() : std::string("NULL")) + " END";
    return r;
  }
  case ExprKind::CAST: {
    std::string tn = op.empty() ? TypeToCastDisplay(cast_type) : op;
    return std::string(try_cast ? "TRY_CAST(" : "CAST(") + children[0]->ToString() + " AS " + tn + ")";
  }
  case ExprKind::SUBQUERY: {
    std::string sq = subquery ? subquery->ToString() : "";
    switch (subquery_type) {
    case SubqueryType::EXISTS: return "EXISTS(" + sq + ")";
    case SubqueryType::NOT_EXISTS: return "(NOT EXISTS(" + sq + "))";
    case SubqueryType::SCALAR: return "(" + sq + ")";
    case SubqueryType::ANY: return "(" + children[0]->ToString() + " " + comparison_type + " ANY(" + sq + "))";
    case SubqueryType::ALL: {
      std::string neg = comparison_type == "=" ? "!=" : comparison_type == "!=" ? "=" : comparison_type == "<" ? ">=" : comparison_type == ">" ? "<=" : comparison_type == "<=" ? ">" : "<";
      return "(NOT (" + children[0]->ToString() + " " + neg + " ANY(" + sq + ")))";
    }
    }
    return "";
  }
  case ExprKind::BETWEEN: return "(" + children[0]->ToString() + " BETWEEN " + children[1]->ToString() + " AND " + children[2]->ToString() + ")";
  case ExprKind::COLLATE: return children[0]->ToString() + " COLLATE " + collation;
  case ExprKind::LAMBDA: {
    std::string params = JoinStrings(lambda_params, ", ");
    if (op == "->") {
      if (lambda_params.size() > 1) params = "(" + params + ")";
      return "(" + params + " -> " + children[0]->ToString() + ")";
    }
    return "(lambda " + params + ": " + children[0]->ToString() + ")";
  }
  case ExprKind::WINDOW: {
    std::string lname = ToLower(op);
    std::string r;
    if (!schema.empty()) r += schema + ".";
    std::string fn = IsKeyword(lname) ? "\"" + lname + "\"" : lname;
    if (lname == "first" || lname == "last") fn = "\"" + lname + "\"";
    if (lname == "count_star") { lname = "count"; fn = "count"; }
    r += fn + "(";
    if (distinct) r += "DISTINCT ";
    r += ChildrenToString(children);
    if (!order_bys.empty()) {
      r += " ORDER BY ";
      for (size_t i = 0; i < order_bys.size(); i++) { if (i) r += ", "; r += OrderByToString(order_bys[i]); }
    }
    r += ")";
    if (filter) r += " FILTER (WHERE " + filter->ToString() + ")";
    if (ignore_nulls) r += " IGNORE NULLS";
    r += " OVER " + WindowSpecToString(*window, lname);
    return r;
  }
  case ExprKind::POSITIONAL_REF: return "#" + std::to_string(index);
  case ExprKind::PARAMETER: return param_name.empty() ? "?" : "$" + param_name;
  case ExprKind::DEFAULT: return "DEFAULT";
  case ExprKind::LAMBDA_REF: return names.empty() ? op : names.back();
  }
  return "";
}

static std::unique_ptr<WindowSpec> CopyWindow(const WindowSpec &w) {
  auto r = std::make_unique<WindowSpec>();
  r->name = w.name;
  for (auto &p : w.partitions) r->partitions.push_back(p->Copy());
  for (auto &o : w.orders) { OrderByNode n; n.expr = o.expr->Copy(); n.type = o.type; n.null_order = o.null_order; r->orders.push_back(std::move(n)); }
  r->frame.rows = w.frame.rows; r->frame.groups = w.frame.groups; r->frame.start = w.frame.start; r->frame.end = w.frame.end; r->frame.specified = w.frame.specified; r->frame.exclude = w.frame.exclude;
  if (w.frame.start_expr) r->frame.start_expr = w.frame.start_expr->Copy();
  if (w.frame.end_expr) r->frame.end_expr = w.frame.end_expr->Copy();
  return r;
}

ExprPtr Expr::Copy() const {
  auto e = std::make_unique<Expr>(kind);
  e->alias = alias; e->position = position; e->value = value; e->names = names; e->op = op; e->schema = schema;
  for (auto &c : children) e->children.push_back(c->Copy());
  e->distinct = distinct;
  if (filter) e->filter = filter->Copy();
  for (auto &o : order_bys) { OrderByNode n; n.expr = o.expr->Copy(); n.type = o.type; n.null_order = o.null_order; e->order_bys.push_back(std::move(n)); }
  e->is_operator = is_operator; e->export_state = export_state;
  e->exclude_list = exclude_list;
  for (auto &r : replace_list) e->replace_list.push_back({r.first, r.second->Copy()});
  for (auto &r : rename_list) e->rename_list.push_back({r.first, r.second->Copy()});
  e->relation_name = relation_name;
  if (columns_expr) e->columns_expr = columns_expr->Copy();
  e->columns_star = columns_star; e->columns_regex = columns_regex;
  for (auto &cc : case_checks) { CaseCheck n; n.when = cc.when->Copy(); n.then = cc.then->Copy(); e->case_checks.push_back(std::move(n)); }
  if (else_expr) e->else_expr = else_expr->Copy();
  e->cast_type = cast_type; e->try_cast = try_cast;
  if (subquery) e->subquery = subquery->Copy();
  e->subquery_type = subquery_type; e->comparison_type = comparison_type; e->collation = collation; e->lambda_params = lambda_params;
  if (window) e->window = CopyWindow(*window);
  e->ignore_nulls = ignore_nulls; e->index = index; e->param_name = param_name;
  return e;
}

bool Expr::IsAggregate() const { return false; }

// ---------------------------------------------------------------- TableRef / QueryNode ToString
static std::string JoinTypeToString(JoinType t) {
  switch (t) {
  case JoinType::INNER: return "INNER";
  case JoinType::LEFT: return "LEFT";
  case JoinType::RIGHT: return "RIGHT";
  case JoinType::FULL: return "FULL";
  case JoinType::CROSS: return "CROSS";
  case JoinType::SEMI: return "SEMI";
  case JoinType::ANTI: return "ANTI";
  case JoinType::POSITIONAL: return "POSITIONAL";
  case JoinType::ASOF: return "ASOF";
  default: return "INNER";
  }
}

std::string TableRef::ToString() const {
  std::string r;
  switch (kind) {
  case TableRefKind::BASE_TABLE: {
    if (!catalog.empty()) r += QuoteIdentifierIfNeeded(catalog) + ".";
    if (!schema.empty()) r += QuoteIdentifierIfNeeded(schema) + ".";
    r += QuoteIdentifierIfNeeded(table_name);
    break;
  }
  case TableRefKind::SUBQUERY: r = "(" + subquery->ToString() + ")"; break;
  case TableRefKind::JOIN: {
    r = left->ToString();
    if (ref_type == JoinRefType::CROSS && join_type == JoinType::CROSS && lateral) { r += " , " + right->ToString(); return r; }
    if (ref_type == JoinRefType::NATURAL) r += " NATURAL";
    if (join_type == JoinType::CROSS) r += " CROSS JOIN " + right->ToString();
    else if (ref_type == JoinRefType::POSITIONAL) r += " POSITIONAL JOIN " + right->ToString();
    else {
      if (ref_type == JoinRefType::ASOF) r += " ASOF";
      r += " " + JoinTypeToString(join_type) + " JOIN " + right->ToString();
      if (condition) r += " ON (" + condition->ToString() + ")";
      else if (!using_columns.empty()) r += " USING (" + JoinStrings(using_columns, ", ") + ")";
    }
    return r;
  }
  case TableRefKind::TABLE_FUNCTION: {
    std::string fn = IsKeyword(function_name) || function_name == "range" ? "\"" + function_name + "\"" : function_name;
    r = fn + "(";
    for (size_t i = 0; i < function_args.size(); i++) { if (i) r += ", "; r += function_args[i]->ToString(); }
    for (size_t i = 0; i < named_args.size(); i++) { if (i || !function_args.empty()) r += ", "; r += named_args[i].first + " := " + named_args[i].second->ToString(); }
    r += ")";
    break;
  }
  case TableRefKind::EXPRESSION_LIST: {
    r = "(VALUES ";
    for (size_t i = 0; i < values.size(); i++) {
      if (i) r += ", ";
      r += "(";
      for (size_t j = 0; j < values[i].size(); j++) { if (j) r += ", "; r += values[i][j]->ToString(); }
      r += ")";
    }
    r += ")";
    break;
  }
  case TableRefKind::EMPTY: return "";
  default: break;
  }
  if (!alias.empty()) {
    r += " AS " + QuoteIdentifierIfNeeded(alias);
    if (!column_aliases.empty()) {
      r += "(";
      for (size_t i = 0; i < column_aliases.size(); i++) { if (i) r += ", "; r += QuoteIdentifierIfNeeded(column_aliases[i]); }
      r += ")";
    }
  }
  return r;
}

static std::string ModifiersToString(const QueryNode &n) {
  std::string r;
  if (!n.orders.empty()) {
    r += " ORDER BY ";
    if (n.order_by_all) {
      r += "ALL";
      if (n.orders[0].type == OrderType::DESC) r += " DESC";
      if (n.orders[0].null_order == NullOrder::NULLS_FIRST) r += " NULLS FIRST";
      else if (n.orders[0].null_order == NullOrder::NULLS_LAST) r += " NULLS LAST";
    } else {
      for (size_t i = 0; i < n.orders.size(); i++) { if (i) r += ", "; r += OrderByToString(n.orders[i]); }
    }
  }
  if (n.limit) r += " LIMIT " + n.limit->ToString() + (n.limit_percent ? "%" : "");
  if (n.offset) r += " OFFSET " + n.offset->ToString();
  return r;
}

std::string QueryNode::ToString() const {
  std::string r;
  if (!ctes.empty()) {
    r += "WITH ";
    if (recursive_ctes) r += "RECURSIVE ";
    for (size_t i = 0; i < ctes.size(); i++) {
      if (i) r += ", ";
      r += QuoteIdentifierIfNeeded(ctes[i]->name);
      if (!ctes[i]->aliases.empty()) {
        r += "(";
        for (size_t j = 0; j < ctes[i]->aliases.size(); j++) { if (j) r += ", "; r += QuoteIdentifierIfNeeded(ctes[i]->aliases[j]); }
        r += ")";
      }
      r += " AS ";
      if (ctes[i]->materialized) r += "MATERIALIZED ";
      r += "(" + ctes[i]->query->ToString() + ")";
    }
    if (kind == QueryNodeKind::SELECT) r += " ";
  }
  if (kind == QueryNodeKind::SET_OPERATION) {
    std::string op;
    switch (setop) {
    case SetOpType::UNION: op = "UNION"; break;
    case SetOpType::UNION_ALL: op = "UNION ALL"; break;
    case SetOpType::UNION_BY_NAME: op = "UNION BY NAME"; break;
    case SetOpType::UNION_ALL_BY_NAME: op = "UNION ALL BY NAME"; break;
    case SetOpType::EXCEPT: op = "EXCEPT"; break;
    case SetOpType::EXCEPT_ALL: op = "EXCEPT ALL"; break;
    case SetOpType::INTERSECT: op = "INTERSECT"; break;
    case SetOpType::INTERSECT_ALL: op = "INTERSECT ALL"; break;
    }
    r += "(" + left->ToString() + ") " + op + " (" + right->ToString() + ")";
    r += ModifiersToString(*this);
    return r;
  }
  if (kind == QueryNodeKind::SELECT) {
    r += "SELECT ";
    if (distinct) {
      r += "DISTINCT ";
      if (!distinct_on.empty()) {
        r += "ON (";
        for (size_t i = 0; i < distinct_on.size(); i++) { if (i) r += ", "; r += distinct_on[i]->ToString(); }
        r += ") ";
      }
    }
    for (size_t i = 0; i < select_list.size(); i++) {
      if (i) r += ", ";
      r += select_list[i]->ToString();
      if (!select_list[i]->alias.empty()) r += " AS " + QuoteIdentifierIfNeeded(select_list[i]->alias);
    }
    if (from && from->kind != TableRefKind::EMPTY) r += " FROM " + from->ToString();
    if (where) r += " WHERE " + where->ToString();
    if (!groups.empty() || group_by_all) {
      r += " GROUP BY ";
      if (group_by_all) r += "ALL";
      else for (size_t i = 0; i < groups.size(); i++) { if (i) r += ", "; r += groups[i]->ToString(); }
    }
    if (having) r += " HAVING " + having->ToString();
    if (qualify) r += " QUALIFY " + qualify->ToString();
    r += ModifiersToString(*this);
    return r;
  }
  return r;
}

std::string SelectStatement::ToString() const { return node->ToString(); }

std::unique_ptr<SelectStatement> SelectStatement::Copy() const {
  // re-parse from string (simplest robust approach)
  auto s = Parser::ParseSelectFromString(ToString());
  return s;
}
