LogicalType Catalog::ResolveType(const LogicalType &t) {
  if (t.id == TypeId::INVALID && t.info && !t.info->alias.empty()) {
    auto te = FindType("", "", t.info->alias);
    if (!te) {
      std::string n = t.info->alias;
      if (IEquals(n, "json")) {
        throw CatalogException("Type with name \"JSON\" is not in the catalog, but it exists in the json extension.\n\nPlease try installing and loading the json extension by running:\nINSTALL json;\nLOAD json;\n\nAlternatively, consider enabling auto-install and auto-load by running:\nSET autoinstall_known_extensions=1;\nSET autoload_known_extensions=1;");
      }
      throw CatalogException("Type with name " + n + " does not exist!\nDid you mean \"" + n + "\"?");
    }
    return te->type;
  }
  if (t.info && !t.info->children.empty()) {
    LogicalType r = t;
    r.info = std::make_shared<TypeInfo>(*t.info);
    for (auto &c : r.info->children) c = ResolveType(c);
    return r;
  }
  return t;
}

// ---------------------------------------------------------------- similarity
double JaroWinkler(const std::string &s1, const std::string &s2) {
  if (s1.empty() && s2.empty()) return 1.0;
  if (s1.empty() || s2.empty()) return 0.0;
  size_t len1 = s1.size(), len2 = s2.size();
  size_t match_dist = std::max(len1, len2) / 2;
  if (match_dist > 0) match_dist--;
  std::vector<bool> m1(len1, false), m2(len2, false);
  size_t matches = 0;
  for (size_t i = 0; i < len1; i++) {
    size_t start = i > match_dist ? i - match_dist : 0;
    size_t end = std::min(i + match_dist + 1, len2);
    for (size_t j = start; j < end; j++) {
      if (m2[j] || s1[i] != s2[j]) continue;
      m1[i] = m2[j] = true;
      matches++;
      break;
    }
  }
  if (matches == 0) return 0.0;
  size_t t = 0, k = 0;
  for (size_t i = 0; i < len1; i++) {
    if (!m1[i]) continue;
    while (!m2[k]) k++;
    if (s1[i] != s2[k]) t++;
    k++;
  }
  double m = (double)matches;
  double jaro = (m / len1 + m / len2 + (m - t / 2.0) / m) / 3.0;
  size_t prefix = 0;
  for (size_t i = 0; i < std::min({len1, len2, (size_t)4}); i++) { if (s1[i] == s2[i]) prefix++; else break; }
  return jaro + prefix * 0.1 * (1.0 - jaro);
}

std::vector<std::string> TopSimilar(const std::string &name, const std::vector<std::string> &candidates, size_t max, double threshold) {
  std::vector<std::pair<double, std::string>> scored;
  std::string lname = ToLower(name);
  for (auto &c : candidates) {
    double s = JaroWinkler(lname, ToLower(c));
    if (s >= threshold) scored.push_back({s, c});
  }
  std::stable_sort(scored.begin(), scored.end(), [](const std::pair<double, std::string> &a, const std::pair<double, std::string> &b) {
    return a.first > b.first;
  });
  std::vector<std::string> r;
  for (size_t i = 0; i < scored.size() && i < max; i++) r.push_back(scored[i].second);
  return r;
}

std::string SimilarNamesSuggestion(const std::string &name, const std::vector<std::string> &candidates, size_t max) {
  auto top = TopSimilar(name, candidates, max);
  if (top.empty()) return "";
  std::string r = "\nDid you mean \"" + top[0] + "\"?";
  return r;
}
