  for (auto &s : databases["system"]->schemas) r.push_back({"system", s.second});
  for (auto &s : databases["temp"]->schemas) r.push_back({"temp", s.second});
  return r;
}

template <class T>
static std::shared_ptr<T> LookupIn(std::map<std::string, std::shared_ptr<T>> &m, const std::string &name) {
  auto it = m.find(name);
  if (it != m.end()) return it->second;
  for (auto &kv : m) if (IEquals(kv.first, name)) return kv.second;
  return nullptr;
}

#define LOOKUP_IMPL(TYPE, MEMBER, FNAME) \
std::shared_ptr<TYPE> Catalog::FNAME(const std::string &catalog, const std::string &schema, const std::string &name, std::string *found_db, std::string *found_schema) { \
  if (!catalog.empty() || !schema.empty()) { \
    if (!catalog.empty() && !schema.empty()) { auto s = FindSchema(catalog, schema); if (!s) return nullptr; auto r = LookupIn(s->MEMBER, name); if (r && found_db) *found_db = catalog; if (r && found_schema) *found_schema = s->name; return r; } \
    /* one qualifier: schema or database */ \
    auto &db = DefaultDatabase(); \
    auto it = db.schemas.find(schema); \
    if (it != db.schemas.end()) { auto r = LookupIn(it->second->MEMBER, name); if (r) { if (found_db) *found_db = db.name; if (found_schema) *found_schema = it->first; return r; } } \
    auto other = FindDatabase(schema); \
    if (other) { auto r = LookupIn(other->schemas["main"]->MEMBER, name); if (r) { if (found_db) *found_db = other->name; if (found_schema) *found_schema = "main"; return r; } } \
    auto tmp = databases["temp"]->schemas.find(schema); \
    if (tmp != databases["temp"]->schemas.end()) { auto r = LookupIn(tmp->second->MEMBER, name); if (r) { if (found_db) *found_db = "temp"; if (found_schema) *found_schema = "main"; return r; } } \
    auto sys = databases["system"]->schemas.find(schema); \
    if (sys != databases["system"]->schemas.end()) { auto r = LookupIn(sys->second->MEMBER, name); if (r) { if (found_db) *found_db = "system"; if (found_schema) *found_schema = schema; return r; } } \
    return nullptr; \
  } \
  /* unqualified: temp first, then default schema, then search path */ \
  { auto r = LookupIn(databases["temp"]->schemas["main"]->MEMBER, name); if (r) { if (found_db) *found_db = "temp"; if (found_schema) *found_schema = "main"; return r; } } \
  auto &db = DefaultDatabase(); \
  { auto it = db.schemas.find(default_schema); if (it != db.schemas.end()) { auto r = LookupIn(it->second->MEMBER, name); if (r) { if (found_db) *found_db = db.name; if (found_schema) *found_schema = default_schema; return r; } } } \
  for (auto &sp : search_path) { auto s = FindSchema("", sp); if (s) { auto r = LookupIn(s->MEMBER, name); if (r) { if (found_db) *found_db = db.name; if (found_schema) *found_schema = s->name; return r; } } } \
  { auto r = LookupIn(databases["system"]->schemas["main"]->MEMBER, name); if (r) { if (found_db) *found_db = "system"; if (found_schema) *found_schema = "main"; return r; } } \
  { auto r = LookupIn(databases["system"]->schemas["pg_catalog"]->MEMBER, name); if (r) { if (found_db) *found_db = "system"; if (found_schema) *found_schema = "pg_catalog"; return r; } } \
  return nullptr; \
}

LOOKUP_IMPL(TableEntry, tables, FindTable)
LOOKUP_IMPL(ViewEntry, views, FindView)

std::shared_ptr<SequenceEntry> Catalog::FindSequence(const std::string &catalog, const std::string &schema, const std::string &name) {
  if (!schema.empty()) { auto s = FindSchema(catalog, schema); if (!s) return nullptr; return LookupIn(s->sequences, name); }
  auto r = LookupIn(databases["temp"]->schemas["main"]->sequences, name);
  if (r) return r;
  auto &db = DefaultDatabase();
  auto it = db.schemas.find(default_schema);
  if (it != db.schemas.end()) { r = LookupIn(it->second->sequences, name); if (r) return r; }
  for (auto &sp : search_path) { auto s = FindSchema("", sp); if (s) { r = LookupIn(s->sequences, name); if (r) return r; } }
  return nullptr;
}
std::shared_ptr<MacroEntry> Catalog::FindMacro(const std::string &catalog, const std::string &schema, const std::string &name) {
  if (!schema.empty()) { auto s = FindSchema(catalog, schema); if (!s) return nullptr; return LookupIn(s->macros, name); }
  auto r = LookupIn(databases["temp"]->schemas["main"]->macros, name);
  if (r) return r;
  auto &db = DefaultDatabase();
  auto it = db.schemas.find(default_schema);
  if (it != db.schemas.end()) { r = LookupIn(it->second->macros, name); if (r) return r; }
  for (auto &sp : search_path) { auto s = FindSchema("", sp); if (s) { r = LookupIn(s->macros, name); if (r) return r; } }
  r = LookupIn(databases["system"]->schemas["main"]->macros, name);
  return r;
}
std::shared_ptr<TypeEntry> Catalog::FindType(const std::string &catalog, const std::string &schema, const std::string &name) {
  if (!schema.empty()) { auto s = FindSchema(catalog, schema); if (!s) return nullptr; return LookupIn(s->types, name); }
  auto r = LookupIn(databases["temp"]->schemas["main"]->types, name);
  if (r) return r;
  auto &db = DefaultDatabase();
  auto it = db.schemas.find(default_schema);
  if (it != db.schemas.end()) { r = LookupIn(it->second->types, name); if (r) return r; }
  for (auto &sp : search_path) { auto s = FindSchema("", sp); if (s) { r = LookupIn(s->types, name); if (r) return r; } }
  return nullptr;
}
std::shared_ptr<IndexEntry> Catalog::FindIndex(const std::string &name) {
  for (auto &sc : AllSchemas()) { auto r = LookupIn(sc.second->indexes, name); if (r) return r; }
  return nullptr;
}

SchemaEntry &Catalog::ResolveSchemaForCreate(const std::string &catalog, const std::string &schema, bool temporary) {
  if (temporary) return *databases["temp"]->schemas["main"];
  if (!catalog.empty()) {
    auto db = FindDatabase(catalog);
    if (!db) throw CatalogException("Catalog with name " + catalog + " does not exist!");
    auto it = db->schemas.find(schema.empty() ? "main" : schema);
    if (it == db->schemas.end()) throw CatalogException("Schema with name " + schema + " does not exist!");
    return *it->second;
  }
  if (!schema.empty()) {
    if (schema == "temp") return *databases["temp"]->schemas["main"];
    auto s = FindSchema("", schema);
    if (!s) throw CatalogException("Schema with name " + schema + " does not exist!");
    return *s;
  }
  auto &db = DefaultDatabase();
  auto it = db.schemas.find(default_schema);
  if (it == db.schemas.end()) throw CatalogException("Schema with name " + default_schema + " does not exist!");
  return *it->second;
}

std::vector<std::string> Catalog::AllTableLikeNames() {
  std::vector<std::string> names;
  for (auto &sc : AllSchemas()) {
    for (auto &t : sc.second->tables) names.push_back(t.first);
    for (auto &v : sc.second->views) names.push_back(v.first);
  }
  return names;
}
std::vector<std::string> Catalog::AllEntryNames() { return AllTableLikeNames(); }

LogicalType Catalog::ResolveType(const LogicalType &t) {
  if (t.id == TypeId::INVALID && t.info && !t.info->alias.empty()) {
    auto te = FindType("", "", t.info->alias);
    if (!te) {
      std::string n = t.info->alias;
      if (IEquals(n, "json")) {
        throw CatalogException("Type with name \"JSON\" is not in the catalog, but it exists in the json extension.\n\nPlease try installing and loading the json extension by running:\nINSTALL json;\nLOAD json;\n\nAlternatively, consider enabling auto-install and auto-load by running:\nSET autoinstall_known_extensions=1;\nSET autoload_known_extensions=1;");
      }
      throw CatalogException("Type with name " + n + " does not exist!\nDid you mean \"" + n + "\"?");
    }
    return te->type;
  }
  if (t.info && !t.info->children.empty()) {
    LogicalType r = t;
    r.info = std::make_shared<TypeInfo>(*t.info);
    for (auto &c : r.info->children) c = ResolveType(c);
    return r;
  }
  return t;
}

// ---------------------------------------------------------------- similarity
double JaroWinkler(const std::string &s1, const std::string &s2) {
  if (s1.empty() && s2.empty()) return 1.0;
  if (s1.empty() || s2.empty()) return 0.0;
  size_t len1 = s1.size(), len2 = s2.size();
  size_t match_dist = std::max(len1, len2) / 2;
  if (match_dist > 0) match_dist--;
  std::vector<bool> m1(len1, false), m2(len2, false);
  size_t matches = 0;
  for (size_t i = 0; i < len1; i++) {
    size_t start = i > match_dist ? i - match_dist : 0;
    size_t end = std::min(i + match_dist + 1, len2);
    for (size_t j = start; j < end; j++) {
      if (m2[j] || s1[i] != s2[j]) continue;
      m1[i] = m2[j] = true;
      matches++;
      break;
    }
  }
  if (matches == 0) return 0.0;
  size_t t = 0, k = 0;
  for (size_t i = 0; i < len1; i++) {
    if (!m1[i]) continue;
    while (!m2[k]) k++;
    if (s1[i] != s2[k]) t++;
    k++;
  }
  double m = (double)matches;
  double jaro = (m / len1 + m / len2 + (m - t / 2.0) / m) / 3.0;
  size_t prefix = 0;
  for (size_t i = 0; i < std::min({len1, len2, (size_t)4}); i++) { if (s1[i] == s2[i]) prefix++; else break; }
  return jaro + prefix * 0.1 * (1.0 - jaro);
}

std::vector<std::string> TopSimilar(const std::string &name, const std::vector<std::string> &candidates, size_t max, double threshold) {
  std::vector<std::pair<double, std::string>> scored;
  std::string lname = ToLower(name);
  for (auto &c : candidates) {
    double s = JaroWinkler(lname, ToLower(c));
    if (s >= threshold) scored.push_back({s, c});
  }
  std::stable_sort(scored.begin(), scored.end(), [](const std::pair<double, std::string> &a, const std::pair<double, std::string> &b) {
    return a.first > b.first;
  });
  std::vector<std::string> r;
  for (size_t i = 0; i < scored.size() && i < max; i++) r.push_back(scored[i].second);
  return r;
}

std::string SimilarNamesSuggestion(const std::string &name, const std::vector<std::string> &candidates, size_t max) {
  auto top = TopSimilar(name, candidates, max);
  if (top.empty()) return "";
  std::string r = "\nDid you mean \"" + top[0] + "\"?";
  return r;
}
