Value NormalizeLiteral(const Value &v) {
  Value r = v;
  if (r.type.id == TypeId::STRING_LITERAL) r.type = LogicalType(TypeId::VARCHAR);
  if (r.type.id == TypeId::INTEGER_LITERAL) r.type = LogicalType(TypeId::INTEGER);
  return r;
}

static LogicalType Normalize(const LogicalType &t) {
  if (t.id == TypeId::STRING_LITERAL) return LogicalType(TypeId::VARCHAR);
  if (t.id == TypeId::INTEGER_LITERAL) return LogicalType(TypeId::INTEGER);
  if (t.id == TypeId::SQLNULL) return LogicalType(TypeId::INTEGER);
  return t;
}

LogicalType UnifyTypes(const std::vector<LogicalType> &types) {
  LogicalType r(TypeId::SQLNULL);
  for (auto &t : types) r = MaxLogicalType(r, t);
  if (r.id == TypeId::SQLNULL) return LogicalType(TypeId::INTEGER);
  return Normalize(r);
}

LogicalType CommonTypeForComparison(const LogicalType &a, const LogicalType &b) {
  if (a.id == TypeId::SQLNULL) return Normalize(b);
  if (b.id == TypeId::SQLNULL) return Normalize(a);
  if (a == b) return a;
  bool as = a.IsStringLike(), bs = b.IsStringLike();
  if (as && !bs) return b.id == TypeId::INTEGER_LITERAL ? LogicalType(TypeId::INTEGER) : b;
  if (bs && !as) return a.id == TypeId::INTEGER_LITERAL ? LogicalType(TypeId::INTEGER) : a;
  if (a.id == TypeId::BOOLEAN && b.IsNumeric()) return a;
  if (b.id == TypeId::BOOLEAN && a.IsNumeric()) return b;
  if (a.id == TypeId::ENUM && b.id == TypeId::ENUM) return LogicalType(TypeId::VARCHAR);
  if (a.id == TypeId::ENUM) return b.IsStringLike() ? a : LogicalType(TypeId::VARCHAR);
  if (b.id == TypeId::ENUM) return a.IsStringLike() ? b : LogicalType(TypeId::VARCHAR);
  return Normalize(MaxLogicalType(a, b));
}

