// ---------------------------------------------------------------- helpers
static BExpr MakeConstant(const Value &v) {
  auto e = std::make_shared<BoundExpr>(BKind::CONSTANT);
  e->constant = v;
  e->type = v.type;
  return e;
}

BExpr Executor::BindCast(BExpr child, const LogicalType &target_in, bool try_cast) {
  LogicalType target = ResolveType(target_in);
  if (child->type == target) return child;
  if (child->kind == BKind::CONSTANT) {
    // constant fold
    Value r;
    if (try_cast) { if (!TryCastValue(child->constant, target, r)) r = Value::Null(target); return MakeConstant(r); }
    // string literal casts are folded (so errors come at bind time)
    if (child->constant.type.id == TypeId::STRING_LITERAL || child->constant.type.id == TypeId::INTEGER_LITERAL || child->constant.is_null) {
      Value casted = CastValue(child->constant, target, false);
      return MakeConstant(casted);
    }
  }
  auto e = std::make_shared<BoundExpr>(BKind::CAST);
  e->children.push_back(child);
  e->type = target;
  e->try_cast = try_cast;
  return e;
}

static bool IsIntegerLiteralExpr(const BExpr &e) {
  return e->kind == BKind::CONSTANT && e->constant.type.id == TypeId::INTEGER_LITERAL;
}
static bool IsStringLiteralExpr(const BExpr &e) {
  return e->kind == BKind::CONSTANT && e->constant.type.id == TypeId::STRING_LITERAL;
}

// cast a literal to a target type if it fits, used for INTEGER_LITERAL adaptation
static bool LiteralFits(const Value &v, const LogicalType &t) {
  if (!t.IsInteger()) return false;
  Value r;
  return TryCastValue(NormalizeLiteral(v), t, r);
}

BExpr Executor::BindComparison(const std::string &op, BExpr l, BExpr r, int64_t pos) {
  LogicalType lt = l->type, rt = r->type;
  LogicalType common;
  if (IsIntegerLiteralExpr(l) && rt.IsInteger() && LiteralFits(l->constant, rt)) common = rt;
  else if (IsIntegerLiteralExpr(r) && lt.IsInteger() && LiteralFits(r->constant, lt)) common = lt;
  else if (IsIntegerLiteralExpr(l) && rt.id == TypeId::DECIMAL) common = MaxLogicalType(LogicalType(TypeId::INTEGER), rt);
  else if (IsIntegerLiteralExpr(r) && lt.id == TypeId::DECIMAL) common = MaxLogicalType(lt, LogicalType(TypeId::INTEGER));
  else common = CommonTypeForComparison(lt, rt);
  if (common.id == TypeId::SQLNULL) common = LogicalType(TypeId::INTEGER);
  auto e = std::make_shared<BoundExpr>(BKind::COMPARISON);
  e->op = op;
  e->position = pos;
  try {
    e->children.push_back(BindCast(l, common, false));
    e->children.push_back(BindCast(r, common, false));
  } catch (DBException &ex) {
    if (ex.position < 0) ex.position = pos;
    throw;
  }
  e->type = LogicalType(TypeId::BOOLEAN);
  return e;
}

static std::string ArithOpName(const std::string &op) {
  if (op == "+") return "addition";
  if (op == "-") return "subtraction";
  if (op == "*") return "multiplication";
  if (op == "//") return "division";
  if (op == "%") return "modulo";
  return op;
}

void CheckOverflow(const std::string &op, const Value &a, const Value &b, const LogicalType &t, int128_t result) {
  if (!t.IsInteger() || t.id == TypeId::HUGEINT || t.id == TypeId::UHUGEINT) return;
  if (result < NumericMin(t.id) || result > NumericMax(t.id)) {
    throw OutOfRangeException("Overflow in " + ArithOpName(op) + " of " + t.ToStringInternal() + " (" + a.ToString() + " " + op + " " + b.ToString() + ")!");
  }
}

static LogicalType DecimalOf(const LogicalType &t) {
  if (t.id == TypeId::DECIMAL) return t;
  switch (t.id) {
  case TypeId::TINYINT: case TypeId::UTINYINT: return LogicalType::Decimal(3, 0);
  case TypeId::SMALLINT: case TypeId::USMALLINT: return LogicalType::Decimal(5, 0);
  case TypeId::INTEGER: case TypeId::UINTEGER: case TypeId::INTEGER_LITERAL: return LogicalType::Decimal(10, 0);
  case TypeId::BIGINT: return LogicalType::Decimal(19, 0);
  case TypeId::UBIGINT: return LogicalType::Decimal(20, 0);
  default: return LogicalType::Decimal(38, 0);
  }
}

BExpr Executor::BindArithmetic(const std::string &op, BExpr l, BExpr r, int64_t pos) {
  LogicalType lt = l->type, rt = r->type;
  auto fail = [&]() {
    std::string lname = lt.ToString(), rname = rt.ToString();
