    else if (op == "-") candidates = "\t-(" + Normalize(lt).ToString() + ", " + Normalize(lt).ToString() + ") -> " + Normalize(lt).ToString() + "\n";
    else candidates = "\t" + op + "(" + Normalize(lt).ToString() + ", " + Normalize(lt).ToString() + ") -> " + Normalize(lt).ToString() + "\n";
    if (lt.IsStringLike() && !rt.IsStringLike()) {
      std::string rn = Normalize(rt).ToString();
      candidates = "\t" + op + "(" + (op == "+" ? "DATE, " + rn + ") -> DATE\n\t+(" : "") + rn + ", " + rn + ") -> " + rn + "\n";
      if (op != "+") candidates = "\t" + op + "(" + rn + ", " + rn + ") -> " + rn + "\n";
    }
    BinderException e("Could not choose a best candidate function for the function call \"" + op + "(" + lname + ", " + rname + ")\". In order to select one, please add explicit type casts.\n\tCandidate functions:\n" + candidates + "\n");
    e.position = pos;
    throw e;
  };
  auto make = [&](const LogicalType &result, const LogicalType &castl, const LogicalType &castr) {
    auto e = std::make_shared<BoundExpr>(BKind::ARITH);
    e->op = op;
    e->position = pos;
    e->children.push_back(castl.id == TypeId::INVALID ? l : BindCast(l, castl, false));
    e->children.push_back(castr.id == TypeId::INVALID ? r : BindCast(r, castr, false));
    e->type = result;
    return e;
  };
  LogicalType none(TypeId::INVALID);
  // NULL handling
  if (lt.id == TypeId::SQLNULL && rt.id == TypeId::SQLNULL) return make(LogicalType(TypeId::INTEGER), none, none);
  if (lt.id == TypeId::SQLNULL) { if (rt.IsStringLike()) fail(); LogicalType t = Normalize(rt); if (op == "/" || op == "^" || op == "**") t = LogicalType(TypeId::DOUBLE); return make(t, none, none); }
  if (rt.id == TypeId::SQLNULL) { if (lt.IsStringLike()) fail(); LogicalType t = Normalize(lt); if (op == "/" || op == "^" || op == "**") t = LogicalType(TypeId::DOUBLE); return make(t, none, none); }
  // string literal with numeric: try casting literal to number
  if (lt.IsStringLike() || rt.IsStringLike()) {
