    if (lt.IsStringLike() && rt.IsStringLike()) fail();
    if (lt.IsStringLike() && (rt.IsTemporal())) { /* interval/date + string literal: cast string to the temporal */ }
    fail();
  }
  // temporal arithmetic
  if (lt.id == TypeId::DATE || rt.id == TypeId::DATE || lt.IsTimestamp() || rt.IsTimestamp() || lt.id == TypeId::INTERVAL || rt.id == TypeId::INTERVAL || lt.id == TypeId::TIME || rt.id == TypeId::TIME) {
    if (op == "+") {
      if (lt.id == TypeId::DATE && rt.IsInteger()) return make(LogicalType(TypeId::DATE), none, LogicalType(TypeId::INTEGER));
      if (rt.id == TypeId::DATE && lt.IsInteger()) return make(LogicalType(TypeId::DATE), LogicalType(TypeId::INTEGER), none);
      if (lt.id == TypeId::DATE && rt.id == TypeId::INTERVAL) return make(LogicalType(TypeId::TIMESTAMP), none, none);
      if (rt.id == TypeId::DATE && lt.id == TypeId::INTERVAL) return make(LogicalType(TypeId::TIMESTAMP), none, none);
      if (lt.id == TypeId::DATE && rt.id == TypeId::TIME) return make(LogicalType(TypeId::TIMESTAMP), none, none);
      if (rt.id == TypeId::DATE && lt.id == TypeId::TIME) return make(LogicalType(TypeId::TIMESTAMP), none, none);
      if (lt.IsTimestamp() && rt.id == TypeId::INTERVAL) return make(lt, none, none);
      if (rt.IsTimestamp() && lt.id == TypeId::INTERVAL) return make(rt, none, none);
      if (lt.id == TypeId::TIME && rt.id == TypeId::INTERVAL) return make(lt, none, none);
      if (rt.id == TypeId::TIME && lt.id == TypeId::INTERVAL) return make(rt, none, none);
      if (lt.id == TypeId::INTERVAL && rt.id == TypeId::INTERVAL) return make(lt, none, none);
    } else if (op == "-") {
      if (lt.id == TypeId::DATE && rt.IsInteger()) return make(LogicalType(TypeId::DATE), none, LogicalType(TypeId::INTEGER));
      if (lt.id == TypeId::DATE && rt.id == TypeId::DATE) return make(LogicalType(TypeId::BIGINT), none, none);
      if (lt.id == TypeId::DATE && rt.id == TypeId::INTERVAL) return make(LogicalType(TypeId::TIMESTAMP), none, none);
      if (lt.IsTimestamp() && rt.IsTimestamp()) return make(LogicalType(TypeId::INTERVAL), none, none);
      if (lt.IsTimestamp() && rt.id == TypeId::DATE) return make(LogicalType(TypeId::INTERVAL), none, LogicalType(TypeId::TIMESTAMP));
