    return make(LogicalType(TypeId::DOUBLE), LogicalType(TypeId::DOUBLE), LogicalType(TypeId::DOUBLE));
  }
  if (lt.IsFloating() || rt.IsFloating()) {
    LogicalType t = (lt.id == TypeId::DOUBLE || rt.id == TypeId::DOUBLE) ? LogicalType(TypeId::DOUBLE) : LogicalType(TypeId::FLOAT);
    if (op == "//") t = LogicalType(TypeId::DOUBLE);
    return make(t, t, t);
  }
  if (lt.id == TypeId::DECIMAL || rt.id == TypeId::DECIMAL) {
    if (op == "//") return make(LogicalType(TypeId::DOUBLE), LogicalType(TypeId::DOUBLE), LogicalType(TypeId::DOUBLE));
    LogicalType dl = DecimalOf(lt), dr = DecimalOf(rt);
    LogicalType result;
    if (op == "*") {
      int w = dl.width + dr.width, s = dl.scale + dr.scale;
      if (w > 38) { w = 38; }
      if (s > 38) s = 38;
      result = LogicalType::Decimal(w, s);
      // DuckDB: if result width exceeds, converts to DOUBLE? It caps; keep decimals
      return make(result, dl, dr);
    }
    int s = std::max(dl.scale, dr.scale);
    int w = std::max(dl.width - dl.scale, dr.width - dr.scale) + s + (op == "%" ? 0 : 1);
    if (w > 38) w = 38;
    result = LogicalType::Decimal(w, s);
    LogicalType cl = LogicalType::Decimal(std::min(38, dl.width + (s - dl.scale)), s);
    LogicalType cr = LogicalType::Decimal(std::min(38, dr.width + (s - dr.scale)), s);
    if (cl.width < cl.scale) cl.width = cl.scale;
    if (cr.width < cr.scale) cr.width = cr.scale;
    return make(result, cl, cr);
  }
  // integers
  LogicalType t;
  if (IsIntegerLiteralExpr(l) && !IsIntegerLiteralExpr(r)) t = LiteralFits(l->constant, rt) ? rt : MaxLogicalType(lt, rt);
  else if (IsIntegerLiteralExpr(r) && !IsIntegerLiteralExpr(l)) t = LiteralFits(r->constant, lt) ? lt : MaxLogicalType(lt, rt);
  else t = Normalize(MaxLogicalType(lt, rt));
  if (op == "<<" || op == ">>" || op == "&" || op == "|" || op == "#") { return make(t, t, t); }
  return make(t, t, t);
}

// ---------------------------------------------------------------- column binding
bool Executor::TryBindColumn(const std::vector<std::string> &names, BindContext &context, BExpr &result, int depth) {
  // lambda params
  for (int si = (int)context.lambda_scopes.size() - 1; si >= 0; si--) {
    auto &scope = context.lambda_scopes[si];
    for (size_t pi = 0; pi < scope.size(); pi++) {
      if (IEquals(scope[pi], names[0])) {
        auto e = std::make_shared<BoundExpr>(BKind::LAMBDA_PARAM);
        e->lambda_depth = (int)context.lambda_scopes.size() - 1 - si;  // 0 = innermost
        e->lambda_index = (int)pi;
        e->type = LogicalType(TypeId::ANY);
        e->name = names[0];
        result = e;
        // struct field access on lambda param
        for (size_t k = 1; k < names.size(); k++) {
          std::vector<BExpr> args = {result, MakeConstant(Value::Varchar(names[k]))};
          result = BindScalarCall("struct_extract", args, nullptr, context);
        }
        return true;
      }
    }
  }
  // try [table.]column
  auto make_col = [&](const Binding &b, size_t col) {
    auto e = std::make_shared<BoundExpr>(depth == 0 ? BKind::COLUMN : BKind::OUTER_COLUMN);
    e->index = b.offset + (int)col;
    e->type = b.types[col];
    e->ctx = &context;
    e->name = b.names[col];
    return e;
  };
  // using columns: unqualified name resolves to merged column
  if (names.size() == 1 || true) {
    const std::string &col = names.size() == 1 ? names[0] : names[1];
    if (names.size() == 1) {
      auto um = context.using_map.find(ToLower(col));
      if (um != context.using_map.end() && !um->second.empty()) {
        // find binding containing index
        int idx = um->second[0];
        for (auto &b : context.bindings) {
          if (idx >= b.offset && idx < b.offset + (int)b.names.size()) {
            result = make_col(b, idx - b.offset);
            return true;
          }
        }
      }
      // search all bindings
      std::vector<std::pair<const Binding *, size_t>> matches;
      for (auto &b : context.bindings) {
        for (size_t i = 0; i < b.names.size(); i++) {
          if (IEquals(b.names[i], col)) { matches.push_back({&b, i}); break; }
        }
      }
      if (matches.size() > 1) {
        // check if all matches are the same hidden using column
        std::string cands;
        for (auto &m : matches) cands += "\n\"" + m.first->alias + "." + m.first->names[m.second] + "\"";
        throw BinderException("Ambiguous reference to column name \"" + col + "\" (use: " + (matches[0].first->alias.empty() ? "" : "\"" + matches[0].first->alias + "." + col + "\" or \"" + matches[1].first->alias + "." + col + "\"") + ")");
      }
      if (matches.size() == 1) { result = make_col(*matches[0].first, matches[0].second); return true; }
      return false;
    }
    // qualified: names[0] could be table alias
    const Binding *b = context.FindBinding(names[0]);
    if (b) {
      for (size_t i = 0; i < b->names.size(); i++) {
        if (IEquals(b->names[i], names[1])) {
          result = make_col(*b, i);
          for (size_t k = 2; k < names.size(); k++) {
            std::vector<BExpr> args = {result, MakeConstant(Value::Varchar(names[k]))};
            result = BindScalarCall("struct_extract", args, nullptr, context);
          }
          return true;
        }
      }
      // table exists but column doesn't
      std::string cands;
      std::vector<std::string> cnames(b->names.begin(), b->names.end());
      auto top = TopSimilar(names[1], cnames, 1, 0.0);
      std::string cand = top.empty() ? "" : "\"" + top[0] + "\"";
      BinderException e("Table \"" + names[0] + "\" does not have a column named \"" + names[1] + "\"\n\nCandidate bindings: : " + cand);
      throw e;
    }
    // names[0] might be a column (struct) -> struct_extract chain
    for (auto &bb : context.bindings) {
      for (size_t i = 0; i < bb.names.size(); i++) {
        if (IEquals(bb.names[i], names[0])) {
          result = make_col(bb, i);
          for (size_t k = 1; k < names.size(); k++) {
            std::vector<BExpr> args = {result, MakeConstant(Value::Varchar(names[k]))};
            result = BindScalarCall("struct_extract", args, nullptr, context);
          }
          return true;
        }
      }
    }
    // schema.table.column
    if (names.size() >= 3) {
      const Binding *b2 = context.FindBinding(names[1]);
      if (b2) {
        for (size_t i = 0; i < b2->names.size(); i++) {
          if (IEquals(b2->names[i], names[2])) {
            result = make_col(*b2, i);
            for (size_t k = 3; k < names.size(); k++) {
              std::vector<BExpr> args = {result, MakeConstant(Value::Varchar(names[k]))};
              result = BindScalarCall("struct_extract", args, nullptr, context);
            }
            return true;
          }
        }
      }
    }
  }
  return false;
}

BExpr Executor::BindColumnRef(const Expr &e, BindContext &context) {
  BExpr result;
  // aggregate stage: check group expressions / aliases
  if (context.in_aggregate_stage) {
    std::string key = e.ToString();
    for (auto &g : context.group_exprs) {
      if (g.first == key) {
        auto c = std::make_shared<BoundExpr>(BKind::COLUMN);
        c->index = g.second;
        c->type = context.bindings[0].types[g.second];
        c->name = e.names.back();
        return c;
      }
    }
  }
  if (context.allow_select_alias && e.names.size() == 1) {
    for (auto &a : context.select_aliases) {
      if (IEquals(a.first, e.names[0])) {
        auto c = std::make_shared<BoundExpr>(BKind::COLUMN);
        c->index = a.second;
        c->type = context.bindings[0].types[a.second];
        c->name = e.names[0];
        return c;
      }
    }
  }
  BindContext *cur = &context;
  int depth = 0;
  while (cur) {
    if (TryBindColumn(e.names, *cur, result, depth)) {
      if (depth > 0 && result->kind == BKind::COLUMN) result->kind = BKind::OUTER_COLUMN;
      // mark subexpressions of struct_extract chains that are outer columns
      return result;
    }
    if (cur->in_aggregate_stage && cur->bindings.size() > 0 && cur != &context) {
      // outer aggregate-stage context: check group exprs
      std::string key = e.ToString();
      for (auto &g : cur->group_exprs) {
        if (g.first == key) {
          auto c = std::make_shared<BoundExpr>(BKind::OUTER_COLUMN);
          c->index = g.second; c->type = cur->bindings[0].types[g.second]; c->ctx = cur; c->name = e.names.back();
          return c;
        }
      }
    }
    cur = cur->parent;
    depth++;
  }
  // not found: error
  std::string colname = e.names.back();
  std::string full = JoinStrings(e.names, ".");
  if (context.bindings.empty() && !context.parent) {
    BinderException ex("Referenced column \"" + full + "\" was not found because the FROM clause is missing");
    ex.position = e.position;
    throw ex;
  }
  if (context.in_aggregate_stage) {
    // column exists in FROM but not grouped
    BinderException ex("column \"" + colname + "\" must appear in the GROUP BY clause or must be part of an aggregate function.\nEither add it to the GROUP BY list, or use \"ANY_VALUE(" + colname + ")\" if the exact value of \"" + colname + "\" is not important.");
    ex.position = e.position;
    throw ex;
  }
  // candidates
  std::vector<std::string> cands;
  for (BindContext *c = &context; c; c = c->parent) {
    for (auto &b : c->bindings) for (auto &n : b.names) cands.push_back(b.alias.empty() ? n : b.alias + "." + n);
  }
  std::string candstr;
  if (!cands.empty()) {
    auto top = TopSimilar(colname, cands, 1, 0.0);
    // DuckDB lists candidate bindings sorted by similarity, shows top
    std::vector<std::pair<double, std::string>> scored;
    for (auto &c : cands) {
      std::string base = c.substr(c.find('.') == std::string::npos ? 0 : c.find('.') + 1);
      scored.push_back({JaroWinkler(ToLower(colname), ToLower(base)), c});
    }
    std::stable_sort(scored.begin(), scored.end(), [](auto &a, auto &b) { return a.first > b.first; });
    candstr = "\nCandidate bindings: \"" + scored[0].second + "\"";
  }
  BinderException ex("Referenced column \"" + full + "\" not found in FROM clause!" + candstr);
  ex.position = e.position;
  throw ex;
}

// ---------------------------------------------------------------- function binding
static int OverloadCost(const ScalarOverload &ov, const std::vector<LogicalType> &types, const std::vector<BExpr> &args) {
  if (!ov.varargs && types.size() != ov.params.size()) return -1;
  if (ov.varargs && types.size() < ov.params.size()) return -1;
  int total = 0;
  for (size_t i = 0; i < types.size(); i++) {
    const LogicalType &p = i < ov.params.size() ? ov.params[i] : (ov.params.empty() ? LogicalType(TypeId::ANY) : ov.params.back());
    if (p.id == TypeId::ANY) { total += 0; continue; }
    const LogicalType &t = types[i];
    if (t == p) continue;
    if (t.id == TypeId::SQLNULL) { total += 1; continue; }
    if (p.id == TypeId::LIST && t.id == TypeId::LIST && p.child().id == TypeId::ANY) continue;
    if (p.id == TypeId::LIST && t.id == TypeId::ARRAY && p.child().id == TypeId::ANY) { total += 1; continue; }
    if (p.id == TypeId::STRUCT && t.id == TypeId::STRUCT) continue;
    if (p.id == TypeId::MAP && t.id == TypeId::MAP) continue;
    if (p.id == TypeId::UNION && t.id == TypeId::UNION) continue;
    if (p.id == TypeId::ENUM && t.id == TypeId::ENUM) continue;
    if (t.id == TypeId::INTEGER_LITERAL && p.IsNumeric()) {
      if (p.IsInteger()) { if (!LiteralFits(args[i]->constant, p)) { if (p.id == TypeId::BIGINT || p.id == TypeId::HUGEINT) { total += 2; continue; } return -1; } total += (p.id == TypeId::INTEGER ? 0 : 1); continue; }
      total += 5; continue;
    }
    int c = ImplicitCastCost(t, p);
    if (c < 0) {
      if (t.IsStringLike() && p.id == TypeId::VARCHAR) { total += 1; continue; }
      return -1;
    }
    total += c;
  }
  return total;
}

static void ThrowNoMatch(const std::string &name, const ScalarFunction &f, const std::vector<LogicalType> &types, int64_t pos) {
  std::string msg = "No function matches the given name and argument types '" + name + "(" + TypeListToString(types) + ")'. You might need to add explicit type casts.\n\tCandidate functions:\n";
  for (auto &ov : f.overloads) msg += "\t" + ov.Signature(name) + "\n";
  BinderException e(msg);
  e.position = pos;
  throw e;
}

BExpr Executor::BindScalarCall(const std::string &name_in, std::vector<BExpr> args, const Expr *e, BindContext &context) {
  std::string name = ToLower(name_in);
  auto &reg = Functions();
  ScalarFunction *f = reg.FindScalar(name);
  int64_t pos = e ? e->position : -1;
  if (!f) {
    // macro?
    auto macro = catalog.FindMacro("", e ? e->schema : "", name);
    if (macro && !macro->is_table && e) return BindMacroCall(*macro, *e, context, false, false);
    std::vector<std::string> names = reg.AllNames();
    for (auto &sc : catalog.AllSchemas()) for (auto &m : sc.second->macros) names.push_back(m.first);
    auto top = TopSimilar(name, names, 1);
    std::string sugg = top.empty() ? "" : "\nDid you mean \"" + top[0] + "\"?";
    if (reg.FindAgg(name)) {
      // aggregate used where not allowed
      BinderException ex("Aggregate functions are not allowed here");  // generic
      ex.position = pos;
      throw ex;
    }
    CatalogException ex("Scalar Function with name " + name + " does not exist!" + sugg);
    ex.position = pos;
    throw ex;
  }
  std::vector<LogicalType> types;
  for (auto &a : args) types.push_back(a->type);
  // choose overload
  const ScalarOverload *best = nullptr;
  int best_cost = -1;
  bool ambiguous = false;
  for (auto &ov : f->overloads) {
    int c = OverloadCost(ov, types, args);
    if (c < 0) continue;
    if (!best || c < best_cost) { best = &ov; best_cost = c; ambiguous = false; }
    else if (c == best_cost) ambiguous = true;
  }
  if (!best) ThrowNoMatch(name, *f, types, pos);
  (void)ambiguous;
  auto be = std::make_shared<BoundExpr>(BKind::FUNCTION);
  be->op = name;
  be->func = best;
  be->position = pos;
  // cast args
  for (size_t i = 0; i < args.size(); i++) {
    const LogicalType &p = i < best->params.size() ? best->params[i] : (best->params.empty() ? LogicalType(TypeId::ANY) : best->params.back());
    if (p.id == TypeId::ANY || (p.IsNested() && !p.info->children.empty() && p.info->children[0].id == TypeId::ANY)) {
      // normalize literals
      if (args[i]->kind == BKind::CONSTANT && (args[i]->type.id == TypeId::STRING_LITERAL || args[i]->type.id == TypeId::INTEGER_LITERAL)) {
        args[i] = MakeConstant(NormalizeLiteral(args[i]->constant));
      } else if (args[i]->type.id == TypeId::STRING_LITERAL || args[i]->type.id == TypeId::INTEGER_LITERAL) {
        args[i]->type = Normalize(args[i]->type);
      }
      be->children.push_back(args[i]);
      continue;
    }
    if (args[i]->type == p) { be->children.push_back(args[i]); continue; }
    if (args[i]->type.id == TypeId::SQLNULL) { be->children.push_back(MakeConstant(Value::Null(p))); continue; }
    try {
      be->children.push_back(BindCast(args[i], p, false));
    } catch (DBException &ex) {
      if (ex.position < 0) ex.position = pos;
      throw;
    }
  }
  std::vector<LogicalType> final_types;
  for (auto &c : be->children) final_types.push_back(c->type);
  if (best->bind) be->type = best->bind(final_types, be->children, ctx);
  else be->type = best->ret;
  if (e) for (auto &c : e->children) be->arg_names.push_back(c->alias);
  // constant folding for deterministic functions with all-constant args
  bool all_const = !best->volatile_fn && !be->children.empty();
  for (auto &c : be->children) if (c->kind != BKind::CONSTANT) { all_const = false; break; }
  if (all_const && !be->type.IsNested() && be->type.id != TypeId::ANY) {
    try {
      Row dummy;
      Value v = Eval(*be, dummy);
      v.type = be->type;
      if (v.is_null) v = Value::Null(be->type);
      return MakeConstant(v);
    } catch (DBException &ex) {
      if (ex.position < 0) ex.position = pos;
      throw;
    }
  }
  return be;
}

std::vector<BExpr> Executor::BindFunctionArgs(const Expr &e, BindContext &context, bool allow_agg, bool allow_win) {
  std::vector<BExpr> args;
  for (auto &c : e.children) args.push_back(Bind(*c, context, allow_agg, allow_win));
  return args;
}

BExpr Executor::BindMacroCall(MacroEntry &m, const Expr &e, BindContext &context, bool allow_agg, bool allow_win) {
  // find overload by arg count
  size_t positional = 0;
  for (auto &c : e.children) if (c->alias.empty()) positional++;
  const MacroEntry::Overload *ov = nullptr;
  for (auto &o : m.overloads) if (o.params.size() == positional) { ov = &o; break; }
  if (!ov) {
    std::string msg = "Macro function '" + m.name + "(";
    if (!m.overloads.empty()) msg += JoinStrings(m.overloads[0].params, ", ");
    msg += ")' requires ";
    size_t req = m.overloads.empty() ? 0 : m.overloads[0].params.size();
    msg += (req == 1 ? "a single positional argument" : std::to_string(req) + " positional arguments") + ", but " + std::to_string(positional) + " positional argument" + (positional == 1 ? " was" : "s were") + " provided.";
    BinderException ex(msg);
    ex.position = e.position;
    throw ex;
  }
  if (std::find(macro_stack.begin(), macro_stack.end(), m.name) != macro_stack.end()) {
    throw BinderException("Recursive macro definition!");
  }
  // substitute parameters in expression
  ExprPtr body = Parser::ParseExpressionFromString(ov->expr);
  std::map<std::string, const Expr *> subs;
  size_t pi = 0;
  for (auto &c : e.children) {
    if (c->alias.empty()) subs[ov->params[pi++]] = c.get();
    else subs[c->alias] = c.get();
  }
  std::map<std::string, ExprPtr> defaults;
  for (auto &d : ov->defaults) if (!subs.count(d.first)) { defaults[d.first] = Parser::ParseExpressionFromString(d.second); subs[d.first] = defaults[d.first].get(); }
  std::function<void(ExprPtr &)> replace = [&](ExprPtr &x) {
    if (!x) return;
    if (x->kind == ExprKind::COLUMN_REF && x->names.size() == 1 && subs.count(ToLower(x->names[0]))) {
      std::string alias = x->alias;
      x = subs[ToLower(x->names[0])]->Copy();
      x->alias = alias;
      return;
    }
    if (x->kind == ExprKind::COLUMN_REF && x->names.size() > 1 && subs.count(ToLower(x->names[0]))) {
      // struct access on param
      ExprPtr base = subs[ToLower(x->names[0])]->Copy();
      for (size_t k = 1; k < x->names.size(); k++) {
        std::vector<ExprPtr> args; args.push_back(std::move(base)); args.push_back(Expr::Constant(Value::Varchar(x->names[k])));
        base = Expr::Function("struct_extract", std::move(args));
      }
      x = std::move(base);
      return;
    }
    for (auto &c : x->children) replace(c);
    if (x->filter) replace(x->filter);
    for (auto &cc : x->case_checks) { replace(cc.when); replace(cc.then); }
    if (x->else_expr) replace(x->else_expr);
    for (auto &o : x->order_bys) replace(o.expr);
    if (x->window) { for (auto &p : x->window->partitions) replace(p); for (auto &o : x->window->orders) replace(o.expr); }
    // subqueries: leave as-is (parameters inside subqueries not substituted) - limitation
  };
  replace(body);
  macro_stack.push_back(m.name);
  BExpr r;
  try {
    r = Bind(*body, context, allow_agg, allow_win);
  } catch (...) { macro_stack.pop_back(); throw; }
  macro_stack.pop_back();
  return r;
}

BExpr Executor::BindFunction(const Expr &e, BindContext &context, bool allow_agg, bool allow_win) {
  std::string name = ToLower(e.op);
  auto &reg = Functions();
  // special forms
  if (name == "coalesce" || name == "ifnull") {
    auto args = BindFunctionArgs(e, context, allow_agg, allow_win);
    std::vector<LogicalType> types;
    for (auto &a : args) types.push_back(a->type);
    LogicalType t = UnifyTypes(types);
    auto be = std::make_shared<BoundExpr>(BKind::FUNCTION);
    be->op = "coalesce";
    static ScalarOverload coalesce_ov;
    coalesce_ov.impl = [](std::vector<Value> &a, ExecContext &, const BoundExpr &) { for (auto &v : a) if (!v.is_null) return v; return a.empty() ? Value() : Value::Null(a[0].type); };
    be->func = &coalesce_ov;
    for (auto &a : args) be->children.push_back(BindCast(a, t, false));
    be->type = t;
    be->position = e.position;
    return be;
  }
  // aggregate?
  AggFunction *agg = reg.FindAgg(name);
  ScalarFunction *sc = reg.FindScalar(name);
  if (agg && !sc) {
    if (!allow_agg) {
      if (context.in_aggregate_stage) {
        // check agg_exprs
      }
      BinderException ex("Aggregate functions are not allowed here");
      ex.position = e.position;
      throw ex;
    }
    // aggregate reference must be pre-registered in context
    std::string key = e.ToString();
    for (BindContext *c = &context; c; c = c->parent) {
      for (auto &a : c->agg_exprs) {
        if (a.first == key) {
          auto be = std::make_shared<BoundExpr>(c == &context ? BKind::COLUMN : BKind::OUTER_COLUMN);
          be->index = a.second;
          be->type = c->bindings[0].types[a.second];
          be->ctx = c;
          be->name = key;
          return be;
        }
      }
    }
    BinderException ex("Aggregate function " + name + " not resolved (internal)");
    ex.position = e.position;
    throw ex;
  }
  // macro takes precedence over builtin? DuckDB: catalog lookup; user macros in main schema shadow? we check builtin first unless schema specified
  if (!e.schema.empty() && e.schema != "main" && e.schema != "pg_catalog") {
    auto macro = catalog.FindMacro("", e.schema, name);
    if (macro && !macro->is_table) return BindMacroCall(*macro, e, context, allow_agg, allow_win);
  }
  if (!sc) {
    auto macro = catalog.FindMacro("", "", name);
    if (macro && !macro->is_table) return BindMacroCall(*macro, e, context, allow_agg, allow_win);
  }
  auto args = BindFunctionArgs(e, context, allow_agg, allow_win);
  return BindScalarCall(name, args, &e, context);
}

BExpr Executor::BindOperator(const Expr &e, BindContext &context, bool allow_agg, bool allow_win) {
  const std::string &op = e.op;
  if (op == "NOT") {
    auto c = Bind(*e.children[0], context, allow_agg, allow_win);
    auto be = std::make_shared<BoundExpr>(BKind::NOT);
    be->children.push_back(BindCast(c, LogicalType(TypeId::BOOLEAN), false));
    be->type = LogicalType(TypeId::BOOLEAN);
    return be;
  }
  if (op == "IS NULL" || op == "IS NOT NULL") {
    auto c = Bind(*e.children[0], context, allow_agg, allow_win);
    auto be = std::make_shared<BoundExpr>(op == "IS NULL" ? BKind::IS_NULL : BKind::IS_NOT_NULL);
    be->children.push_back(c);
    be->type = LogicalType(TypeId::BOOLEAN);
    return be;
  }
  if (op == "IN" || op == "NOT IN") {
    std::vector<BExpr> args;
    for (auto &c : e.children) args.push_back(Bind(*c, context, allow_agg, allow_win));
    std::vector<LogicalType> types;
    for (auto &a : args) types.push_back(a->type);
    LogicalType t = args[0]->type;
    // common type between lhs and all list elements
    for (size_t i = 1; i < args.size(); i++) {
      if (IsIntegerLiteralExpr(args[i]) && t.IsInteger() && LiteralFits(args[i]->constant, t)) continue;
      t = CommonTypeForComparison(t, args[i]->type);
    }
    if (t.id == TypeId::SQLNULL) t = LogicalType(TypeId::INTEGER);
    t = Normalize(t);
    auto be = std::make_shared<BoundExpr>(BKind::IN_LIST);
    be->negated = op == "NOT IN";
    for (auto &a : args) be->children.push_back(BindCast(a, t, false));
    be->type = LogicalType(TypeId::BOOLEAN);
    be->position = e.position;
    return be;
  }
  if (e.children.size() == 1) {
    auto c = Bind(*e.children[0], context, allow_agg, allow_win);
    if (op == "-") {
      auto be = std::make_shared<BoundExpr>(BKind::NEGATE);
      LogicalType t = c->type;
      if (t.id == TypeId::INTEGER_LITERAL) t = LogicalType(TypeId::INTEGER);
      if (!t.IsNumeric() && t.id != TypeId::INTERVAL && t.id != TypeId::SQLNULL) {
        BinderException ex("No function matches the given name and argument types '-(" + c->type.ToString() + ")'. You might need to add explicit type casts.\n\tCandidate functions:\n\t-(TINYINT) -> TINYINT\n\t-(SMALLINT) -> SMALLINT\n\t-(INTEGER) -> INTEGER\n\t-(BIGINT) -> BIGINT\n\t-(HUGEINT) -> HUGEINT\n\t-(FLOAT) -> FLOAT\n\t-(DOUBLE) -> DOUBLE\n\t-(DECIMAL) -> DECIMAL\n\t-(INTERVAL) -> INTERVAL\n");
        ex.position = e.position;
        throw ex;
      }
      be->children.push_back(c);
      be->type = t.id == TypeId::SQLNULL ? LogicalType(TypeId::INTEGER) : t;
      if (c->kind == BKind::CONSTANT) { Row dummy; return MakeConstant(Eval(*be, dummy)); }
      return be;
    }
    if (op == "+") { if (c->type.id == TypeId::INTEGER_LITERAL) c->type = LogicalType(TypeId::INTEGER); return c; }
    if (op == "~") {
      std::vector<BExpr> args = {c};
      return BindScalarCall("~", args, &e, context);
    }
    if (op == "@") {
      std::vector<BExpr> args = {c};
      return BindScalarCall("abs", args, &e, context);
    }
  }
  if (e.children.size() == 2) {
    auto l = Bind(*e.children[0], context, allow_agg, allow_win);
    auto r = Bind(*e.children[1], context, allow_agg, allow_win);
    if (op == "||") {
      std::vector<BExpr> args = {l, r};
      return BindScalarCall("||", args, &e, context);
    }
    if (op == "&" || op == "|" || op == "<<" || op == ">>" || op == "#") {
      std::vector<BExpr> args = {l, r};
      return BindScalarCall(op == "#" ? "xor" : op, args, &e, context);
    }
    if (op == "->>" ) {
      std::vector<BExpr> args = {l, r};
      return BindScalarCall("->>", args, &e, context);
    }
    auto be = BindArithmetic(op, l, r, e.position);
    if (be->children[0]->kind == BKind::CONSTANT && be->children[1]->kind == BKind::CONSTANT) {
      Row dummy;
      Value v = Eval(*be, dummy);
      return MakeConstant(v);
    }
    return be;
  }
  throw BinderException("Unsupported operator " + op);
}

LogicalType Executor::EvalConstantType(const Expr &e) {
  BindContext ctx;
  return Bind(e, ctx)->type;
}

Value EvaluateConstantExpression(Executor &ex, const Expr &e) {
  BindContext ctx;
  auto b = ex.Bind(e, ctx);
  Row dummy;
  Value v = ex.Eval(*b, dummy);
  return NormalizeLiteral(v);
}

// ---------------------------------------------------------------- main Bind
BExpr Executor::Bind(const Expr &e, BindContext &context, bool allow_agg, bool allow_win) {
  switch (e.kind) {
  case ExprKind::CONSTANT: {
    Value v = e.value;
    if (v.type.id == TypeId::INTEGER && !v.is_null) v.type = LogicalType(TypeId::INTEGER_LITERAL);
    auto c = MakeConstant(v);
    c->position = e.position;
    return c;
  }
  case ExprKind::COLUMN_REF: {
    auto r = BindColumnRef(e, context);
    if (r->position < 0) r->position = e.position;
    return r;
  }
  case ExprKind::POSITIONAL_REF: {
    // #n refers to the n-th column of the FROM
    int n = (int)e.index;
    int total = context.TotalColumns();
    if (n < 1 || n > total) { BinderException ex("Positional reference " + std::to_string(n) + " out of range"); ex.position = e.position; throw ex; }
    int idx = n - 1;
    for (auto &b : context.bindings) {
      if (idx >= b.offset && idx < b.offset + (int)b.names.size()) {
        auto c = std::make_shared<BoundExpr>(BKind::COLUMN);
        c->index = idx; c->type = b.types[idx - b.offset]; c->name = b.names[idx - b.offset];
        return c;
      }
    }
    throw BinderException("Positional reference out of range");
  }
  case ExprKind::STAR: {
    BinderException ex("STAR expression is not supported here");
    ex.position = e.position;
    throw ex;
  }
  case ExprKind::FUNCTION: {
    // check for window/aggregate placeholders
    if (context.in_aggregate_stage || !context.agg_exprs.empty()) {
      std::string key = e.ToString();
      for (auto &a : context.agg_exprs) {
        if (a.first == key) {
          auto be = std::make_shared<BoundExpr>(BKind::COLUMN);
          be->index = a.second; be->type = context.bindings[0].types[a.second]; be->name = key;
          return be;
        }
      }
    }
    // lambda functions: bind specially (handled in BindFunction via list functions with lambda args)
    for (auto &c : e.children) {
      if (c->kind == ExprKind::LAMBDA) {
        // bind non-lambda args first to know list type
        std::vector<BExpr> args;
        LogicalType list_type(TypeId::SQLNULL);
        for (auto &c2 : e.children) {
          if (c2->kind == ExprKind::LAMBDA) { args.push_back(nullptr); continue; }
          auto b = Bind(*c2, context, allow_agg, allow_win);
          if (list_type.id == TypeId::SQLNULL && (b->type.id == TypeId::LIST || b->type.id == TypeId::ARRAY)) list_type = b->type;
          args.push_back(b);
        }
        for (size_t i = 0; i < e.children.size(); i++) {
          if (e.children[i]->kind != ExprKind::LAMBDA) continue;
          auto &lam = *e.children[i];
          auto be = std::make_shared<BoundExpr>(BKind::LAMBDA);
          be->lambda_params = lam.lambda_params;
          context.lambda_scopes.push_back(lam.lambda_params);
          // register param types via a temporary: we store element type in be->type for the first param
          be->type = list_type.id == TypeId::LIST || list_type.id == TypeId::ARRAY ? list_type.child() : LogicalType(TypeId::ANY);
          // bind body
          BExpr body;
          try {
            // Set param types: we use a binding trick - LAMBDA_PARAM exprs get type from be->type at eval; for binding of body we need types
            // Push element type into scope info
            lambda_param_types.push_back({be->type, (lam.lambda_params.size() > 1 ? LogicalType(TypeId::BIGINT) : LogicalType(TypeId::ANY))});
            body = Bind(*lam.children[0], context, false, false);
            lambda_param_types.pop_back();
          } catch (...) { context.lambda_scopes.pop_back(); lambda_param_types.pop_back(); throw; }
          context.lambda_scopes.pop_back();
          be->children.push_back(body);
          args[i] = be;
        }
        return BindScalarCall(ToLower(e.op), args, &e, context);
      }
    }
    return BindFunction(e, context, allow_agg, allow_win);
  }
  case ExprKind::WINDOW: {
    std::string key = e.ToString();
    for (BindContext *c = &context; c; c = c->parent) {
      for (auto &w : c->window_exprs) {
        if (w.first == key) {
          auto be = std::make_shared<BoundExpr>(c == &context ? BKind::COLUMN : BKind::OUTER_COLUMN);
          be->index = w.second; be->type = c->bindings[0].types[w.second]; be->ctx = c; be->name = key;
          return be;
        }
      }
    }
    if (!allow_win) {
      BinderException ex("WINDOW functions are not allowed here");
      ex.position = e.position;
      throw ex;
    }
    BinderException ex("Window function not resolved (internal)");
    ex.position = e.position;
    throw ex;
  }
  case ExprKind::OPERATOR: return BindOperator(e, context, allow_agg, allow_win);
  case ExprKind::COMPARISON: {
    auto l = Bind(*e.children[0], context, allow_agg, allow_win);
    auto r = Bind(*e.children[1], context, allow_agg, allow_win);
    auto be = BindComparison(e.op, l, r, e.position);
    if (be->children[0]->kind == BKind::CONSTANT && be->children[1]->kind == BKind::CONSTANT) { Row d; return MakeConstant(Eval(*be, d)); }
    return be;
  }
  case ExprKind::CONJUNCTION: {
    auto be = std::make_shared<BoundExpr>(BKind::CONJUNCTION);
    be->op = e.op;
    for (auto &c : e.children) {
      auto b = Bind(*c, context, allow_agg, allow_win);
      be->children.push_back(BindCast(b, LogicalType(TypeId::BOOLEAN), false));
    }
    be->type = LogicalType(TypeId::BOOLEAN);
    return be;
  }
  case ExprKind::CASE: {
    auto be = std::make_shared<BoundExpr>(BKind::CASE);
    std::vector<BExpr> results;
    std::vector<LogicalType> types;
    for (auto &cc : e.case_checks) {
      auto w = Bind(*cc.when, context, allow_agg, allow_win);
      auto t = Bind(*cc.then, context, allow_agg, allow_win);
      be->cases.push_back({BindCast(w, LogicalType(TypeId::BOOLEAN), false), t});
      types.push_back(t->type);
    }
    BExpr els = e.else_expr ? Bind(*e.else_expr, context, allow_agg, allow_win) : MakeConstant(Value());
    types.push_back(els->type);
    // unify: integer literals adapt
    LogicalType t(TypeId::SQLNULL);
    for (auto &ty : types) t = MaxLogicalType(t, ty);
    if (t.id == TypeId::SQLNULL) t = LogicalType(TypeId::INTEGER);
    t = Normalize(t);
    for (auto &c : be->cases) c.second = BindCast(c.second, t, false);
    be->else_expr = BindCast(els, t, false);
    be->type = t;
    return be;
  }
  case ExprKind::CAST: {
    auto c = Bind(*e.children[0], context, allow_agg, allow_win);
    LogicalType target = ResolveType(e.cast_type);
    try {
      return BindCast(c, target, e.try_cast);
    } catch (DBException &ex) {
      if (ex.position < 0) ex.position = e.children[0]->position >= 0 ? e.children[0]->position : e.position;
      throw;
    }
  }
  case ExprKind::SUBQUERY: {
    auto be = std::make_shared<BoundExpr>(BKind::SUBQUERY);
    be->subquery = std::make_shared<BoundSubquery>();
    be->subquery->stmt = e.subquery.get();
    be->subquery->outer = &context;
    be->sq_type = e.subquery_type;
    be->cmp_op = e.comparison_type;
    be->position = e.position;
    // determine type by binding the subquery's column names/types
    if (e.subquery_type == SubqueryType::SCALAR) {
      // bind to get type: execute lazily; we need the type -> do a dry bind via ExecuteNode with a flag? Simplest: execute with outer context now if uncorrelated; else type ANY
      QueryResult r = ExecuteNode(*e.subquery->node, &context);
      if (r.types.empty()) throw BinderException("Subquery returns no columns");
      if (r.types.size() > 1) {
        // DuckDB: scalar subquery with multiple columns returns a STRUCT
        be->type = LogicalType::Struct(r.names, r.types);
      } else be->type = r.types[0];
      be->subquery->lambda_param_names.clear();
      cached_results[be.get()] = std::make_shared<QueryResult>(std::move(r));
    } else if (e.subquery_type == SubqueryType::ANY || e.subquery_type == SubqueryType::ALL) {
      be->children.push_back(Bind(*e.children[0], context, allow_agg, allow_win));
      QueryResult r = ExecuteNode(*e.subquery->node, &context);
      if (r.types.size() != 1) throw BinderException("Subquery returns " + std::to_string(r.types.size()) + " columns - expected 1");
      LogicalType common = CommonTypeForComparison(be->children[0]->type, r.types[0]);
      if (IsIntegerLiteralExpr(be->children[0]) && r.types[0].IsInteger()) common = r.types[0];
      be->children[0] = BindCast(be->children[0], common, false);
      be->type = LogicalType(TypeId::BOOLEAN);
      be->cmp_op = e.comparison_type;
      cached_results[be.get()] = std::make_shared<QueryResult>(std::move(r));
      be->constant.type = common;  // store common type for casting results
    } else {
      be->type = LogicalType(TypeId::BOOLEAN);
    }
    return be;
  }
  case ExprKind::BETWEEN: {
    auto v = Bind(*e.children[0], context, allow_agg, allow_win);
    auto lo = Bind(*e.children[1], context, allow_agg, allow_win);
    auto hi = Bind(*e.children[2], context, allow_agg, allow_win);
    LogicalType t = CommonTypeForComparison(CommonTypeForComparison(v->type, lo->type), hi->type);
    if (v->type.IsInteger() && IsIntegerLiteralExpr(lo) && IsIntegerLiteralExpr(hi)) t = v->type;
    auto be = std::make_shared<BoundExpr>(BKind::BETWEEN);
    be->children.push_back(BindCast(v, t, false));
    be->children.push_back(BindCast(lo, t, false));
    be->children.push_back(BindCast(hi, t, false));
    be->type = LogicalType(TypeId::BOOLEAN);
    return be;
  }
  case ExprKind::COLLATE: {
    auto c = Bind(*e.children[0], context, allow_agg, allow_win);
    std::string coll = ToLower(e.collation);
    if (coll == "nocase") { std::vector<BExpr> args = {c}; return BindScalarCall("lower", args, nullptr, context); }
    if (coll == "noaccent") { std::vector<BExpr> args = {c}; return BindScalarCall("strip_accents", args, nullptr, context); }
    return c;
  }
  case ExprKind::LAMBDA: {
    BinderException ex("Lambda expressions are only allowed as function arguments");
    ex.position = e.position;
    throw ex;
  }
  case ExprKind::PARAMETER: {
    if (ctx.parameters) {
      std::string key = e.param_name;
      auto it = ctx.parameters->find(key);
      if (it != ctx.parameters->end()) return MakeConstant(it->second);
    }
    BinderException ex("Not all parameters are bound");
    throw ex;
  }
  case ExprKind::DEFAULT: {
    auto be = std::make_shared<BoundExpr>(BKind::DEFAULT);
    be->type = LogicalType(TypeId::SQLNULL);
    return be;
  }
  default: break;
  }
  throw BinderException("Unsupported expression kind");
}
