{"command":"cat > /workspace/src/expr_eval.cpp <<'EOF'
#include "binder.h"
#include <cmath>
#include <algorithm>

bool ValuesEqual(const Value &a, const Value &b) {
  if (a.is_null || b.is_null) return a.is_null && b.is_null;
  return Value::Compare(a, b) == 0;
}
int CompareValuesForSort(const Value &a, const Value &b) { return Value::Compare(a, b); }

static Value Bool(bool b) { return Value::Boolean(b); }

static int128_t AddInterval(int64_t micros, const Interval &iv, bool is_date_based_ts) {
  (void)is_date_based_ts;
  // apply months then days then micros
  int32_t days = TimestampToDate(micros);
  int64_t tod = micros - DateToTimestampMicros(days);
  if (iv.months) {
    DateParts p = DateToYMD(days);
    int64_t total = (int64_t)p.year * 12 + (p.month - 1) + iv.months;
    int32_t ny = (int32_t)(total / 12), nm = (int32_t)(total % 12);
    if (nm < 0) { nm += 12; ny--; }
    nm += 1;
    int dim = DaysInMonth(ny, nm);
    int nd = p.day > dim ? dim : p.day;
    days = DateFromYMD(ny, nm, nd);
  }
  days += iv.days;
  int128_t result = (int128_t)DateToTimestampMicros(days) + tod + iv.micros;
  return result;
}

static Value IntervalArith(const std::string &op, const Value &a, const Value &b, const LogicalType &rt) {
  // a is temporal/interval, b is interval or numeric
  TypeId ta = a.type.id, tb = b.type.id;
  if (ta == TypeId::INTERVAL && tb == TypeId::INTERVAL) {
    Interval r;
    if (op == "+") { r.months = a.interval.months + b.interval.months; r.days = a.interval.days + b.interval.days; r.micros = a.interval.micros + b.interval.micros; }
    else { r.months = a.interval.months - b.interval.months; r.days = a.interval.days - b.interval.days; r.micros = a.interval.micros - b.interval.micros; }
    return Value::IntervalV(r);
  }
  if (ta == TypeId::INTERVAL && (tb != TypeId::INTERVAL) && !LogicalType(tb).IsTemporal()) {
    // interval * number or interval / number
    double f = b.GetDouble();
    Interval r;
    if (op == "*") {
      if (b.type.IsInteger()) { r.months = (int32_t)(a.interval.months * b.ival); r.days = (int32_t)(a.interval.days * b.ival); r.micros = (int64_t)(a.interval.micros * b.ival); }
      else {
        double months = a.interval.months * f;
        r.months = (int32_t)months;
        double days = a.interval.days * f + (months - r.months) * 30;
        r.days = (int32_t)days;
        r.micros = (int64_t)std::llround(a.interval.micros * f + (days - r.days) * 86400000000.0);
      }
    } else {
      if (f == 0) throw OutOfRangeException("Interval division by zero");
      double months = a.interval.months / f;
      r.months = (int32_t)months;
      double days = a.interval.days / f + (months - r.months) * 30;
      r.days = (int32_t)days;
      r.micros = (int64_t)std::llround(a.interval.micros / f + (days - r.days) * 86400000000.0);
    }
    return Value::IntervalV(r);
  }
  if ((tb == TypeId::INTERVAL) && !LogicalType(ta).IsTemporal() && ta != TypeId::INTERVAL) {
    return IntervalArith(op, b, a, rt);
  }
  Interval iv = tb == TypeId::INTERVAL ? b.interval : a.interval;
  const Value &temporal = tb == TypeId::INTERVAL ? a : b;
  if (op == "-") { iv.months = -iv.months; iv.days = -iv.days; iv.micros = -iv.micros; }
  if (temporal.type.id == TypeId::DATE) {
    int64_t micros = DateToTimestampMicros((int32_t)temporal.ival);
    int128_t r = AddInterval(micros, iv, true);
    return Value::Timestamp((int64_t)r);
  }
  if (temporal.type.IsTimestamp()) {
    int64_t us = (int64_t)temporal.ival;
    if (us == INT64_MAX || us == -INT64_MAX) return Value::Timestamp(us, temporal.type.id);
    int128_t r = AddInterval(us, iv, false);
    if (r > INT64_MAX || r < -INT64_MAX) throw OutOfRangeException("Timestamp out of range");
    return Value::Timestamp((int64_t)r, temporal.type.id);
  }
  if (temporal.type.id == TypeId::TIME || temporal.type.id == TypeId::TIME_TZ) {
    int64_t us = (int64_t)temporal.ival + iv.micros;
    us %= 86400000000LL;
    if (us < 0) us += 86400000000LL;
    Value v(temporal.type); v.is_null = false; v.ival = us;
    return v;
  }
  throw BinderException("Unsupported interval arithmetic");
}

Value ComputeArith(const std::string &op, const Value &a, const Value &b, const LogicalType &rt) {
  if (a.is_null || b.is_null) return Value::Null(rt);
  TypeId ta = a.type.id, tb = b.type.id;
  // temporal
  if (ta == TypeId::INTERVAL || tb == TypeId::INTERVAL) return IntervalArith(op, a, b, rt);
  if (ta == TypeId::DATE && tb == TypeId::DATE) {
    if (op == "-") return Value::BigInt((int64_t)a.ival - (int64_t)b.ival);
  }
  if (ta == TypeId::DATE && b.type.IsInteger()) {
    int64_t d = (int64_t)a.ival + (op == "+" ? (int64_t)b.ival : -(int64_t)b.ival);
    if (d < -INT32_MAX + 1 || d > INT32_MAX - 1) throw OutOfRangeException("Date out of range");
    return Value::Date((int32_t)d);
  }
  if (tb == TypeId::DATE && a.type.IsInteger() && op == "+") {
    int64_t d = (int64_t)b.ival + (int64_t)a.ival;
    return Value::Date((int32_t)d);
  }
  if (ta == TypeId::DATE && tb == TypeId::TIME) return Value::Timestamp(DateToTimestampMicros((int32_t)a.ival) + (int64_t)b.ival);
  if (tb == TypeId::DATE && ta == TypeId::TIME) return Value::Timestamp(DateToTimestampMicros((int32_t)b.ival) + (int64_t)a.ival);
  if (a.type.IsTimestamp() && b.type.IsTimestamp() && op == "-") {
    int64_t diff = (int64_t)a.ival - (int64_t)b.ival;
    Interval r;
    r.days = (int32_t)(diff / 86400000000LL);
    r.micros = diff % 86400000000LL;
    return Value::IntervalV(r);
  }
  if (ta == TypeId::TIME && tb == TypeId::TIME && op == "-") {
    Interval r; r.micros = (int64_t)a.ival - (int64_t)b.ival;
    return Value::IntervalV(r);
  }
  // numeric
  if (rt.id == TypeId::DOUBLE || rt.id == TypeId::FLOAT) {
    double x = a.GetDouble(), y = b.GetDouble();
    double r;
    if (op == "+") r = x + y;
    else if (op == "-") r = x - y;
    else if (op == "*") r = x * y;
    else if (op == "/") r = y == 0 ? (x == 0 || std::isnan(x) ? NAN : (x > 0 ? INFINITY : -INFINITY)) : x / y;
    else if (op == "//") { if (y == 0) r = NAN; else r = std::floor(x / y); }
    else if (op == "%") { if (y == 0) r = NAN; else r = std::fmod(x, y); }
    else if (op == "^" || op == "**") r = std::pow(x, y);
    else throw BinderException("Unknown operator " + op);
    if (rt.id == TypeId::FLOAT) {
      if (std::isfinite(r) && std::fabs(r) > 3.4028235e38) throw OutOfRangeException("Overflow in " + op + " of FLOAT");
      return Value::Float((float)r);
    }
    return Value::Double(r);
  }
  if (rt.id == TypeId::DECIMAL) {
    int128_t x = a.ival, y = b.ival;
    // operands already cast to appropriate scales
    int128_t r;
    if (op == "+") r = x + y;
    else if (op == "-") r = x - y;
    else if (op == "*") r = x * y;
    else if (op == "%") { if (y == 0) throw OutOfRangeException("Modulo by zero"); r = x % y; }
    else throw BinderException("Unknown decimal operator " + op);
    int128_t limit = Pow10(rt.width);
    if (r >= limit || r <= -limit) {
      throw OutOfRangeException("Overflow in " + (op == "+" ? std::string("addition") : op == "-" ? std::string("subtraction") : std::string("multiplication")) + " of DECIMAL(" + std::to_string(rt.width) + "," + std::to_string(rt.scale) + ") (" + a.ToString() + " " + op + " " + b.ToString() + ")!");
    }
    return Value::Decimal(r, rt.width, rt.scale);
  }
  // integers
  int128_t x = a.ival, y = b.ival;
  int128_t r;
  if (op == "+") r = x + y;
  else if (op == "-") r = x - y;
  else if (op == "*") {
    r = x * y;
    if (x != 0 && (r / x != y)) throw OutOfRangeException("Overflow in multiplication of " + rt.ToStringInternal() + " (" + a.ToString() + " * " + b.ToString() + ")!");
  }
  else if (op == "//") {
    if (y == 0) throw OutOfRangeException("Division by zero!");
    r = x / y;
  }
  else if (op == "%") {
    if (y == 0) throw OutOfRangeException("Modulo by zero!");
    r = x % y;
  }
  else if (op == "&") r = x & y;
  else if (op == "|") r = x | y;
  else if (op == "#") r = x ^ y;
  else if (op == "<<") { if (y < 0 || y >= 128) r = 0; else r = x << (int)y; }
  else if (op == ">>") { if (y < 0 || y >= 128) r = 0; else r = x >> (int)y; }
  else throw BinderException("Unknown operator " + op);
  CheckOverflow(op, a, b, rt, r);
  Value v(rt); v.is_null = false; v.ival = r;
  return v;
}

Value CastWithError(const Value &v, const LogicalType &target, bool try_cast) {
  return CastValue(v, target, try_cast);
}

Value Executor::EvalLambda(const BoundExpr &lambda, std::vector<Value> args) {
  ctx.lambda_frames.push_back(std::move(args));
  Row dummy;
  Value r;
  try {
    r = Eval(*lambda.children[0], dummy);
  } catch (...) { ctx.lambda_frames.pop_back(); throw; }
  ctx.lambda_frames.pop_back();
  return r;
}

static bool CompareOp(const std::string &op, int c) {
  if (op == "=") return c == 0;
  if (op == "!=" || op == "<>") return c != 0;
  if (op == "<") return c < 0;
  if (op == ">") return c > 0;
  if (op == "<=") return c <= 0;
  if (op == ">=") return c >= 0;
  return false;
}

Value Executor::Eval(const BoundExpr &e, const Row &row) {
  switch (e.kind) {
  case BKind::CONSTANT: return e.constant;
  case BKind::COLUMN: {
    if (e.index < 0 || e.index >= (int)row.size()) throw InternalException("column index out of range");
    return row[e.index];
  }
  case BKind::OUTER_COLUMN: {
    if (!e.ctx || !e.ctx->current_row) throw InternalException("outer column without row");
    const Row &r = *e.ctx->current_row;
    if (e.index < 0 || e.index >= (int)r.size()) throw InternalException("outer column index out of range");
    return r[e.index];
  }
  case BKind::LAMBDA_PARAM: {
    int depth = e.lambda_depth;
    int fi = (int)ctx.lambda_frames.size() - 1 - depth;
    if (fi < 0) throw InternalException("lambda param out of frame");
    auto &frame = ctx.lambda_frames[fi];
    if (e.lambda_index >= (int)frame.size()) return Value();
    return frame[e.lambda_index];
  }
  case BKind::FUNCTION: {
    std::vector<Value> args;
    args.reserve(e.children.size());
    for (auto &c : e.children) {
      if (c->kind == BKind::LAMBDA) { args.push_back(Value()); continue; }
      args.push_back(Eval(*c, row));
    }
    Value r = e.func->impl(args, ctx, e);
    if (r.is_null && r.type.id == TypeId::SQLNULL && e.type.id != TypeId::ANY) r.type = e.type;
    return r;
  }
  case BKind::ARITH: {
    Value a = Eval(*e.children[0], row);
    Value b = Eval(*e.children[1], row);
    try {
      return ComputeArith(e.op, a, b, e.type);
    } catch (DBException &ex) {
      if (ex.position < 0) ex.position = e.position;
      throw;
    }
  }
  case BKind::NEGATE: {
    Value a = Eval(*e.children[0], row);
    if (a.is_null) return Value::Null(e.type);
    Value r = a;
    r.type = e.type;
    if (a.type.IsFloating()) r.dval = -a.dval;
    else if (a.type.id == TypeId::INTERVAL) { r.interval.months = -a.interval.months; r.interval.days = -a.interval.days; r.interval.micros = -a.interval.micros; }
    else {
      if (a.type.IsInteger() && a.ival == NumericMin(a.type.id) && a.type.id != TypeId::HUGEINT) throw OutOfRangeException("Overflow in negation of " + a.type.ToStringInternal() + " (" + a.ToString() + ")!");
      r.ival = -a.ival;
    }
    return r;
  }
  case BKind::CASE: {
    for (auto &c : e.cases) {
      Value w = Eval(*c.first, row);
      if (!w.is_null && w.ival) return Eval(*c.second, row);
    }
    return Eval(*e.else_expr, row);
  }
  case BKind::CAST: {
    Value v = Eval(*e.children[0], row);
    try {
      return CastValue(v, e.type, e.try_cast);
    } catch (DBException &ex) {
      if (ex.position < 0) ex.position = e.position;
      throw;
    }
  }
  case BKind::COMPARISON: {
    Value a = Eval(*e.children[0], row);
    Value b = Eval(*e.children[1], row);
    if (e.op == "IS DISTINCT FROM") return Bool(!ValuesEqual(a, b));
    if (e.op == "IS NOT DISTINCT FROM") return Bool(ValuesEqual(a, b));
    if (a.is_null || b.is_null) return Value::Null(LogicalType(TypeId::BOOLEAN));
    if (a.type.IsFloating() && b.type.IsFloating()) {
      double x = a.dval, y = b.dval;
      if (std::isnan(x) || std::isnan(y)) {
        // NaN == NaN true, NaN greater than everything
        int c = (std::isnan(x) && std::isnan(y)) ? 0 : (std::isnan(x) ? 1 : -1);
        return Bool(CompareOp(e.op, c));
      }
    }
    return Bool(CompareOp(e.op, Value::Compare(a, b)));
  }
  case BKind::CONJUNCTION: {
    bool is_and = e.op == "AND";
    bool has_null = false;
    for (auto &c : e.children) {
      Value v = Eval(*c, row);
      if (v.is_null) { has_null = true; continue; }
      if (is_and && !v.ival) return Bool(false);
      if (!is_and && v.ival) return Bool(true);
    }
    if (has_null) return Value::Null(LogicalType(TypeId::BOOLEAN));
    return Bool(is_and);
  }
  case BKind::NOT: {
    Value v = Eval(*e.children[0], row);
    if (v.is_null) return Value::Null(LogicalType(TypeId::BOOLEAN));
    return Bool(!v.ival);
  }
  case BKind::IS_NULL: return Bool(Eval(*e.children[0], row).is_null);
  case BKind::IS_NOT_NULL: return Bool(!Eval(*e.children[0], row).is_null);
  case BKind::IN_LIST: {
    Value v = Eval(*e.children[0], row);
    if (v.is_null) return Value::Null(LogicalType(TypeId::BOOLEAN));
    bool has_null = false;
    for (size_t i = 1; i < e.children.size(); i++) {
      Value x = Eval(*e.children[i], row);
      if (x.is_null) { has_null = true; continue; }
      if (Value::Compare(v, x) == 0) return Bool(!e.negated);
    }
    if (has_null) return Value::Null(LogicalType(TypeId::BOOLEAN));
    return Bool(e.negated);
  }
  case BKind::BETWEEN: {
    Value v = Eval(*e.children[0], row);
    Value lo = Eval(*e.children[1], row);
    Value hi = Eval(*e.children[2], row);
    if (v.is_null) return Value::Null(LogicalType(TypeId::BOOLEAN));
    // NULL handling: v >= lo AND v <= hi with 3-valued logic
    Value ge = lo.is_null ? Value::Null(LogicalType(TypeId::BOOLEAN)) : Bool(Value::Compare(v, lo) >= 0);
    Value le = hi.is_null ? Value::Null(LogicalType(TypeId::BOOLEAN)) : Bool(Value::Compare(v, hi) <= 0);
    if ((!ge.is_null && !ge.ival) || (!le.is_null && !le.ival)) return Bool(false);
    if (ge.is_null || le.is_null) return Value::Null(LogicalType(TypeId::BOOLEAN));
    return Bool(true);
  }
  case BKind::SUBQUERY: {
    std::shared_ptr<QueryResult> res;
    auto it = cached_results.find(&e);
    if (it != cached_results.end()) res = it->second;
    else {
      // correlated: execute with current row
      BindContext *outer = e.subquery->outer;
      const Row *saved = outer->current_row;
      outer->current_row = &row;
      subquery_depth++;
      try {
        res = std::make_shared<QueryResult>(ExecuteNode(*e.subquery->stmt->node, outer));
      } catch (...) { outer->current_row = saved; subquery_depth--; throw; }
      subquery_depth--;
      outer->current_row = saved;
    }
    switch (e.sq_type) {
    case SubqueryType::SCALAR: {
      if (res->rows.empty()) return Value::Null(e.type);
      if (res->rows.size() > 1) throw InvalidInputException("More than one row returned by a subquery used as an expression - scalar subqueries can only return a single row.\n\nUse \"SET scalar_subquery_error_on_multiple_rows=false\" to revert to previous behavior of returning a random row.");
      if (res->types.size() > 1) {
        return Value::Struct(res->names, res->rows[0]);
      }
      Value v = res->rows[0][0];
      if (e.type.id != TypeId::ANY && v.type != e.type && !v.is_null) v = CastValue(v, e.type, true);
      return v;
    }
    case SubqueryType::EXISTS: return Bool(!res->rows.empty());
    case SubqueryType::NOT_EXISTS: return Bool(res->rows.empty());
    case SubqueryType::ANY: case SubqueryType::ALL: {
      Value v = Eval(*e.children[0], row);
      bool is_any = e.sq_type == SubqueryType::ANY;
      if (res->rows.empty()) return Bool(!is_any);
      if (v.is_null) return Value::Null(LogicalType(TypeId::BOOLEAN));
      bool has_null = false;
      LogicalType common = e.constant.type.id == TypeId::INVALID ? v.type : e.constant.type;
      for (auto &r : res->rows) {
        Value x = r[0];
        if (x.is_null) { has_null = true; continue; }
        if (x.type != common && common.id != TypeId::ANY) x = CastValue(x, common, false);
        Value vv = v.type != common && common.id != TypeId::ANY ? CastValue(v, common, false) : v;
        bool c = CompareOp(e.cmp_op, Value::Compare(vv, x));
        if (is_any && c) return Bool(true);
        if (!is_any && !c) return Bool(false);
      }
      if (has_null) return Value::Null(LogicalType(TypeId::BOOLEAN));
      return Bool(!is_any);
    }
    }
    return Value();
  }
  case BKind::LAMBDA: return Value();
  case BKind::DEFAULT: return Value();
  case BKind::AGGREGATE_REF: case BKind::WINDOW_REF: return row[e.index];
  default: break;
  }
  throw InternalException("Unsupported bound expression");
}
