  case BKind::ARITH: {
    Value a = Eval(*e.children[0], row);
    Value b = Eval(*e.children[1], row);
    try {
      return ComputeArith(e.op, a, b, e.type);
    } catch (DBException &ex) {
      if (ex.position < 0) ex.position = e.position;
      throw;
    }
  }
  case BKind::NEGATE: {
    Value a = Eval(*e.children[0], row);
    if (a.is_null) return Value::Null(e.type);
    Value r = a;
    r.type = e.type;
    if (a.type.IsFloating()) r.dval = -a.dval;
    else if (a.type.id == TypeId::INTERVAL) { r.interval.months = -a.interval.months; r.interval.days = -a.interval.days; r.interval.micros = -a.interval.micros; }
    else {
      if (a.type.IsInteger() && a.ival == NumericMin(a.type.id) && a.type.id != TypeId::HUGEINT) throw OutOfRangeException("Overflow in negation of " + a.type.ToStringInternal() + " (" + a.ToString() + ")!");
      r.ival = -a.ival;
    }
    return r;
  }
  case BKind::CASE: {
    for (auto &c : e.cases) {
      Value w = Eval(*c.first, row);
      if (!w.is_null && w.ival) return Eval(*c.second, row);
    }
    return Eval(*e.else_expr, row);
  }
  case BKind::CAST: {
    Value v = Eval(*e.children[0], row);
    try {
      return CastValue(v, e.type, e.try_cast);
    } catch (DBException &ex) {
