#include "binder.h"
#include "parser.h"
#include <algorithm>
#include <unordered_set>
#include <cmath>

// ---------------------------------------------------------------- helpers
static std::string ExprName(const Expr &e) {
  if (!e.alias.empty()) return e.alias;
  if (e.kind == ExprKind::COLUMN_REF) return e.names.back();
  if (e.kind == ExprKind::CONSTANT && e.value.type.id == TypeId::BOOLEAN && !e.value.is_null) return e.ToString();
  return e.ToString();
}

static void CollectAggregates(const Expr &e, std::vector<const Expr *> &out, bool in_window = false) {
  if (e.kind == ExprKind::FUNCTION) {
    std::string name = ToLower(e.op);
    auto &reg = Functions();
    if (reg.FindAgg(name) && !reg.FindScalar(name)) {
      out.push_back(&e);
      return;  // don't descend
    }
  }
  if (e.kind == ExprKind::SUBQUERY) return;
  for (auto &c : e.children) if (c) CollectAggregates(*c, out, in_window);
  if (e.filter) CollectAggregates(*e.filter, out, in_window);
  for (auto &cc : e.case_checks) { CollectAggregates(*cc.when, out); CollectAggregates(*cc.then, out); }
  if (e.else_expr) CollectAggregates(*e.else_expr, out);
  for (auto &o : e.order_bys) CollectAggregates(*o.expr, out);
  if (e.window) {
    for (auto &p : e.window->partitions) CollectAggregates(*p, out, true);
    for (auto &o : e.window->orders) CollectAggregates(*o.expr, out, true);
  }
  for (auto &r : e.replace_list) CollectAggregates(*r.second, out);
}

static void CollectWindows(const Expr &e, std::vector<const Expr *> &out) {
  if (e.kind == ExprKind::WINDOW) { out.push_back(&e); return; }
  if (e.kind == ExprKind::SUBQUERY) return;
  for (auto &c : e.children) if (c) CollectWindows(*c, out);
  if (e.filter) CollectWindows(*e.filter, out);
  for (auto &cc : e.case_checks) { CollectWindows(*cc.when, out); CollectWindows(*cc.then, out); }
  if (e.else_expr) CollectWindows(*e.else_expr, out);
}

static bool ContainsAggregate(const Expr &e) {
  std::vector<const Expr *> aggs;
  CollectAggregates(e, aggs);
  return !aggs.empty();
}
static bool ContainsWindow(const Expr &e) {
  std::vector<const Expr *> w;
  CollectWindows(e, w);
  return !w.empty();
}
static bool ContainsUnnest(const Expr &e) {
  if (e.kind == ExprKind::FUNCTION && IEquals(e.op, "unnest")) return true;
  if (e.kind == ExprKind::SUBQUERY) return false;
  for (auto &c : e.children) if (c && ContainsUnnest(*c)) return true;
  return false;
}

static std::vector<std::string> DedupNames(const std::vector<std::string> &names) {
  std::vector<std::string> r;
  std::unordered_set<std::string> seen;
  for (auto &n : names) {
    std::string name = n;
    if (seen.count(ToLower(name))) {
      int k = 1;
      while (seen.count(ToLower(n + "_" + std::to_string(k)))) k++;
      name = n + "_" + std::to_string(k);
    }
    seen.insert(ToLower(name));
    r.push_back(name);
  }
  return r;
}

QueryResult Executor::ExecuteSelect(const SelectStatement &stmt, BindContext *outer) {
  return ExecuteNode(*stmt.node, outer);
}

std::vector<Row> Executor::ApplyOrderBy(std::vector<Row> rows, const std::vector<std::pair<int, std::pair<OrderType, NullOrder>>> &keys) {
  std::stable_sort(rows.begin(), rows.end(), [&](const Row &a, const Row &b) {
    for (auto &k : keys) {
      const Value &x = a[k.first];
      const Value &y = b[k.first];
      bool desc = k.second.first == OrderType::DESC;
      NullOrder no = k.second.second;
      bool nulls_first = no == NullOrder::NULLS_FIRST;
      if (no == NullOrder::DEFAULT) nulls_first = false;  // DuckDB default: NULLS LAST
      if (x.is_null || y.is_null) {
        if (x.is_null && y.is_null) continue;
        if (x.is_null) return nulls_first;
        return !nulls_first;
      }
      int c = Value::Compare(x, y);
      if (c == 0) continue;
      return desc ? c > 0 : c < 0;
    }
    return false;
  });
  return rows;
}

// cast rows of a set operation to unified types
static void CastColumn(std::vector<Row> &rows, size_t col, const LogicalType &t) {
  for (auto &r : rows) {
    if (r[col].type != t) r[col] = CastValue(r[col], t, false);
  }
}

static size_t RowHash(const Row &r) {
  size_t h = 0;
  for (auto &v : r) h = h * 1000003 + v.Hash();
  return h;
}
struct RowHasher { size_t operator()(const Row &r) const { return RowHash(r); } };
struct RowEq { bool operator()(const Row &a, const Row &b) const { if (a.size() != b.size()) return false; for (size_t i = 0; i < a.size(); i++) if (!ValuesEqual(a[i], b[i])) return false; return true; } };

static std::vector<Row> DistinctRows(const std::vector<Row> &rows) {
  std::vector<Row> out;
  std::unordered_set<Row, RowHasher, RowEq> seen;
  for (auto &r : rows) if (seen.insert(r).second) out.push_back(r);
  return out;
}

// ---------------------------------------------------------------- CTE handling
static std::shared_ptr<CTEBinding> FindCTE(BindContext *ctx, const std::string &name) {
  for (BindContext *c = ctx; c; c = c->parent) {
    auto it = c->ctes.find(ToLower(name));
    if (it != c->ctes.end()) return it->second;
    for (auto &kv : c->ctes) if (IEquals(kv.first, name)) return kv.second;
  }
  return nullptr;
}

QueryResult Executor::ExecuteNode(const QueryNode &node, BindContext *outer, BindContext *cte_ctx) {
  // handle CTEs by creating a scope
  BindContext cte_scope;
  BindContext *scope = outer;
  std::vector<std::shared_ptr<CTEBinding>> owned;
  if (!node.ctes.empty()) {
    cte_scope.parent = outer;
    if (outer) cte_scope.current_row = nullptr;
    scope = &cte_scope;
    for (auto &cte : node.ctes) {
      auto b = std::make_shared<CTEBinding>();
      b->cte = cte.get();
      b->aliases = cte->aliases;
      if (cte->recursive && cte->query->node->kind == QueryNodeKind::SET_OPERATION) {
        // recursive CTE: evaluate iteratively
        auto &setop = *cte->query->node;
        bool union_all = setop.setop == SetOpType::UNION_ALL;
        QueryResult base = ExecuteNode(*setop.left, scope);
        auto result = std::make_shared<QueryResult>();
        result->names = base.names;
        result->types = base.types;
        if (!cte->aliases.empty()) for (size_t i = 0; i < cte->aliases.size() && i < result->names.size(); i++) result->names[i] = cte->aliases[i];
        std::vector<Row> working = base.rows;
        if (!union_all) working = DistinctRows(working);
        result->rows = working;
        std::unordered_set<Row, RowHasher, RowEq> seen(working.begin(), working.end());
        auto wb = std::make_shared<CTEBinding>();
        wb->cte = cte.get();
        wb->aliases = cte->aliases;
        cte_scope.ctes[ToLower(cte->name)] = wb;
        int iterations = 0;
        while (!working.empty()) {
          auto wr = std::make_shared<QueryResult>();
          wr->names = result->names; wr->types = result->types; wr->rows = working;
          wb->materialized = wr;
          QueryResult step = ExecuteNode(*setop.right, scope);
          std::vector<Row> next;
          for (auto &r : step.rows) {
            Row casted = r;
            for (size_t i = 0; i < casted.size() && i < result->types.size(); i++) if (casted[i].type != result->types[i]) casted[i] = CastValue(casted[i], result->types[i], false);
            if (union_all) next.push_back(casted);
            else if (seen.insert(casted).second) next.push_back(casted);
          }
          for (auto &r : next) result->rows.push_back(r);
          working = next;
          if (++iterations > 100000) throw InvalidInputException("Recursive CTE exceeded iteration limit");
        }
        b->materialized = result;
        cte_scope.ctes[ToLower(cte->name)] = b;
      } else {
        cte_scope.ctes[ToLower(cte->name)] = b;
      }
    }
  }
  if (node.kind == QueryNodeKind::SET_OPERATION) {
    QueryResult left = ExecuteNode(*node.left, scope);
    QueryResult right = ExecuteNode(*node.right, scope);
    QueryResult result;
    bool by_name = node.setop == SetOpType::UNION_BY_NAME || node.setop == SetOpType::UNION_ALL_BY_NAME;
    if (by_name) {
      // union columns by name
      std::vector<std::string> names = left.names;
      std::vector<LogicalType> types = left.types;
      std::vector<int> right_map(right.names.size(), -1);
      for (size_t i = 0; i < right.names.size(); i++) {
        int found = -1;
        for (size_t j = 0; j < names.size(); j++) if (IEquals(names[j], right.names[i])) { found = (int)j; break; }
        if (found < 0) { names.push_back(right.names[i]); types.push_back(right.types[i]); found = (int)names.size() - 1; }
        else types[found] = MaxLogicalType(types[found], right.types[i]);
        right_map[i] = found;
      }
      result.names = names; result.types = types;
      for (auto &r : left.rows) { Row nr(names.size()); for (size_t i = 0; i < r.size(); i++) nr[i] = r[i]; for (size_t i = 0; i < nr.size(); i++) { if (nr[i].type != types[i]) nr[i] = CastValue(nr[i], types[i], false); } result.rows.push_back(nr); }
      for (auto &r : right.rows) { Row nr(names.size()); for (size_t i = 0; i < names.size(); i++) nr[i] = Value::Null(types[i]); for (size_t i = 0; i < r.size(); i++) nr[right_map[i]] = r[i]; for (size_t i = 0; i < nr.size(); i++) { if (nr[i].type != types[i]) nr[i] = CastValue(nr[i], types[i], false); } result.rows.push_back(nr); }
      if (node.setop == SetOpType::UNION_BY_NAME) result.rows = DistinctRows(result.rows);
    } else {
      if (left.types.size() != right.types.size()) {
        throw BinderException("Set operations can only apply to expressions with the same number of result columns");
      }
      result.names = left.names;
      for (size_t i = 0; i < left.types.size(); i++) {
        LogicalType t = MaxLogicalType(left.types[i], right.types[i]);
        if (t.id == TypeId::SQLNULL) t = LogicalType(TypeId::INTEGER);
        if (t.id == TypeId::STRING_LITERAL) t = LogicalType(TypeId::VARCHAR);
        result.types.push_back(t);
        CastColumn(left.rows, i, t);
        CastColumn(right.rows, i, t);
      }
      switch (node.setop) {
      case SetOpType::UNION_ALL:
        result.rows = left.rows;
        for (auto &r : right.rows) result.rows.push_back(r);
        break;
      case SetOpType::UNION: {
        result.rows = left.rows;
        for (auto &r : right.rows) result.rows.push_back(r);
        result.rows = DistinctRows(result.rows);
        break;
      }
      case SetOpType::EXCEPT: case SetOpType::EXCEPT_ALL: {
        std::unordered_multiset<Row, RowHasher, RowEq> rs(right.rows.begin(), right.rows.end());
        std::vector<Row> out;
        for (auto &r : left.rows) {
          auto it = rs.find(r);
          if (it != rs.end()) { if (node.setop == SetOpType::EXCEPT_ALL) rs.erase(it); continue; }
          out.push_back(r);
        }
        result.rows = node.setop == SetOpType::EXCEPT ? DistinctRows(out) : out;
        break;
      }
      case SetOpType::INTERSECT: case SetOpType::INTERSECT_ALL: {
        std::unordered_multiset<Row, RowHasher, RowEq> rs(right.rows.begin(), right.rows.end());
        std::vector<Row> out;
        for (auto &r : left.rows) {
          auto it = rs.find(r);
          if (it != rs.end()) { out.push_back(r); if (node.setop == SetOpType::INTERSECT_ALL) rs.erase(it); }
        }
        result.rows = node.setop == SetOpType::INTERSECT ? DistinctRows(out) : out;
        break;
      }
      default: break;
      }
    }
    // modifiers
    if (!node.orders.empty()) {
      BindContext octx;
      octx.parent = scope;
      Binding b; b.alias = ""; b.names = result.names; b.types = result.types; b.offset = 0;
      octx.bindings.push_back(b);
      std::vector<std::pair<int, std::pair<OrderType, NullOrder>>> keys;
      std::vector<Row> rows = result.rows;
      size_t ncols = result.names.size();
      if (node.order_by_all) {
        for (size_t i = 0; i < ncols; i++) keys.push_back({(int)i, {node.orders[0].type, node.orders[0].null_order}});
      } else {
        for (auto &o : node.orders) {
          if (o.expr->kind == ExprKind::CONSTANT && o.expr->value.type.IsInteger()) {
            int idx = (int)o.expr->value.GetInt64() - 1;
            if (idx < 0 || idx >= (int)ncols) throw BinderException("ORDER term out of range - should be between 1 and " + std::to_string(ncols));
            keys.push_back({idx, {o.type, o.null_order}});
          } else {
            BExpr be = Bind(*o.expr, octx);
            for (auto &r : rows) r.push_back(Eval(*be, r));
            keys.push_back({(int)rows[0].size() - 1, {o.type, o.null_order}});
          }
        }
      }
      rows = ApplyOrderBy(rows, keys);
      for (auto &r : rows) r.resize(ncols);
      result.rows = rows;
    }
    if (node.limit || node.offset) {
      int64_t off = 0, lim = -1;
      if (node.offset) { Value v = EvaluateConstantExpression(*this, *node.offset); if (!v.is_null) off = v.GetInt64(); }
      if (node.limit) { Value v = EvaluateConstantExpression(*this, *node.limit); if (!v.is_null) lim = v.GetInt64(); }
      std::vector<Row> out;
      for (size_t i = (size_t)std::max<int64_t>(0, off); i < result.rows.size(); i++) {
        if (lim >= 0 && (int64_t)out.size() >= lim) break;
        out.push_back(result.rows[i]);
      }
      result.rows = out;
    }
    return result;
  }

  // ---------------------------------------------------------------- SELECT node
  BindContext from_ctx;
  from_ctx.parent = scope;
  std::vector<Row> rows;
  if (node.from) {
    BindTableRef(*node.from, from_ctx, rows);
  } else {
    rows.push_back(Row());
  }
  // expand select list
  std::vector<ExprPtr> select_exprs;
  for (auto &e : node.select_list) {
    if (e->kind == ExprKind::STAR) ExpandStar(*e, from_ctx, select_exprs, &node.select_list);
    else {
      // nested star in function: e.g. COLUMNS(*) inside function - not supported broadly
      select_exprs.push_back(e->Copy());
    }
  }
  if (select_exprs.empty() && !node.select_list.empty()) {
    // star expanded to nothing (no columns) - keep empty
  }
  // WHERE
  if (node.where) {
    BExpr w = Bind(*node.where, from_ctx);
    w = BindCast(w, LogicalType(TypeId::BOOLEAN), false);
    std::vector<Row> filtered;
    for (auto &r : rows) {
      from_ctx.current_row = &r;
      Value v = Eval(*w, r);
      if (!v.is_null && v.ival) filtered.push_back(r);
    }
    from_ctx.current_row = nullptr;
    rows = filtered;
  }
  // collect aggregates
  std::vector<const Expr *> aggs;
  for (auto &e : select_exprs) CollectAggregates(*e, aggs);
  if (node.having) CollectAggregates(*node.having, aggs);
  if (node.qualify) CollectAggregates(*node.qualify, aggs);
  for (auto &o : node.orders) CollectAggregates(*o.expr, aggs);
  bool has_group = !node.groups.empty() || node.group_by_all || !aggs.empty();
  BindContext agg_ctx;
  BindContext *cur_ctx = &from_ctx;
  std::vector<std::string> cur_names;   // names of columns in current rows (for aggregate stage)
  if (has_group) {
    // determine group expressions
    std::vector<ExprPtr> group_exprs;
    if (node.group_by_all) {
      for (auto &e : select_exprs) {
        if (!ContainsAggregate(*e) && !ContainsWindow(*e)) group_exprs.push_back(e->Copy());
      }
    } else {
      for (auto &g : node.groups) {
        if (g->kind == ExprKind::CONSTANT && g->value.type.IsInteger() && !g->value.is_null) {
          int idx = (int)g->value.GetInt64() - 1;
          if (idx < 0 || idx >= (int)select_exprs.size()) throw BinderException("GROUP BY term out of range - should be between 1 and " + std::to_string(select_exprs.size()));
          auto c = select_exprs[idx]->Copy();
          c->alias = "";
          group_exprs.push_back(std::move(c));
        } else if (g->kind == ExprKind::COLUMN_REF && g->names.size() == 1) {
          // alias reference?
          bool found = false;
          BExpr tmp;
          bool is_col = false;
          try { is_col = TryBindColumn(g->names, from_ctx, tmp, 0); } catch (...) { is_col = false; }
          if (!is_col) {
            for (auto &e : select_exprs) {
              if (IEquals(e->alias, g->names[0])) { auto c = e->Copy(); c->alias = ""; group_exprs.push_back(std::move(c)); found = true; break; }
            }
          }
          if (!found) group_exprs.push_back(g->Copy());
        } else group_exprs.push_back(g->Copy());
      }
    }
    // bind group exprs
    std::vector<BExpr> bound_groups;
    for (auto &g : group_exprs) bound_groups.push_back(Bind(*g, from_ctx));
    // bind aggregates: dedupe by ToString
    struct AggInfo { const Expr *expr; std::string key; std::vector<BExpr> args; BExpr filter; const AggOverload *ov; LogicalType type; std::vector<std::pair<BExpr, std::pair<OrderType, NullOrder>>> orders; };
    std::vector<AggInfo> agg_infos;
    for (auto *a : aggs) {
      std::string key = a->ToString();
      bool dup = false;
      for (auto &ai : agg_infos) if (ai.key == key) { dup = true; break; }
      if (dup) continue;
      AggInfo info;
      info.expr = a;
      info.key = key;
      std::string name = ToLower(a->op);
      AggFunction *af = Functions().FindAgg(name);
      if (!af) throw BinderException("Unknown aggregate " + name);
      for (auto &c : a->children) {
        if (c->kind == ExprKind::STAR) continue;
        info.args.push_back(Bind(*c, from_ctx));
      }
      if (a->filter) info.filter = BindCast(Bind(*a->filter, from_ctx), LogicalType(TypeId::BOOLEAN), false);
      for (auto &o : a->order_bys) info.orders.push_back({Bind(*o.expr, from_ctx), {o.type, o.null_order}});
      // choose overload
      std::vector<LogicalType> types;
      for (auto &x : info.args) types.push_back(x->type);
      const AggOverload *best = nullptr;
      int best_cost = -1;
      for (auto &ov : af->overloads) {
        if (!ov.varargs && ov.params.size() != types.size()) continue;
        if (ov.varargs && types.size() < ov.params.size()) continue;
        int cost = 0;
        bool ok = true;
        for (size_t i = 0; i < types.size(); i++) {
          const LogicalType &p = i < ov.params.size() ? ov.params[i] : (ov.params.empty() ? LogicalType(TypeId::ANY) : ov.params.back());
          if (p.id == TypeId::ANY) continue;
          if (types[i] == p) continue;
          if (types[i].id == TypeId::SQLNULL) { cost += 1; continue; }
          if (types[i].id == TypeId::INTEGER_LITERAL && p.IsNumeric()) { cost += p.id == TypeId::INTEGER ? 0 : 2; continue; }
          if (p.id == TypeId::LIST && (types[i].id == TypeId::LIST || types[i].id == TypeId::ARRAY)) continue;
          int c = ImplicitCastCost(types[i], p);
          if (c < 0) { if (types[i].IsStringLike() && p.id == TypeId::VARCHAR) { cost += 1; continue; } ok = false; break; }
          cost += c;
        }
        if (!ok) continue;
        if (!best || cost < best_cost) { best = &ov; best_cost = cost; }
      }
      if (!best) {
        std::string msg = "No function matches the given name and argument types '" + name + "(" + TypeListToString(types) + ")'. You might need to add explicit type casts.\n\tCandidate functions:\n";
        for (auto &ov : af->overloads) {
          msg += "\t" + name + "(";
          for (size_t i = 0; i < ov.params.size(); i++) { if (i) msg += ", "; msg += ov.params[i].ToString(); }
          msg += ") -> " + ov.ret.ToString() + "\n";
        }
        BinderException ex(msg);
        ex.position = a->position;
        throw ex;
      }
      for (size_t i = 0; i < info.args.size(); i++) {
        const LogicalType &p = i < best->params.size() ? best->params[i] : (best->params.empty() ? LogicalType(TypeId::ANY) : best->params.back());
        if (p.id == TypeId::ANY || p.id == TypeId::LIST) {
          if (info.args[i]->type.id == TypeId::STRING_LITERAL) { info.args[i]->type = LogicalType(TypeId::VARCHAR); if (info.args[i]->kind == BKind::CONSTANT) info.args[i]->constant.type = LogicalType(TypeId::VARCHAR); }
          if (info.args[i]->type.id == TypeId::INTEGER_LITERAL) { info.args[i]->type = LogicalType(TypeId::INTEGER); if (info.args[i]->kind == BKind::CONSTANT) info.args[i]->constant.type = LogicalType(TypeId::INTEGER); }
          continue;
        }
        if (info.args[i]->type != p) info.args[i] = BindCast(info.args[i], p, false);
      }
      info.ov = best;
      std::vector<LogicalType> ftypes;
      for (auto &x : info.args) ftypes.push_back(x->type);
      if (best->bind) info.type = best->bind(ftypes, info.args, ctx);
      else info.type = best->ret;
      agg_infos.push_back(std::move(info));
    }
    // compute groups
    std::vector<std::vector<size_t>> groups;  // row indexes per group
    std::vector<Row> group_keys;
    {
      std::unordered_map<Row, size_t, RowHasher, RowEq> index;
      for (size_t ri = 0; ri < rows.size(); ri++) {
        from_ctx.current_row = &rows[ri];
        Row key;
        for (auto &bg : bound_groups) key.push_back(Eval(*bg, rows[ri]));
        auto it = index.find(key);
        if (it == index.end()) { index[key] = groups.size(); groups.push_back({ri}); group_keys.push_back(key); }
        else groups[it->second].push_back(ri);
      }
      from_ctx.current_row = nullptr;
    }
    // grouping sets (ROLLUP/CUBE/GROUPING SETS)
    std::vector<std::vector<int>> gsets = node.grouping_sets;
    if (bound_groups.empty() && groups.empty()) { groups.push_back({}); group_keys.push_back(Row()); }
    // compute aggregate values per group
    std::vector<Row> grouped_rows;
    auto compute_group = [&](const std::vector<size_t> &gidx, const Row &key, const std::vector<int> *active_set) {
      Row out;
      for (size_t gi = 0; gi < key.size(); gi++) {
        if (active_set && std::find(active_set->begin(), active_set->end(), (int)gi) == active_set->end()) out.push_back(Value::Null(bound_groups[gi]->type));
        else out.push_back(key[gi]);
      }
      for (auto &ai : agg_infos) {
        std::vector<std::vector<Value>> arg_rows;
        std::vector<size_t> sel;
        for (size_t ri : gidx) {
          if (ai.filter) {
            from_ctx.current_row = &rows[ri];
            Value f = Eval(*ai.filter, rows[ri]);
            if (f.is_null || !f.ival) continue;
          }
          sel.push_back(ri);
        }
        // ordering within aggregate
        if (!ai.orders.empty()) {
          std::vector<std::pair<Row, size_t>> keyed;
          for (size_t ri : sel) {
            from_ctx.current_row = &rows[ri];
            Row k;
            for (auto &o : ai.orders) k.push_back(Eval(*o.first, rows[ri]));
            keyed.push_back({k, ri});
          }
          std::stable_sort(keyed.begin(), keyed.end(), [&](const std::pair<Row, size_t> &a, const std::pair<Row, size_t> &b) {
            for (size_t i = 0; i < ai.orders.size(); i++) {
              const Value &x = a.first[i], &y = b.first[i];
              bool desc = ai.orders[i].second.first == OrderType::DESC;
              bool nulls_first = ai.orders[i].second.second == NullOrder::NULLS_FIRST;
              if (x.is_null || y.is_null) { if (x.is_null && y.is_null) continue; if (x.is_null) return nulls_first; return !nulls_first; }
              int c = Value::Compare(x, y);
              if (c == 0) continue;
              return desc ? c > 0 : c < 0;
            }
            return false;
          });
          sel.clear();
          for (auto &k : keyed) sel.push_back(k.second);
        }
        for (size_t ri : sel) {
          from_ctx.current_row = &rows[ri];
          std::vector<Value> vals;
          for (auto &a : ai.args) vals.push_back(Eval(*a, rows[ri]));
          arg_rows.push_back(std::move(vals));
        }
        if (ai.expr->distinct && !arg_rows.empty()) {
          std::vector<std::vector<Value>> d;
          std::unordered_set<Row, RowHasher, RowEq> seen;
          for (auto &r : arg_rows) if (seen.insert(r).second) d.push_back(r);
          arg_rows = d;
        }
        BoundExpr dummy(BKind::FUNCTION);
        dummy.type = ai.type;
        for (auto &a : ai.args) dummy.children.push_back(a);
        Value v = ai.ov->impl(arg_rows, ctx, dummy);
        if (v.is_null) v = Value::Null(ai.type);
        else if (v.type != ai.type && !ai.type.IsNested() && ai.type.id != TypeId::ANY) v = CastValue(v, ai.type, false);
        out.push_back(v);
      }
      from_ctx.current_row = nullptr;
      grouped_rows.push_back(out);
    };
    if (gsets.empty()) {
      for (size_t g = 0; g < groups.size(); g++) compute_group(groups[g], group_keys[g], nullptr);
    } else {
      for (auto &set : gsets) {
        // regroup by subset of keys
        std::unordered_map<Row, size_t, RowHasher, RowEq> index;
        std::vector<std::vector<size_t>> sg;
        std::vector<Row> sk;
        for (size_t g = 0; g < groups.size(); g++) {
          Row key = group_keys[g];
          for (size_t gi = 0; gi < key.size(); gi++) if (std::find(set.begin(), set.end(), (int)gi) == set.end()) key[gi] = Value::Null(bound_groups[gi]->type);
          auto it = index.find(key);
          if (it == index.end()) { index[key] = sg.size(); sg.push_back(groups[g]); sk.push_back(key); }
          else for (auto ri : groups[g]) sg[it->second].push_back(ri);
        }
        if (sg.empty()) { sg.push_back({}); Row key; for (auto &bg : bound_groups) key.push_back(Value::Null(bg->type)); sk.push_back(key); }
        for (size_t g = 0; g < sg.size(); g++) compute_group(sg[g], sk[g], &set);
      }
    }
    // if no groups and no rows: one row of aggregates over empty set
    // build aggregate context
    agg_ctx.parent = scope;
    agg_ctx.in_aggregate_stage = true;
    Binding b;
    b.alias = "";
    for (size_t gi = 0; gi < group_exprs.size(); gi++) {
      b.names.push_back(ExprName(*group_exprs[gi]));
      b.types.push_back(bound_groups[gi]->type.id == TypeId::INTEGER_LITERAL ? LogicalType(TypeId::INTEGER) : (bound_groups[gi]->type.id == TypeId::STRING_LITERAL ? LogicalType(TypeId::VARCHAR) : bound_groups[gi]->type));
      agg_ctx.group_exprs.push_back({group_exprs[gi]->ToString(), (int)gi});
      // also register plain column name if group expr is a column ref
      if (group_exprs[gi]->kind == ExprKind::COLUMN_REF) {
        agg_ctx.group_exprs.push_back({group_exprs[gi]->names.back(), (int)gi});
        // qualified forms
        if (bound_groups[gi]->kind == BKind::COLUMN) {
          for (auto &fb : from_ctx.bindings) {
            if (bound_groups[gi]->index >= fb.offset && bound_groups[gi]->index < fb.offset + (int)fb.names.size()) {
              std::string cn = fb.names[bound_groups[gi]->index - fb.offset];
              agg_ctx.group_exprs.push_back({cn, (int)gi});
              if (!fb.alias.empty()) agg_ctx.group_exprs.push_back({QuoteIdentifierIfNeeded(fb.alias) + "." + QuoteIdentifierIfNeeded(cn), (int)gi});
            }
          }
        }
      }
    }
    for (size_t ai = 0; ai < agg_infos.size(); ai++) {
      b.names.push_back(agg_infos[ai].key);
      b.types.push_back(agg_infos[ai].type);
      agg_ctx.agg_exprs.push_back({agg_infos[ai].key, (int)(group_exprs.size() + ai)});
    }
    agg_ctx.bindings.push_back(b);
    // fix types of grouped values
    for (auto &r : grouped_rows) for (size_t i = 0; i < r.size() && i < b.types.size(); i++) { if (r[i].type != b.types[i]) { if (r[i].is_null) r[i] = Value::Null(b.types[i]); else r[i] = CastValue(r[i], b.types[i], false); } }
    rows = grouped_rows;
    cur_ctx = &agg_ctx;
    // HAVING
    if (node.having) {
      BExpr h = BindCast(Bind(*node.having, agg_ctx, true), LogicalType(TypeId::BOOLEAN), false);
      std::vector<Row> filtered;
      for (auto &r : rows) { agg_ctx.current_row = &r; Value v = Eval(*h, r); if (!v.is_null && v.ival) filtered.push_back(r); }
      agg_ctx.current_row = nullptr;
      rows = filtered;
    }
  } else if (node.having) {
    throw BinderException("HAVING clause requires aggregation");
  }
  // window functions
  std::vector<const Expr *> windows;
  for (auto &e : select_exprs) CollectWindows(*e, windows);
  if (node.qualify) CollectWindows(*node.qualify, windows);
  for (auto &o : node.orders) CollectWindows(*o.expr, windows);
  BindContext win_ctx;
  if (!windows.empty()) {
    extern void ComputeWindowFunctions(Executor &ex, const QueryNode &node, std::vector<const Expr *> &windows, BindContext &cur, std::vector<Row> &rows, BindContext &win_ctx);
    ComputeWindowFunctions(*this, node, windows, *cur_ctx, rows, win_ctx);
    cur_ctx = &win_ctx;
  }
  if (node.qualify) {
    BExpr q = BindCast(Bind(*node.qualify, *cur_ctx, true, true), LogicalType(TypeId::BOOLEAN), false);
    std::vector<Row> filtered;
    for (auto &r : rows) { cur_ctx->current_row = &r; Value v = Eval(*q, r); if (!v.is_null && v.ival) filtered.push_back(r); }
    cur_ctx->current_row = nullptr;
    rows = filtered;
  }
  // projection
  QueryResult result;
  std::vector<BExpr> proj;
  for (auto &e : select_exprs) {
    BExpr be = Bind(*e, *cur_ctx, true, true);
    LogicalType t = be->type;
    if (t.id == TypeId::STRING_LITERAL) t = LogicalType(TypeId::VARCHAR);
    if (t.id == TypeId::INTEGER_LITERAL) t = LogicalType(TypeId::INTEGER);
    if (t.id == TypeId::SQLNULL) t = LogicalType(TypeId::INTEGER);
    if (t.id == TypeId::UNKNOWN) t = LogicalType(TypeId::INTEGER);
    proj.push_back(be);
    result.names.push_back(ExprName(*e));
    result.types.push_back(t);
  }
  // ORDER BY binding
  std::vector<std::pair<int, std::pair<OrderType, NullOrder>>> order_keys;
  std::vector<BExpr> extra_order;   // extra expressions evaluated per row
  size_t ncols = proj.size();
  if (!node.orders.empty()) {
    if (node.order_by_all) {
      for (size_t i = 0; i < ncols; i++) order_keys.push_back({(int)i, {node.orders[0].type, node.orders[0].null_order}});
    } else {
      for (auto &o : node.orders) {
        if (o.expr->kind == ExprKind::CONSTANT && o.expr->value.type.IsInteger() && !o.expr->value.is_null) {
          int idx = (int)o.expr->value.GetInt64() - 1;
          if (idx < 0 || idx >= (int)ncols) {
            BinderException ex("ORDER term out of range - should be between 1 and " + std::to_string(ncols));
            ex.position = o.expr->position;
            throw ex;
          }
          order_keys.push_back({idx, {o.type, o.null_order}});
          continue;
        }
        // alias match
        int matched = -1;
        if (o.expr->kind == ExprKind::COLUMN_REF && o.expr->names.size() == 1) {
          for (size_t i = 0; i < select_exprs.size(); i++) {
            if (!select_exprs[i]->alias.empty() && IEquals(select_exprs[i]->alias, o.expr->names[0])) { matched = (int)i; break; }
          }
          if (matched < 0) {
            // column that exists in FROM takes precedence over output name? DuckDB: prefers select-list alias
            // check if it's bindable in ctx; if not, try select-list names
            BExpr tmp;
            bool bindable = false;
            try { bindable = TryBindColumn(o.expr->names, *cur_ctx, tmp, 0); } catch (...) {}
            if (!bindable && cur_ctx->in_aggregate_stage) {
              for (auto &g : cur_ctx->group_exprs) if (g.first == o.expr->ToString()) bindable = true;
            }
            if (!bindable) {
              for (size_t i = 0; i < select_exprs.size(); i++) if (IEquals(result.names[i], o.expr->names[0])) { matched = (int)i; break; }
            }
          }
        } else {
          // expression equal to a select expression?
          std::string key = o.expr->ToString();
          for (size_t i = 0; i < select_exprs.size(); i++) if (select_exprs[i]->ToString() == key) { matched = (int)i; break; }
        }
        if (matched >= 0) { order_keys.push_back({matched, {o.type, o.null_order}}); continue; }
        BExpr be = Bind(*o.expr, *cur_ctx, true, true);
        extra_order.push_back(be);
        order_keys.push_back({(int)(ncols + extra_order.size() - 1), {o.type, o.null_order}});
      }
    }
  }
  // evaluate projection
  std::vector<Row> out_rows;
  bool has_unnest = false;
  for (auto &e : select_exprs) if (ContainsUnnest(*e)) has_unnest = true;
  for (auto &r : rows) {
    cur_ctx->current_row = &r;
    Row out;
    out.reserve(ncols + extra_order.size());
    for (size_t i = 0; i < proj.size(); i++) {
      Value v = Eval(*proj[i], r);
      if (v.type != result.types[i]) {
        if (v.is_null) v = Value::Null(result.types[i]);
        else if (result.types[i].id != TypeId::ANY) v = CastValue(v, result.types[i], false);
      }
      out.push_back(std::move(v));
    }
    for (auto &be : extra_order) out.push_back(Eval(*be, r));
    out_rows.push_back(std::move(out));
  }
  cur_ctx->current_row = nullptr;
  if (has_unnest) {
    // expand list columns produced by unnest: find select exprs that are unnest calls (top-level)
    std::vector<Row> expanded;
    std::vector<bool> is_unnest(ncols, false);
    for (size_t i = 0; i < select_exprs.size(); i++) is_unnest[i] = ContainsUnnest(*select_exprs[i]);
    for (size_t i = 0; i < ncols; i++) if (is_unnest[i] && result.types[i].id == TypeId::LIST) result.types[i] = result.types[i].child();
    for (auto &r : out_rows) {
      size_t maxlen = 0;
      for (size_t i = 0; i < ncols; i++) if (is_unnest[i] && !r[i].is_null && r[i].children) maxlen = std::max(maxlen, r[i].children->size());
      for (size_t k = 0; k < maxlen; k++) {
        Row nr = r;
        for (size_t i = 0; i < ncols; i++) {
          if (is_unnest[i]) {
            if (!r[i].is_null && r[i].children && k < r[i].children->size()) nr[i] = (*r[i].children)[k];
            else nr[i] = Value::Null(result.types[i]);
          }
        }
        expanded.push_back(nr);
      }
    }
    out_rows = expanded;
  }
  // DISTINCT
  if (node.distinct) {
    if (!node.distinct_on.empty()) {
      // bind DISTINCT ON exprs against the output rows (by alias or expression)
      std::vector<BExpr> don;
      std::vector<int> don_cols;
      for (auto &d : node.distinct_on) {
        int matched = -1;
        std::string key = d->ToString();
        for (size_t i = 0; i < select_exprs.size(); i++) {
          if (select_exprs[i]->ToString() == key || (d->kind == ExprKind::COLUMN_REF && d->names.size() == 1 && IEquals(result.names[i], d->names[0]))) { matched = (int)i; break; }
        }
        if (matched < 0) {
          if (d->kind == ExprKind::CONSTANT && d->value.type.IsInteger()) matched = (int)d->value.GetInt64() - 1;
        }
        if (matched < 0) {
          // evaluate per original row: need alignment; fall back to error
          throw BinderException("DISTINCT ON expression must appear in select list");
        }
        don_cols.push_back(matched);
      }
      // keep first row per key (after ordering if ORDER BY given: DuckDB applies ORDER BY first)
      std::vector<Row> ordered = out_rows;
      if (!order_keys.empty()) ordered = ApplyOrderBy(ordered, order_keys);
      std::unordered_set<Row, RowHasher, RowEq> seen;
      std::vector<Row> kept;
      for (auto &r : ordered) {
        Row key;
        for (int c : don_cols) key.push_back(r[c]);
        if (seen.insert(key).second) kept.push_back(r);
      }
      out_rows = kept;
      order_keys.clear();  // already ordered
    } else {
      std::vector<Row> d;
      std::unordered_set<Row, RowHasher, RowEq> seen;
      for (auto &r : out_rows) { Row key(r.begin(), r.begin() + ncols); if (seen.insert(key).second) d.push_back(r); }
      out_rows = d;
    }
  }
  if (!order_keys.empty()) out_rows = ApplyOrderBy(out_rows, order_keys);
  for (auto &r : out_rows) r.resize(ncols);
  // LIMIT / OFFSET
  if (node.limit || node.offset) {
    int64_t off = 0, lim = -1;
    if (node.offset) { Value v = EvaluateConstantExpression(*this, *node.offset); if (!v.is_null) off = v.GetInt64(); }
    if (node.limit) {
      Value v = EvaluateConstantExpression(*this, *node.limit);
      if (!v.is_null) {
        if (node.limit_percent) lim = (int64_t)std::ceil(v.GetDouble() / 100.0 * (double)out_rows.size());
        else lim = v.GetInt64();
      }
    }
    std::vector<Row> limited;
    for (size_t i = (size_t)std::max<int64_t>(0, off); i < out_rows.size(); i++) {
      if (lim >= 0 && (int64_t)limited.size() >= lim) break;
      limited.push_back(out_rows[i]);
    }
    out_rows = limited;
  }
  result.rows = std::move(out_rows);
  return result;
}

// ---------------------------------------------------------------- star expansion
void Executor::ExpandStar(const Expr &star, BindContext &context, std::vector<ExprPtr> &out, const std::vector<ExprPtr> *select_list) {
  std::vector<std::pair<std::string, std::string>> cols;  // (alias, name)
  if (star.columns_star && star.columns_expr) {
    // COLUMNS('regex') or COLUMNS(lambda)
    const Expr &ce = *star.columns_expr;
    std::vector<std::pair<std::string, std::string>> all;
    for (auto &b : context.bindings) for (size_t i = 0; i < b.names.size(); i++) { if (b.hidden.count(ToLower(b.names[i]))) continue; all.push_back({b.alias, b.names[i]}); }
    if (ce.kind == ExprKind::CONSTANT) {
      std::string pattern = ce.value.str;
      extern bool RegexSearch(const std::string &s, const std::string &pattern, std::string *match);
      for (auto &c : all) if (RegexSearch(c.second, pattern, nullptr)) cols.push_back(c);
    } else if (ce.kind == ExprKind::LAMBDA) {
      // lambda col -> predicate on name
      for (auto &c : all) {
        BindContext tmp;
        tmp.lambda_scopes.push_back({{ce.lambda_params[0], LogicalType(TypeId::VARCHAR)}});
        BExpr body = Bind(*ce.children[0], tmp);
        ctx.lambda_frames.push_back({Value::Varchar(c.second)});
        Row d;
        Value v = Eval(*body, d);
        ctx.lambda_frames.pop_back();
        if (!v.is_null && v.ival) cols.push_back(c);
      }
    } else if (ce.kind == ExprKind::FUNCTION && ce.op == "list_value") {
      for (auto &ch : ce.children) {
        std::string n = ch->value.str;
        for (auto &c : all) if (IEquals(c.second, n)) cols.push_back(c);
      }
    }
  } else {
    if (!star.relation_name.empty()) {
      const Binding *b = context.FindBinding(star.relation_name);
      if (!b) {
        // maybe a struct column: t.* -> expand struct fields (unsupported) ; error
        BinderException ex("Referenced table \"" + star.relation_name + "\" not found!");
        ex.position = star.position;
        throw ex;
      }
      for (size_t i = 0; i < b->names.size(); i++) { if (b->hidden.count(ToLower(b->names[i]))) continue; cols.push_back({b->alias, b->names[i]}); }
    } else {
      // all bindings; USING columns appear once (from left)
      for (auto &b : context.bindings) {
        for (size_t i = 0; i < b.names.size(); i++) {
          if (b.hidden.count(ToLower(b.names[i]))) continue;
          cols.push_back({b.alias, b.names[i]});
        }
      }
    }
  }
  // exclude
  std::vector<std::pair<std::string, std::string>> filtered;
  for (auto &c : cols) {
    bool excluded = false;
    for (auto &ex : star.exclude_list) {
      std::string exl = ToLower(ex);
      size_t dot = exl.find('.');
      if (dot != std::string::npos) { if (IEquals(exl.substr(0, dot), c.first) && IEquals(exl.substr(dot + 1), c.second)) excluded = true; }
      else if (IEquals(exl, c.second)) excluded = true;
    }
    if (!excluded) filtered.push_back(c);
  }
  for (auto &ex : star.exclude_list) {
    bool found = false;
    for (auto &c : cols) { std::string exl = ex; size_t dot = exl.find('.'); if (dot != std::string::npos) exl = exl.substr(dot + 1); if (IEquals(exl, c.second)) found = true; }
    if (!found) { BinderException e("Column \"" + ex + "\" in EXCLUDE list not found in " + (star.relation_name.empty() ? "*" : star.relation_name + ".*")); e.position = star.position; throw e; }
  }
  for (auto &c : filtered) {
    // replace?
    bool replaced = false;
    for (auto &r : star.replace_list) {
      if (IEquals(r.first, c.second)) {
        auto e = r.second->Copy();
        e->alias = c.second;
        out.push_back(std::move(e));
        replaced = true;
        break;
      }
    }
    if (replaced) continue;
    std::vector<std::string> names;
    // qualify when ambiguous (same column name in multiple bindings)
    int count = 0;
    for (auto &b : context.bindings) for (auto &n : b.names) if (IEquals(n, c.second)) count++;
    if (count > 1 && !c.first.empty() && !context.using_map.count(ToLower(c.second))) names = {c.first, c.second};
    else names = {c.second};
    auto e = Expr::ColumnRef(names);
    e->position = star.position;
    for (auto &rn : star.rename_list) if (IEquals(rn.first, c.second)) e->alias = rn.second->value.str;
    out.push_back(std::move(e));
  }
}

// ---------------------------------------------------------------- FROM clause
std::vector<Row> Executor::ScanTable(TableEntry &t) { return t.rows; }

static void AddBinding(BindContext &ctx, const std::string &alias, const std::vector<std::string> &names, const std::vector<LogicalType> &types, const std::string &table_name = "") {
  Binding b;
  b.alias = alias;
  b.names = names;
  b.types = types;
  b.offset = ctx.TotalColumns();
  b.table_name = table_name;
  ctx.bindings.push_back(b);
}

static void ApplyColumnAliases(const TableRef &ref, std::vector<std::string> &names) {
  for (size_t i = 0; i < ref.column_aliases.size() && i < names.size(); i++) names[i] = ref.column_aliases[i];
  if (ref.column_aliases.size() > names.size()) {
    throw BinderException("Table \"" + ref.alias + "\" has " + std::to_string(names.size()) + " columns available but " + std::to_string(ref.column_aliases.size()) + " columns specified");
  }
}

QueryResult Executor::ExecuteView(ViewEntry &view, BindContext *outer) {
  auto stmt = Parser::ParseSelectFromString(view.sql);
  QueryResult r = ExecuteNode(*stmt->node, nullptr);
  for (size_t i = 0; i < view.aliases.size() && i < r.names.size(); i++) r.names[i] = view.aliases[i];
  return r;
}

void Executor::BindTableRef(const TableRef &ref, BindContext &context, std::vector<Row> &rows) {
  switch (ref.kind) {
  case TableRefKind::EMPTY: rows.push_back(Row()); return;
  case TableRefKind::BASE_TABLE: {
    std::string name = ref.table_name;
    // CTE?
    if (ref.schema.empty()) {
      auto cte = FindCTE(&context, name);
      if (cte) {
        QueryResult r;
        if (cte->materialized) r = *cte->materialized;
        else {
          // avoid infinite recursion for self reference without recursive: error
          r = ExecuteNode(*cte->cte->query->node, context.parent);
          if (!cte->aliases.empty()) for (size_t i = 0; i < cte->aliases.size() && i < r.names.size(); i++) r.names[i] = cte->aliases[i];
        }
        std::vector<std::string> names = r.names;
        ApplyColumnAliases(ref, names);
        AddBinding(context, ref.alias.empty() ? name : ref.alias, names, r.types, name);
        rows = std::move(r.rows);
        return;
      }
    }
    std::string fdb, fschema;
    auto table = catalog.FindTable(ref.catalog, ref.schema, name, &fdb, &fschema);
    if (table) {
      std::vector<std::string> names;
      std::vector<LogicalType> types;
