        int cost = 0; bool ok = true;
        for (size_t i = 0; i < types.size(); i++) {
          const LogicalType &p = i < ov.params.size() ? ov.params[i] : (ov.params.empty() ? LogicalType(TypeId::ANY) : ov.params.back());
          if (p.id == TypeId::ANY || types[i] == p) continue;
          if (types[i].id == TypeId::INTEGER_LITERAL && p.IsNumeric()) { cost += p.id == TypeId::INTEGER ? 0 : 2; continue; }
          if (types[i].id == TypeId::SQLNULL) { cost += 1; continue; }
          if (p.id == TypeId::LIST && (types[i].id == TypeId::LIST || types[i].id == TypeId::ARRAY)) continue;
          int c = ImplicitCastCost(types[i], p);
          if (c < 0) { if (types[i].IsStringLike() && p.id == TypeId::VARCHAR) { cost += 1; continue; } ok = false; break; }
          cost += c;
        }
        if (!ok) continue;
        if (!agg_ov || cost < best_cost) { agg_ov = &ov; best_cost = cost; }
      }
      if (!agg_ov) {
        std::string msg = "No function matches the given name and argument types '" + fname + "(" + TypeListToString(types) + ")'. You might need to add explicit type casts.\n\tCandidate functions:\n";
        for (auto &ov : agg->overloads) { msg += "\t" + fname + "("; for (size_t i = 0; i < ov.params.size(); i++) { if (i) msg += ", "; msg += ov.params[i].ToString(); } msg += ") -> " + ov.ret.ToString() + "\n"; }
        BinderException e(msg); e.position = w.position; throw e;
      }
      for (size_t i = 0; i < args.size(); i++) {
        const LogicalType &p = i < agg_ov->params.size() ? agg_ov->params[i] : (agg_ov->params.empty() ? LogicalType(TypeId::ANY) : agg_ov->params.back());
        if (p.id == TypeId::ANY || p.id == TypeId::LIST) {
          if (args[i]->type.id == TypeId::STRING_LITERAL) { args[i]->type = LogicalType(TypeId::VARCHAR); if (args[i]->kind == BKind::CONSTANT) args[i]->constant.type = args[i]->type; }
          if (args[i]->type.id == TypeId::INTEGER_LITERAL) { args[i]->type = LogicalType(TypeId::INTEGER); if (args[i]->kind == BKind::CONSTANT) args[i]->constant.type = args[i]->type; }
          continue;
        }
        if (args[i]->type != p) args[i] = ex.BindCast(args[i], p, false);
      }
      std::vector<LogicalType> ftypes;
      for (auto &a : args) ftypes.push_back(a->type);
      rtype = agg_ov->bind ? agg_ov->bind(ftypes, args, ex.ctx) : agg_ov->ret;
    }
    // compute partition keys and order keys per row
    size_t np = ws.partitions.size(), no = ws.orders.size();
    std::vector<Row> keyed(nrows);
    std::vector<size_t> idx(nrows);
    for (size_t i = 0; i < nrows; i++) {
      cur.current_row = &rows[i];
      Row k;
      for (auto &p : ws.partitions) k.push_back(ex.Eval(*p, rows[i]));
      for (auto &o : ws.orders) k.push_back(ex.Eval(*o.first, rows[i]));
      keyed[i] = k;
      idx[i] = i;
    }
    cur.current_row = nullptr;
    std::stable_sort(idx.begin(), idx.end(), [&](size_t a, size_t b) {
      int c = CompareRowsByKeys(keyed[a], keyed[b], 0, np);
      if (c) return c < 0;
      for (size_t i = 0; i < no; i++) {
        const Value &x = keyed[a][np + i], &y = keyed[b][np + i];
        bool desc = ws.orders[i].second.first == OrderType::DESC;
        bool nulls_first = ws.orders[i].second.second == NullOrder::NULLS_FIRST;
        if (x.is_null || y.is_null) { if (x.is_null && y.is_null) continue; if (x.is_null) return nulls_first; return !nulls_first; }
        int cc = Value::Compare(x, y);
        if (cc == 0) continue;
        return desc ? cc > 0 : cc < 0;
      }
      return false;
    });
    std::vector<Value> results(nrows);
    // iterate partitions
    size_t start = 0;
    while (start < nrows) {
      size_t end = start + 1;
      while (end < nrows && CompareRowsByKeys(keyed[idx[start]], keyed[idx[end]], 0, np) == 0) end++;
      size_t psize = end - start;
      // peer groups by order keys
      std::vector<size_t> peer_start(psize), peer_end(psize);
      for (size_t i = 0; i < psize;) {
        size_t j = i + 1;
        while (j < psize && CompareRowsByKeys(keyed[idx[start + i]], keyed[idx[start + j]], np, no) == 0) j++;
        for (size_t k = i; k < j; k++) { peer_start[k] = i; peer_end[k] = j; }
        i = j;
      }
      // frame computation
      auto frame_bounds = [&](size_t i, size_t &fs, size_t &fe) {
        const WindowFrame &f = spec->frame;
        bool range_mode = !f.rows && !f.groups;
        if (!f.specified) {
          // default: RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW (if ORDER BY) else whole partition
          fs = 0;
          fe = no > 0 ? peer_end[i] : psize;
          return;
        }
        auto bound = [&](WindowFrame::Bound b, const ExprPtr &e, bool is_start) -> int64_t {
          switch (b) {
          case WindowFrame::UNBOUNDED_PRECEDING: return 0;
          case WindowFrame::UNBOUNDED_FOLLOWING: return (int64_t)psize;
          case WindowFrame::CURRENT_ROW:
            if (f.rows) return is_start ? (int64_t)i : (int64_t)i + 1;
            return is_start ? (int64_t)peer_start[i] : (int64_t)peer_end[i];
          case WindowFrame::EXPR_PRECEDING: case WindowFrame::EXPR_FOLLOWING: {
            Value v = EvaluateConstantExpression(ex, *e);
            if (f.rows) {
              int64_t n = v.GetInt64();
              int64_t pos = b == WindowFrame::EXPR_PRECEDING ? (int64_t)i - n : (int64_t)i + n;
              if (!is_start) pos += 1;
              if (pos < 0) pos = 0;
              if (pos > (int64_t)psize) pos = (int64_t)psize;
              return pos;
            }
            if (f.groups) {
              // group offsets
              int64_t n = v.GetInt64();
              // find peer group index of i
              std::vector<size_t> gstarts;
              for (size_t k = 0; k < psize; k++) if (peer_start[k] == k) gstarts.push_back(k);
              int64_t gi = 0;
              for (size_t g = 0; g < gstarts.size(); g++) if (gstarts[g] == peer_start[i]) gi = (int64_t)g;
              int64_t target = b == WindowFrame::EXPR_PRECEDING ? gi - n : gi + n;
              if (is_start) { if (target < 0) return 0; if (target >= (int64_t)gstarts.size()) return (int64_t)psize; return (int64_t)gstarts[target]; }
              if (target < 0) return 0;
              if (target >= (int64_t)gstarts.size()) return (int64_t)psize;
              return (int64_t)(target + 1 < (int64_t)gstarts.size() ? gstarts[target + 1] : psize);
            }
            // RANGE with offset: order key +/- value
            if (no != 1) throw BinderException("RANGE frames with offsets require exactly one ORDER BY expression");
            const Value &cur_key = keyed[idx[start + i]][np];
            if (cur_key.is_null) { return is_start ? (int64_t)peer_start[i] : (int64_t)peer_end[i]; }
            bool desc = ws.orders[0].second.first == OrderType::DESC;
            Value delta = v;
            // compute boundary value
            auto add = [&](const Value &k, const Value &d, bool subtract) -> Value {
              LogicalType rt = k.type;
              if (k.type.IsTemporal() && d.type.id != TypeId::INTERVAL) throw BinderException("Invalid RANGE offset");
              if (k.type.IsNumeric() && d.type.id != TypeId::DECIMAL && !d.type.IsFloating()) { Value dd = CastValue(d, k.type, false); return ComputeArith(subtract ? "-" : "+", k, dd, k.type); }
              if (k.type.IsNumeric()) { LogicalType dt = MaxLogicalType(k.type, d.type); return ComputeArith(subtract ? "-" : "+", CastValue(k, dt, false), CastValue(d, dt, false), dt); }
              return ComputeArith(subtract ? "-" : "+", k, d, k.type.id == TypeId::DATE ? LogicalType(TypeId::TIMESTAMP) : rt);
            };
            bool preceding = b == WindowFrame::EXPR_PRECEDING;
            Value boundary = add(cur_key, delta, preceding != desc);
            // find positions
            if (is_start) {
              size_t pos = 0;
              while (pos < psize) {
                const Value &k = keyed[idx[start + pos]][np];
                if (k.is_null) { pos++; continue; }
                int c = Value::Compare(k, boundary);
                if (desc ? c <= 0 : c >= 0) break;
                pos++;
              }
              return (int64_t)pos;
            } else {
              size_t pos = psize;
              while (pos > 0) {
                const Value &k = keyed[idx[start + pos - 1]][np];
                if (k.is_null) { pos--; continue; }
                int c = Value::Compare(k, boundary);
                if (desc ? c >= 0 : c <= 0) break;
                pos--;
              }
              return (int64_t)pos;
            }
          }
          }
          return 0;
        };
        int64_t s = bound(f.start, f.start_expr, true);
        int64_t e = bound(f.end, f.end_expr, false);
        (void)range_mode;
        if (s < 0) s = 0;
        if (e > (int64_t)psize) e = (int64_t)psize;
        if (e < s) e = s;
        fs = (size_t)s; fe = (size_t)e;
      };
      for (size_t i = 0; i < psize; i++) {
        size_t row_idx = idx[start + i];
        Value r;
        if (fname == "row_number") r = Value::BigInt((int64_t)i + 1);
        else if (fname == "rank") r = Value::BigInt((int64_t)peer_start[i] + 1);
        else if (fname == "dense_rank" || fname == "rank_dense") {
          int64_t d = 0;
          for (size_t k = 0; k <= i; k++) if (peer_start[k] == k) d++;
          r = Value::BigInt(d);
        } else if (fname == "percent_rank") {
          r = Value::Double(psize <= 1 ? 0.0 : (double)peer_start[i] / (double)(psize - 1));
        } else if (fname == "cume_dist") {
          r = Value::Double((double)peer_end[i] / (double)psize);
        } else if (fname == "ntile") {
          cur.current_row = &rows[row_idx];
          Value nv = ex.Eval(*args[0], rows[row_idx]);
          int64_t n = nv.GetInt64();
          if (n <= 0) throw InvalidInputException("Argument for ntile must be greater than zero");
          int64_t per = (int64_t)psize / n, rem = (int64_t)psize % n;
          int64_t pos = (int64_t)i;
          int64_t bucket;
          if (pos < rem * (per + 1)) bucket = pos / (per + 1);
          else bucket = rem + (pos - rem * (per + 1)) / (per > 0 ? per : 1);
          r = Value::BigInt(bucket + 1);
        } else if (fname == "lag" || fname == "lead") {
          cur.current_row = &rows[row_idx];
          int64_t off = 1;
          if (args.size() >= 2) { Value ov = ex.Eval(*args[1], rows[row_idx]); off = ov.is_null ? 1 : ov.GetInt64(); }
          int64_t target = fname == "lag" ? (int64_t)i - off : (int64_t)i + off;
          if (target >= 0 && target < (int64_t)psize) {
            size_t tr = idx[start + target];
            cur.current_row = &rows[tr];
            r = ex.Eval(*args[0], rows[tr]);
          } else if (args.size() >= 3) {
            cur.current_row = &rows[row_idx];
            r = ex.Eval(*args[2], rows[row_idx]);
          } else r = Value::Null(rtype);
        } else if (fname == "first_value" || fname == "last_value" || fname == "nth_value") {
          size_t fs, fe;
          frame_bounds(i, fs, fe);
          if (fs >= fe) r = Value::Null(rtype);
          else {
            size_t tr;
            if (fname == "first_value") {
              tr = idx[start + fs];
              if (w.ignore_nulls) { size_t k = fs; while (k < fe) { cur.current_row = &rows[idx[start + k]]; if (!ex.Eval(*args[0], rows[idx[start + k]]).is_null) break; k++; } tr = k < fe ? idx[start + k] : idx[start + fs]; }
            } else if (fname == "last_value") {
              tr = idx[start + fe - 1];
              if (w.ignore_nulls) { size_t k = fe; while (k > fs) { cur.current_row = &rows[idx[start + k - 1]]; if (!ex.Eval(*args[0], rows[idx[start + k - 1]]).is_null) break; k--; } tr = k > fs ? idx[start + k - 1] : idx[start + fe - 1]; }
            } else {
              cur.current_row = &rows[row_idx];
              int64_t n = ex.Eval(*args[1], rows[row_idx]).GetInt64();
              if (n < 1) throw InvalidInputException("nth_value needs a positive index");
              if (fs + (size_t)n - 1 >= fe) { r = Value::Null(rtype); results[row_idx] = r; continue; }
              tr = idx[start + fs + n - 1];
            }
            cur.current_row = &rows[tr];
            r = ex.Eval(*args[0], rows[tr]);
          }
        } else {
          // aggregate over frame
          size_t fs, fe;
          frame_bounds(i, fs, fe);
          std::vector<std::vector<Value>> arg_rows;
          for (size_t k = fs; k < fe; k++) {
            if (spec->frame.exclude == WindowFrame::EXCLUDE_CURRENT_ROW && k == i) continue;
            if (spec->frame.exclude == WindowFrame::EXCLUDE_GROUP && peer_start[k] == peer_start[i]) continue;
            if (spec->frame.exclude == WindowFrame::EXCLUDE_TIES && peer_start[k] == peer_start[i] && k != i) continue;
            size_t tr = idx[start + k];
            cur.current_row = &rows[tr];
            if (filter) { Value f = ex.Eval(*filter, rows[tr]); if (f.is_null || !f.ival) continue; }
            std::vector<Value> vals;
            for (auto &a : args) vals.push_back(ex.Eval(*a, rows[tr]));
            arg_rows.push_back(vals);
          }
          if (w.distinct) {
            std::vector<std::vector<Value>> d;
            for (auto &ar : arg_rows) { bool dup = false; for (auto &x : d) { bool same = true; for (size_t q = 0; q < ar.size(); q++) if (!ValuesEqual(ar[q], x[q])) { same = false; break; } if (same) { dup = true; break; } } if (!dup) d.push_back(ar); }
            arg_rows = d;
          }
          BoundExpr dummy(BKind::FUNCTION);
          dummy.type = rtype;
          for (auto &a : args) dummy.children.push_back(a);
          r = agg_ov->impl(arg_rows, ex.ctx, dummy);
          if (r.is_null) r = Value::Null(rtype);
          else if (r.type != rtype && !rtype.IsNested() && rtype.id != TypeId::ANY) r = CastValue(r, rtype, false);
        }
        if (r.is_null) r = Value::Null(rtype);
        results[row_idx] = r;
      }
      start = end;
    }
    cur.current_row = nullptr;
    for (size_t i = 0; i < nrows; i++) rows[i].push_back(results[i]);
    wb.names.push_back(w.ToString());
    wb.types.push_back(rtype);
    win_ctx.window_exprs.push_back({w.ToString(), base_cols + (int)wi});
  }
  win_ctx.bindings.push_back(wb);
}
EOF
echo done"}

actions.command:
cat > /workspace/src/window.cpp <<'EOF'
#include "binder.h"
#include <algorithm>
#include <cmath>

struct WinSpec {
  std::vector<BExpr> partitions;
  std::vector<std::pair<BExpr, std::pair<OrderType, NullOrder>>> orders;
  WindowFrame frame;
};

static int CompareRowsByKeys(const Row &a, const Row &b, size_t start, size_t n) {
  for (size_t i = 0; i < n; i++) {
    int c = Value::Compare(a[start + i], b[start + i]);
    if (c) return c;
  }
  return 0;
}

void ComputeWindowFunctions(Executor &ex, const QueryNode &node, std::vector<const Expr *> &windows, BindContext &cur, std::vector<Row> &rows, BindContext &win_ctx) {
  // dedupe
  std::vector<const Expr *> uniq;
  for (auto *w : windows) {
    bool dup = false;
    for (auto *u : uniq) if (u->ToString() == w->ToString()) { dup = true; break; }
    if (!dup) uniq.push_back(w);
  }
  // new context: copy bindings of cur, plus one binding for window results
  win_ctx.parent = cur.parent;
  win_ctx.bindings = cur.bindings;
  win_ctx.in_aggregate_stage = cur.in_aggregate_stage;
  win_ctx.group_exprs = cur.group_exprs;
  win_ctx.agg_exprs = cur.agg_exprs;
  win_ctx.using_map = cur.using_map;
  win_ctx.ctes = cur.ctes;
  int base_cols = cur.TotalColumns();
  Binding wb;
  wb.alias = "";
  wb.offset = base_cols;
  size_t nrows = rows.size();
  for (size_t wi = 0; wi < uniq.size(); wi++) {
    const Expr &w = *uniq[wi];
    // resolve window spec (named windows)
    const WindowSpec *spec = w.window.get();
    WindowSpec merged;
    if (spec && !spec->name.empty()) {
      const WindowSpec *named = nullptr;
      for (auto &nw : node.named_windows) if (IEquals(nw.first, spec->name)) named = nw.second.get();
      if (!named) throw BinderException("window \"" + spec->name + "\" does not exist");
      // merge: named provides partitions/orders; local may add orders/frame
      for (auto &p : named->partitions) merged.partitions.push_back(p->Copy());
      for (auto &o : named->orders) { OrderByNode n; n.expr = o.expr->Copy(); n.type = o.type; n.null_order = o.null_order; merged.orders.push_back(std::move(n)); }
      for (auto &o : spec->orders) { OrderByNode n; n.expr = o.expr->Copy(); n.type = o.type; n.null_order = o.null_order; merged.orders.push_back(std::move(n)); }
      merged.frame.specified = spec->frame.specified || named->frame.specified;
      const WindowFrame &f = spec->frame.specified ? spec->frame : named->frame;
      merged.frame.rows = f.rows; merged.frame.groups = f.groups; merged.frame.start = f.start; merged.frame.end = f.end; merged.frame.exclude = f.exclude;
      if (f.start_expr) merged.frame.start_expr = f.start_expr->Copy();
      if (f.end_expr) merged.frame.end_expr = f.end_expr->Copy();
      spec = &merged;
    }
    WinSpec ws;
    for (auto &p : spec->partitions) ws.partitions.push_back(ex.Bind(*p, cur, true));
    for (auto &o : spec->orders) ws.orders.push_back({ex.Bind(*o.expr, cur, true), {o.type, o.null_order}});
    std::string fname = ToLower(w.op);
    std::vector<BExpr> args;
    for (auto &c : w.children) { if (c->kind == ExprKind::STAR) continue; args.push_back(ex.Bind(*c, cur, true)); }
    BExpr filter;
    if (w.filter) filter = ex.BindCast(ex.Bind(*w.filter, cur, true), LogicalType(TypeId::BOOLEAN), false);
    // determine result type
    LogicalType rtype;
    auto &reg = Functions();
    AggFunction *agg = nullptr;
    const AggOverload *agg_ov = nullptr;
    if (fname == "row_number" || fname == "rank" || fname == "dense_rank" || fname == "ntile" || fname == "rank_dense") rtype = LogicalType(TypeId::BIGINT);
    else if (fname == "percent_rank" || fname == "cume_dist") rtype = LogicalType(TypeId::DOUBLE);
    else if (fname == "lag" || fname == "lead" || fname == "first_value" || fname == "last_value" || fname == "nth_value") {
      if (args.empty()) throw BinderException("Window function " + fname + " requires an argument");
      rtype = args[0]->type;
      if (rtype.id == TypeId::STRING_LITERAL) rtype = LogicalType(TypeId::VARCHAR);
      if (rtype.id == TypeId::INTEGER_LITERAL) rtype = LogicalType(TypeId::INTEGER);
      if (fname == "lag" || fname == "lead") {
        if (args.size() >= 3) { LogicalType t = MaxLogicalType(rtype, args[2]->type); if (t.id == TypeId::INTEGER_LITERAL) t = LogicalType(TypeId::INTEGER); rtype = t; args[2] = ex.BindCast(args[2], rtype, false); }
      }
    } else {
      agg = reg.FindAgg(fname == "count_star" ? "count_star" : fname);
      if (!agg) {
        CatalogException e("Aggregate Function with name " + fname + " does not exist!");
        e.position = w.position;
        throw e;
      }
      std::vector<LogicalType> types;
      for (auto &a : args) types.push_back(a->type);
      int best_cost = -1;
      for (auto &ov : agg->overloads) {
        if (!ov.varargs && ov.params.size() != types.size()) continue;
        if (ov.varargs && types.size() < ov.params.size()) continue;
        int cost = 0; bool ok = true;
        for (size_t i = 0; i < types.size(); i++) {
          const LogicalType &p = i < ov.params.size() ? ov.params[i] : (ov.params.empty() ? LogicalType(TypeId::ANY) : ov.params.back());
          if (p.id == TypeId::ANY || types[i] == p) continue;
          if (types[i].id == TypeId::INTEGER_LITERAL && p.IsNumeric()) { cost += p.id == TypeId::INTEGER ? 0 : 2; continue; }
          if (types[i].id == TypeId::SQLNULL) { cost += 1; continue; }
          if (p.id == TypeId::LIST && (types[i].id == TypeId::LIST || types[i].id == TypeId::ARRAY)) continue;
          int c = ImplicitCastCost(types[i], p);
          if (c < 0) { if (types[i].IsStringLike() && p.id == TypeId::VARCHAR) { cost += 1; continue; } ok = false; break; }
          cost += c;
        }
        if (!ok) continue;
        if (!agg_ov || cost < best_cost) { agg_ov = &ov; best_cost = cost; }
      }
      if (!agg_ov) {
        std::string msg = "No function matches the given name and argument types '" + fname + "(" + TypeListToString(types) + ")'. You might need to add explicit type casts.\n\tCandidate functions:\n";
        for (auto &ov : agg->overloads) { msg += "\t" + fname + "("; for (size_t i = 0; i < ov.params.size(); i++) { if (i) msg += ", "; msg += ov.params[i].ToString(); } msg += ") -> " + ov.ret.ToString() + "\n"; }
        BinderException e(msg); e.position = w.position; throw e;
      }
      for (size_t i = 0; i < args.size(); i++) {
        const LogicalType &p = i < agg_ov->params.size() ? agg_ov->params[i] : (agg_ov->params.empty() ? LogicalType(TypeId::ANY) : agg_ov->params.back());
        if (p.id == TypeId::ANY || p.id == TypeId::LIST) {
          if (args[i]->type.id == TypeId::STRING_LITERAL) { args[i]->type = LogicalType(TypeId::VARCHAR); if (args[i]->kind == BKind::CONSTANT) args[i]->constant.type = args[i]->type; }
          if (args[i]->type.id == TypeId::INTEGER_LITERAL) { args[i]->type = LogicalType(TypeId::INTEGER); if (args[i]->kind == BKind::CONSTANT) args[i]->constant.type = args[i]->type; }
          continue;
        }
        if (args[i]->type != p) args[i] = ex.BindCast(args[i], p, false);
      }
      std::vector<LogicalType> ftypes;
      for (auto &a : args) ftypes.push_back(a->type);
      rtype = agg_ov->bind ? agg_ov->bind(ftypes, args, ex.ctx) : agg_ov->ret;
    }
    // compute partition keys and order keys per row
    size_t np = ws.partitions.size(), no = ws.orders.size();
    std::vector<Row> keyed(nrows);
    std::vector<size_t> idx(nrows);
    for (size_t i = 0; i < nrows; i++) {
      cur.current_row = &rows[i];
      Row k;
      for (auto &p : ws.partitions) k.push_back(ex.Eval(*p, rows[i]));
      for (auto &o : ws.orders) k.push_back(ex.Eval(*o.first, rows[i]));
      keyed[i] = k;
      idx[i] = i;
    }
    cur.current_row = nullptr;
    std::stable_sort(idx.begin(), idx.end(), [&](size_t a, size_t b) {
