#include "func_util.h"
#include <regex>
#include <random>
#include <chrono>
#include <unistd.h>

// ---------------------------------------------------------------- regex helpers (std::regex ECMAScript)
static std::regex MakeRegex(const std::string &pattern, bool icase = false) {
  try {
    // translate some RE2 constructs: (?i) prefix
    std::string p = pattern;
    auto flags = std::regex::ECMAScript;
    if (StartsWith(p, "(?i)")) { p = p.substr(4); icase = true; }
    if (icase) flags |= std::regex::icase;
    // \d etc are supported; named classes like [[:alpha:]] supported
    return std::regex(p, flags);
  } catch (std::regex_error &e) {
    throw InvalidInputException("Could not parse regex pattern: " + pattern);
  }
}
bool RegexSearch(const std::string &s, const std::string &pattern, std::string *match) {
  std::regex re = MakeRegex(pattern);
  std::smatch m;
  if (std::regex_search(s, m, re)) { if (match) *match = m.str(0); return true; }
  return false;
}
bool RegexFullMatch(const std::string &s, const std::string &pattern) {
  std::regex re = MakeRegex(pattern);
  return std::regex_match(s, re);
}
std::string RegexExtract(const std::string &s, const std::string &pattern, int group, bool &matched) {
  std::regex re = MakeRegex(pattern);
  std::smatch m;
  matched = std::regex_search(s, m, re);
  if (!matched) return "";
  if (group < 0 || group >= (int)m.size()) throw InvalidInputException("Group index out of range of regex");
  return m.str(group);
}
std::vector<std::string> RegexExtractAll(const std::string &s, const std::string &pattern, int group) {
  std::regex re = MakeRegex(pattern);
  std::vector<std::string> out;
  for (auto it = std::sregex_iterator(s.begin(), s.end(), re); it != std::sregex_iterator(); ++it) {
    if (group < (int)it->size()) out.push_back(it->str(group));
  }
  return out;
}
std::string RegexReplace(const std::string &s, const std::string &pattern, const std::string &repl, const std::string &options) {
  bool global = options.find('g') != std::string::npos;
  bool icase = options.find('i') != std::string::npos;
  std::regex re = MakeRegex(pattern, icase);
  // convert \1 to $1
  std::string r;
  for (size_t i = 0; i < repl.size(); i++) {
    if (repl[i] == '\\' && i + 1 < repl.size() && isdigit((unsigned char)repl[i + 1])) { r += '$'; r += repl[i + 1]; i++; }
    else if (repl[i] == '$') r += "$$";
    else r += repl[i];
  }
  return std::regex_replace(s, re, r, global ? std::regex_constants::format_default : std::regex_constants::format_first_only);
}
std::vector<std::string> RegexSplit(const std::string &s, const std::string &pattern) {
  std::regex re = MakeRegex(pattern);
  std::vector<std::string> out;
  std::sregex_token_iterator it(s.begin(), s.end(), re, -1), end;
  for (; it != end; ++it) out.push_back(*it);
  if (out.empty()) out.push_back("");
  return out;
}

bool LikeMatch(const std::string &s, const std::string &p, char escape, bool ci) {
  // iterative wildcard matching on bytes (utf8 '_' handled approximately by char)
  size_t si = 0, pi = 0, star_p = std::string::npos, star_s = 0;
  auto eq = [&](char a, char b) { return ci ? tolower((unsigned char)a) == tolower((unsigned char)b) : a == b; };
  while (si < s.size()) {
    if (pi < p.size() && p[pi] == escape && escape != 0 && pi + 1 < p.size()) {
      if (eq(s[si], p[pi + 1])) { si++; pi += 2; continue; }
    } else if (pi < p.size() && p[pi] == '%') {
      star_p = pi++;
      star_s = si;
      continue;
    } else if (pi < p.size() && (p[pi] == '_' || eq(p[pi], s[si]))) {
      if (p[pi] == '_') {
        int len = Utf8CharLen((unsigned char)s[si]);
        si += len;
      } else si++;
      pi++;
      continue;
    }
    if (star_p != std::string::npos) {
      pi = star_p + 1;
      star_s += Utf8CharLen((unsigned char)s[star_s]);
      si = star_s;
      continue;
    }
    return false;
  }
  while (pi < p.size() && p[pi] == '%') pi++;
  return pi == p.size();
}

bool GlobMatch(const std::string &s, const std::string &p) {
  size_t si = 0, pi = 0, star_p = std::string::npos, star_s = 0;
  while (si < s.size()) {
    if (pi < p.size() && p[pi] == '*') { star_p = pi++; star_s = si; continue; }
    if (pi < p.size() && p[pi] == '[') {
      size_t close = p.find(']', pi + 1);
      if (close != std::string::npos) {
        bool neg = pi + 1 < p.size() && (p[pi + 1] == '!' || p[pi + 1] == '^');
        size_t k = pi + 1 + (neg ? 1 : 0);
        bool matched = false;
        while (k < close) {
          if (k + 2 < close && p[k + 1] == '-') { if (s[si] >= p[k] && s[si] <= p[k + 2]) matched = true; k += 3; }
          else { if (s[si] == p[k]) matched = true; k++; }
        }
        if (matched != neg) { si++; pi = close + 1; continue; }
      }
    } else if (pi < p.size() && (p[pi] == '?' || p[pi] == s[si])) { si++; pi++; continue; }
    if (star_p != std::string::npos) { pi = star_p + 1; si = ++star_s; continue; }
    return false;
  }
  while (pi < p.size() && p[pi] == '*') pi++;
  return pi == p.size();
}

