static std::vector<uint32_t> DecodeUtf8All(const std::string &s) {
  std::vector<uint32_t> cps;
  for (size_t i = 0; i < s.size();) {
    unsigned char c = s[i];
    int len = Utf8CharLen(c);
    uint32_t cp;
    if (len == 1) cp = c; else if (len == 2) cp = c & 0x1F; else if (len == 3) cp = c & 0x0F; else cp = c & 0x07;
