static int64_t Instr(const std::string &hay, const std::string &needle) {
  if (needle.empty()) return 1;
  size_t p = hay.find(needle);
  if (p == std::string::npos) return 0;
  return (int64_t)Utf8Length(hay.substr(0, p)) + 1;
}

static std::string TrimChars(const std::string &s, const std::string &chars, bool left, bool right) {
  auto cs = Utf8Chars(s);
  auto trimset = Utf8Chars(chars);
  auto in_set = [&](const std::string &c) { for (auto &t : trimset) if (t == c) return true; return false; };
  size_t a = 0, b = cs.size();
  if (left) while (a < b && in_set(cs[a])) a++;
  if (right) while (b > a && in_set(cs[b - 1])) b--;
  std::string r;
  for (size_t i = a; i < b; i++) r += cs[i];
  return r;
}

