    m += (char)0x80;
    while (m.size() % 64 != 56) m += (char)0;
    for (int i = 0; i < 8; i++) m += (char)((bitlen >> (8 * i)) & 0xFF);
    for (size_t off = 0; off < m.size(); off += 64) {
      uint32_t M[16];
      for (int i = 0; i < 16; i++) M[i] = (uint32_t)(unsigned char)m[off + i * 4] | ((uint32_t)(unsigned char)m[off + i * 4 + 1] << 8) | ((uint32_t)(unsigned char)m[off + i * 4 + 2] << 16) | ((uint32_t)(unsigned char)m[off + i * 4 + 3] << 24);
      uint32_t A = a0, B = b0, C = c0, D = d0;
      for (int i = 0; i < 64; i++) {
        uint32_t F; int g;
        if (i < 16) { F = (B & C) | (~B & D); g = i; }
        else if (i < 32) { F = (D & B) | (~D & C); g = (5 * i + 1) % 16; }
        else if (i < 48) { F = B ^ C ^ D; g = (3 * i + 5) % 16; }
        else { F = C ^ (B | ~D); g = (7 * i) % 16; }
        F = F + A + K[i] + M[g];
        A = D; D = C; C = B;
        B = B + rotl(F, S[i]);
      }
      a0 += A; b0 += B; c0 += C; d0 += D;
    }
    char buf[33];
    uint32_t parts[4] = {a0, b0, c0, d0};
    for (int i = 0; i < 4; i++) for (int j = 0; j < 4; j++) snprintf(buf + i * 8 + j * 2, 3, "%02x", (parts[i] >> (8 * j)) & 0xFF);
    return std::string(buf, 32);
  }
};
