static std::string FormatNumberWithSep(int128_t v) {
  std::string s = Int128ToString(v < 0 ? -v : v);
  std::string out;
  int cnt = 0;
  for (int i = (int)s.size() - 1; i >= 0; i--) { out = s[i] + out; if (++cnt % 3 == 0 && i > 0) out = "," + out; }
  if (v < 0) out = "-" + out;
  return out;
}

