static std::string PrintfFormat(const std::string &fmt, const std::vector<Value> &args, bool python_style) {
  std::string out;
  size_t ai = 0;
  for (size_t i = 0; i < fmt.size(); i++) {
    char c = fmt[i];
    if (python_style) {
      if (c == '{') {
        if (i + 1 < fmt.size() && fmt[i + 1] == '{') { out += '{'; i++; continue; }
        size_t close = fmt.find('}', i);
        if (close == std::string::npos) throw InvalidInputException("Invalid format string");
        std::string spec = fmt.substr(i + 1, close - i - 1);
        size_t colon = spec.find(':');
        std::string idxs = colon == std::string::npos ? spec : spec.substr(0, colon);
        std::string fs = colon == std::string::npos ? "" : spec.substr(colon + 1);
        size_t idx = idxs.empty() ? ai++ : (size_t)atoi(idxs.c_str());
        if (idx >= args.size()) throw InvalidInputException("Not enough parameters for format string");
        const Value &v = args[idx];
        std::string s = v.is_null ? "NULL" : v.ToString();
        if (fs == ",") { if (v.type.IsInteger()) s = FormatNumberWithSep(v.ival); }
        else if (fs == "d" && v.type.IsNumeric()) { s = Int128ToString((int128_t)v.GetDouble()); }
        else if (fs == "s") {}
        else if (!fs.empty() && fs.back() == 'f') { char buf[64]; int prec = 6; if (fs.size() > 1 && fs[0] == '.') prec = atoi(fs.substr(1, fs.size() - 2).c_str()); snprintf(buf, sizeof(buf), "%.*f", prec, v.GetDouble()); s = buf; }
        else if (fs == "x") { char buf[64]; snprintf(buf, sizeof(buf), "%llx", (long long)v.GetInt64()); s = buf; }
        else if (fs == "X") { char buf[64]; snprintf(buf, sizeof(buf), "%llX", (long long)v.GetInt64()); s = buf; }
        else if (fs == "o") { char buf[64]; snprintf(buf, sizeof(buf), "%llo", (long long)v.GetInt64()); s = buf; }
        else if (fs == "b") { std::string b; int128_t x = v.ival; if (x == 0) b = "0"; while (x > 0) { b = (char)('0' + (int)(x & 1)) + b; x >>= 1; } s = b; }
        else if (fs == "e") { char buf[64]; snprintf(buf, sizeof(buf), "%e", v.GetDouble()); s = buf; }
        else if (!fs.empty() && (isdigit((unsigned char)fs[0]) || fs[0] == '<' || fs[0] == '>' || fs[0] == '^')) {
          char align = '>'; size_t p = 0;
          if (fs[0] == '<' || fs[0] == '>' || fs[0] == '^') { align = fs[0]; p = 1; }
          int width = atoi(fs.substr(p).c_str());
          if (!v.type.IsNumeric() && p == 0) align = '<';
          int pad = width - (int)Utf8Length(s);
          if (pad > 0) { if (align == '<') s += std::string(pad, ' '); else if (align == '>') s = std::string(pad, ' ') + s; else { s = std::string(pad / 2, ' ') + s + std::string(pad - pad / 2, ' '); } }
        }
        out += s;
        i = close;
        continue;
      }
      if (c == '}' && i + 1 < fmt.size() && fmt[i + 1] == '}') { out += '}'; i++; continue; }
      out += c;
      continue;
    }
    if (c != '%') { out += c; continue; }
    if (i + 1 < fmt.size() && fmt[i + 1] == '%') { out += '%'; i++; continue; }
    // parse spec
    size_t j = i + 1;
    std::string flags;
    while (j < fmt.size() && strchr("-+ 0#'", fmt[j])) flags += fmt[j++];
    std::string width;
    while (j < fmt.size() && isdigit((unsigned char)fmt[j])) width += fmt[j++];
    std::string prec;
    if (j < fmt.size() && fmt[j] == '.') { j++; prec = "."; while (j < fmt.size() && isdigit((unsigned char)fmt[j])) prec += fmt[j++]; }
    while (j < fmt.size() && (fmt[j] == 'l' || fmt[j] == 'h')) j++;
    if (j >= fmt.size()) throw InvalidInputException("Invalid format string");
    char conv = fmt[j];
    if (ai >= args.size()) throw InvalidInputException("Not enough parameters for format string");
    const Value &v = args[ai++];
    char buf[512];
    std::string spec = "%" + flags + width + prec;
    std::string s;
    switch (conv) {
    case 'd': case 'i': {
      if (flags.find('\'') != std::string::npos) { s = FormatNumberWithSep((int128_t)v.GetDouble()); std::string f2 = flags; f2.erase(std::remove(f2.begin(), f2.end(), '\''), f2.end()); snprintf(buf, sizeof(buf), ("%" + f2 + width + "s").c_str(), s.c_str()); s = buf; break; }
      snprintf(buf, sizeof(buf), (spec + "lld").c_str(), (long long)(v.type.IsFloating() ? (int64_t)v.dval : v.GetInt64())); s = buf; break;
    }
    case 's': s = v.is_null ? "NULL" : v.ToString(); snprintf(buf, sizeof(buf), (spec + "s").c_str(), s.c_str()); s = buf; break;
    case 'f': case 'F': case 'e': case 'E': case 'g': case 'G': snprintf(buf, sizeof(buf), (spec + conv).c_str(), v.GetDouble()); s = buf; break;
    case 'x': case 'X': case 'o': snprintf(buf, sizeof(buf), (spec + "ll" + conv).c_str(), (long long)v.GetInt64()); s = buf; break;
    case 'c': s = std::string(1, (char)v.GetInt64()); break;
    case 'b': { std::string b; int128_t x = v.ival; if (x == 0) b = "0"; while (x > 0) { b = (char)('0' + (int)(x & 1)) + b; x >>= 1; } s = b; break; }
    default: throw InvalidInputException("Invalid format specifier");
    }
    out += s;
    i = j;
  }
  return out;
}

static std::string Bar(double x, double min, double max, double width) {
  if (width <= 0) throw InvalidInputException("Width must be positive");
  double frac = max == min ? 1.0 : (x - min) / (max - min);
  if (frac < 0) frac = 0;
  if (frac > 1) frac = 1;
  double chars = frac * width;
  int full = (int)chars;
  std::string r;
  for (int i = 0; i < full; i++) r += "\xE2\x96\x88";
  static const char *partials[] = {"", "\xE2\x96\x8F", "\xE2\x96\x8E", "\xE2\x96\x8D", "\xE2\x96\x8C", "\xE2\x96\x8B", "\xE2\x96\x8A", "\xE2\x96\x89"};
  int part = (int)((chars - full) * 8);
  if (part > 0 && part < 8) r += partials[part];
  return r;
}

