std::string FormatBytes(int64_t bytes, bool binary) {
  const char *units_bin[] = {"bytes", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"};
  const char *units_dec[] = {"bytes", "kB", "MB", "GB", "TB", "PB", "EB"};
  double base = binary ? 1024.0 : 1000.0;
  double v = (double)bytes;
  int idx = 0;
  bool neg = v < 0;
  if (neg) v = -v;
  while (v >= base && idx < 6) { v /= base; idx++; }
  char buf[64];
  if (idx == 0) snprintf(buf, sizeof(buf), "%s%lld bytes", neg ? "-" : "", (long long)(neg ? -bytes : bytes));
  else snprintf(buf, sizeof(buf), "%s%.1f %s", neg ? "-" : "", v, binary ? units_bin[idx] : units_dec[idx]);
  return buf;
}
