static LogicalType NumType(const LogicalType &t) {
  if (t.id == TypeId::INTEGER_LITERAL) return T(TypeId::INTEGER);
  if (t.id == TypeId::STRING_LITERAL) return T(TypeId::DOUBLE);
  if (t.id == TypeId::SQLNULL) return T(TypeId::INTEGER);
  return t;
}

// generic unary double function
static void AddDoubleFn(FunctionRegistry &r, const char *name, double (*fn)(double)) {
  r.AddScalar(name, OV({T(TypeId::DOUBLE)}, T(TypeId::DOUBLE), [fn](std::vector<Value> &a, ExecContext &, const BoundExpr &) -> Value {
    if (a[0].is_null) return NullOf(T(TypeId::DOUBLE));
    return VDbl(fn(a[0].dval));
  }));
}

static Value RoundValue(const Value &v, int64_t digits, const LogicalType &rt) {
  if (v.is_null) return NullOf(rt);
  if (v.type.id == TypeId::DECIMAL) {
    int scale = v.type.scale;
    if (digits >= scale) return v;
    if (digits < 0) digits = 0;
    int128_t div = Pow10(scale - (int)digits);
    int128_t x = v.ival;
    int128_t q = x / div, rem = x % div;
    if (rem >= (div + 1) / 2) q++;
    else if (rem <= -((div + 1) / 2)) q--;
    // result scale = digits
    Value out = Value::Decimal(q, rt.width, rt.scale);
    return out;
  }
  if (v.type.IsInteger()) return v;
  double d = v.GetDouble();
  double m = std::pow(10.0, (double)digits);
  double r = std::round(d * m) / m;
  if (digits < 0) { r = std::round(d / std::pow(10.0, (double)-digits)) * std::pow(10.0, (double)-digits); }
  if (v.type.id == TypeId::FLOAT) return Value::Float((float)r);
  return VDbl(r);
}

