static Value AgeInterval(int64_t a, int64_t b) {
  // a - b as interval with years/months/days/time
  bool neg = a < b;
  if (neg) std::swap(a, b);
  int32_t da = TimestampToDate(a), db = TimestampToDate(b);
  int64_t ta = a - DateToTimestampMicros(da), tb = b - DateToTimestampMicros(db);
  DateParts pa = DateToYMD(da), pb = DateToYMD(db);
  int64_t micros = ta - tb;
  int days = pa.day - pb.day;
  int months = (pa.year - pb.year) * 12 + (pa.month - pb.month);
  if (micros < 0) { micros += 86400000000LL; days--; }
  if (days < 0) { months--; int pm = pa.month - 1; int py = pa.year; if (pm < 1) { pm = 12; py--; } days += DaysInMonth(py, pm); }
  Interval iv; iv.months = months; iv.days = days; iv.micros = micros;
  if (neg) { iv.months = -iv.months; iv.days = -iv.days; iv.micros = -iv.micros; }
  return Value::IntervalV(iv);
}

