static int IsoWeek(int32_t days, int *iso_year = nullptr) {
  DateParts p = DateToYMD(days);
  int dow = DayOfWeek(days);  // 0 = sunday
  int isodow = dow == 0 ? 7 : dow;
  int doy = DayOfYear(days);
  int week = (doy - isodow + 10) / 7;
  int year = p.year;
  if (week < 1) {
