    case 'p': out += h < 12 ? "AM" : "PM"; break;
    case 'A': out += kDayNames[DayOfWeek(days)]; break;
    case 'a': out += kDayAbbr[DayOfWeek(days)]; break;
    case 'B': out += kMonthNames[p.month - 1]; break;
    case 'b': case 'h': out += kMonthAbbr[p.month - 1]; break;
    case 'j': snprintf(buf, sizeof(buf), nopad ? "%d" : "%03d", DayOfYear(days)); out += buf; break;
    case 'w': snprintf(buf, sizeof(buf), "%d", DayOfWeek(days)); out += buf; break;
    case 'u': { int d = DayOfWeek(days); snprintf(buf, sizeof(buf), "%d", d == 0 ? 7 : d); out += buf; break; }
    case 'U': { int doy = DayOfYear(days) - 1; int dow = DayOfWeek(days); snprintf(buf, sizeof(buf), "%02d", (doy + 7 - dow) / 7); out += buf; break; }
    case 'W': { int doy = DayOfYear(days) - 1; int dow = (DayOfWeek(days) + 6) % 7; snprintf(buf, sizeof(buf), "%02d", (doy + 7 - dow) / 7); out += buf; break; }
    case 'V': snprintf(buf, sizeof(buf), "%02d", IsoWeek(days)); out += buf; break;
    case 'G': { int y; IsoWeek(days, &y); snprintf(buf, sizeof(buf), "%04d", y); out += buf; break; }
