bool StrpTime(const std::string &s, const std::string &fmt, int64_t &micros, std::string &err, bool &has_time) {
  int year = 1970, month = 1, day = 1; int64_t h = 0, mi = 0, sec = 0, us = 0; bool pm = false, has_ampm = false; int tz_off = 0;
  has_time = false;
  size_t si = 0;
  auto read_num = [&](int maxd, int64_t &out) -> bool {
    size_t start = si; int64_t v = 0; int cnt = 0;
    while (si < s.size() && isdigit((unsigned char)s[si]) && cnt < maxd) { v = v * 10 + (s[si] - '0'); si++; cnt++; }
    if (si == start) return false;
    out = v; return true;
  };
  for (size_t i = 0; i < fmt.size(); i++) {
    if (fmt[i] != '%') {
      if (isspace((unsigned char)fmt[i])) { while (si < s.size() && isspace((unsigned char)s[si])) si++; continue; }
      if (si >= s.size() || s[si] != fmt[i]) { err = "Expected character '" + std::string(1, fmt[i]) + "' at position " + std::to_string(si); return false; }
      si++;
