    }
    char c = fmt[++i];
    if (c == '-') c = fmt[++i];
    int64_t v;
    switch (c) {
    case 'Y': { bool neg = false; if (si < s.size() && s[si] == '-') { neg = true; si++; } if (!read_num(4, v)) { err = "Expected year"; return false; } year = (int)(neg ? -v : v); break; }
    case 'y': if (!read_num(2, v)) { err = "Expected year"; return false; } year = (int)(v < 69 ? 2000 + v : 1900 + v); break;
    case 'm': if (!read_num(2, v)) { err = "Expected month"; return false; } month = (int)v; break;
    case 'd': if (!read_num(2, v)) { err = "Expected day"; return false; } day = (int)v; break;
    case 'H': if (!read_num(2, v)) { err = "Expected hour"; return false; } h = v; has_time = true; break;
    case 'I': if (!read_num(2, v)) { err = "Expected hour"; return false; } h = v; has_time = true; break;
    case 'M': if (!read_num(2, v)) { err = "Expected minute"; return false; } mi = v; has_time = true; break;
    case 'S': if (!read_num(2, v)) { err = "Expected second"; return false; } sec = v; has_time = true; break;
    case 'f': { size_t start = si; if (!read_num(6, v)) { err = "Expected microseconds"; return false; } int cnt = (int)(si - start); while (cnt < 6) { v *= 10; cnt++; } us = v; has_time = true; break; }
    case 'g': { if (!read_num(3, v)) { err = "Expected milliseconds"; return false; } us = v * 1000; has_time = true; break; }
    case 'p': { if (si + 1 < s.size()) { std::string ap = ToUpper(s.substr(si, 2)); if (ap == "AM" || ap == "PM") { pm = ap == "PM"; has_ampm = true; si += 2; } else { err = "Expected AM/PM"; return false; } } else { err = "Expected AM/PM"; return false; } break; }
    case 'B': case 'b': case 'h': {
      bool found = false;
      for (int m = 0; m < 12; m++) {
        std::string full = kMonthNames[m], ab = kMonthAbbr[m];
        if (c == 'B' && s.size() - si >= full.size() && IEquals(s.substr(si, full.size()), full)) { month = m + 1; si += full.size(); found = true; break; }
        if (c != 'B' && s.size() - si >= ab.size() && IEquals(s.substr(si, ab.size()), ab)) { month = m + 1; si += ab.size(); found = true; break; }
      }
      if (!found) { err = "Expected month name"; return false; }
      break;
    }
    case 'A': case 'a': {
      bool found = false;
      for (int d = 0; d < 7; d++) {
        std::string full = kDayNames[d], ab = kDayAbbr[d];
        if (c == 'A' && s.size() - si >= full.size() && IEquals(s.substr(si, full.size()), full)) { si += full.size(); found = true; break; }
        if (c == 'a' && s.size() - si >= ab.size() && IEquals(s.substr(si, ab.size()), ab)) { si += ab.size(); found = true; break; }
      }
      if (!found) { err = "Expected day name"; return false; }
      break;
    }
    case 'j': if (!read_num(3, v)) { err = "Expected day of year"; return false; } { int32_t d = DateFromYMD(year, 1, 1) + (int32_t)v - 1; DateParts p = DateToYMD(d); month = p.month; day = p.day; } break;
    case 'z': {
      if (si < s.size() && (s[si] == '+' || s[si] == '-')) {
        bool neg = s[si] == '-'; si++;
        int64_t hh = 0, mm = 0;
        if (!read_num(2, hh)) { err = "Expected timezone"; return false; }
        if (si < s.size() && s[si] == ':') si++;
        read_num(2, mm);
        tz_off = (int)((hh * 60 + mm) * (neg ? -1 : 1));
      } else if (si < s.size() && (s[si] == 'Z' || s[si] == 'z')) si++;
      break;
    }
    case 'Z': { while (si < s.size() && (isalpha((unsigned char)s[si]) || s[si] == '/' || s[si] == '_')) si++; break; }
    case '%': if (si < s.size() && s[si] == '%') si++; break;
    default: err = "Unsupported format specifier"; return false;
    }
  }
  if (si != s.size()) { err = "Full specifier did not match: trailing characters"; return false; }
  if (has_ampm) { if (pm && h < 12) h += 12; if (!pm && h == 12) h = 0; }
  if (!IsValidYMD(year, month, day)) { err = "Invalid date"; return false; }
  micros = DateToTimestampMicros(DateFromYMD(year, month, day)) + h * 3600000000LL + mi * 60000000LL + sec * 1000000LL + us - (int64_t)tz_off * 60000000LL;
  return true;
}

static int64_t NowMicros() {
  auto now = std::chrono::system_clock::now();
  return std::chrono::duration_cast<std::chrono::microseconds>(now.time_since_epoch()).count();
}

static Value MakeIntervalFromDouble(double v, const std::string &unit) {
  Interval iv;
  if (unit == "years") iv.months = (int32_t)(v * 12);
  else if (unit == "months") iv.months = (int32_t)v;
  else if (unit == "weeks") iv.days = (int32_t)(v * 7);
  else if (unit == "days") iv.days = (int32_t)v;
  else if (unit == "hours") iv.micros = (int64_t)(v * 3600000000.0);
  else if (unit == "minutes") iv.micros = (int64_t)(v * 60000000.0);
  else if (unit == "seconds") iv.micros = (int64_t)std::llround(v * 1000000.0);
  else if (unit == "milliseconds") iv.micros = (int64_t)std::llround(v * 1000.0);
  else if (unit == "microseconds") iv.micros = (int64_t)std::llround(v);
  else if (unit == "decades") iv.months = (int32_t)(v * 120);
  else if (unit == "centuries") iv.months = (int32_t)(v * 1200);
  else if (unit == "millennia") iv.months = (int32_t)(v * 12000);
  else if (unit == "quarters") iv.months = (int32_t)(v * 3);
  return Value::IntervalV(iv);
}

static int64_t DateDiff(const std::string &part_in, int64_t a, int64_t b) {
  std::string part = ToLower(part_in);
  // count boundaries crossed
  bool td;
  if (part == "microsecond" || part == "microseconds" || part == "us") return b - a;
  if (part == "millisecond" || part == "milliseconds" || part == "ms") return TruncMicros("ms", b, td) / 1000 - TruncMicros("ms", a, td) / 1000;
  if (part == "second" || part == "seconds" || part == "s" || part == "sec") return TruncMicros("s", b, td) / 1000000 - TruncMicros("s", a, td) / 1000000;
  if (part == "minute" || part == "minutes" || part == "min") return TruncMicros("min", b, td) / 60000000LL - TruncMicros("min", a, td) / 60000000LL;
  if (part == "hour" || part == "hours" || part == "h") return TruncMicros("h", b, td) / 3600000000LL - TruncMicros("h", a, td) / 3600000000LL;
  int32_t da = TimestampToDate(a), db = TimestampToDate(b);
  DateParts pa = DateToYMD(da), pb = DateToYMD(db);
  if (part == "day" || part == "days" || part == "d") return (int64_t)db - da;
  if (part == "week" || part == "weeks" || part == "w") return TruncMicros("week", b, td) / 86400000000LL / 7 - TruncMicros("week", a, td) / 86400000000LL / 7 + (((TruncMicros("week", b, td) / 86400000000LL) % 7 + 7) % 7 - ((TruncMicros("week", a, td) / 86400000000LL) % 7 + 7) % 7 != 0 ? ((TruncMicros("week", b, td) - TruncMicros("week", a, td)) / (7 * 86400000000LL) - (TruncMicros("week", b, td) / 86400000000LL / 7 - TruncMicros("week", a, td) / 86400000000LL / 7)) : 0);
  if (part == "month" || part == "months" || part == "mon") return (int64_t)(pb.year - pa.year) * 12 + (pb.month - pa.month);
  if (part == "quarter" || part == "quarters") return (int64_t)(pb.year - pa.year) * 4 + ((pb.month - 1) / 3 - (pa.month - 1) / 3);
  if (part == "year" || part == "years" || part == "y") return pb.year - pa.year;
  if (part == "decade" || part == "decades") return pb.year / 10 - pa.year / 10;
  if (part == "century" || part == "centuries") return (pb.year - 1) / 100 - (pa.year - 1) / 100;
  if (part == "millennium" || part == "millennia") return (pb.year - 1) / 1000 - (pa.year - 1) / 1000;
  throw NotImplementedException("\"" + part_in + "\" units \"" + part_in + "\" not recognized");
}

static Value AgeInterval(int64_t a, int64_t b) {
  // a - b as interval with years/months/days/time
  bool neg = a < b;
  if (neg) std::swap(a, b);
  int32_t da = TimestampToDate(a), db = TimestampToDate(b);
  int64_t ta = a - DateToTimestampMicros(da), tb = b - DateToTimestampMicros(db);
  DateParts pa = DateToYMD(da), pb = DateToYMD(db);
  int64_t micros = ta - tb;
  int days = pa.day - pb.day;
  int months = (pa.year - pb.year) * 12 + (pa.month - pb.month);
  if (micros < 0) { micros += 86400000000LL; days--; }
  if (days < 0) { months--; int pm = pa.month - 1; int py = pa.year; if (pm < 1) { pm = 12; py--; } days += DaysInMonth(py, pm); }
  Interval iv; iv.months = months; iv.days = days; iv.micros = micros;
  if (neg) { iv.months = -iv.months; iv.days = -iv.days; iv.micros = -iv.micros; }
  return Value::IntervalV(iv);
}

