static AggOverload AOV(std::vector<LogicalType> params, LogicalType ret, AggImpl impl) { AggOverload o; o.params = params; o.ret = ret; o.impl = impl; return o; }
static AggOverload AOVB(std::vector<LogicalType> params, BindFn bind, AggImpl impl) { AggOverload o; o.params = params; o.bind = bind; o.impl = impl; o.ret = LogicalType(TypeId::ANY); return o; }

static LogicalType FirstType(std::vector<LogicalType> &types) {
  LogicalType t = types.empty() ? T(TypeId::INTEGER) : types[0];
  if (t.id == TypeId::INTEGER_LITERAL) t = T(TypeId::INTEGER);
  if (t.id == TypeId::STRING_LITERAL) t = T(TypeId::VARCHAR);
  if (t.id == TypeId::SQLNULL) t = T(TypeId::INTEGER);
  return t;
}

static double Mean(const std::vector<double> &v) { double s = 0; for (double x : v) s += x; return v.empty() ? 0 : s / v.size(); }

static std::vector<double> Doubles(std::vector<std::vector<Value>> &rows, size_t col = 0) {
  std::vector<double> out;
  for (auto &r : rows) if (!r[col].is_null) out.push_back(r[col].GetDouble());
  return out;
}

static Value Quantile(std::vector<Value> vals, double q, bool cont, const LogicalType &rt) {
  if (vals.empty()) return NullOf(rt);
  vals = SortedValues(vals);
  double pos = q * (vals.size() - 1);
  size_t lo = (size_t)std::floor(pos), hi = (size_t)std::ceil(pos);
  if (!cont) {
    // DuckDB quantile_disc: uses floor? It picks element at ceil(q*n)-1 ... use nearest-rank on sorted: index = ceil(q * n) - 1
    size_t idx = (size_t)std::ceil(q * vals.size());
    if (idx > 0) idx--;
    if (idx >= vals.size()) idx = vals.size() - 1;
    return vals[idx];
  }
  const Value &a = vals[lo], &b = vals[hi];
  double frac = pos - lo;
  if (rt.id == TypeId::DOUBLE) { return VDbl(a.GetDouble() + (b.GetDouble() - a.GetDouble()) * frac); }
  if (rt.id == TypeId::DECIMAL) { double x = (double)a.ival + ((double)b.ival - (double)a.ival) * frac; return Value::Decimal((int128_t)std::llround(x), rt.width, rt.scale); }
  if (rt.IsTemporal()) { int64_t x = (int64_t)a.ival; int64_t y = (int64_t)b.ival; Value v(rt); v.is_null = false; v.ival = x + (int64_t)std::llround((double)(y - x) * frac); if (a.type.id == TypeId::DATE) v.ival = DateToTimestampMicros((int32_t)x) + (int64_t)std::llround((double)(DateToTimestampMicros((int32_t)y) - DateToTimestampMicros((int32_t)x)) * frac); return v; }
  if (rt.id == TypeId::INTERVAL) { Value v(rt); v.is_null = false; v.interval.months = (int32_t)(a.interval.months + (b.interval.months - a.interval.months) * frac); v.interval.days = (int32_t)(a.interval.days + (b.interval.days - a.interval.days) * frac); v.interval.micros = (int64_t)(a.interval.micros + (b.interval.micros - a.interval.micros) * frac); return v; }
  return frac < 0.5 ? a : b;
}

static LogicalType QuantileContType(const LogicalType &t) {
  if (t.id == TypeId::DECIMAL) return t;
  if (t.IsNumeric()) return T(TypeId::DOUBLE);
  if (t.id == TypeId::DATE) return T(TypeId::TIMESTAMP);
  return t;
}

void RegisterAggregateFunctions(FunctionRegistry &r) {
  LogicalType ANY = T(TypeId::ANY), B = T(TypeId::BIGINT), D = T(TypeId::DOUBLE), V = T(TypeId::VARCHAR), BOOL = T(TypeId::BOOLEAN), H = T(TypeId::HUGEINT);
  r.AddAgg("count_star", AOV({}, B, AGGIMPL { return VBig((int64_t)rows.size()); }));
  r.AddAgg("count", AOV({}, B, AGGIMPL { return VBig((int64_t)rows.size()); }));
  r.AddAgg("count", AOV({ANY}, B, AGGIMPL { int64_t c = 0; for (auto &rw : rows) if (!rw[0].is_null) c++; return VBig(c); }));
  r.AddAgg("count_if", AOV({BOOL}, H, AGGIMPL { int64_t c = 0; for (auto &rw : rows) if (!rw[0].is_null && rw[0].ival) c++; return Value::HugeInt(c); }));
  r.AddAgg("countif", r.aggregates["count_if"].overloads[0]);
  // sum
  r.AddAgg("sum", AOVB({ANY}, BINDFN {
    LogicalType t = FirstType(types);
    if (t.id == TypeId::DECIMAL) return LogicalType::Decimal(38, t.scale);
    if (t.IsFloating()) return T(TypeId::DOUBLE);
    if (t.IsInteger() || t.id == TypeId::BOOLEAN) return T(TypeId::HUGEINT);
    if (t.id == TypeId::INTERVAL) return t;
    throw BinderException("No function matches the given name and argument types 'sum(" + t.ToString() + ")'. You might need to add explicit type casts.\n\tCandidate functions:\n\tsum(DECIMAL) -> DECIMAL\n\tsum(BOOLEAN) -> HUGEINT\n\tsum(SMALLINT) -> HUGEINT\n\tsum(INTEGER) -> HUGEINT\n\tsum(BIGINT) -> HUGEINT\n\tsum(HUGEINT) -> HUGEINT\n\tsum(DOUBLE) -> DOUBLE\n");
  }, AGGIMPL {
    bool any = false;
    if (e.type.id == TypeId::DOUBLE) { double s = 0; for (auto &rw : rows) if (!rw[0].is_null) { s += rw[0].GetDouble(); any = true; } return any ? VDbl(s) : NullOf(e.type); }
    if (e.type.id == TypeId::INTERVAL) { Interval s; for (auto &rw : rows) if (!rw[0].is_null) { s.months += rw[0].interval.months; s.days += rw[0].interval.days; s.micros += rw[0].interval.micros; any = true; } return any ? Value::IntervalV(s) : NullOf(e.type); }
    int128_t s = 0;
    for (auto &rw : rows) if (!rw[0].is_null) { s += rw[0].ival; any = true; }
    if (!any) return NullOf(e.type);
    if (e.type.id == TypeId::DECIMAL) return Value::Decimal(s, 38, e.type.scale);
    return Value::HugeInt(s);
  }));
  r.AddAgg("sum_no_overflow", r.aggregates["sum"].overloads[0]);
  r.AddAgg("fsum", AOV({D}, D, AGGIMPL { bool any = false; double s = 0, c = 0; for (auto &rw : rows) if (!rw[0].is_null) { any = true; double y = rw[0].dval - c; double t = s + y; c = (t - s) - y; s = t; } return any ? VDbl(s) : NullOf(T(TypeId::DOUBLE)); }));
  r.AddAgg("kahan_sum", r.aggregates["fsum"].overloads[0]);
  r.AddAgg("sumkahan", r.aggregates["fsum"].overloads[0]);
  r.AddAgg("avg", AOVB({ANY}, BINDFN { LogicalType t = FirstType(types); if (!t.IsNumeric()) throw BinderException("No function matches the given name and argument types 'avg(" + t.ToString() + ")'. You might need to add explicit type casts.\n\tCandidate functions:\n\tavg(DECIMAL) -> DECIMAL\n\tavg(SMALLINT) -> DOUBLE\n\tavg(INTEGER) -> DOUBLE\n\tavg(BIGINT) -> DOUBLE\n\tavg(HUGEINT) -> DOUBLE\n\tavg(DOUBLE) -> DOUBLE\n"); return T(TypeId::DOUBLE); }, AGGIMPL {
    auto v = Doubles(rows); if (v.empty()) return NullOf(T(TypeId::DOUBLE));
    if (!rows.empty() && rows[0][0].type.IsInteger()) { int128_t s = 0; int64_t n = 0; for (auto &rw : rows) if (!rw[0].is_null) { s += rw[0].ival; n++; } return VDbl((double)s / (double)n); }
    return VDbl(Mean(v));
  }));
  r.AddAgg("mean", r.aggregates["avg"].overloads[0]);
  r.AddAgg("favg", AOV({D}, D, AGGIMPL { auto v = Doubles(rows); if (v.empty()) return NullOf(T(TypeId::DOUBLE)); return VDbl(Mean(v)); }));
  // min / max
  for (auto name : {"min", "max"}) {
    bool is_min = std::string(name) == "min";
    r.AddAgg(name, AOVB({ANY}, BINDFN { return FirstType(types); }, [is_min](std::vector<std::vector<Value>> &rows, ExecContext &, const BoundExpr &e) -> Value {
      Value best; bool have = false;
      for (auto &rw : rows) { if (rw[0].is_null) continue; if (!have || (is_min ? Value::Compare(rw[0], best) < 0 : Value::Compare(rw[0], best) > 0)) { best = rw[0]; have = true; } }
      return have ? best : NullOf(e.type);
    }));
    r.AddAgg(name, AOVB({ANY, B}, BINDFN { return TLIST(FirstType(types)); }, [is_min](std::vector<std::vector<Value>> &rows, ExecContext &, const BoundExpr &e) -> Value {
      std::vector<Value> vals; for (auto &rw : rows) if (!rw[0].is_null) vals.push_back(rw[0]);
      vals = SortedValues(vals);
      if (!is_min) std::reverse(vals.begin(), vals.end());
      int64_t n = rows.empty() ? 0 : rows[0][1].GetInt64();
      if ((int64_t)vals.size() > n) vals.resize((size_t)n);
      return Value::List(e.type.child(), vals);
    }));
  }
  for (auto name : {"first", "arbitrary", "any_value"}) {
    bool skip_null = std::string(name) == "any_value";
    r.AddAgg(name, AOVB({ANY}, BINDFN { return FirstType(types); }, [skip_null](std::vector<std::vector<Value>> &rows, ExecContext &, const BoundExpr &e) -> Value {
      for (auto &rw : rows) { if (skip_null && rw[0].is_null) continue; return rw[0].is_null ? NullOf(e.type) : rw[0]; }
      return NullOf(e.type);
    }));
  }
  r.AddAgg("last", AOVB({ANY}, BINDFN { return FirstType(types); }, AGGIMPL { if (rows.empty()) return NullOf(e.type); return rows.back()[0].is_null ? NullOf(e.type) : rows.back()[0]; }));
  for (auto name : {"list", "array_agg"}) {
    r.AddAgg(name, AOVB({ANY}, BINDFN { return TLIST(FirstType(types)); }, AGGIMPL {
      if (rows.empty()) return NullOf(e.type);
      std::vector<Value> vals; for (auto &rw : rows) { Value v = rw[0]; if (v.is_null) v = NullOf(e.type.child()); vals.push_back(v); }
      return Value::List(e.type.child(), vals);
    }));
  }
  for (auto name : {"string_agg", "group_concat", "listagg"}) {
    r.AddAgg(name, AOV({V}, V, AGGIMPL { bool any = false; std::string s; for (auto &rw : rows) { if (rw[0].is_null) continue; if (any) s += ","; s += rw[0].str; any = true; } return any ? VStr(s) : NullOf(T(TypeId::VARCHAR)); }));
    r.AddAgg(name, AOV({V, V}, V, AGGIMPL { bool any = false; std::string s; for (auto &rw : rows) { if (rw[0].is_null) continue; if (any) s += rw[1].is_null ? "" : rw[1].str; s += rw[0].str; any = true; } return any ? VStr(s) : NullOf(T(TypeId::VARCHAR)); }));
  }
  r.AddAgg("bool_and", AOV({BOOL}, BOOL, AGGIMPL { bool any = false, r = true; for (auto &rw : rows) if (!rw[0].is_null) { any = true; r = r && rw[0].ival; } return any ? VBool(r) : NullOf(T(TypeId::BOOLEAN)); }));
  r.AddAgg("bool_or", AOV({BOOL}, BOOL, AGGIMPL { bool any = false, r = false; for (auto &rw : rows) if (!rw[0].is_null) { any = true; r = r || rw[0].ival; } return any ? VBool(r) : NullOf(T(TypeId::BOOLEAN)); }));
  r.AddAgg("product", AOV({D}, D, AGGIMPL { bool any = false; double p = 1; for (auto &rw : rows) if (!rw[0].is_null) { any = true; p *= rw[0].dval; } return any ? VDbl(p) : NullOf(T(TypeId::DOUBLE)); }));
  r.AddAgg("geomean", AOV({D}, D, AGGIMPL { auto v = Doubles(rows); if (v.empty()) return NullOf(T(TypeId::DOUBLE)); double s = 0; for (double x : v) s += std::log(x); return VDbl(std::exp(s / v.size())); }));
  r.AddAgg("geometric_mean", r.aggregates["geomean"].overloads[0]);
  // median / quantiles
  r.AddAgg("median", AOVB({ANY}, BINDFN { return QuantileContType(FirstType(types)); }, AGGIMPL {
    std::vector<Value> vals; for (auto &rw : rows) if (!rw[0].is_null) vals.push_back(rw[0]);
    if (e.type.id == TypeId::VARCHAR || (!e.type.IsNumeric() && !e.type.IsTemporal())) return Quantile(vals, 0.5, false, e.type);
    return Quantile(vals, 0.5, true, e.type);
  }));
  r.AddAgg("quantile_cont", AOVB({ANY, D}, BINDFN { return QuantileContType(FirstType(types)); }, AGGIMPL {
    std::vector<Value> vals; for (auto &rw : rows) if (!rw[0].is_null) vals.push_back(rw[0]);
    if (rows.empty()) return NullOf(e.type);
    double q = rows[0][1].GetDouble();
    if (q < 0 || q > 1) throw InvalidInputException("QUANTILE can only take parameters in the range [0, 1]");
    return Quantile(vals, q, true, e.type);
  }));
  r.AddAgg("quantile_cont", AOVB({ANY, TLIST(D)}, BINDFN { return TLIST(QuantileContType(FirstType(types))); }, AGGIMPL {
    std::vector<Value> vals; for (auto &rw : rows) if (!rw[0].is_null) vals.push_back(rw[0]);
    if (rows.empty()) return NullOf(e.type);
    std::vector<Value> out;
    for (auto &q : *rows[0][1].children) out.push_back(Quantile(vals, q.GetDouble(), true, e.type.child()));
    return Value::List(e.type.child(), out);
  }));
  for (auto name : {"quantile_disc", "quantile"}) {
    r.AddAgg(name, AOVB({ANY, D}, BINDFN { return FirstType(types); }, AGGIMPL {
      std::vector<Value> vals; for (auto &rw : rows) if (!rw[0].is_null) vals.push_back(rw[0]);
      if (rows.empty()) return NullOf(e.type);
      double q = rows[0][1].GetDouble();
      if (q < 0 || q > 1) throw InvalidInputException("QUANTILE can only take parameters in the range [0, 1]");
      return Quantile(vals, q, false, e.type);
    }));
    r.AddAgg(name, AOVB({ANY, TLIST(D)}, BINDFN { return TLIST(FirstType(types)); }, AGGIMPL {
      std::vector<Value> vals; for (auto &rw : rows) if (!rw[0].is_null) vals.push_back(rw[0]);
      if (rows.empty()) return NullOf(e.type);
      std::vector<Value> out;
      for (auto &q : *rows[0][1].children) out.push_back(Quantile(vals, q.GetDouble(), false, e.type.child()));
      return Value::List(e.type.child(), out);
    }));
    r.AddAgg(name, AOVB({ANY}, BINDFN { return FirstType(types); }, AGGIMPL { std::vector<Value> vals; for (auto &rw : rows) if (!rw[0].is_null) vals.push_back(rw[0]); return Quantile(vals, 0.5, false, e.type); }));
  }
  r.AddAgg("approx_quantile", r.aggregates["quantile_disc"].overloads[0]);
  r.AddAgg("approx_quantile", r.aggregates["quantile_disc"].overloads[1]);
  r.AddAgg("mad", AOVB({ANY}, BINDFN { LogicalType t = FirstType(types); if (t.IsTemporal()) return T(TypeId::INTERVAL); if (t.id == TypeId::DECIMAL) return t; return T(TypeId::DOUBLE); }, AGGIMPL {
    std::vector<Value> vals; for (auto &rw : rows) if (!rw[0].is_null) vals.push_back(rw[0]);
    if (vals.empty()) return NullOf(e.type);
    Value med = Quantile(vals, 0.5, true, e.type.id == TypeId::INTERVAL ? vals[0].type : e.type);
    std::vector<Value> devs;
    for (auto &v : vals) { if (e.type.id == TypeId::DECIMAL) { int128_t d = v.ival - med.ival; devs.push_back(Value::Decimal(d < 0 ? -d : d, e.type.width, e.type.scale)); } else { double d = std::fabs(v.GetDouble() - med.GetDouble()); devs.push_back(VDbl(d)); } }
    return Quantile(devs, 0.5, true, e.type);
  }));
  r.AddAgg("mode", AOVB({ANY}, BINDFN { return FirstType(types); }, AGGIMPL {
    std::vector<std::pair<Value, int64_t>> counts;
    for (auto &rw : rows) { if (rw[0].is_null) continue; bool f = false; for (auto &c : counts) if (ValuesEqual(c.first, rw[0])) { c.second++; f = true; break; } if (!f) counts.push_back({rw[0], 1}); }
    if (counts.empty()) return NullOf(e.type);
    auto best = counts[0]; for (auto &c : counts) if (c.second > best.second) best = c;
    return best.first;
  }));
  // variance / stddev
  auto var_impl = [](bool sample, bool sqrt) {
    return [sample, sqrt](std::vector<std::vector<Value>> &rows, ExecContext &, const BoundExpr &) -> Value {
      auto v = Doubles(rows);
      if (v.empty() || (sample && v.size() < 2)) return NullOf(T(TypeId::DOUBLE));
      double m = Mean(v), s = 0; for (double x : v) s += (x - m) * (x - m);
      double var = s / (sample ? v.size() - 1 : v.size());
      return VDbl(sqrt ? std::sqrt(var) : var);
    };
  };
  for (auto name : {"var_samp", "variance", "var"}) r.AddAgg(name, AOV({D}, D, var_impl(true, false)));
  r.AddAgg("var_pop", AOV({D}, D, var_impl(false, false)));
  for (auto name : {"stddev_samp", "stddev", "std"}) r.AddAgg(name, AOV({D}, D, var_impl(true, true)));
  r.AddAgg("stddev_pop", AOV({D}, D, var_impl(false, true)));
  r.AddAgg("sem", AOV({D}, D, AGGIMPL { auto v = Doubles(rows); if (v.size() < 2) return NullOf(T(TypeId::DOUBLE)); double m = Mean(v), s = 0; for (double x : v) s += (x - m) * (x - m); return VDbl(std::sqrt(s / (v.size() - 1)) / std::sqrt((double)v.size())); }));
  r.AddAgg("skewness", AOV({D}, D, AGGIMPL { auto v = Doubles(rows); size_t n = v.size(); if (n < 3) return NullOf(T(TypeId::DOUBLE)); double m = Mean(v), s2 = 0, s3 = 0; for (double x : v) { s2 += (x - m) * (x - m); s3 += (x - m) * (x - m) * (x - m); } double var = s2 / n; if (var == 0) return NullOf(T(TypeId::DOUBLE)); double sk = (s3 / n) / std::pow(var, 1.5); return VDbl(sk * std::sqrt((double)n * (n - 1)) / (n - 2)); }));
  r.AddAgg("kurtosis", AOV({D}, D, AGGIMPL { auto v = Doubles(rows); double n = (double)v.size(); if (n < 4) return NullOf(T(TypeId::DOUBLE)); double m = Mean(v), s2 = 0, s4 = 0; for (double x : v) { s2 += (x - m) * (x - m); s4 += std::pow(x - m, 4); } double var = s2 / n; if (var == 0) return NullOf(T(TypeId::DOUBLE)); double k = (s4 / n) / (var * var); return VDbl(((n - 1) / ((n - 2) * (n - 3))) * ((n + 1) * k - 3 * (n - 1))); }));
  r.AddAgg("kurtosis_pop", AOV({D}, D, AGGIMPL { auto v = Doubles(rows); double n = (double)v.size(); if (n < 1) return NullOf(T(TypeId::DOUBLE)); double m = Mean(v), s2 = 0, s4 = 0; for (double x : v) { s2 += (x - m) * (x - m); s4 += std::pow(x - m, 4); } double var = s2 / n; if (var == 0) return NullOf(T(TypeId::DOUBLE)); return VDbl((s4 / n) / (var * var) - 3); }));
  r.AddAgg("entropy", AOV({ANY}, D, AGGIMPL { std::vector<std::pair<Value, int64_t>> counts; int64_t total = 0; for (auto &rw : rows) { if (rw[0].is_null) continue; total++; bool f = false; for (auto &c : counts) if (ValuesEqual(c.first, rw[0])) { c.second++; f = true; break; } if (!f) counts.push_back({rw[0], 1}); } if (total == 0) return VDbl(0); double h = 0; for (auto &c : counts) { double p = (double)c.second / total; h -= p * std::log2(p); } return VDbl(h); }));
  r.AddAgg("approx_count_distinct", AOV({ANY}, B, AGGIMPL { std::unordered_set<std::string> s; for (auto &rw : rows) if (!rw[0].is_null) s.insert(rw[0].ToString()); return VBig((int64_t)s.size()); }));
  for (auto name : {"bit_and", "bit_or", "bit_xor"}) {
    std::string op = name;
    r.AddAgg(name, AOVB({ANY}, BINDFN { return FirstType(types); }, [op](std::vector<std::vector<Value>> &rows, ExecContext &, const BoundExpr &e) -> Value {
      bool any = false; int128_t acc = 0;
      for (auto &rw : rows) { if (rw[0].is_null) continue; if (!any) { acc = rw[0].ival; any = true; continue; } if (op == "bit_and") acc &= rw[0].ival; else if (op == "bit_or") acc |= rw[0].ival; else acc ^= rw[0].ival; }
      if (!any) return NullOf(e.type);
      Value v(e.type); v.is_null = false; v.ival = acc; return v;
    }));
  }
  r.AddAgg("bitstring_agg", AOVB({ANY}, BINDFN { return T(TypeId::BIT); }, AGGIMPL {
    bool any = false; int64_t mn = 0, mx = 0;
    for (auto &rw : rows) { if (rw[0].is_null) continue; int64_t v = rw[0].GetInt64(); if (!any) { mn = mx = v; any = true; } mn = std::min(mn, v); mx = std::max(mx, v); }
    if (!any) return NullOf(T(TypeId::BIT));
    std::string bits(mx - mn + 1, '0');
    for (auto &rw : rows) if (!rw[0].is_null) bits[rw[0].GetInt64() - mn] = '1';
    Value v(T(TypeId::BIT)); v.is_null = false; v.str = bits; return v;
  }));
  r.AddAgg("histogram", AOVB({ANY}, BINDFN { return LogicalType::Map(FirstType(types), T(TypeId::UBIGINT)); }, AGGIMPL {
    std::vector<std::pair<Value, int64_t>> counts;
    for (auto &rw : rows) { if (rw[0].is_null) continue; bool f = false; for (auto &c : counts) if (ValuesEqual(c.first, rw[0])) { c.second++; f = true; break; } if (!f) counts.push_back({rw[0], 1}); }
    std::stable_sort(counts.begin(), counts.end(), [](auto &a, auto &b) { return Value::Compare(a.first, b.first) < 0; });
    std::vector<Value> k, v;
    for (auto &c : counts) { k.push_back(c.first); v.push_back(Value::Int(c.second, TypeId::UBIGINT)); }
    if (counts.empty()) return NullOf(e.type);
    return Value::Map(e.type.info->children[0], e.type.info->children[1], k, v);
  }));
  for (auto name : {"arg_max", "max_by", "argmax"}) r.AddAgg(name, AOVB({ANY, ANY}, BINDFN { return FirstType(types); }, AGGIMPL { bool have = false; Value best, bestk; for (auto &rw : rows) { if (rw[1].is_null || rw[0].is_null) continue; if (!have || Value::Compare(rw[1], bestk) > 0) { best = rw[0]; bestk = rw[1]; have = true; } } return have ? best : NullOf(e.type); }));
