#include "func_util.h"
#include <unordered_set>

static AggOverload AOV(std::vector<LogicalType> params, LogicalType ret, AggImpl impl) { AggOverload o; o.params = params; o.ret = ret; o.impl = impl; return o; }
static AggOverload AOVB(std::vector<LogicalType> params, BindFn bind, AggImpl impl) { AggOverload o; o.params = params; o.bind = bind; o.impl = impl; o.ret = LogicalType(TypeId::ANY); return o; }

static LogicalType FirstType(std::vector<LogicalType> &types) {
  LogicalType t = types.empty() ? T(TypeId::INTEGER) : types[0];
  if (t.id == TypeId::INTEGER_LITERAL) t = T(TypeId::INTEGER);
  if (t.id == TypeId::STRING_LITERAL) t = T(TypeId::VARCHAR);
  if (t.id == TypeId::SQLNULL) t = T(TypeId::INTEGER);
  return t;
}

static double Mean(const std::vector<double> &v) { double s = 0; for (double x : v) s += x; return v.empty() ? 0 : s / v.size(); }

static std::vector<double> Doubles(std::vector<std::vector<Value>> &rows, size_t col = 0) {
  std::vector<double> out;
  for (auto &r : rows) if (!r[col].is_null) out.push_back(r[col].GetDouble());
  return out;
}

static Value Quantile(std::vector<Value> vals, double q, bool cont, const LogicalType &rt) {
  if (vals.empty()) return NullOf(rt);
  vals = SortedValues(vals);
  double pos = q * (vals.size() - 1);
  size_t lo = (size_t)std::floor(pos), hi = (size_t)std::ceil(pos);
  if (!cont) {
    // DuckDB quantile_disc: uses floor? It picks element at ceil(q*n)-1 ... use nearest-rank on sorted: index = ceil(q * n) - 1
    size_t idx = (size_t)std::ceil(q * vals.size());
    if (idx > 0) idx--;
    if (idx >= vals.size()) idx = vals.size() - 1;
    return vals[idx];
  }
  const Value &a = vals[lo], &b = vals[hi];
  double frac = pos - lo;
  if (rt.id == TypeId::DOUBLE) { return VDbl(a.GetDouble() + (b.GetDouble() - a.GetDouble()) * frac); }
  if (rt.id == TypeId::DECIMAL) { double x = (double)a.ival + ((double)b.ival - (double)a.ival) * frac; return Value::Decimal((int128_t)std::llround(x), rt.width, rt.scale); }
  if (rt.IsTemporal()) { int64_t x = (int64_t)a.ival; int64_t y = (int64_t)b.ival; Value v(rt); v.is_null = false; v.ival = x + (int64_t)std::llround((double)(y - x) * frac); if (a.type.id == TypeId::DATE) v.ival = DateToTimestampMicros((int32_t)x) + (int64_t)std::llround((double)(DateToTimestampMicros((int32_t)y) - DateToTimestampMicros((int32_t)x)) * frac); return v; }
  if (rt.id == TypeId::INTERVAL) { Value v(rt); v.is_null = false; v.interval.months = (int32_t)(a.interval.months + (b.interval.months - a.interval.months) * frac); v.interval.days = (int32_t)(a.interval.days + (b.interval.days - a.interval.days) * frac); v.interval.micros = (int64_t)(a.interval.micros + (b.interval.micros - a.interval.micros) * frac); return v; }
  return frac < 0.5 ? a : b;
}

static LogicalType QuantileContType(const LogicalType &t) {
  if (t.id == TypeId::DECIMAL) return t;
  if (t.IsNumeric()) return T(TypeId::DOUBLE);
  if (t.id == TypeId::DATE) return T(TypeId::TIMESTAMP);
  return t;
}

void RegisterAggregateFunctions(FunctionRegistry &r) {
