    if (e.type.id == TypeId::INTERVAL) { Interval s; for (auto &rw : rows) if (!rw[0].is_null) { s.months += rw[0].interval.months; s.days += rw[0].interval.days; s.micros += rw[0].interval.micros; any = true; } return any ? Value::IntervalV(s) : NullOf(e.type); }
