QueryResult Executor::ExecuteAttach(AttachStatement &s) {
  std::string name = s.name;
  if (name.empty()) {
    name = s.path;
    size_t slash = name.find_last_of('/'); if (slash != std::string::npos) name = name.substr(slash + 1);
    size_t dot = name.find('.'); if (dot != std::string::npos) name = name.substr(0, dot);
    if (s.path == ":memory:" || s.path.empty()) name = "memory";
  }
  if (catalog.FindDatabase(name)) {
    if (s.if_not_exists) return NoResult();
    throw BinderException("Unique file handle conflict: Database \"" + name + "\" is already attached with path \"" + s.path + "\", ");
  }
  catalog.AddDatabase(name, s.path == ":memory:" ? "" : s.path);
  auto &db = catalog.GetDatabase(name);
  for (auto &o : s.options) if (ToLower(o.first) == "readonly" || ToLower(o.first) == "read_only") db.readonly = true;
  if (!db.path.empty()) LoadDatabase(catalog, db);
  return NoResult();
}

