int64_t Executor::NextVal(SequenceEntry &seq) {
  int64_t v;
  if (!seq.used) { v = seq.start; seq.used = true; }
  else {
    int64_t next;
    if (__builtin_add_overflow(seq.current, seq.increment, &next) || next > seq.max_value || next < seq.min_value) {
      if (seq.cycle) next = seq.increment > 0 ? seq.min_value : seq.max_value;
      else throw SequenceException("nextval: reached " + std::string(seq.increment > 0 ? "maximum" : "minimum") + " value of sequence \"" + seq.name + "\" (" + std::to_string(seq.increment > 0 ? seq.max_value : seq.min_value) + ")");
    }
    v = next;
  }
  seq.current = v;
  return v;
}

// ---------------------------------------------------------------- DESCRIBE / SHOW
QueryResult Executor::Describe(const QueryResult &in) {
  QueryResult r;
  r.names = {"column_name", "column_type", "null", "key", "default", "extra"};
  for (int i = 0; i < 6; i++) r.types.push_back(LogicalType(TypeId::VARCHAR));
  for (size_t i = 0; i < in.names.size(); i++) {
    r.rows.push_back({Value::Varchar(in.names[i]), Value::Varchar(in.types[i].ToString()), Value::Varchar("YES"), Value::Null(LogicalType(TypeId::VARCHAR)), Value::Null(LogicalType(TypeId::VARCHAR)), Value::Null(LogicalType(TypeId::VARCHAR))});
  }
  return r;
}

QueryResult Executor::DescribeTable(const std::string &qname) {
  auto parts = SplitString(qname, '.');
  std::string name = parts.back();
  std::string schema = parts.size() > 1 ? parts[parts.size() - 2] : "";
  std::string cat = parts.size() > 2 ? parts[parts.size() - 3] : "";
  auto table = catalog.FindTable(cat, schema, name);
  QueryResult r;
  r.names = {"column_name", "column_type", "null", "key", "default", "extra"};
  for (int i = 0; i < 6; i++) r.types.push_back(LogicalType(TypeId::VARCHAR));
  if (table) {
    auto pk = table->PrimaryKeyColumns();
    for (auto &c : table->columns) {
      bool is_pk = std::find_if(pk.begin(), pk.end(), [&](const std::string &p) { return IEquals(p, c.name); }) != pk.end();
      bool is_uni = false;
      for (auto &con : table->constraints) if (con.kind == Constraint::UNIQUE && con.columns.size() == 1 && IEquals(con.columns[0], c.name)) is_uni = true;
      Value key = is_pk ? Value::Varchar("PRI") : (is_uni ? Value::Varchar("UNI") : Value::Null(LogicalType(TypeId::VARCHAR)));
      Value def = c.default_value ? Value::Varchar(c.default_value->ToString()) : Value::Null(LogicalType(TypeId::VARCHAR));
      r.rows.push_back({Value::Varchar(c.name), Value::Varchar(c.type.ToString()), Value::Varchar(c.not_null ? "NO" : "YES"), key, def, Value::Null(LogicalType(TypeId::VARCHAR))});
    }
    return r;
  }
  auto view = catalog.FindView(cat, schema, name);
  if (view) {
    for (size_t i = 0; i < view->column_names.size(); i++) r.rows.push_back({Value::Varchar(view->column_names[i]), Value::Varchar(view->column_types[i].ToString()), Value::Varchar("YES"), Value::Null(LogicalType(TypeId::VARCHAR)), Value::Null(LogicalType(TypeId::VARCHAR)), Value::Null(LogicalType(TypeId::VARCHAR))});
    return r;
  }
  // system view?
  try { QueryResult sv = SystemView(cat, schema, name); return Describe(sv); } catch (CatalogException &) {}
  throw CatalogException(TableNotFound(catalog, name));
}

QueryResult Executor::Summarize(const QueryResult &in) {
  QueryResult r;
  r.names = {"column_name", "column_type", "min", "max", "approx_unique", "avg", "std", "q25", "q50", "q75", "count", "null_percentage"};
  r.types = {LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR), LogicalType(TypeId::BIGINT), LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR), LogicalType(TypeId::BIGINT), LogicalType::Decimal(9, 2)};
  for (size_t ci = 0; ci < in.names.size(); ci++) {
    std::vector<Value> vals;
    int64_t nulls = 0;
    for (auto &row : in.rows) { if (row[ci].is_null) nulls++; else vals.push_back(row[ci]); }
    std::vector<Value> sorted = SortedValues(vals);
    Value mn = sorted.empty() ? Value::Null(LogicalType(TypeId::VARCHAR)) : Value::Varchar(sorted.front().ToString());
    Value mx = sorted.empty() ? Value::Null(LogicalType(TypeId::VARCHAR)) : Value::Varchar(sorted.back().ToString());
    std::unordered_set<std::string> uniq; for (auto &v : vals) uniq.insert(v.ToString());
    const LogicalType &t = in.types[ci];
    Value avg = Value::Null(LogicalType(TypeId::VARCHAR)), sd = Value::Null(LogicalType(TypeId::VARCHAR)), q25 = Value::Null(LogicalType(TypeId::VARCHAR)), q50 = Value::Null(LogicalType(TypeId::VARCHAR)), q75 = Value::Null(LogicalType(TypeId::VARCHAR));
    if (t.IsNumeric() && !vals.empty()) {
      double s = 0; for (auto &v : vals) s += v.GetDouble();
      double m = s / vals.size();
      avg = Value::Varchar(DoubleToString(m));
      double ss = 0; for (auto &v : vals) ss += (v.GetDouble() - m) * (v.GetDouble() - m);
      sd = vals.size() > 1 ? Value::Varchar(DoubleToString(std::sqrt(ss / (vals.size() - 1)))) : Value::Null(LogicalType(TypeId::VARCHAR));
      auto q = [&](double p) { double pos = p * (sorted.size() - 1); size_t lo = (size_t)std::floor(pos); size_t hi = (size_t)std::ceil(pos); double v = sorted[lo].GetDouble() + (sorted[hi].GetDouble() - sorted[lo].GetDouble()) * (pos - lo); if (t.IsInteger()) return Value::Varchar(Int128ToString((int128_t)std::llround(v))); return Value::Varchar(DoubleToString(v)); };
      q25 = q(0.25); q50 = q(0.5); q75 = q(0.75);
    }
    int128_t pct = in.rows.empty() ? 0 : (int128_t)std::llround((double)nulls * 10000.0 / (double)in.rows.size());
    r.rows.push_back({Value::Varchar(in.names[ci]), Value::Varchar(t.ToString()), mn, mx, Value::BigInt((int64_t)uniq.size()), avg, sd, q25, q50, q75, Value::BigInt((int64_t)in.rows.size()), Value::Decimal(pct, 9, 2)});
  }
  return r;
}

QueryResult Executor::ExecuteShow(ShowStatement &s) {
  if (s.kind == "TABLES") {
    QueryResult r;
    r.names = {"name"}; r.types = {LogicalType(TypeId::VARCHAR)};
    std::vector<std::string> names;
    auto &db = catalog.DefaultDatabase();
    auto it = db.schemas.find(catalog.default_schema);
    if (it != db.schemas.end()) {
      for (auto &t : it->second->tables) names.push_back(t.first);
      for (auto &v : it->second->views) names.push_back(v.first);
    }
    for (auto &t : catalog.databases["temp"]->schemas["main"]->tables) names.push_back(t.first);
    for (auto &v : catalog.databases["temp"]->schemas["main"]->views) names.push_back(v.first);
    std::sort(names.begin(), names.end());
    for (auto &n : names) r.rows.push_back({Value::Varchar(n)});
    return r;
  }
  if (s.kind == "ALL TABLES") {
    QueryResult r;
    r.names = {"database", "schema", "name", "column_names", "column_types", "temporary"};
    r.types = {LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR), LogicalType::List(LogicalType(TypeId::VARCHAR)), LogicalType::List(LogicalType(TypeId::VARCHAR)), LogicalType(TypeId::BOOLEAN)};
    for (auto &sc : catalog.AllSchemas()) {
      if (sc.first == "system") continue;
      std::vector<std::pair<std::string, Row>> entries;
      for (auto &t : sc.second->tables) {
        std::vector<Value> cn, ct;
        for (auto &c : t.second->columns) { cn.push_back(Value::Varchar(c.name)); ct.push_back(Value::Varchar(c.type.ToString())); }
        entries.push_back({t.first, {Value::Varchar(sc.first), Value::Varchar(sc.second->name), Value::Varchar(t.first), Value::List(LogicalType(TypeId::VARCHAR), cn), Value::List(LogicalType(TypeId::VARCHAR), ct), Value::Boolean(t.second->temporary)}});
      }
      for (auto &v : sc.second->views) {
        std::vector<Value> cn, ct;
        for (size_t i = 0; i < v.second->column_names.size(); i++) { cn.push_back(Value::Varchar(v.second->column_names[i])); ct.push_back(Value::Varchar(v.second->column_types[i].ToString())); }
        entries.push_back({v.first, {Value::Varchar(sc.first), Value::Varchar(sc.second->name), Value::Varchar(v.first), Value::List(LogicalType(TypeId::VARCHAR), cn), Value::List(LogicalType(TypeId::VARCHAR), ct), Value::Boolean(v.second->temporary)}});
      }
      std::sort(entries.begin(), entries.end(), [](auto &a, auto &b) { return a.first < b.first; });
      for (auto &e : entries) r.rows.push_back(e.second);
    }
    return r;
  }
  if (s.kind == "DATABASES") {
    QueryResult r;
    r.names = {"database_name"}; r.types = {LogicalType(TypeId::VARCHAR)};
    for (auto &n : catalog.database_order) r.rows.push_back({Value::Varchar(n)});
    return r;
  }
  if (s.kind == "SCHEMAS") {
    QueryResult r; r.names = {"schema_name"}; r.types = {LogicalType(TypeId::VARCHAR)};
    for (auto &sc : catalog.AllSchemas()) r.rows.push_back({Value::Varchar(sc.second->name)});
    return r;
  }
  if (s.kind == "VARIABLES") {
    QueryResult r; r.names = {"name", "value", "type"}; r.types = {LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR)};
    for (auto &v : catalog.variables) r.rows.push_back({Value::Varchar(v.first), Value::Varchar(v.second.ToString()), Value::Varchar(v.second.type.ToString())});
    return r;
  }
  if (s.kind == "SUMMARIZE") {
    QueryResult in;
    if (s.query) in = ExecuteSelect(*s.query);
    else {
      auto stmt = Parser::ParseSelectFromString("SELECT * FROM " + s.name);
      in = ExecuteSelect(*stmt);
    }
    return Summarize(in);
  }
  // DESCRIBE
  if (s.query) {
    QueryResult in = ExecuteSelect(*s.query);
    return Describe(in);
  }
  return DescribeTable(s.name);
}
EOF
echo done"}

