static std::string TableNotFound(Catalog &catalog, const std::string &name) {
  std::vector<std::string> cands = catalog.AllTableLikeNames();
  for (auto s : {"duckdb_columns", "duckdb_constraints", "duckdb_databases", "duckdb_indexes", "duckdb_logs", "duckdb_schemas", "duckdb_tables", "duckdb_types", "duckdb_views", "pragma_database_list", "sqlite_master", "sqlite_schema", "sqlite_temp_master", "sqlite_temp_schema", "pg_am", "pg_attrdef", "pg_attribute", "pg_class", "pg_constraint", "pg_database", "pg_depend", "pg_description", "pg_enum", "pg_index", "pg_indexes", "pg_namespace", "pg_prepared_statements", "pg_proc", "pg_sequence", "pg_sequences", "pg_settings", "pg_tables", "pg_tablespace", "pg_type", "pg_views", "character_sets", "check_constraints", "columns", "constraint_column_usage", "constraint_table_usage", "key_column_usage", "referential_constraints", "schemata", "table_constraints", "tables", "views"}) cands.push_back(s);
  auto top = TopSimilar(name, cands, 1, 0.5);
  std::string sugg = top.empty() ? "" : "\nDid you mean \"" + top[0] + "\"?";
  return "Table with name " + name + " does not exist!" + sugg;
}

QueryResult Executor::Execute(Statement &stmt) {
  switch (stmt.type) {
  case StatementType::SELECT: return ExecuteSelect(static_cast<SelectStatement &>(stmt));
  case StatementType::CREATE_TABLE: return ExecuteCreateTable(static_cast<CreateTableStatement &>(stmt));
  case StatementType::CREATE_VIEW: return ExecuteCreateView(static_cast<CreateViewStatement &>(stmt));
  case StatementType::INSERT: return ExecuteInsert(static_cast<InsertStatement &>(stmt));
  case StatementType::UPDATE: return ExecuteUpdate(static_cast<UpdateStatement &>(stmt));
  case StatementType::DELETE: return ExecuteDelete(static_cast<DeleteStatement &>(stmt));
  case StatementType::DROP: return ExecuteDrop(static_cast<DropStatement &>(stmt));
  case StatementType::ALTER: return ExecuteAlter(static_cast<AlterStatement &>(stmt));
  case StatementType::COPY: return ExecuteCopy(static_cast<CopyStatement &>(stmt));
  case StatementType::SHOW: return ExecuteShow(static_cast<ShowStatement &>(stmt));
  case StatementType::PRAGMA: return ExecutePragma(static_cast<PragmaStatement &>(stmt));
  case StatementType::SET: return ExecuteSet(static_cast<SetStatement &>(stmt));
  case StatementType::EXPLAIN: return ExecuteExplain(static_cast<ExplainStatement &>(stmt));
  case StatementType::CALL: return ExecuteCall(static_cast<CallStatement &>(stmt));
  case StatementType::ATTACH: return ExecuteAttach(static_cast<AttachStatement &>(stmt));
  case StatementType::EXPORT: return ExecuteExport(static_cast<ExportStatement &>(stmt));
  case StatementType::TRANSACTION: {
    auto &t = static_cast<TransactionStatement &>(stmt);
    if (t.kind == "BEGIN") {
      if (ctx.in_transaction) throw TransactionException("cannot start a transaction within a transaction");
      ctx.in_transaction = true;
    } else {
      if (!ctx.in_transaction) throw TransactionException(t.kind == "COMMIT" ? "cannot commit - no transaction is active" : "cannot rollback - no transaction is active");
      ctx.in_transaction = false;
    }
    return NoResult();
  }
  case StatementType::CREATE_SCHEMA: {
    auto &s = static_cast<CreateSchemaStatement &>(stmt);
    auto &db = catalog.DefaultDatabase();
    if (db.schemas.count(s.schema)) {
      if (s.on_conflict == OnCreateConflict::IGNORE) return NoResult();
      throw CatalogException("Schema with name \"" + s.schema + "\" already exists!");
    }
    auto sc = std::make_shared<SchemaEntry>(); sc->name = s.schema; sc->oid = catalog.NextOid();
    db.schemas[s.schema] = sc;
    db.dirty = true;
    return NoResult();
  }
  case StatementType::CREATE_SEQUENCE: {
    auto &s = static_cast<CreateSequenceStatement &>(stmt);
    auto &schema = catalog.ResolveSchemaForCreate("", s.schema, s.temporary);
    if (schema.sequences.count(s.name)) {
      if (s.on_conflict == OnCreateConflict::IGNORE) return NoResult();
      if (s.on_conflict == OnCreateConflict::ERROR) throw CatalogException("Sequence with name \"" + s.name + "\" already exists!");
    }
    auto seq = std::make_shared<SequenceEntry>();
    seq->name = s.name; seq->schema = schema.name; seq->start = s.start; seq->increment = s.increment;
    seq->min_value = s.has_min ? s.min_value : (s.increment > 0 ? 1 : INT64_MIN);
    seq->max_value = s.has_max ? s.max_value : (s.increment > 0 ? INT64_MAX : -1);
    seq->cycle = s.cycle; seq->current = s.start; seq->oid = catalog.NextOid(); seq->temporary = s.temporary;
    seq->sql = stmt.query + ";";
    schema.sequences[s.name] = seq;
    catalog.MarkDirty(catalog.default_database);
    return NoResult();
  }
  case StatementType::CREATE_INDEX: {
    auto &s = static_cast<CreateIndexStatement &>(stmt);
    auto table = catalog.FindTable("", s.schema, s.table);
    if (!table) throw CatalogException(TableNotFound(catalog, s.table));
    auto &schema = catalog.ResolveSchemaForCreate("", s.schema.empty() ? table->schema : s.schema, false);
    if (schema.indexes.count(s.index_name)) {
      if (s.on_conflict == OnCreateConflict::IGNORE) return NoResult();
      throw CatalogException("Index with name \"" + s.index_name + "\" already exists!");
    }
    auto idx = std::make_shared<IndexEntry>();
    idx->name = s.index_name; idx->schema = schema.name; idx->table = table->name; idx->unique = s.unique; idx->oid = catalog.NextOid();
    for (auto &e : s.expressions) idx->expressions.push_back(e->ToString());
    idx->sql = stmt.query + ";";
    if (s.unique) {
      Constraint c; c.kind = Constraint::UNIQUE;
      for (auto &e : s.expressions) if (e->kind == ExprKind::COLUMN_REF) c.columns.push_back(e->names.back());
      c.name = s.index_name;
      // verify uniqueness
      std::unordered_set<std::string> seen;
      for (auto &row : table->rows) { std::string key; for (auto &cn : c.columns) { int ci = table->ColumnIndex(cn); key += row[ci].ToString() + "\x01"; } if (!seen.insert(key).second) throw ConstraintException("Data contains duplicates on indexed column(s)"); }
      table->constraints.push_back(std::move(c));
    }
    schema.indexes[s.index_name] = idx;
    return NoResult();
  }
  case StatementType::CREATE_MACRO: {
    auto &s = static_cast<CreateMacroStatement &>(stmt);
    auto &schema = catalog.ResolveSchemaForCreate("", s.schema, s.temporary);
    if (schema.macros.count(s.name)) {
      if (s.on_conflict == OnCreateConflict::IGNORE) return NoResult();
      if (s.on_conflict == OnCreateConflict::ERROR) throw CatalogException("Macro Function with name \"" + s.name + "\" already exists!");
    }
    auto m = std::make_shared<MacroEntry>();
    m->name = s.name; m->schema = schema.name; m->is_table = s.is_table; m->oid = catalog.NextOid(); m->temporary = s.temporary;
    for (auto &ov : s.overloads) {
      MacroEntry::Overload o;
      o.params = ov.params;
      for (auto &d : ov.defaults) o.defaults.push_back({d.first, d.second->ToString()});
      if (ov.expr) o.expr = ov.expr->ToString();
      if (ov.query) o.query = ov.query->ToString();
      m->overloads.push_back(o);
    }
    m->sql = stmt.query + ";";
    schema.macros[s.name] = m;
    schema.creation_order.push_back("macro:" + s.name);
    return NoResult();
  }
  case StatementType::CREATE_TYPE: {
    auto &s = static_cast<CreateTypeStatement &>(stmt);
    auto &schema = catalog.ResolveSchemaForCreate("", s.schema, false);
    if (schema.types.count(s.name)) {
      if (s.on_conflict == OnCreateConflict::IGNORE) return NoResult();
      if (s.on_conflict == OnCreateConflict::ERROR) throw CatalogException("Type with name \"" + s.name + "\" already exists!");
    }
    auto t = std::make_shared<TypeEntry>();
    t->name = s.name; t->schema = schema.name; t->oid = catalog.NextOid();
    if (s.query) {
      QueryResult r = ExecuteSelect(*s.query);
      if (r.types.size() != 1) throw BinderException("The query must return a single column");
      std::vector<std::string> vals;
      std::unordered_set<std::string> seen;
      for (auto &row : r.rows) if (!row[0].is_null && seen.insert(row[0].ToString()).second) vals.push_back(row[0].ToString());
      t->type = LogicalType::Enum(vals);
    } else t->type = ResolveType(s.type);
    t->type.info = t->type.info ? std::make_shared<TypeInfo>(*t->type.info) : std::make_shared<TypeInfo>();
    t->type.info->alias = s.name;
    if (t->type.id != TypeId::ENUM && t->type.id != TypeId::STRUCT && t->type.id != TypeId::LIST && t->type.id != TypeId::MAP && t->type.id != TypeId::UNION) t->type.info->alias = "";
    t->sql = stmt.query + ";";
    schema.types[s.name] = t;
    return NoResult();
  }
  case StatementType::TRUNCATE: {
    auto &s = static_cast<TruncateStatement &>(stmt);
    auto table = catalog.FindTable("", s.schema, s.table);
    if (!table) throw CatalogException(TableNotFound(catalog, s.table));
    ctx.rows_changed = (int64_t)table->rows.size();
    table->rows.clear();
    QueryResult r = NoResult();
    r.changed_rows = ctx.rows_changed;
    return r;
  }
  case StatementType::USE: {
    auto &s = static_cast<UseStatement &>(stmt);
    auto parts = SplitString(s.name, '.');
    if (parts.size() == 1) {
      auto db = catalog.FindDatabase(parts[0]);
      if (db) { catalog.default_database = db->name; catalog.default_schema = "main"; return NoResult(); }
      auto sc = catalog.FindSchema("", parts[0]);
      if (sc) { catalog.default_schema = sc->name; return NoResult(); }
      throw CatalogException("SET schema: No catalog + schema named \"" + s.name + "\" found.");
    }
    auto db = catalog.FindDatabase(parts[0]);
    if (!db || !db->schemas.count(parts[1])) throw CatalogException("SET schema: No catalog + schema named \"" + s.name + "\" found.");
    catalog.default_database = db->name;
    catalog.default_schema = parts[1];
    return NoResult();
  }
  case StatementType::DETACH: {
    auto &s = static_cast<DetachStatement &>(stmt);
    auto db = catalog.FindDatabase(s.name);
    if (!db) { if (s.if_exists) return NoResult(); throw CatalogException("Database with name \"" + s.name + "\" does not exist!"); }
    if (db->name == catalog.default_database) throw BinderException("Cannot detach database \"" + s.name + "\" because it is the default database. Select a different database using `USE` to allow detaching this database");
    extern void SaveDatabase(DatabaseEntry &db);
    if (!db->path.empty() && db->dirty) SaveDatabase(*db);
    catalog.RemoveDatabase(db->name);
    return NoResult();
  }
  case StatementType::CHECKPOINT: case StatementType::VACUUM: case StatementType::ANALYZE: case StatementType::LOAD: case StatementType::UPDATE_EXTENSIONS: case StatementType::CREATE_SECRET:
    if (stmt.type == StatementType::LOAD) {
      auto &s = static_cast<SimpleStatement &>(stmt);
      std::string n = ToLower(s.name);
      if (n == "json" || n == "icu" || n == "httpfs" || n == "spatial" || n == "fts" || n == "excel" || n == "sqlite" || n == "postgres" || n == "mysql" || n == "parquet" || n == "autocomplete" || n == "inet" || n == "tpch" || n == "tpcds" || n == "vss" || n == "delta" || n == "iceberg" || n == "aws" || n == "azure" || n == "ui" || n == "core_functions" || n == "jemalloc" || n == "shell") {
        if (n == "parquet" || n == "core_functions" || n == "jemalloc" || n == "shell") return NoResult();
        throw IOException("Extension \"" + ReplaceAll(std::string(getenv("HOME") ? getenv("HOME") : "~") + "/.duckdb/extensions/v0.0.1/linux_amd64/" + n + ".duckdb_extension", "//", "/") + "\" not found.\nExtension \"" + n + "\" is an existing extension.\n\nInstall it first using \"INSTALL " + n + "\".");
      }
      throw IOException("Extension \"" + s.name + "\" not found.\nCandidate extensions: \"" + s.name + "\"");
    }
    return NoResult();
  case StatementType::INSTALL: {
    auto &s = static_cast<SimpleStatement &>(stmt);
    throw IOException("Failed to download extension \"" + s.name + "\" at URL \"http://extensions.duckdb.org/v0.0.1/linux_amd64/" + s.name + ".duckdb_extension.gz\" (HTTP 403)\nExtension \"" + s.name + "\" is an existing extension.\n\nAre you using a development build? In this case, extensions might not (yet) be uploaded.");
  }
  case StatementType::PREPARE: {
    auto &s = static_cast<PrepareStatement &>(stmt);
    catalog.prepared[s.name] = s.stmt->query;
    return NoResult();
  }
  case StatementType::EXECUTE: {
    auto &s = static_cast<ExecuteStatement &>(stmt);
    auto it = catalog.prepared.find(s.name);
    if (it == catalog.prepared.end()) throw BinderException("Prepared statement \"" + s.name + "\" does not exist");
    std::map<std::string, Value> params;
    for (size_t i = 0; i < s.params.size(); i++) params[std::to_string(i + 1)] = EvaluateConstantExpression(*this, *s.params[i]);
    for (auto &np : s.named_params) params[np.first] = EvaluateConstantExpression(*this, *np.second);
    // positional '?' parameters are named "" ; map sequentially
    auto saved = ctx.parameters;
    ctx.parameters = &params;
    Parser p(it->second);
    auto stmts = p.ParseStatements();
    // replace '?' params with indexes
    QueryResult r;
    try {
      std::function<void(Expr &, int &)> fix = [&](Expr &e, int &counter) {
        if (e.kind == ExprKind::PARAMETER && e.param_name.empty()) e.param_name = std::to_string(++counter);
        for (auto &c : e.children) if (c) fix(*c, counter);
        for (auto &cc : e.case_checks) { fix(*cc.when, counter); fix(*cc.then, counter); }
        if (e.else_expr) fix(*e.else_expr, counter);
        if (e.filter) fix(*e.filter, counter);
      };
      int counter = 0;
      if (stmts[0]->type == StatementType::SELECT) {
        auto &sel = static_cast<SelectStatement &>(*stmts[0]);
        std::function<void(QueryNode &)> fixnode = [&](QueryNode &n) {
          for (auto &e : n.select_list) fix(*e, counter);
          if (n.where) fix(*n.where, counter);
          if (n.having) fix(*n.having, counter);
          if (n.limit) fix(*n.limit, counter);
          if (n.offset) fix(*n.offset, counter);
          for (auto &g : n.groups) fix(*g, counter);
          for (auto &o : n.orders) fix(*o.expr, counter);
          if (n.left) fixnode(*n.left);
          if (n.right) fixnode(*n.right);
        };
        fixnode(*sel.node);
      }
      r = Execute(*stmts[0]);
    } catch (...) { ctx.parameters = saved; throw; }
    ctx.parameters = saved;
    return r;
  }
  case StatementType::DEALLOCATE: {
    auto &s = static_cast<SimpleStatement &>(stmt);
    catalog.prepared.erase(s.name);
    return NoResult();
  }
  case StatementType::COMMENT: {
    auto &s = static_cast<CommentStatement &>(stmt);
    auto parts = SplitString(s.name, '.');
    std::string schema = parts.size() > 1 ? parts[parts.size() - 2] : "";
    std::string name = parts.back();
    if (s.entry_type == "TABLE" || s.entry_type == "COLUMN") {
      auto t = catalog.FindTable("", schema, name);
      if (t) {
        if (s.entry_type == "COLUMN") { int ci = t->ColumnIndex(s.column); if (ci < 0) throw BinderException("Column \"" + s.column + "\" does not exist"); t->columns[ci].comment = s.comment.is_null ? "" : s.comment.str; }
        else t->comment = s.comment.is_null ? "" : s.comment.str;
        return NoResult();
      }
      auto v = catalog.FindView("", schema, name);
      if (v) { v->comment = s.comment.is_null ? "" : s.comment.str; return NoResult(); }
      throw CatalogException(TableNotFound(catalog, name));
    }
    if (s.entry_type == "VIEW") {
      auto v = catalog.FindView("", schema, name);
      if (!v) throw CatalogException("View with name " + name + " does not exist!");
      v->comment = s.comment.is_null ? "" : s.comment.str;
      return NoResult();
    }
    return NoResult();
  }
  default: break;
  }
  throw NotImplementedException("Statement type not implemented");
}

// ---------------------------------------------------------------- CREATE TABLE
static Row DefaultRow(Executor &ex, TableEntry &t) {
  Row r;
  for (auto &c : t.columns) {
    if (c.default_value) {
      Value v = EvaluateConstantExpression(ex, *c.default_value);
      if (v.type != c.type) v = CastValue(v, c.type, false);
      r.push_back(v);
    } else r.push_back(Value::Null(c.type));
  }
  return r;
}

QueryResult Executor::ExecuteCreateTable(CreateTableStatement &s) {
  auto &schema = catalog.ResolveSchemaForCreate(s.catalog, s.schema, s.temporary);
  if (schema.tables.count(s.table) || schema.views.count(s.table)) {
    if (s.on_conflict == OnCreateConflict::IGNORE) return NoResult();
    if (s.on_conflict == OnCreateConflict::ERROR) {
      if (schema.views.count(s.table)) throw CatalogException("View with name \"" + s.table + "\" already exists!");
      throw CatalogException("Table with name \"" + s.table + "\" already exists!");
    }
  }
  auto table = std::make_shared<TableEntry>();
  table->name = s.table;
  table->schema = schema.name;
  table->temporary = s.temporary;
  table->oid = catalog.NextOid();
  if (s.query) {
    QueryResult r = ExecuteSelect(*s.query);
    std::vector<std::string> names = r.names;
    std::unordered_set<std::string> seen;
    for (auto &n : names) {
      std::string base = n;
      if (!seen.insert(ToLower(base)).second) {
        // DuckDB: CREATE TABLE AS fails on duplicate names
        throw BinderException("Table \"" + s.table + "\" has duplicate column name \"" + n + "\"");
      }
    }
    for (size_t i = 0; i < r.names.size(); i++) {
      ColumnInfo c; c.name = names[i];
      c.type = r.types[i];
      if (c.type.id == TypeId::SQLNULL) c.type = LogicalType(TypeId::INTEGER);
      table->columns.push_back(std::move(c));
    }
    if (!s.columns.empty()) {
      for (size_t i = 0; i < s.columns.size() && i < table->columns.size(); i++) table->columns[i].name = s.columns[i].name;
    }
    for (auto &row : r.rows) {
      Row nr = row;
      for (size_t i = 0; i < nr.size(); i++) if (nr[i].type != table->columns[i].type) nr[i] = CastValue(nr[i], table->columns[i].type, false);
      table->rows.push_back(nr);
    }
  } else {
    std::unordered_set<std::string> seen;
    for (auto &cd : s.columns) {
      if (!seen.insert(ToLower(cd.name)).second) throw CatalogException("Column with name " + cd.name + " already exists!");
      ColumnInfo c;
      c.name = cd.name;
      c.type = ResolveType(cd.type);
      c.not_null = cd.not_null || cd.primary_key;
      if (cd.default_value) c.default_value = cd.default_value->Copy();
      if (cd.generated) c.generated = cd.generated->Copy();
      c.type_name = cd.type_name;
      table->columns.push_back(std::move(c));
      if (cd.primary_key) { Constraint pk; pk.kind = Constraint::PRIMARY_KEY; pk.columns.push_back(cd.name); table->constraints.push_back(std::move(pk)); }
      if (cd.unique) { Constraint u; u.kind = Constraint::UNIQUE; u.columns.push_back(cd.name); table->constraints.push_back(std::move(u)); }
      if (cd.check) { Constraint ck; ck.kind = Constraint::CHECK; ck.check = cd.check->Copy(); table->constraints.push_back(std::move(ck)); }
    }
    for (auto &con : s.constraints) {
      Constraint c;
      c.kind = con.kind; c.columns = con.columns; c.fk_table = con.fk_table; c.fk_columns = con.fk_columns; c.name = con.name;
      if (con.check) c.check = con.check->Copy();
      for (auto &cn : c.columns) if (table->ColumnIndex(cn) < 0) throw BinderException("Column \"" + cn + "\" referenced in constraint does not exist");
      if (c.kind == Constraint::PRIMARY_KEY) {
        for (auto &cn : c.columns) table->columns[table->ColumnIndex(cn)].not_null = true;
        for (auto &existing : table->constraints) if (existing.kind == Constraint::PRIMARY_KEY) throw ParserException("table \"" + s.table + "\" has more than one primary key");
      }
      if (c.kind == Constraint::FOREIGN_KEY) {
        auto ft = catalog.FindTable("", "", c.fk_table);
        if (!ft) throw CatalogException("Table with name " + c.fk_table + " does not exist!");
        if (c.fk_columns.empty()) c.fk_columns = ft->PrimaryKeyColumns();
      }
      table->constraints.push_back(std::move(c));
    }
  }
  if (schema.tables.count(s.table)) schema.creation_order.erase(std::remove(schema.creation_order.begin(), schema.creation_order.end(), "table:" + s.table), schema.creation_order.end());
  schema.views.erase(s.table);
  schema.tables[s.table] = table;
  schema.creation_order.push_back("table:" + s.table);
  catalog.MarkDirty(s.temporary ? "temp" : catalog.default_database);
  return NoResult();
}

QueryResult Executor::ExecuteCreateView(CreateViewStatement &s) {
  auto &schema = catalog.ResolveSchemaForCreate(s.catalog, s.schema, s.temporary);
  if (schema.views.count(s.view) || schema.tables.count(s.view)) {
    if (s.on_conflict == OnCreateConflict::IGNORE) return NoResult();
    if (s.on_conflict == OnCreateConflict::ERROR) {
      if (schema.tables.count(s.view)) throw CatalogException("Table with name \"" + s.view + "\" already exists!");
      throw CatalogException("View with name \"" + s.view + "\" already exists!");
    }
  }
  // bind to validate and get types
  QueryResult r = ExecuteSelect(*s.query);
  auto view = std::make_shared<ViewEntry>();
  view->name = s.view; view->schema = schema.name; view->temporary = s.temporary; view->oid = catalog.NextOid();
  view->sql = s.query->ToString();
  view->aliases = s.aliases;
  view->column_names = r.names;
  for (size_t i = 0; i < s.aliases.size() && i < view->column_names.size(); i++) view->column_names[i] = s.aliases[i];
  view->column_types = r.types;
  std::string cv = "CREATE VIEW " + QuoteIdentifierIfNeeded(s.view);
  if (!s.aliases.empty()) { cv += "("; for (size_t i = 0; i < s.aliases.size(); i++) { if (i) cv += ", "; cv += QuoteIdentifierIfNeeded(s.aliases[i]); } cv += ")"; }
  cv += " AS " + view->sql + ";";
  view->create_sql = cv;
  if (schema.views.count(s.view)) schema.creation_order.erase(std::remove(schema.creation_order.begin(), schema.creation_order.end(), "view:" + s.view), schema.creation_order.end());
  schema.views[s.view] = view;
  schema.creation_order.push_back("view:" + s.view);
  catalog.MarkDirty(s.temporary ? "temp" : catalog.default_database);
  return NoResult();
}

// ---------------------------------------------------------------- constraints
void Executor::CheckConstraints(TableEntry &table, const Row &row, size_t skip_row_idx, const std::vector<Row> *pending) {
  for (size_t i = 0; i < table.columns.size(); i++) {
    if (table.columns[i].not_null && row[i].is_null) throw ConstraintException("NOT NULL constraint failed: " + table.name + "." + table.columns[i].name);
  }
  for (auto &c : table.constraints) {
    if (c.kind == Constraint::PRIMARY_KEY || c.kind == Constraint::UNIQUE) {
      std::vector<int> idxs;
      for (auto &cn : c.columns) idxs.push_back(table.ColumnIndex(cn));
      bool any_null = false;
      for (int ci : idxs) if (row[ci].is_null) any_null = true;
      if (any_null) continue;
      auto check_against = [&](const std::vector<Row> &rows, size_t skip) {
        for (size_t ri = 0; ri < rows.size(); ri++) {
          if (ri == skip) continue;
          bool same = true;
          for (int ci : idxs) if (!ValuesEqual(rows[ri][ci], row[ci]) || rows[ri][ci].is_null) { same = false; break; }
          if (same) {
            std::string key;
            if (idxs.size() == 1) key = row[idxs[0]].ToString();
            else { for (size_t k = 0; k < idxs.size(); k++) { if (k) key += ", "; key += c.columns[k] + ": " + row[idxs[k]].ToString(); } }
            throw ConstraintException(std::string(c.kind == Constraint::PRIMARY_KEY ? "Duplicate key \"" : "Duplicate key \"") + (idxs.size() == 1 ? c.columns[0] + ": " + key : key) + "\" violates " + (c.kind == Constraint::PRIMARY_KEY ? "primary key" : "unique") + " constraint.");
          }
        }
      };
      check_against(table.rows, skip_row_idx);
      if (pending) check_against(*pending, (size_t)-1);
    } else if (c.kind == Constraint::CHECK) {
      BindContext bc;
      Binding b; b.alias = table.name;
      for (auto &col : table.columns) { b.names.push_back(col.name); b.types.push_back(col.type); }
      bc.bindings.push_back(b);
      BExpr be = Bind(*c.check, bc);
      Value v = Eval(*be, row);
      if (!v.is_null && !v.ival) throw ConstraintException("CHECK constraint failed on table " + table.name + " with expression " + c.check->ToString());
    } else if (c.kind == Constraint::FOREIGN_KEY) {
      auto ft = catalog.FindTable("", "", c.fk_table);
      if (!ft) continue;
      std::vector<int> idxs; for (auto &cn : c.columns) idxs.push_back(table.ColumnIndex(cn));
      std::vector<int> fidx; for (auto &cn : c.fk_columns) fidx.push_back(ft->ColumnIndex(cn));
      bool any_null = false; for (int ci : idxs) if (row[ci].is_null) any_null = true;
      if (any_null) continue;
      bool found = false;
      for (auto &fr : ft->rows) { bool same = true; for (size_t k = 0; k < idxs.size(); k++) if (!ValuesEqual(fr[fidx[k]], row[idxs[k]])) { same = false; break; } if (same) { found = true; break; } }
      if (!found) throw ConstraintException("Violates foreign key constraint because key \"" + c.fk_columns[0] + ": " + row[idxs[0]].ToString() + "\" does not exist in the referenced table");
    }
  }
}

// ---------------------------------------------------------------- INSERT
QueryResult Executor::ExecuteInsert(InsertStatement &s) {
  auto table = catalog.FindTable(s.catalog, s.schema, s.table);
  if (!table) {
    auto view = catalog.FindView(s.catalog, s.schema, s.table);
    if (view) throw CatalogException("Cannot insert into a view");
    throw CatalogException(TableNotFound(catalog, s.table));
  }
  std::vector<int> col_map;  // target column index for each value column
  std::vector<std::string> columns = s.columns;
  QueryResult src;
  if (s.default_values) {
    src.rows.push_back(Row());
  } else {
    // CTEs: wrap
    if (!s.ctes.empty()) {
      auto &node = *s.select->node;
      for (auto &c : s.ctes) node.ctes.insert(node.ctes.begin(), std::move(c));
      s.ctes.clear();
    }
    src = ExecuteSelect(*s.select);
    if (s.by_name) {
      columns = src.names;
    }
  }
  if (columns.empty()) {
    if (!s.default_values && src.types.size() > table->columns.size()) {
      throw BinderException("table " + table->name + " has " + std::to_string(table->columns.size()) + " columns but " + std::to_string(src.types.size()) + " values were supplied");
    }
    for (size_t i = 0; i < (s.default_values ? 0 : src.types.size()); i++) col_map.push_back((int)i);
  } else {
    std::unordered_set<std::string> seen;
    for (auto &c : columns) {
      int idx = table->ColumnIndex(c);
      if (idx < 0) throw BinderException("Table \"" + table->name + "\" does not have a column with name \"" + c + "\"");
      if (!seen.insert(ToLower(c)).second) throw BinderException("Duplicate column name \"" + c + "\" in INSERT");
      col_map.push_back(idx);
    }
    if (!s.default_values && src.types.size() != col_map.size()) {
      throw BinderException("table " + table->name + " has " + std::to_string(col_map.size()) + " columns but " + std::to_string(src.types.size()) + " values were supplied");
    }
  }
  std::vector<Row> new_rows;
  std::vector<Row> returning_rows;
  int64_t count = 0;
  std::vector<size_t> replaced;
  for (auto &vrow : src.rows) {
    Row r = DefaultRow(*this, *table);
    for (size_t i = 0; i < col_map.size(); i++) {
      Value v = vrow[i];
      const LogicalType &t = table->columns[col_map[i]].type;
      if (v.type != t) {
        if (v.is_null) v = Value::Null(t);
        else {
          try { v = CastValue(v, t, false); }
          catch (DBException &ex) { throw ConversionException(std::string(ex.what())); }
        }
      }
      r[col_map[i]] = v;
    }
    // generated columns
    for (size_t ci = 0; ci < table->columns.size(); ci++) {
      if (table->columns[ci].generated) {
        BindContext bc; Binding b; b.alias = table->name;
        for (auto &col : table->columns) { b.names.push_back(col.name); b.types.push_back(col.type); }
        bc.bindings.push_back(b);
        BExpr be = Bind(*table->columns[ci].generated, bc);
        Value v = Eval(*be, r);
        if (v.type != table->columns[ci].type && !v.is_null) v = CastValue(v, table->columns[ci].type, false);
        r[ci] = v;
      }
    }
    // conflict handling
    bool skip = false;
    if (s.or_ignore || s.or_replace || s.on_conflict) {
      // find conflicting existing row on PK/UNIQUE
      int conflict_idx = -1;
      for (auto &c : table->constraints) {
        if (c.kind != Constraint::PRIMARY_KEY && c.kind != Constraint::UNIQUE) continue;
        std::vector<int> idxs; for (auto &cn : c.columns) idxs.push_back(table->ColumnIndex(cn));
        if (s.on_conflict && !s.on_conflict->indexed_columns.empty()) {
          bool match = idxs.size() == s.on_conflict->indexed_columns.size();
          for (auto &ic : s.on_conflict->indexed_columns) { bool f = false; for (auto &cn : c.columns) if (IEquals(cn, ic)) f = true; if (!f) match = false; }
          if (!match) continue;
        }
        for (size_t ri = 0; ri < table->rows.size(); ri++) {
          bool same = true;
          for (int ci : idxs) if (table->rows[ri][ci].is_null || !ValuesEqual(table->rows[ri][ci], r[ci])) { same = false; break; }
          if (same) { conflict_idx = (int)ri; break; }
        }
        if (conflict_idx >= 0) break;
      }
      if (conflict_idx >= 0) {
        if (s.or_ignore || (s.on_conflict && s.on_conflict->action == OnConflictInfo::NOTHING)) skip = true;
        else if (s.or_replace) { table->rows[conflict_idx] = r; skip = true; count++; }
        else if (s.on_conflict && s.on_conflict->action == OnConflictInfo::UPDATE) {
          // evaluate SET expressions with excluded.* referencing new row
          BindContext bc;
          Binding b; b.alias = table->name;
          for (auto &col : table->columns) { b.names.push_back(col.name); b.types.push_back(col.type); }
          bc.bindings.push_back(b);
          Binding ex; ex.alias = "excluded"; ex.offset = (int)table->columns.size();
          for (auto &col : table->columns) { ex.names.push_back(col.name); ex.types.push_back(col.type); }
          bc.bindings.push_back(ex);
          Row combined = table->rows[conflict_idx];
          combined.insert(combined.end(), r.begin(), r.end());
          bool do_update = true;
          if (s.on_conflict->where) { BExpr w = Bind(*s.on_conflict->where, bc); Value v = Eval(*w, combined); do_update = !v.is_null && v.ival; }
          if (do_update) {
            Row updated = table->rows[conflict_idx];
            for (size_t k = 0; k < s.on_conflict->set_columns.size(); k++) {
              int ci = table->ColumnIndex(s.on_conflict->set_columns[k]);
              if (ci < 0) throw BinderException("Column \"" + s.on_conflict->set_columns[k] + "\" does not exist");
              BExpr be = Bind(*s.on_conflict->set_exprs[k], bc);
              Value v = Eval(*be, combined);
              if (v.type != table->columns[ci].type) v = CastValue(v, table->columns[ci].type, false);
              updated[ci] = v;
            }
            table->rows[conflict_idx] = updated;
            count++;
            if (!s.returning.empty()) returning_rows.push_back(updated);
          }
          skip = true;
        }
      }
    }
    if (skip) continue;
    CheckConstraints(*table, r, (size_t)-1, &new_rows);
    new_rows.push_back(r);
    count++;
  }
  for (auto &r : new_rows) { table->rows.push_back(r); if (!s.returning.empty()) returning_rows.push_back(r); }
  catalog.MarkDirty(table->temporary ? "temp" : catalog.default_database);
  ctx.rows_changed = count;
  if (!s.returning.empty()) {
    QueryResult r;
    BindContext bc;
    Binding b; b.alias = table->name;
    for (auto &col : table->columns) { b.names.push_back(col.name); b.types.push_back(col.type); }
    bc.bindings.push_back(b);
    std::vector<ExprPtr> exprs;
    for (auto &e : s.returning) { if (e->kind == ExprKind::STAR) ExpandStar(*e, bc, exprs); else exprs.push_back(e->Copy()); }
    std::vector<BExpr> bes;
    for (auto &e : exprs) { bes.push_back(Bind(*e, bc)); r.names.push_back(e->alias.empty() ? (e->kind == ExprKind::COLUMN_REF ? e->names.back() : e->ToString()) : e->alias); r.types.push_back(NormalizeLiteral(Value::Null(bes.back()->type)).type); }
    for (auto &row : returning_rows) { Row out; for (auto &be : bes) out.push_back(Eval(*be, row)); r.rows.push_back(out); }
    return r;
  }
  QueryResult r = NoResult();
  r.changed_rows = count;
  return r;
}

// ---------------------------------------------------------------- UPDATE
QueryResult Executor::ExecuteUpdate(UpdateStatement &s) {
  auto table = catalog.FindTable("", s.schema, s.table);
  if (!table) throw CatalogException(TableNotFound(catalog, s.table));
  BindContext bc;
  Binding b; b.alias = s.alias.empty() ? table->name : s.alias;
  for (auto &col : table->columns) { b.names.push_back(col.name); b.types.push_back(col.type); }
  bc.bindings.push_back(b);
  std::vector<Row> from_rows;
  if (s.from) {
    BindContext fctx;
    fctx.parent = nullptr;
    std::vector<Row> fr;
    BindTableRef(*s.from, fctx, fr);
    for (auto &fb : fctx.bindings) { Binding nb = fb; nb.offset += (int)table->columns.size(); bc.bindings.push_back(nb); }
    from_rows = fr;
  }
  std::vector<int> cols;
  std::vector<BExpr> exprs;
  for (size_t i = 0; i < s.columns.size(); i++) {
    int ci = table->ColumnIndex(s.columns[i]);
    if (ci < 0) throw BinderException("Referenced update column " + s.columns[i] + " not found in table!");
    cols.push_back(ci);
    if (s.expressions[i]->kind == ExprKind::DEFAULT) {
      if (table->columns[ci].default_value) exprs.push_back(Bind(*table->columns[ci].default_value, bc));
      else { auto c = std::make_shared<BoundExpr>(BKind::CONSTANT); c->constant = Value::Null(table->columns[ci].type); c->type = c->constant.type; exprs.push_back(c); }
    } else exprs.push_back(BindCast(Bind(*s.expressions[i], bc), table->columns[ci].type, false));
  }
  BExpr where;
  if (s.where) where = BindCast(Bind(*s.where, bc), LogicalType(TypeId::BOOLEAN), false);
  int64_t count = 0;
  std::vector<Row> returning_rows;
  std::vector<Row> new_rows = table->rows;
  for (size_t ri = 0; ri < table->rows.size(); ri++) {
    Row &row = new_rows[ri];
    bool updated = false;
    if (s.from) {
      for (auto &fr : from_rows) {
        Row combined = table->rows[ri];
        combined.insert(combined.end(), fr.begin(), fr.end());
        bc.current_row = &combined;
        if (where) { Value v = Eval(*where, combined); if (v.is_null || !v.ival) continue; }
        for (size_t k = 0; k < cols.size(); k++) row[cols[k]] = Eval(*exprs[k], combined);
        updated = true;
        break;
      }
    } else {
      bc.current_row = &table->rows[ri];
      if (where) { Value v = Eval(*where, table->rows[ri]); if (v.is_null || !v.ival) continue; }
      Row orig = table->rows[ri];
      for (size_t k = 0; k < cols.size(); k++) row[cols[k]] = Eval(*exprs[k], orig);
      updated = true;
    }
    if (!updated) continue;
    for (size_t ci = 0; ci < table->columns.size(); ci++) {
      if (table->columns[ci].generated) { BExpr ge = Bind(*table->columns[ci].generated, bc); Value v = Eval(*ge, row); if (!v.is_null && v.type != table->columns[ci].type) v = CastValue(v, table->columns[ci].type, false); row[ci] = v; }
    }
    count++;
    if (!s.returning.empty()) returning_rows.push_back(row);
  }
  bc.current_row = nullptr;
  // constraints check on new rows
  for (size_t ri = 0; ri < new_rows.size(); ri++) {
    bool changed = false;
    for (size_t ci = 0; ci < new_rows[ri].size(); ci++) if (!ValuesEqual(new_rows[ri][ci], table->rows[ri][ci])) { changed = true; break; }
    if (!changed) continue;
    std::vector<Row> others;
    TableEntry tmp = *table; tmp.rows = new_rows;
    CheckConstraints(tmp, new_rows[ri], ri, nullptr);
  }
  table->rows = new_rows;
  catalog.MarkDirty(table->temporary ? "temp" : catalog.default_database);
  ctx.rows_changed = count;
  if (!s.returning.empty()) {
    QueryResult r;
    BindContext rc;
    Binding rb; rb.alias = s.alias.empty() ? table->name : s.alias;
    for (auto &col : table->columns) { rb.names.push_back(col.name); rb.types.push_back(col.type); }
    rc.bindings.push_back(rb);
    std::vector<ExprPtr> exprs2;
    for (auto &e : s.returning) { if (e->kind == ExprKind::STAR) ExpandStar(*e, rc, exprs2); else exprs2.push_back(e->Copy()); }
    std::vector<BExpr> bes;
    for (auto &e : exprs2) { bes.push_back(Bind(*e, rc)); r.names.push_back(e->alias.empty() ? (e->kind == ExprKind::COLUMN_REF ? e->names.back() : e->ToString()) : e->alias); r.types.push_back(NormalizeLiteral(Value::Null(bes.back()->type)).type); }
    for (auto &row : returning_rows) { Row out; for (auto &be : bes) out.push_back(Eval(*be, row)); r.rows.push_back(out); }
    return r;
  }
  QueryResult r = NoResult();
  r.changed_rows = count;
  return r;
}

// ---------------------------------------------------------------- DELETE
QueryResult Executor::ExecuteDelete(DeleteStatement &s) {
  auto table = catalog.FindTable("", s.schema, s.table);
  if (!table) throw CatalogException(TableNotFound(catalog, s.table));
  BindContext bc;
  Binding b; b.alias = s.alias.empty() ? table->name : s.alias;
  for (auto &col : table->columns) { b.names.push_back(col.name); b.types.push_back(col.type); }
  bc.bindings.push_back(b);
  std::vector<Row> using_rows;
  bool has_using = !s.using_clauses.empty();
  if (has_using) {
    BindContext uctx;
    std::vector<Row> ur;
    for (size_t i = 0; i < s.using_clauses.size(); i++) {
      if (i == 0) BindTableRef(*s.using_clauses[i], uctx, ur);
      else {
        BindContext tmp; std::vector<Row> rr; BindTableRef(*s.using_clauses[i], tmp, rr);
        int off = uctx.TotalColumns();
        for (auto &tb : tmp.bindings) { Binding nb = tb; nb.offset += off; uctx.bindings.push_back(nb); }
        std::vector<Row> combined;
        for (auto &a : ur) for (auto &b2 : rr) { Row c = a; c.insert(c.end(), b2.begin(), b2.end()); combined.push_back(c); }
        ur = combined;
      }
    }
    for (auto &ub : uctx.bindings) { Binding nb = ub; nb.offset += (int)table->columns.size(); bc.bindings.push_back(nb); }
    using_rows = ur;
  }
  BExpr where;
  if (s.where) where = BindCast(Bind(*s.where, bc), LogicalType(TypeId::BOOLEAN), false);
  std::vector<Row> kept, deleted;
  for (auto &row : table->rows) {
    bool del = true;
    if (where) {
      if (has_using) {
        del = false;
        for (auto &ur : using_rows) { Row combined = row; combined.insert(combined.end(), ur.begin(), ur.end()); bc.current_row = &combined; Value v = Eval(*where, combined); if (!v.is_null && v.ival) { del = true; break; } }
      } else {
        bc.current_row = &row;
        Value v = Eval(*where, row);
        del = !v.is_null && v.ival;
      }
    }
    if (del) deleted.push_back(row); else kept.push_back(row);
  }
  bc.current_row = nullptr;
  // foreign key checks: rows referenced by other tables cannot be deleted
  for (auto &sc : catalog.AllSchemas()) {
    for (auto &ot : sc.second->tables) {
      for (auto &c : ot.second->constraints) {
        if (c.kind != Constraint::FOREIGN_KEY || !IEquals(c.fk_table, table->name)) continue;
        for (auto &drow : deleted) {
          for (auto &orow : ot.second->rows) {
            bool same = true;
            for (size_t k = 0; k < c.columns.size(); k++) { int oi = ot.second->ColumnIndex(c.columns[k]); int ti = table->ColumnIndex(c.fk_columns[k]); if (orow[oi].is_null || !ValuesEqual(orow[oi], drow[ti])) { same = false; break; } }
            if (same) throw ConstraintException("Violates foreign key constraint because key \"" + c.fk_columns[0] + ": " + drow[table->ColumnIndex(c.fk_columns[0])].ToString() + "\" is still referenced by a foreign key in a different table. If this is an unexpected constraint violation, please refer to the foreign key limitations in the documentation");
          }
        }
      }
    }
  }
  table->rows = kept;
  catalog.MarkDirty(table->temporary ? "temp" : catalog.default_database);
  ctx.rows_changed = (int64_t)deleted.size();
  if (!s.returning.empty()) {
    QueryResult r;
    BindContext rc;
    Binding rb; rb.alias = s.alias.empty() ? table->name : s.alias;
    for (auto &col : table->columns) { rb.names.push_back(col.name); rb.types.push_back(col.type); }
    rc.bindings.push_back(rb);
    std::vector<ExprPtr> exprs;
    for (auto &e : s.returning) { if (e->kind == ExprKind::STAR) ExpandStar(*e, rc, exprs); else exprs.push_back(e->Copy()); }
    std::vector<BExpr> bes;
    for (auto &e : exprs) { bes.push_back(Bind(*e, rc)); r.names.push_back(e->alias.empty() ? (e->kind == ExprKind::COLUMN_REF ? e->names.back() : e->ToString()) : e->alias); r.types.push_back(NormalizeLiteral(Value::Null(bes.back()->type)).type); }
    for (auto &row : deleted) { Row out; for (auto &be : bes) out.push_back(Eval(*be, row)); r.rows.push_back(out); }
    return r;
  }
  QueryResult r = NoResult();
  r.changed_rows = (int64_t)deleted.size();
  return r;
}

// ---------------------------------------------------------------- DROP
QueryResult Executor::ExecuteDrop(DropStatement &s) {
  if (s.entry_type == "TABLE") {
    std::string fdb, fschema;
    auto t = catalog.FindTable(s.catalog, s.schema, s.name, &fdb, &fschema);
    if (!t) {
      if (s.if_exists) return NoResult();
      auto v = catalog.FindView(s.catalog, s.schema, s.name);
      if (v) throw CatalogException("Existing object " + s.name + " is of type View, trying to replace with type Table");
      throw CatalogException(TableNotFound(catalog, s.name));
    }
    // dependency check: views referencing? DuckDB doesn't track; foreign keys referencing
    for (auto &sc : catalog.AllSchemas()) for (auto &ot : sc.second->tables) for (auto &c : ot.second->constraints) if (c.kind == Constraint::FOREIGN_KEY && IEquals(c.fk_table, t->name) && ot.second.get() != t.get() && !s.cascade)
      throw CatalogException("Could not drop the table because this table is main key table of the table \"" + ot.second->name + "\".");
    auto *sc = catalog.FindSchema(fdb, fschema);
    sc->tables.erase(t->name);
    sc->creation_order.erase(std::remove(sc->creation_order.begin(), sc->creation_order.end(), "table:" + t->name), sc->creation_order.end());
    for (auto it = sc->indexes.begin(); it != sc->indexes.end();) { if (IEquals(it->second->table, t->name)) it = sc->indexes.erase(it); else ++it; }
    catalog.MarkDirty(fdb);
    return NoResult();
  }
  if (s.entry_type == "VIEW") {
    std::string fdb, fschema;
    auto v = catalog.FindView(s.catalog, s.schema, s.name, &fdb, &fschema);
    if (!v) {
      if (s.if_exists) return NoResult();
      auto t = catalog.FindTable(s.catalog, s.schema, s.name);
      if (t) throw CatalogException("Existing object " + s.name + " is of type Table, trying to replace with type View");
      std::vector<std::string> cands = catalog.AllTableLikeNames();
      auto top = TopSimilar(s.name, cands, 1, 0.5);
      throw CatalogException("View with name " + s.name + " does not exist!" + (top.empty() ? "" : "\nDid you mean \"" + top[0] + "\"?"));
    }
    auto *sc = catalog.FindSchema(fdb, fschema);
    sc->views.erase(v->name);
    sc->creation_order.erase(std::remove(sc->creation_order.begin(), sc->creation_order.end(), "view:" + v->name), sc->creation_order.end());
    catalog.MarkDirty(fdb);
    return NoResult();
  }
  if (s.entry_type == "SCHEMA") {
    auto &db = catalog.DefaultDatabase();
    auto it = db.schemas.find(s.name);
    if (it == db.schemas.end()) { if (s.if_exists) return NoResult(); throw CatalogException("Schema with name " + s.name + " does not exist!"); }
    if (s.name == "main") throw CatalogException("Cannot drop schema \"main\" because it is an internal system entry");
    if (!s.cascade && (!it->second->tables.empty() || !it->second->views.empty())) {
      std::string dep = !it->second->tables.empty() ? "table \"" + it->second->tables.begin()->first + "\"" : "view \"" + it->second->views.begin()->first + "\"";
      throw DependencyException("Cannot drop entry \"" + s.name + "\" because there are entries that depend on it.\n" + dep + " depends on \"" + s.name + "\".\nUse DROP...CASCADE to drop all dependents.");
    }
    db.schemas.erase(it);
    db.dirty = true;
    return NoResult();
  }
  if (s.entry_type == "SEQUENCE") {
    auto seq = catalog.FindSequence(s.catalog, s.schema, s.name);
    if (!seq) { if (s.if_exists) return NoResult(); throw CatalogException("Sequence with name " + s.name + " does not exist!"); }
    for (auto &sc : catalog.AllSchemas()) sc.second->sequences.erase(seq->name);
    return NoResult();
  }
  if (s.entry_type == "MACRO" || s.entry_type == "MACRO TABLE") {
    auto m = catalog.FindMacro(s.catalog, s.schema, s.name);
    if (!m || (m->is_table != (s.entry_type == "MACRO TABLE"))) { if (s.if_exists) return NoResult(); throw CatalogException(std::string(s.entry_type == "MACRO TABLE" ? "Table Macro Function" : "Macro Function") + " with name " + s.name + " does not exist!"); }
    for (auto &sc : catalog.AllSchemas()) { if (sc.second->macros.count(m->name) && sc.second->macros[m->name] == m) { sc.second->macros.erase(m->name); sc.second->creation_order.erase(std::remove(sc.second->creation_order.begin(), sc.second->creation_order.end(), "macro:" + m->name), sc.second->creation_order.end()); } }
    return NoResult();
  }
  if (s.entry_type == "TYPE") {
    auto t = catalog.FindType(s.catalog, s.schema, s.name);
    if (!t) { if (s.if_exists) return NoResult(); throw CatalogException("Type with name " + s.name + " does not exist!"); }
    for (auto &sc : catalog.AllSchemas()) sc.second->types.erase(t->name);
    return NoResult();
  }
  if (s.entry_type == "INDEX") {
    auto idx = catalog.FindIndex(s.name);
    if (!idx) { if (s.if_exists) return NoResult(); throw CatalogException("Index with name " + s.name + " does not exist!"); }
    for (auto &sc : catalog.AllSchemas()) {
      if (sc.second->indexes.count(idx->name)) {
        sc.second->indexes.erase(idx->name);
        auto t = sc.second->tables.find(idx->table);
        if (t != sc.second->tables.end()) {
          auto &cons = t->second->constraints;
          cons.erase(std::remove_if(cons.begin(), cons.end(), [&](const Constraint &c) { return c.name == idx->name; }), cons.end());
        }
      }
    }
    return NoResult();
  }
  if (s.entry_type == "SECRET") return NoResult();
  throw NotImplementedException("DROP " + s.entry_type);
}

// ---------------------------------------------------------------- ALTER
QueryResult Executor::ExecuteAlter(AlterStatement &s) {
  if (s.entry_type == "VIEW") {
    std::string fdb, fschema;
    auto v = catalog.FindView(s.catalog, s.schema, s.table, &fdb, &fschema);
    if (!v) { if (s.if_exists) return NoResult(); throw CatalogException("View with name " + s.table + " does not exist!"); }
    if (s.kind == AlterStatement::RENAME_TABLE) {
      auto *sc = catalog.FindSchema(fdb, fschema);
      sc->views.erase(v->name);
      v->name = s.new_name;
      sc->views[v->name] = v;
      return NoResult();
    }
    throw NotImplementedException("ALTER VIEW action");
  }
  std::string fdb, fschema;
  auto table = catalog.FindTable(s.catalog, s.schema, s.table, &fdb, &fschema);
  if (!table) {
    if (s.if_exists) return NoResult();
    auto v = catalog.FindView(s.catalog, s.schema, s.table, &fdb, &fschema);
    if (v && s.kind == AlterStatement::RENAME_TABLE) {
      auto *sc = catalog.FindSchema(fdb, fschema);
      sc->views.erase(v->name); v->name = s.new_name; sc->views[v->name] = v;
      return NoResult();
    }
    throw CatalogException(TableNotFound(catalog, s.table));
  }
  catalog.MarkDirty(fdb);
  switch (s.kind) {
  case AlterStatement::ADD_COLUMN: {
    if (table->ColumnIndex(s.column.name) >= 0) {
      if (s.if_not_exists) return NoResult();
      throw CatalogException("Column with name " + s.column.name + " already exists!");
    }
    ColumnInfo c; c.name = s.column.name; c.type = ResolveType(s.column.type); c.not_null = s.column.not_null;
    if (s.column.default_value) c.default_value = s.column.default_value->Copy();
    Value dv = c.default_value ? CastValue(EvaluateConstantExpression(*this, *c.default_value), c.type, false) : Value::Null(c.type);
    table->columns.push_back(std::move(c));
    for (auto &r : table->rows) r.push_back(dv);
    return NoResult();
  }
  case AlterStatement::DROP_COLUMN: {
    int ci = table->ColumnIndex(s.column_name);
    if (ci < 0) { if (s.if_column_exists) return NoResult(); throw BinderException("Column with name " + s.column_name + " does not exist!"); }
    for (auto &c : table->constraints) {
      for (auto &cn : c.columns) if (IEquals(cn, s.column_name)) throw DependencyException("Cannot drop column \"" + s.column_name + "\" because there are entries that depend on it.\nUse DROP...CASCADE to drop all dependents.");
    }
    if (table->columns.size() == 1) throw CatalogException("Cannot drop column: table only has one column remaining!");
    table->columns.erase(table->columns.begin() + ci);
    for (auto &r : table->rows) r.erase(r.begin() + ci);
    return NoResult();
  }
  case AlterStatement::RENAME_COLUMN: {
    int ci = table->ColumnIndex(s.column_name);
    if (ci < 0) throw BinderException("Column with name " + s.column_name + " does not exist!");
    if (table->ColumnIndex(s.new_name) >= 0) throw CatalogException("Column with name " + s.new_name + " already exists!");
    table->columns[ci].name = s.new_name;
    for (auto &c : table->constraints) for (auto &cn : c.columns) if (IEquals(cn, s.column_name)) cn = s.new_name;
    return NoResult();
  }
  case AlterStatement::RENAME_TABLE: {
    auto *sc = catalog.FindSchema(fdb, fschema);
    if (sc->tables.count(s.new_name) || sc->views.count(s.new_name)) throw CatalogException("Table with name \"" + s.new_name + "\" already exists!");
    sc->tables.erase(table->name);
    for (auto &co : sc->creation_order) if (co == "table:" + table->name) co = "table:" + s.new_name;
    table->name = s.new_name;
    sc->tables[s.new_name] = table;
    return NoResult();
  }
  case AlterStatement::ALTER_TYPE: {
    int ci = table->ColumnIndex(s.column_name);
    if (ci < 0) throw BinderException("Column with name " + s.column_name + " does not exist!");
    LogicalType nt = ResolveType(s.new_type);
    BindContext bc; Binding b; b.alias = table->name;
    for (auto &col : table->columns) { b.names.push_back(col.name); b.types.push_back(col.type); }
    bc.bindings.push_back(b);
    BExpr be;
    if (s.expression) be = BindCast(Bind(*s.expression, bc), nt, false);
    for (auto &r : table->rows) {
      if (be) r[ci] = Eval(*be, r);
      else r[ci] = CastValue(r[ci], nt, false);
    }
    table->columns[ci].type = nt;
    return NoResult();
  }
  case AlterStatement::SET_DEFAULT: {
    int ci = table->ColumnIndex(s.column_name);
    if (ci < 0) throw BinderException("Column with name " + s.column_name + " does not exist!");
    table->columns[ci].default_value = s.expression->Copy();
    return NoResult();
  }
  case AlterStatement::DROP_DEFAULT: {
    int ci = table->ColumnIndex(s.column_name);
    if (ci < 0) throw BinderException("Column with name " + s.column_name + " does not exist!");
    table->columns[ci].default_value = nullptr;
    return NoResult();
  }
  case AlterStatement::SET_NOT_NULL: {
    int ci = table->ColumnIndex(s.column_name);
    if (ci < 0) throw BinderException("Column with name " + s.column_name + " does not exist!");
    for (auto &r : table->rows) if (r[ci].is_null) throw ConstraintException("NOT NULL constraint failed: " + table->name + "." + s.column_name);
    table->columns[ci].not_null = true;
    return NoResult();
  }
  case AlterStatement::DROP_NOT_NULL: {
    int ci = table->ColumnIndex(s.column_name);
    if (ci < 0) throw BinderException("Column with name " + s.column_name + " does not exist!");
    table->columns[ci].not_null = false;
    return NoResult();
  }
  case AlterStatement::ADD_PK: {
    if (table->HasPrimaryKey()) throw CatalogException("table \"" + table->name + "\" already has a primary key");
    Constraint c; c.kind = Constraint::PRIMARY_KEY; c.columns = s.constraint.columns;
    for (auto &cn : c.columns) { int ci = table->ColumnIndex(cn); if (ci < 0) throw BinderException("Column with name " + cn + " does not exist!"); table->columns[ci].not_null = true; }
    table->constraints.push_back(std::move(c));
    return NoResult();
  }
  case AlterStatement::ADD_CONSTRAINT: {
    Constraint c; c.kind = s.constraint.kind; c.columns = s.constraint.columns; c.name = s.constraint.name;
    if (s.constraint.check) c.check = s.constraint.check->Copy();
    table->constraints.push_back(std::move(c));
    return NoResult();
  }
  case AlterStatement::DROP_PK: {
    auto &cons = table->constraints;
    cons.erase(std::remove_if(cons.begin(), cons.end(), [](const Constraint &c) { return c.kind == Constraint::PRIMARY_KEY; }), cons.end());
    return NoResult();
  }
  default: return NoResult();
  }
}

// ---------------------------------------------------------------- SET / PRAGMA
QueryResult Executor::ExecuteSet(SetStatement &s) {
  std::string name = ToLower(s.name);
  if (s.is_variable) {
    if (s.is_reset) catalog.variables.erase(s.name);
    else catalog.variables[s.name] = EvaluateConstantExpression(*this, *s.value);
    return NoResult();
  }
  if (s.is_reset) { catalog.settings.erase(name); if (name == "schema") catalog.default_schema = "main"; if (name == "search_path") catalog.search_path.clear(); return NoResult(); }
  Value v = EvaluateConstantExpression(*this, *s.value);
  if (name == "schema") {
    std::string sch = v.ToString();
    auto parts = SplitString(sch, '.');
    if (parts.size() == 2) { auto db = catalog.FindDatabase(parts[0]); if (!db || !db->schemas.count(parts[1])) throw CatalogException("SET schema: No catalog + schema named \"" + sch + "\" found."); catalog.default_database = db->name; catalog.default_schema = parts[1]; return NoResult(); }
    auto sc = catalog.FindSchema("", sch);
    if (!sc) throw CatalogException("SET schema: No catalog + schema named \"" + sch + "\" found.");
    catalog.default_schema = sc->name;
    return NoResult();
  }
  if (name == "search_path") {
    catalog.search_path.clear();
    for (auto &p : SplitString(v.ToString(), ',')) { std::string t = Trim(p); if (!t.empty()) { if (!catalog.FindSchema("", t)) throw CatalogException("SET search_path: No catalog + schema named \"" + t + "\" found."); catalog.search_path.push_back(t); } }
    return NoResult();
  }
  static const std::unordered_set<std::string> known = {"threads", "memory_limit", "max_memory", "enable_progress_bar", "preserve_insertion_order", "default_order", "default_null_order", "timezone", "calendar", "autoinstall_known_extensions", "autoload_known_extensions", "enable_object_cache", "temp_directory", "worker_threads", "profiling_mode", "enable_profiling", "profiling_output", "explain_output", "errors_as_json", "scalar_subquery_error_on_multiple_rows", "lambda_syntax", "max_expression_depth", "ordered_aggregate_threshold", "enable_external_access", "null_order", "pivot_limit", "enable_fsst_vectors", "checkpoint_threshold", "wal_autocheckpoint", "force_compression", "force_bitpacking_mode", "perfect_ht_threshold", "home_directory", "extension_directory", "custom_extension_repository", "secret_directory", "default_collation", "integer_division", "immediate_transaction_mode", "enable_http_metadata_cache", "log_query_path", "arrow_large_buffer_size", "binary_as_string", "prefer_range_joins", "produce_arrow_string_view", "partitioned_write_flush_threshold", "partitioned_write_max_open_files", "disabled_optimizers", "enable_macro_dependencies", "enable_view_dependencies", "old_implicit_casting", "ieee_floating_point_ops", "storage_compatibility_version", "duckdb_api", "custom_user_agent", "allow_unsigned_extensions", "allow_community_extensions", "allow_extensions_metadata_mismatch", "allow_unredacted_secrets", "allow_persistent_secrets", "enable_server_cert_verification", "ca_cert_file", "http_proxy", "http_proxy_username", "http_proxy_password", "http_timeout", "http_retries", "http_retry_wait_ms", "http_retry_backoff", "http_keep_alive", "s3_region", "s3_access_key_id", "s3_secret_access_key", "s3_endpoint", "s3_url_style", "s3_use_ssl", "streaming_buffer_size", "username", "user", "password", "access_mode", "default_block_size", "index_scan_percentage", "index_scan_max_count", "merge_join_threshold", "nested_loop_join_threshold", "late_materialization_max_rows", "asof_loop_join_threshold", "allocator_background_threads", "allocator_bulk_deallocation_flush_threshold", "allocator_flush_threshold", "enable_external_file_cache", "catalog_error_max_schemas", "zstd_min_string_length", "order_by_non_integer_literal", "enable_logging", "logging_level", "logging_mode", "logging_storage", "enabled_log_types", "disabled_log_types", "dynamic_or_filter_threshold", "max_vacuum_tasks", "max_temp_directory_size", "temp_file_encryption", "parquet_metadata_cache", "variant_legacy_encoding", "scheduler_process_partial", "debug_force_external", "debug_force_no_cross_product", "debug_asof_iejoin", "debug_window_mode", "debug_checkpoint_abort", "debug_skip_checkpoint_on_commit", "debug_verify_vector", "debug_verify_external", "enable_view_dependencies", "experimental_parallel_csv", "progress_bar_time", "enable_progress_bar_print", "query_timeout", "preserve_identifier_case", "unsafe_enable_version_guessing", "enable_geoparquet_conversion", "schema"};
  if (!known.count(name)) {
    std::vector<std::string> cands(known.begin(), known.end());
    auto top = TopSimilar(name, cands, 1, 0.5);
    throw CatalogException("unrecognized configuration parameter \"" + s.name + "\"" + (top.empty() ? "" : "\n\nDid you mean: \"" + top[0] + "\""));
  }
  catalog.settings[name] = v;
  return NoResult();
}

QueryResult Executor::ExecutePragma(PragmaStatement &s) {
  std::string name = ToLower(s.name);
  if (s.has_assignment) {
    SetStatement set; set.name = s.name; set.value = s.params[0]->Copy();
    return ExecuteSet(set);
  }
  if (name == "table_info") {
    if (s.params.empty()) throw BinderException("table_info requires a table name");
    std::string tname = s.params[0]->kind == ExprKind::CONSTANT ? s.params[0]->value.str : s.params[0]->ToString();
    auto table = catalog.FindTable("", "", tname);
    QueryResult r;
    r.names = {"cid", "name", "type", "notnull", "dflt_value", "pk"};
    r.types = {LogicalType(TypeId::INTEGER), LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR), LogicalType(TypeId::BOOLEAN), LogicalType(TypeId::VARCHAR), LogicalType(TypeId::BOOLEAN)};
    if (!table) {
      auto v = catalog.FindView("", "", tname);
      if (!v) throw CatalogException(TableNotFound(catalog, tname));
      for (size_t i = 0; i < v->column_names.size(); i++) r.rows.push_back({Value::Integer((int32_t)i), Value::Varchar(v->column_names[i]), Value::Varchar(v->column_types[i].ToString()), Value::Boolean(false), Value::Null(LogicalType(TypeId::VARCHAR)), Value::Boolean(false)});
      return r;
    }
    auto pk = table->PrimaryKeyColumns();
    for (size_t i = 0; i < table->columns.size(); i++) {
      auto &c = table->columns[i];
      bool is_pk = std::find_if(pk.begin(), pk.end(), [&](const std::string &p) { return IEquals(p, c.name); }) != pk.end();
      r.rows.push_back({Value::Integer((int32_t)i), Value::Varchar(c.name), Value::Varchar(c.type.ToString()), Value::Boolean(c.not_null), c.default_value ? Value::Varchar(c.default_value->ToString()) : Value::Null(LogicalType(TypeId::VARCHAR)), Value::Boolean(is_pk)});
    }
    return r;
  }
  if (name == "show_tables" || name == "show_tables_expanded") { ShowStatement sh; sh.kind = name == "show_tables" ? "TABLES" : "ALL TABLES"; return ExecuteShow(sh); }
  if (name == "database_list") return SystemView("", "main", "pragma_database_list");
  if (name == "version") {
    QueryResult r; r.names = {"library_version", "source_id"}; r.types = {LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR)};
    r.rows.push_back({Value::Varchar("v0.0.1"), Value::Varchar("780a73962f")});
    return r;
  }
  if (name == "platform") { QueryResult r; r.names = {"platform"}; r.types = {LogicalType(TypeId::VARCHAR)}; r.rows.push_back({Value::Varchar("linux_amd64")}); return r; }
  if (name == "user_agent") { QueryResult r; r.names = {"user_agent"}; r.types = {LogicalType(TypeId::VARCHAR)}; r.rows.push_back({Value::Varchar("duckdb/v0.0.1(linux_amd64)")}); return r; }
  if (name == "database_size") {
    QueryResult r; r.names = {"database_name", "database_size", "block_size", "total_blocks", "used_blocks", "free_blocks", "wal_size", "memory_usage", "memory_limit"};
    for (size_t i = 0; i < 9; i++) r.types.push_back(i == 0 || i == 1 || i == 6 || i == 7 || i == 8 ? LogicalType(TypeId::VARCHAR) : LogicalType(TypeId::BIGINT));
    r.rows.push_back({Value::Varchar(catalog.default_database), Value::Varchar("0 bytes"), Value::BigInt(0), Value::BigInt(0), Value::BigInt(0), Value::BigInt(0), Value::Varchar("0 bytes"), Value::Varchar("0 bytes"), Value::Varchar("12.3 GiB")});
    return r;
  }
  if (name == "storage_info" || name == "metadata_info") { QueryResult r; r.names = {"row_group_id"}; r.types = {LogicalType(TypeId::BIGINT)}; return r; }
  if (name == "enable_progress_bar" || name == "disable_progress_bar" || name == "enable_profiling" || name == "disable_profiling" || name == "enable_verification" || name == "disable_verification" || name == "enable_optimizer" || name == "disable_optimizer" || name == "enable_print_progress_bar" || name == "disable_print_progress_bar" || name == "force_checkpoint" || name == "enable_object_cache" || name == "disable_object_cache" || name == "verify_parallelism" || name == "disable_verify_parallelism" || name == "force_index_join" || name == "enable_checkpoint_on_shutdown" || name == "disable_checkpoint_on_shutdown" || name == "verify_external" || name == "disable_verify_external" || name == "force_compression" || name == "threads" || name == "memory_limit" || name == "debug_force_external" || name == "enable_force_parallelism" || name == "verify_serializer" || name == "disable_verify_serializer" || name == "enable_fsst_vectors") return NoResult();
  if (name == "functions") return SystemView("", "main", "duckdb_functions");
  if (name == "collations") { QueryResult r; r.names = {"collname"}; r.types = {LogicalType(TypeId::VARCHAR)}; for (auto c : {"noaccent", "nocase", "nfc"}) r.rows.push_back({Value::Varchar(c)}); return r; }
  throw CatalogException("Pragma Function with name " + name + " does not exist!");
}

