  r.types = {LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR)};
  r.rows.push_back({Value::Varchar("physical_plan"), Value::Varchar("┌───────────────────────────┐\n│         PROJECTION        │\n└───────────────────────────┘\n")});
