int64_t Executor::NextVal(SequenceEntry &seq) {
  int64_t v;
  if (!seq.used) { v = seq.start; seq.used = true; }
  else {
    int64_t next;
    if (__builtin_add_overflow(seq.current, seq.increment, &next) || next > seq.max_value || next < seq.min_value) {
      if (seq.cycle) next = seq.increment > 0 ? seq.min_value : seq.max_value;
      else throw SequenceException("nextval: reached " + std::string(seq.increment > 0 ? "maximum" : "minimum") + " value of sequence \"" + seq.name + "\" (" + std::to_string(seq.increment > 0 ? seq.max_value : seq.min_value) + ")");
    }
    v = next;
  }
  seq.current = v;
  return v;
}

// ---------------------------------------------------------------- DESCRIBE / SHOW
QueryResult Executor::Describe(const QueryResult &in) {
  QueryResult r;
  r.names = {"column_name", "column_type", "null", "key", "default", "extra"};
  for (int i = 0; i < 6; i++) r.types.push_back(LogicalType(TypeId::VARCHAR));
  for (size_t i = 0; i < in.names.size(); i++) {
    r.rows.push_back({Value::Varchar(in.names[i]), Value::Varchar(in.types[i].ToString()), Value::Varchar("YES"), Value::Null(LogicalType(TypeId::VARCHAR)), Value::Null(LogicalType(TypeId::VARCHAR)), Value::Null(LogicalType(TypeId::VARCHAR))});
  }
  return r;
}

QueryResult Executor::DescribeTable(const std::string &qname) {
  auto parts = SplitString(qname, '.');
  std::string name = parts.back();
  std::string schema = parts.size() > 1 ? parts[parts.size() - 2] : "";
  std::string cat = parts.size() > 2 ? parts[parts.size() - 3] : "";
  auto table = catalog.FindTable(cat, schema, name);
  QueryResult r;
  r.names = {"column_name", "column_type", "null", "key", "default", "extra"};
  for (int i = 0; i < 6; i++) r.types.push_back(LogicalType(TypeId::VARCHAR));
  if (table) {
    auto pk = table->PrimaryKeyColumns();
    for (auto &c : table->columns) {
      bool is_pk = std::find_if(pk.begin(), pk.end(), [&](const std::string &p) { return IEquals(p, c.name); }) != pk.end();
      bool is_uni = false;
      for (auto &con : table->constraints) if (con.kind == Constraint::UNIQUE && con.columns.size() == 1 && IEquals(con.columns[0], c.name)) is_uni = true;
      Value key = is_pk ? Value::Varchar("PRI") : (is_uni ? Value::Varchar("UNI") : Value::Null(LogicalType(TypeId::VARCHAR)));
      Value def = c.default_value ? Value::Varchar(c.default_value->ToString()) : Value::Null(LogicalType(TypeId::VARCHAR));
      r.rows.push_back({Value::Varchar(c.name), Value::Varchar(c.type.ToString()), Value::Varchar(c.not_null ? "NO" : "YES"), key, def, Value::Null(LogicalType(TypeId::VARCHAR))});
    }
    return r;
  }
  auto view = catalog.FindView(cat, schema, name);
  if (view) {
    for (size_t i = 0; i < view->column_names.size(); i++) r.rows.push_back({Value::Varchar(view->column_names[i]), Value::Varchar(view->column_types[i].ToString()), Value::Varchar("YES"), Value::Null(LogicalType(TypeId::VARCHAR)), Value::Null(LogicalType(TypeId::VARCHAR)), Value::Null(LogicalType(TypeId::VARCHAR))});
    return r;
  }
  // system view?
  try { QueryResult sv = SystemView(cat, schema, name); return Describe(sv); } catch (CatalogException &) {}
  throw CatalogException(TableNotFound(catalog, name));
}

QueryResult Executor::Summarize(const QueryResult &in) {
  QueryResult r;
  r.names = {"column_name", "column_type", "min", "max", "approx_unique", "avg", "std", "q25", "q50", "q75", "count", "null_percentage"};
