QueryResult Executor::ExecuteShow(ShowStatement &s) {
  if (s.kind == "TABLES") {
    QueryResult r;
    r.names = {"name"}; r.types = {LogicalType(TypeId::VARCHAR)};
    std::vector<std::string> names;
    auto &db = catalog.DefaultDatabase();
    auto it = db.schemas.find(catalog.default_schema);
    if (it != db.schemas.end()) {
      for (auto &t : it->second->tables) names.push_back(t.first);
      for (auto &v : it->second->views) names.push_back(v.first);
    }
    for (auto &t : catalog.databases["temp"]->schemas["main"]->tables) names.push_back(t.first);
    for (auto &v : catalog.databases["temp"]->schemas["main"]->views) names.push_back(v.first);
    std::sort(names.begin(), names.end());
    for (auto &n : names) r.rows.push_back({Value::Varchar(n)});
    return r;
  }
  if (s.kind == "ALL TABLES") {
    QueryResult r;
    r.names = {"database", "schema", "name", "column_names", "column_types", "temporary"};
    r.types = {LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR), LogicalType::List(LogicalType(TypeId::VARCHAR)), LogicalType::List(LogicalType(TypeId::VARCHAR)), LogicalType(TypeId::BOOLEAN)};
    for (auto &sc : catalog.AllSchemas()) {
      if (sc.first == "system") continue;
      std::vector<std::pair<std::string, Row>> entries;
      for (auto &t : sc.second->tables) {
        std::vector<Value> cn, ct;
        for (auto &c : t.second->columns) { cn.push_back(Value::Varchar(c.name)); ct.push_back(Value::Varchar(c.type.ToString())); }
        entries.push_back({t.first, {Value::Varchar(sc.first), Value::Varchar(sc.second->name), Value::Varchar(t.first), Value::List(LogicalType(TypeId::VARCHAR), cn), Value::List(LogicalType(TypeId::VARCHAR), ct), Value::Boolean(t.second->temporary)}});
      }
      for (auto &v : sc.second->views) {
        std::vector<Value> cn, ct;
        for (size_t i = 0; i < v.second->column_names.size(); i++) { cn.push_back(Value::Varchar(v.second->column_names[i])); ct.push_back(Value::Varchar(v.second->column_types[i].ToString())); }
        entries.push_back({v.first, {Value::Varchar(sc.first), Value::Varchar(sc.second->name), Value::Varchar(v.first), Value::List(LogicalType(TypeId::VARCHAR), cn), Value::List(LogicalType(TypeId::VARCHAR), ct), Value::Boolean(v.second->temporary)}});
      }
      std::sort(entries.begin(), entries.end(), [](auto &a, auto &b) { return a.first < b.first; });
      for (auto &e : entries) r.rows.push_back(e.second);
    }
    return r;
  }
  if (s.kind == "DATABASES") {
    QueryResult r;
    r.names = {"database_name"}; r.types = {LogicalType(TypeId::VARCHAR)};
    for (auto &n : catalog.database_order) r.rows.push_back({Value::Varchar(n)});
    return r;
  }
  if (s.kind == "SCHEMAS") {
    QueryResult r; r.names = {"schema_name"}; r.types = {LogicalType(TypeId::VARCHAR)};
    for (auto &sc : catalog.AllSchemas()) r.rows.push_back({Value::Varchar(sc.second->name)});
    return r;
  }
  if (s.kind == "VARIABLES") {
    QueryResult r; r.names = {"name", "value", "type"}; r.types = {LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR), LogicalType(TypeId::VARCHAR)};
    for (auto &v : catalog.variables) r.rows.push_back({Value::Varchar(v.first), Value::Varchar(v.second.ToString()), Value::Varchar(v.second.type.ToString())});
    return r;
  }
  if (s.kind == "SUMMARIZE") {
    QueryResult in;
    if (s.query) in = ExecuteSelect(*s.query);
    else {
      auto stmt = Parser::ParseSelectFromString("SELECT * FROM " + s.name);
      in = ExecuteSelect(*stmt);
    }
    return Summarize(in);
  }
  // DESCRIBE
  if (s.query) {
    QueryResult in = ExecuteSelect(*s.query);
    return Describe(in);
  }
  return DescribeTable(s.name);
}
