      }
      return r;
    }
    if (name == "pg_database") { r.names = {"oid", "datname", "datdba", "encoding", "datcollate", "datctype", "datistemplate", "datallowconn", "datconnlimit", "datlastsysoid", "datfrozenxid", "datminmxid", "dattablespace", "datacl"}; r.types = {BI(), V(), BI(), LogicalType(TypeId::INTEGER), V(), V(), BO(), BO(), BI(), BI(), BI(), BI(), BI(), V()}; for (auto &n : catalog.database_order) { auto &db = catalog.GetDatabase(n); r.rows.push_back({VB(db.oid), VS(n), VB(0), Value::Integer(6), VS("C"), VS("C"), VBool(false), VBool(true), VB(-1), VB(0), VB(0), VB(0), VB(0), VN()}); } return r; }
    if (name == "pg_settings") { r.names = {"name", "setting", "short_desc"}; r.types = {V(), V(), V()}; QueryResult s = SystemView("", "main", "duckdb_settings"); for (auto &row : s.rows) r.rows.push_back({row[0], row[1], row[2]}); return r; }
    if (name == "pg_type") { r.names = {"oid", "typname", "typnamespace", "typowner", "typlen", "typbyval", "typtype", "typcategory", "typispreferred", "typisdefined", "typdelim", "typrelid", "typsubscript", "typelem", "typarray", "typinput", "typoutput", "typreceive", "typsend", "typmodin", "typmodout", "typanalyze", "typalign", "typstorage", "typnotnull", "typbasetype", "typtypmod", "typndims", "typcollation", "typdefaultbin", "typdefault", "typacl"}; r.types = {BI(), V(), BI(), BI(), LogicalType(TypeId::INTEGER), BO(), V(), V(), BO(), BO(), V(), BI(), V(), BI(), BI(), V(), V(), V(), V(), V(), V(), V(), V(), V(), BO(), BI(), BI(), BI(), BI(), V(), V(), V()}; QueryResult t = SystemView("", "main", "duckdb_types"); for (auto &row : t.rows) { Row rr = {row[4], row[5], row[3], VB(0), row[6].is_null ? Value::Integer(-1) : Value::Integer((int32_t)row[6].GetInt64()), VBool(false), VS("b"), VS("N"), VBool(false), VBool(true), VS(","), VB(0), VN(), VB(0), VB(0), VN(), VN(), VN(), VN(), VN(), VN(), VN(), VN(), VN(), VBool(false), VB(0), VB(-1), VB(0), VB(0), VN(), VN(), VN()}; r.rows.push_back(rr); } return r; }
    if (name == "pg_attribute") { r.names = {"attrelid", "attname", "atttypid", "attstattarget", "attlen", "attnum", "attndims", "attcacheoff", "atttypmod", "attbyval", "attstorage", "attalign", "attnotnull", "atthasdef", "atthasmissing", "attidentity", "attgenerated", "attisdropped", "attislocal", "attinhcount", "attcollation", "attcompression", "attacl", "attoptions", "attfdwoptions", "attmissingval"}; r.types = {BI(), V(), BI(), BI(), BI(), BI(), BI(), BI(), BI(), BO(), V(), V(), BO(), BO(), BO(), V(), V(), BO(), BO(), BI(), BI(), V(), V(), V(), V(), V()}; for (auto &sc : catalog.AllSchemas()) { if (sc.first == "system") continue; for (auto &t : sc.second->tables) for (size_t i = 0; i < t.second->columns.size(); i++) { auto &c = t.second->columns[i]; r.rows.push_back({VB(t.second->oid), VS(c.name), VB(TypeOid(c.type)), VB(0), VB(0), VB((int64_t)i + 1), VB(0), VB(-1), VB(-1), VBool(false), VN(), VN(), VBool(c.not_null), VBool(c.default_value != nullptr), VBool(false), VS(""), VS(""), VBool(false), VBool(true), VB(0), VB(0), VN(), VN(), VN(), VN(), VN()}); } } return r; }
    if (name == "pg_indexes") { r.names = {"schemaname", "tablename", "indexname", "tablespace", "indexdef"}; r.types = {V(), V(), V(), V(), V()}; for (auto &sc : catalog.AllSchemas()) for (auto &i : sc.second->indexes) r.rows.push_back({VS(sc.second->name), VS(i.second->table), VS(i.first), VN(), VS(i.second->sql)}); return r; }
    if (name == "pg_sequences") { r.names = {"schemaname", "sequencename", "sequenceowner", "data_type", "start_value", "min_value", "max_value", "increment_by", "cycle", "cache_size", "last_value"}; r.types = {V(), V(), V(), V(), BI(), BI(), BI(), BI(), BO(), BI(), BI()}; for (auto &sc : catalog.AllSchemas()) for (auto &s : sc.second->sequences) r.rows.push_back({VS(sc.second->name), VS(s.first), VS("duckdb"), VS("BIGINT"), VB(s.second->start), VB(s.second->min_value), VB(s.second->max_value), VB(s.second->increment), VBool(s.second->cycle), VB(1), s.second->used ? VB(s.second->current) : VN(TypeId::BIGINT)}); return r; }
    if (name == "pg_enum") { r.names = {"oid", "enumtypid", "enumsortorder", "enumlabel"}; r.types = {BI(), BI(), LogicalType(TypeId::FLOAT), V()}; int64_t oid = 1; for (auto &sc : catalog.AllSchemas()) for (auto &t : sc.second->types) if (t.second->type.id == TypeId::ENUM) for (size_t i = 0; i < t.second->type.info->names.size(); i++) r.rows.push_back({VB(oid++), VB(t.second->oid), Value::Float((float)i), VS(t.second->type.info->names[i])}); return r; }
    if (name == "pg_am" || name == "pg_attrdef" || name == "pg_constraint" || name == "pg_depend" || name == "pg_description" || name == "pg_index" || name == "pg_prepared_statements" || name == "pg_proc" || name == "pg_sequence" || name == "pg_tablespace") {
      if (name == "pg_proc") { r.names = {"oid", "proname", "pronamespace", "proowner", "prolang", "procost", "prorows", "provariadic", "prosupport", "prokind", "prosecdef", "proleakproof", "proisstrict", "proretset", "provolatile", "proparallel", "pronargs", "pronargdefaults", "prorettype", "proargtypes", "proallargtypes", "proargmodes", "proargnames", "proargdefaults", "protrftypes", "prosrc", "probin", "prosqlbody", "proconfig", "proacl"}; for (size_t i = 0; i < r.names.size(); i++) r.types.push_back(i == 1 ? V() : BI()); return r; }
      r.names = {"oid"}; r.types = {BI()};
      return r;
    }
  }
  if (schema == "information_schema") {
    if (name == "character_sets") { r.names = {"character_set_catalog", "character_set_schema", "character_set_name", "character_repertoire", "form_of_use", "default_collate_catalog", "default_collate_schema", "default_collate_name"}; for (int i = 0; i < 8; i++) r.types.push_back(V()); r.rows.push_back({VN(), VN(), VS("UTF8"), VS("UCS"), VS("UTF8"), VS(catalog.default_database), VS("main"), VS("ucs_basic")}); return r; }
    if (name == "key_column_usage" || name == "table_constraints" || name == "referential_constraints" || name == "check_constraints" || name == "constraint_column_usage" || name == "constraint_table_usage") {
      if (name == "table_constraints") { r.names = {"constraint_catalog", "constraint_schema", "constraint_name", "table_catalog", "table_schema", "table_name", "constraint_type", "is_deferrable", "initially_deferred", "enforced", "nulls_distinct"}; for (int i = 0; i < 11; i++) r.types.push_back(V()); return r; }
      r.names = {"constraint_catalog", "constraint_schema", "constraint_name"}; r.types = {V(), V(), V()};
      return r;
    }
  }
  throw CatalogException("Table with name " + name + " does not exist!");
}

// ---------------------------------------------------------------- table functions
QueryResult Executor::QueryFromTableFunction(const std::string &fname, const std::vector<ExprPtr> &args_in, const std::vector<std::pair<std::string, ExprPtr>> &named_in, BindContext &context) {
  QueryResult r;
  std::vector<Value> args;
  for (auto &a : args_in) {
    BExpr b = Bind(*a, context);
    Row dummy;
    if (context.parent && context.parent->current_row) dummy = *context.parent->current_row;
    Value v = Eval(*b, dummy);
    args.push_back(NormalizeLiteral(v));
  }
  std::map<std::string, Value> named;
  for (auto &n : named_in) {
    BExpr b = Bind(*n.second, context);
    Row dummy;
    named[ToLower(n.first)] = NormalizeLiteral(Eval(*b, dummy));
  }
  if (fname == "range" || fname == "generate_series") {
    bool inclusive = fname == "generate_series";
    if (args.empty() || args.size() > 3) throw BinderException("No function matches the given name and argument types '" + fname + "()'. You might need to add explicit type casts.\n\tCandidate functions:\n\t" + fname + "(BIGINT) -> BIGINT\n\t" + fname + "(BIGINT, BIGINT) -> BIGINT\n\t" + fname + "(BIGINT, BIGINT, BIGINT) -> BIGINT\n\t" + fname + "(TIMESTAMP, TIMESTAMP, INTERVAL) -> TIMESTAMP\n\t" + fname + "(TIMESTAMP WITH TIME ZONE, TIMESTAMP WITH TIME ZONE, INTERVAL) -> TIMESTAMP WITH TIME ZONE\n");
    if (args.size() == 3 && (args[0].type.IsTimestamp() || args[0].type.id == TypeId::DATE || args[0].type.id == TypeId::VARCHAR)) {
      LogicalType tt = args[0].type.id == TypeId::TIMESTAMP_TZ ? LogicalType(TypeId::TIMESTAMP_TZ) : LogicalType(TypeId::TIMESTAMP);
      r.names = {fname}; r.types = {tt};
      if (args[0].is_null || args[1].is_null || args[2].is_null) return r;
      Value cur = CastValue(args[0], tt, false), end = CastValue(args[1], tt, false);
      Value step = CastValue(args[2], LogicalType(TypeId::INTERVAL), false);
      const Interval &iv = step.interval;
      if (iv.months == 0 && iv.days == 0 && iv.micros == 0) throw InvalidInputException("interval cannot be 0!");
      bool positive = iv.months > 0 || (iv.months == 0 && (iv.days > 0 || (iv.days == 0 && iv.micros > 0)));
      for (int guard = 0; guard < 100000000; guard++) {
        int c = Value::Compare(cur, end);
        if (positive ? (inclusive ? c > 0 : c >= 0) : (inclusive ? c < 0 : c <= 0)) break;
        r.rows.push_back({cur});
        cur = ComputeArith("+", cur, step, tt);
      }
      return r;
    }
    r.names = {fname}; r.types = {LogicalType(TypeId::BIGINT)};
    for (auto &a : args) if (a.is_null) return r;
    int64_t start = 0, end, step = 1;
    if (args.size() == 1) end = CastValue(args[0], LogicalType(TypeId::BIGINT), false).GetInt64();
    else { start = CastValue(args[0], LogicalType(TypeId::BIGINT), false).GetInt64(); end = CastValue(args[1], LogicalType(TypeId::BIGINT), false).GetInt64(); if (args.size() == 3) step = CastValue(args[2], LogicalType(TypeId::BIGINT), false).GetInt64(); }
    if (step == 0) throw InvalidInputException("interval cannot be 0!");
    if (step > 0) for (int64_t i = start; inclusive ? i <= end : i < end; i += step) r.rows.push_back({Value::BigInt(i)});
    else for (int64_t i = start; inclusive ? i >= end : i > end; i += step) r.rows.push_back({Value::BigInt(i)});
    return r;
  }
  if (fname == "unnest") {
    if (args.size() != 1) throw BinderException("unnest takes exactly one argument");
    Value v = args[0];
    if (v.type.id == TypeId::LIST || v.type.id == TypeId::ARRAY) {
      r.names = {"unnest"}; r.types = {v.type.child()};
      if (!v.is_null) for (auto &x : *v.children) r.rows.push_back({x});
      return r;
    }
    if (v.type.id == TypeId::STRUCT) {
      r.names = v.type.info->names; r.types = v.type.info->children;
      if (!v.is_null) r.rows.push_back(*v.children);
      return r;
    }
    r.names = {"unnest"}; r.types = {LogicalType(TypeId::INTEGER)};
    return r;
  }
  if (fname == "read_csv" || fname == "read_csv_auto" || fname == "read_text" || fname == "read_blob") {
    if (fname == "read_text" || fname == "read_blob") {
      r.names = {"filename", "content", "size", "last_modified"};
      r.types = {V(), fname == "read_text" ? V() : LogicalType(TypeId::BLOB), BI(), LogicalType(TypeId::TIMESTAMP)};
      std::vector<std::string> files;
      glob_t g; memset(&g, 0, sizeof(g));
      if (glob(args[0].str.c_str(), 0, nullptr, &g) == 0) for (size_t i = 0; i < g.gl_pathc; i++) files.push_back(g.gl_pathv[i]);
      globfree(&g);
      if (files.empty()) throw IOException("No files found that match the pattern \"" + args[0].str + "\"");
      for (auto &f : files) {
        FILE *fp = fopen(f.c_str(), "rb");
        if (!fp) continue;
        std::string s; char buf[4096]; size_t n; while ((n = fread(buf, 1, sizeof(buf), fp)) > 0) s.append(buf, n); fclose(fp);
        struct stat st; stat(f.c_str(), &st);
        r.rows.push_back({VS(f), fname == "read_text" ? VS(s) : Value::Blob(s), VB((int64_t)s.size()), Value::Timestamp((int64_t)st.st_mtime * 1000000)});
      }
      return r;
    }
    if (args.empty()) throw BinderException("read_csv requires a file name");
    std::string path = args[0].type.id == TypeId::LIST ? (args[0].children->empty() ? "" : (*args[0].children)[0].str) : args[0].str;
    return ReadCSV(path, named);
  }
  if (fname == "read_parquet" || fname == "parquet_scan") {
    std::string path = args.empty() ? "" : args[0].ToString();
    FILE *f = fopen(path.c_str(), "rb");
    if (!f) throw IOException("No files found that match the pattern \"" + path + "\"");
    fclose(f);
    throw NotImplementedException("Parquet reading is not supported");
  }
  if (fname == "read_json" || fname == "read_json_auto" || fname == "read_ndjson" || fname == "read_ndjson_auto" || fname == "read_json_objects") {
    throw CatalogException("Table Function with name \"" + fname + "\" is not in the catalog, but it exists in the json extension.\n\nPlease try installing and loading the json extension by running:\nINSTALL json;\nLOAD json;\n\nAlternatively, consider enabling auto-install and auto-load by running:\nSET autoinstall_known_extensions=1;\nSET autoload_known_extensions=1;");
  }
  if (fname == "glob") {
    r.names = {"file"}; r.types = {V()};
    glob_t g; memset(&g, 0, sizeof(g));
    std::string pattern = args.empty() ? "*" : args[0].str;
    if (glob(pattern.c_str(), 0, nullptr, &g) == 0) for (size_t i = 0; i < g.gl_pathc; i++) r.rows.push_back({VS(g.gl_pathv[i])});
    globfree(&g);
    return r;
  }
  if (fname == "repeat") {
    r.names = {"repeat"}; r.types = {args[0].type};
    for (int64_t i = 0; i < args[1].GetInt64(); i++) r.rows.push_back({args[0]});
    return r;
  }
  if (fname == "repeat_row") {
    int64_t n = named.count("num_rows") ? named["num_rows"].GetInt64() : 1;
    for (size_t i = 0; i < args.size(); i++) { r.names.push_back("column" + std::to_string(i)); r.types.push_back(args[i].type); }
    for (int64_t i = 0; i < n; i++) r.rows.push_back(args);
    return r;
  }
  if (fname == "pragma_table_info") {
    PragmaStatement p; p.name = "table_info"; p.params.push_back(Expr::Constant(args[0]));
    return ExecutePragma(p);
  }
  if (fname == "pragma_version") { PragmaStatement p; p.name = "version"; return ExecutePragma(p); }
  if (fname == "pragma_platform") { PragmaStatement p; p.name = "platform"; return ExecutePragma(p); }
  if (fname == "pragma_database_size") { PragmaStatement p; p.name = "database_size"; return ExecutePragma(p); }
  if (fname == "pragma_storage_info" || fname == "pragma_metadata_info") { PragmaStatement p; p.name = "storage_info"; return ExecutePragma(p); }
  if (fname == "pragma_collations") { PragmaStatement p; p.name = "collations"; return ExecutePragma(p); }
  if (fname == "pragma_show" || fname == "pragma_show_tables") { ShowStatement s; s.kind = "TABLES"; return ExecuteShow(s); }
  if (fname == "pragma_user_agent") { PragmaStatement p; p.name = "user_agent"; return ExecutePragma(p); }
  if (fname == "current_schemas") { r.names = {"current_schemas"}; r.types = {V()}; return r; }
  if (fname == "duckdb_tables" || fname == "duckdb_views" || fname == "duckdb_columns" || fname == "duckdb_schemas" || fname == "duckdb_databases" || fname == "duckdb_sequences" || fname == "duckdb_indexes" || fname == "duckdb_constraints" || fname == "duckdb_types" || fname == "duckdb_functions" || fname == "duckdb_settings" || fname == "duckdb_extensions" || fname == "duckdb_keywords" || fname == "duckdb_dependencies" || fname == "duckdb_logs" || fname == "duckdb_memory" || fname == "duckdb_optimizers" || fname == "duckdb_secrets" || fname == "duckdb_temporary_files" || fname == "duckdb_variables" || fname == "duckdb_prepared_statements" || fname == "duckdb_log_contexts" || fname == "duckdb_external_file_cache" || fname == "duckdb_secret_types" || fname == "duckdb_which_secret" || fname == "pragma_database_list" || fname == "sqlite_master") {
    return SystemView("", "main", fname);
  }
  if (fname == "test_all_types") {
    throw NotImplementedException("test_all_types is not supported");
  }
  if (fname == "checkpoint" || fname == "force_checkpoint") { r.names = {"Success"}; r.types = {BO()}; return r; }
  if (fname == "summary" || fname == "summarize") { throw BinderException("summarize is a statement"); }
  if (fname == "json_each" || fname == "json_tree") throw CatalogException("Table Function with name \"" + fname + "\" is not in the catalog, but it exists in the json extension.\n\nPlease try installing and loading the json extension by running:\nINSTALL json;\nLOAD json;\n\nAlternatively, consider enabling auto-install and auto-load by running:\nSET autoinstall_known_extensions=1;\nSET autoload_known_extensions=1;");
  if (fname == "query" || fname == "query_table") {
    if (fname == "query") { auto stmt = Parser::ParseSelectFromString(args[0].str); return ExecuteSelect(*stmt); }
    std::string tn = args[0].type.id == TypeId::LIST ? "" : args[0].str;
    if (args[0].type.id == TypeId::LIST) { std::string sql; for (auto &t : *args[0].children) { if (!sql.empty()) sql += " UNION ALL "; sql += "SELECT * FROM " + QuoteIdentifierIfNeeded(t.str); } auto stmt = Parser::ParseSelectFromString(sql); return ExecuteSelect(*stmt); }
    auto stmt = Parser::ParseSelectFromString("SELECT * FROM " + QuoteIdentifierIfNeeded(tn));
    return ExecuteSelect(*stmt);
  }
  // table macro?
  auto macro = catalog.FindMacro("", "", fname);
  if (macro && macro->is_table) return ExecuteMacroTable(*macro, args_in, context);
  if (macro) throw BinderException("Scalar macro " + fname + " cannot be used as a table function");
  // not found
  std::vector<std::string> cands = {"range", "generate_series", "unnest", "read_csv", "read_csv_auto", "read_parquet", "glob", "repeat", "duckdb_tables", "duckdb_columns", "duckdb_views", "duckdb_functions", "duckdb_settings", "duckdb_types", "duckdb_databases", "duckdb_schemas", "duckdb_constraints", "duckdb_indexes", "duckdb_sequences", "duckdb_extensions", "duckdb_keywords", "duckdb_dependencies", "pragma_table_info", "pragma_version", "pragma_database_size", "pragma_storage_info", "read_text", "read_blob", "query", "query_table", "sniff_csv", "checkpoint", "parquet_scan", "parquet_metadata", "parquet_schema", "read_json", "read_json_auto", "summary", "test_all_types", "duckdb_memory", "duckdb_optimizers", "duckdb_secrets", "duckdb_variables", "duckdb_logs", "duckdb_temporary_files", "arrow_scan", "repeat_row", "which_secret", "icu_calendar_names", "pragma_collations", "pragma_metadata_info", "pragma_platform", "pragma_user_agent", "pragma_show", "pragma_database_list", "sql_auto_complete", "seq_scan", "index_scan", "duckdb_log_contexts", "duckdb_external_file_cache", "duckdb_prepared_statements", "duckdb_secret_types", "duckdb_which_secret", "duckdb_table_sample", "generate_subscripts"};
  for (auto &sc : catalog.AllSchemas()) for (auto &m : sc.second->macros) if (m.second->is_table) cands.push_back(m.first);
  auto top = TopSimilar(fname, cands, 1, 0.5);
  if (Functions().FindScalar(fname) || Functions().FindAgg(fname)) {
    throw CatalogException("Table Function with name " + fname + " does not exist!" + (top.empty() ? "" : "\nDid you mean \"" + top[0] + "\"?"));
  }
  throw CatalogException("Table Function with name " + fname + " does not exist!" + (top.empty() ? "" : "\nDid you mean \"" + top[0] + "\"?"));
}

QueryResult Executor::ExecuteMacroTable(MacroEntry &m, const std::vector<ExprPtr> &args, BindContext &context) {
  size_t positional = 0;
  for (auto &c : args) if (c->alias.empty()) positional++;
  const MacroEntry::Overload *ov = nullptr;
  for (auto &o : m.overloads) if (o.params.size() == positional) { ov = &o; break; }
  if (!ov) throw BinderException("Macro function '" + m.name + "' requires " + std::to_string(m.overloads.empty() ? 0 : m.overloads[0].params.size()) + " positional arguments, but " + std::to_string(positional) + " positional arguments were provided.");
  auto stmt = Parser::ParseSelectFromString(ov->query);
  // substitute parameters: wrap as CTE-like binding by replacing column refs
  std::map<std::string, const Expr *> subs;
  size_t pi = 0;
  for (auto &c : args) { if (c->alias.empty()) subs[ov->params[pi++]] = c.get(); else subs[c->alias] = c.get(); }
  std::map<std::string, ExprPtr> defaults;
  for (auto &d : ov->defaults) if (!subs.count(d.first)) { defaults[d.first] = Parser::ParseExpressionFromString(d.second); subs[d.first] = defaults[d.first].get(); }
  std::function<void(ExprPtr &)> replace = [&](ExprPtr &x) {
    if (!x) return;
    if (x->kind == ExprKind::COLUMN_REF && x->names.size() == 1 && subs.count(ToLower(x->names[0]))) { std::string alias = x->alias; x = subs[ToLower(x->names[0])]->Copy(); if (x->alias.empty()) x->alias = alias; return; }
    for (auto &c : x->children) replace(c);
    if (x->filter) replace(x->filter);
    for (auto &cc : x->case_checks) { replace(cc.when); replace(cc.then); }
    if (x->else_expr) replace(x->else_expr);
    for (auto &o : x->order_bys) replace(o.expr);
  };
  std::function<void(QueryNode &)> walk;
  std::function<void(TableRef &)> walk_ref = [&](TableRef &tr) {
    if (tr.condition) replace(tr.condition);
    for (auto &a : tr.function_args) replace(a);
    if (tr.left) walk_ref(*tr.left);
    if (tr.right) walk_ref(*tr.right);
    if (tr.subquery) walk(*tr.subquery->node);
    for (auto &row : tr.values) for (auto &v : row) replace(v);
  };
  walk = [&](QueryNode &n) {
    for (auto &e : n.select_list) replace(e);
    if (n.where) replace(n.where);
    if (n.having) replace(n.having);
    if (n.qualify) replace(n.qualify);
    for (auto &g : n.groups) replace(g);
    for (auto &o : n.orders) replace(o.expr);
    if (n.limit) replace(n.limit);
    if (n.offset) replace(n.offset);
    if (n.from) walk_ref(*n.from);
    if (n.left) walk(*n.left);
    if (n.right) walk(*n.right);
    for (auto &c : n.ctes) walk(*c->query->node);
  };
  walk(*stmt->node);
  return ExecuteNode(*stmt->node, &context);
}

// ---------------------------------------------------------------- PIVOT
void ExecutePivot(Executor &ex, const TableRef &ref, BindContext &context, std::vector<Row> &rows) {
  // Execute source
  BindContext sctx;
  sctx.parent = context.parent;
  std::vector<Row> src_rows;
  ex.BindTableRef(*ref.source, sctx, src_rows);
  std::vector<std::string> names;
  std::vector<LogicalType> types;
  for (auto &b : sctx.bindings) for (size_t i = 0; i < b.names.size(); i++) { names.push_back(b.names[i]); types.push_back(b.types[i]); }
  if (ref.is_unpivot) {
    auto &pc = ref.pivots[0];
    std::vector<std::vector<int>> groups;
    for (auto &g : pc.unpivot_cols) { std::vector<int> idxs; for (auto &cn : g) { int found = -1; for (size_t i = 0; i < names.size(); i++) if (IEquals(names[i], cn)) found = (int)i; if (found < 0) throw BinderException("Column \"" + cn + "\" not found in UNPIVOT"); idxs.push_back(found); } groups.push_back(idxs); }
    if (!pc.pivot_exprs.empty() && pc.pivot_exprs[0]->kind == ExprKind::STAR) {
      std::vector<ExprPtr> expanded;
      ex.ExpandStar(*pc.pivot_exprs[0], sctx, expanded);
      for (auto &e : expanded) { for (size_t i = 0; i < names.size(); i++) if (IEquals(names[i], e->names.back())) groups.push_back({(int)i}); }
    }
    std::set<int> unpivoted;
    for (auto &g : groups) for (int i : g) unpivoted.insert(i);
    std::string name_col = ref.unpivot_names.empty() ? "name" : ref.unpivot_names[0];
    std::vector<std::string> value_cols;
    for (size_t i = 1; i < ref.unpivot_names.size(); i++) value_cols.push_back(ref.unpivot_names[i]);
    if (value_cols.empty()) value_cols.push_back("value");
    Binding b;
    b.alias = ref.alias.empty() ? "unpivot" : ref.alias;
    for (size_t i = 0; i < names.size(); i++) if (!unpivoted.count((int)i)) { b.names.push_back(names[i]); b.types.push_back(types[i]); }
    b.names.push_back(name_col); b.types.push_back(LogicalType(TypeId::VARCHAR));
    std::vector<LogicalType> vtypes(value_cols.size(), LogicalType(TypeId::SQLNULL));
    for (auto &g : groups) for (size_t k = 0; k < g.size() && k < vtypes.size(); k++) vtypes[k] = MaxLogicalType(vtypes[k], types[g[k]]);
    for (size_t k = 0; k < value_cols.size(); k++) { b.names.push_back(value_cols[k]); b.types.push_back(vtypes[k].id == TypeId::SQLNULL ? LogicalType(TypeId::INTEGER) : vtypes[k]); }
    b.offset = context.TotalColumns();
    for (auto &r : src_rows) {
      for (size_t gi = 0; gi < groups.size(); gi++) {
        Row out;
        for (size_t i = 0; i < names.size(); i++) if (!unpivoted.count((int)i)) out.push_back(r[i]);
        std::string label = gi < pc.entry_aliases.size() && !pc.entry_aliases[gi].empty() ? pc.entry_aliases[gi] : (groups[gi].size() == 1 ? names[groups[gi][0]] : [&]() { std::string s; for (size_t k = 0; k < groups[gi].size(); k++) { if (k) s += "_"; s += names[groups[gi][k]]; } return s; }());
        out.push_back(Value::Varchar(label));
        bool all_null = true;
        for (size_t k = 0; k < value_cols.size(); k++) { Value v = k < groups[gi].size() ? r[groups[gi][k]] : Value(); if (!v.is_null) all_null = false; if (v.type != b.types[b.names.size() - value_cols.size() + k]) v = v.is_null ? Value::Null(b.types[b.names.size() - value_cols.size() + k]) : CastValue(v, b.types[b.names.size() - value_cols.size() + k], false); out.push_back(v); }
        if (all_null && !ref.include_nulls) continue;
        rows.push_back(out);
      }
    }
    context.bindings.push_back(b);
    return;
  }
  // PIVOT: build query: SELECT groups..., agg FILTER (WHERE pivot_col = v) AS "v" ... GROUP BY groups
  if (ref.pivots.empty()) throw BinderException("PIVOT requires an ON clause");
  // group columns: explicit GROUP BY or all other columns not in pivot/aggregates
  std::vector<std::string> pivot_cols;
  for (auto &pc : ref.pivots) for (auto &pe : pc.pivot_exprs) if (pe->kind == ExprKind::COLUMN_REF) pivot_cols.push_back(pe->names.back());
  std::set<std::string> agg_cols;
  std::function<void(const Expr &)> collect = [&](const Expr &e) { if (e.kind == ExprKind::COLUMN_REF) agg_cols.insert(ToLower(e.names.back())); for (auto &c : e.children) if (c) collect(*c); };
  for (auto &a : ref.aggregates) collect(*a);
  std::vector<std::string> group_cols;
  if (!ref.groups.empty()) for (auto &g : ref.groups) group_cols.push_back(g->ToString());
  else for (auto &n : names) { bool is_pivot = false; for (auto &p : pivot_cols) if (IEquals(p, n)) is_pivot = true; if (!is_pivot && !agg_cols.count(ToLower(n))) group_cols.push_back(QuoteIdentifierIfNeeded(n)); }
  // distinct values per pivot column
  std::vector<std::vector<std::vector<Value>>> all_values;  // per pivot column: list of value tuples
  for (auto &pc : ref.pivots) {
    std::vector<std::vector<Value>> vals;
    if (!pc.entries.empty()) {
      for (auto &e : pc.entries) { if (e->kind == ExprKind::FUNCTION && e->op == "row") { std::vector<Value> tup; for (auto &c : e->children) tup.push_back(EvaluateConstantExpression(ex, *c)); vals.push_back(tup); } else vals.push_back({EvaluateConstantExpression(ex, *e)}); }
    } else if (pc.subquery) {
      QueryResult sq = ex.ExecuteSelect(*pc.subquery);
      for (auto &r : sq.rows) vals.push_back(r);
    } else {
      std::vector<BExpr> bes;
      for (auto &pe : pc.pivot_exprs) bes.push_back(ex.Bind(*pe, sctx));
      std::vector<std::vector<Value>> seen;
      for (auto &r : src_rows) { std::vector<Value> tup; for (auto &be : bes) tup.push_back(ex.Eval(*be, r)); bool dup = false; for (auto &s : seen) { bool same = true; for (size_t k = 0; k < tup.size(); k++) if (!ValuesEqual(s[k], tup[k])) { same = false; break; } if (same) { dup = true; break; } } if (!dup) seen.push_back(tup); }
      std::stable_sort(seen.begin(), seen.end(), [](const std::vector<Value> &a, const std::vector<Value> &b) { for (size_t k = 0; k < a.size(); k++) { int c = Value::Compare(a[k], b[k]); if (c) return c < 0; } return false; });
      vals = seen;
    }
    all_values.push_back(vals);
  }
  // cartesian product of pivot values
  std::vector<std::vector<std::vector<Value>>> combos = {{}};
  for (auto &vals : all_values) { std::vector<std::vector<std::vector<Value>>> next; for (auto &c : combos) for (auto &v : vals) { auto nc = c; nc.push_back(v); next.push_back(nc); } combos = next; }
  std::string sql = "SELECT ";
  bool first = true;
  for (auto &g : group_cols) { if (!first) sql += ", "; sql += g; first = false; }
  std::vector<ExprPtr> aggs;
  if (ref.aggregates.empty()) { aggs.push_back(Expr::Function("count_star", {})); }
  else for (auto &a : ref.aggregates) aggs.push_back(a->Copy());
  for (auto &combo : combos) {
    std::string label, cond;
    for (size_t pi = 0; pi < combo.size(); pi++) {
      auto &pc = ref.pivots[pi];
      for (size_t k = 0; k < combo[pi].size(); k++) {
        if (!label.empty()) label += "_";
        // alias
        std::string alias;
        if (!pc.entries.empty()) { for (size_t ei = 0; ei < pc.entries.size(); ei++) { Value ev = pc.entries[ei]->kind == ExprKind::FUNCTION ? Value() : EvaluateConstantExpression(ex, *pc.entries[ei]); if (ValuesEqual(ev, combo[pi][k]) && !pc.entry_aliases[ei].empty()) alias = pc.entry_aliases[ei]; } }
        label += alias.empty() ? combo[pi][k].ToString() : alias;
        if (!cond.empty()) cond += " AND ";
        cond += "(" + pc.pivot_exprs[k]->ToString() + " = " + combo[pi][k].ToSQLString() + ")";
      }
    }
    for (auto &a : aggs) {
      if (!first) sql += ", ";
      first = false;
      std::string aname = a->ToString();
      std::string col_label = label;
      if (aggs.size() > 1 || !a->alias.empty()) col_label = label + "_" + (a->alias.empty() ? aname : a->alias);
      sql += aname + " FILTER (WHERE " + cond + ") AS " + QuoteIdentifierIfNeeded(col_label);
    }
  }
  if (combos.empty() && aggs.size() > 0 && group_cols.empty()) sql += "1";
  sql += " FROM (" + std::string("SELECT * FROM ") + "__pivot_source__)";
  if (!group_cols.empty()) sql += " GROUP BY " + JoinStrings(group_cols, ", ") + " ORDER BY " + JoinStrings(group_cols, ", ");
  auto stmt = Parser::ParseSelectFromString(sql);
  // register source as CTE
  BindContext cte_ctx;
  cte_ctx.parent = context.parent;
  auto cb = std::make_shared<CTEBinding>();
  auto mat = std::make_shared<QueryResult>();
  mat->names = names; mat->types = types; mat->rows = src_rows;
  cb->materialized = mat;
  cte_ctx.ctes["__pivot_source__"] = cb;
  QueryResult r = ex.ExecuteNode(*stmt->node, &cte_ctx);
  Binding b;
  b.alias = ref.alias.empty() ? "pivot" : ref.alias;
  b.names = r.names; b.types = r.types; b.offset = context.TotalColumns();
  context.bindings.push_back(b);
  rows = r.rows;
}
EOF
echo done"}

