    if (name == "pg_am" || name == "pg_attrdef" || name == "pg_constraint" || name == "pg_depend" || name == "pg_description" || name == "pg_index" || name == "pg_prepared_statements" || name == "pg_proc" || name == "pg_sequence" || name == "pg_tablespace") {
      if (name == "pg_proc") { r.names = {"oid", "proname", "pronamespace", "proowner", "prolang", "procost", "prorows", "provariadic", "prosupport", "prokind", "prosecdef", "proleakproof", "proisstrict", "proretset", "provolatile", "proparallel", "pronargs", "pronargdefaults", "prorettype", "proargtypes", "proallargtypes", "proargmodes", "proargnames", "proargdefaults", "protrftypes", "prosrc", "probin", "prosqlbody", "proconfig", "proacl"}; for (size_t i = 0; i < r.names.size(); i++) r.types.push_back(i == 1 ? V() : BI()); return r; }
