// ---------------------------------------------------------------- table functions
QueryResult Executor::QueryFromTableFunction(const std::string &fname, const std::vector<ExprPtr> &args_in, const std::vector<std::pair<std::string, ExprPtr>> &named_in, BindContext &context) {
  QueryResult r;
  std::vector<Value> args;
  for (auto &a : args_in) {
    BExpr b = Bind(*a, context);
    Row dummy;
    if (context.parent && context.parent->current_row) dummy = *context.parent->current_row;
    Value v = Eval(*b, dummy);
    args.push_back(NormalizeLiteral(v));
  }
  std::map<std::string, Value> named;
  for (auto &n : named_in) {
    BExpr b = Bind(*n.second, context);
    Row dummy;
    named[ToLower(n.first)] = NormalizeLiteral(Eval(*b, dummy));
  }
  if (fname == "range" || fname == "generate_series") {
    bool inclusive = fname == "generate_series";
    if (args.empty() || args.size() > 3) throw BinderException("No function matches the given name and argument types '" + fname + "()'. You might need to add explicit type casts.\n\tCandidate functions:\n\t" + fname + "(BIGINT) -> BIGINT\n\t" + fname + "(BIGINT, BIGINT) -> BIGINT\n\t" + fname + "(BIGINT, BIGINT, BIGINT) -> BIGINT\n\t" + fname + "(TIMESTAMP, TIMESTAMP, INTERVAL) -> TIMESTAMP\n\t" + fname + "(TIMESTAMP WITH TIME ZONE, TIMESTAMP WITH TIME ZONE, INTERVAL) -> TIMESTAMP WITH TIME ZONE\n");
    if (args.size() == 3 && (args[0].type.IsTimestamp() || args[0].type.id == TypeId::DATE || args[0].type.id == TypeId::VARCHAR)) {
      LogicalType tt = args[0].type.id == TypeId::TIMESTAMP_TZ ? LogicalType(TypeId::TIMESTAMP_TZ) : LogicalType(TypeId::TIMESTAMP);
      r.names = {fname}; r.types = {tt};
      if (args[0].is_null || args[1].is_null || args[2].is_null) return r;
      Value cur = CastValue(args[0], tt, false), end = CastValue(args[1], tt, false);
      Value step = CastValue(args[2], LogicalType(TypeId::INTERVAL), false);
      const Interval &iv = step.interval;
      if (iv.months == 0 && iv.days == 0 && iv.micros == 0) throw InvalidInputException("interval cannot be 0!");
      bool positive = iv.months > 0 || (iv.months == 0 && (iv.days > 0 || (iv.days == 0 && iv.micros > 0)));
      for (int guard = 0; guard < 100000000; guard++) {
        int c = Value::Compare(cur, end);
        if (positive ? (inclusive ? c > 0 : c >= 0) : (inclusive ? c < 0 : c <= 0)) break;
        r.rows.push_back({cur});
        cur = ComputeArith("+", cur, step, tt);
      }
      return r;
    }
    r.names = {fname}; r.types = {LogicalType(TypeId::BIGINT)};
    for (auto &a : args) if (a.is_null) return r;
    int64_t start = 0, end, step = 1;
    if (args.size() == 1) end = CastValue(args[0], LogicalType(TypeId::BIGINT), false).GetInt64();
    else { start = CastValue(args[0], LogicalType(TypeId::BIGINT), false).GetInt64(); end = CastValue(args[1], LogicalType(TypeId::BIGINT), false).GetInt64(); if (args.size() == 3) step = CastValue(args[2], LogicalType(TypeId::BIGINT), false).GetInt64(); }
    if (step == 0) throw InvalidInputException("interval cannot be 0!");
    if (step > 0) for (int64_t i = start; inclusive ? i <= end : i < end; i += step) r.rows.push_back({Value::BigInt(i)});
    else for (int64_t i = start; inclusive ? i >= end : i > end; i += step) r.rows.push_back({Value::BigInt(i)});
    return r;
  }
  if (fname == "unnest") {
    if (args.size() != 1) throw BinderException("unnest takes exactly one argument");
    Value v = args[0];
    if (v.type.id == TypeId::LIST || v.type.id == TypeId::ARRAY) {
      r.names = {"unnest"}; r.types = {v.type.child()};
      if (!v.is_null) for (auto &x : *v.children) r.rows.push_back({x});
      return r;
    }
    if (v.type.id == TypeId::STRUCT) {
      r.names = v.type.info->names; r.types = v.type.info->children;
      if (!v.is_null) r.rows.push_back(*v.children);
      return r;
    }
    r.names = {"unnest"}; r.types = {LogicalType(TypeId::INTEGER)};
    return r;
  }
  if (fname == "read_csv" || fname == "read_csv_auto" || fname == "read_text" || fname == "read_blob") {
    if (fname == "read_text" || fname == "read_blob") {
      r.names = {"filename", "content", "size", "last_modified"};
      r.types = {V(), fname == "read_text" ? V() : LogicalType(TypeId::BLOB), BI(), LogicalType(TypeId::TIMESTAMP)};
      std::vector<std::string> files;
      glob_t g; memset(&g, 0, sizeof(g));
      if (glob(args[0].str.c_str(), 0, nullptr, &g) == 0) for (size_t i = 0; i < g.gl_pathc; i++) files.push_back(g.gl_pathv[i]);
      globfree(&g);
      if (files.empty()) throw IOException("No files found that match the pattern \"" + args[0].str + "\"");
      for (auto &f : files) {
        FILE *fp = fopen(f.c_str(), "rb");
        if (!fp) continue;
        std::string s; char buf[4096]; size_t n; while ((n = fread(buf, 1, sizeof(buf), fp)) > 0) s.append(buf, n); fclose(fp);
        struct stat st; stat(f.c_str(), &st);
        r.rows.push_back({VS(f), fname == "read_text" ? VS(s) : Value::Blob(s), VB((int64_t)s.size()), Value::Timestamp((int64_t)st.st_mtime * 1000000)});
      }
      return r;
    }
    if (args.empty()) throw BinderException("read_csv requires a file name");
    std::string path = args[0].type.id == TypeId::LIST ? (args[0].children->empty() ? "" : (*args[0].children)[0].str) : args[0].str;
    return ReadCSV(path, named);
  }
  if (fname == "read_parquet" || fname == "parquet_scan") {
    std::string path = args.empty() ? "" : args[0].ToString();
    FILE *f = fopen(path.c_str(), "rb");
    if (!f) throw IOException("No files found that match the pattern \"" + path + "\"");
    fclose(f);
    throw NotImplementedException("Parquet reading is not supported");
  }
  if (fname == "read_json" || fname == "read_json_auto" || fname == "read_ndjson" || fname == "read_ndjson_auto" || fname == "read_json_objects") {
    throw CatalogException("Table Function with name \"" + fname + "\" is not in the catalog, but it exists in the json extension.\n\nPlease try installing and loading the json extension by running:\nINSTALL json;\nLOAD json;\n\nAlternatively, consider enabling auto-install and auto-load by running:\nSET autoinstall_known_extensions=1;\nSET autoload_known_extensions=1;");
  }
  if (fname == "glob") {
    r.names = {"file"}; r.types = {V()};
    glob_t g; memset(&g, 0, sizeof(g));
    std::string pattern = args.empty() ? "*" : args[0].str;
    if (glob(pattern.c_str(), 0, nullptr, &g) == 0) for (size_t i = 0; i < g.gl_pathc; i++) r.rows.push_back({VS(g.gl_pathv[i])});
    globfree(&g);
    return r;
  }
  if (fname == "repeat") {
    r.names = {"repeat"}; r.types = {args[0].type};
    for (int64_t i = 0; i < args[1].GetInt64(); i++) r.rows.push_back({args[0]});
    return r;
  }
  if (fname == "repeat_row") {
    int64_t n = named.count("num_rows") ? named["num_rows"].GetInt64() : 1;
    for (size_t i = 0; i < args.size(); i++) { r.names.push_back("column" + std::to_string(i)); r.types.push_back(args[i].type); }
    for (int64_t i = 0; i < n; i++) r.rows.push_back(args);
    return r;
  }
  if (fname == "pragma_table_info") {
    PragmaStatement p; p.name = "table_info"; p.params.push_back(Expr::Constant(args[0]));
    return ExecutePragma(p);
  }
  if (fname == "pragma_version") { PragmaStatement p; p.name = "version"; return ExecutePragma(p); }
  if (fname == "pragma_platform") { PragmaStatement p; p.name = "platform"; return ExecutePragma(p); }
  if (fname == "pragma_database_size") { PragmaStatement p; p.name = "database_size"; return ExecutePragma(p); }
  if (fname == "pragma_storage_info" || fname == "pragma_metadata_info") { PragmaStatement p; p.name = "storage_info"; return ExecutePragma(p); }
  if (fname == "pragma_collations") { PragmaStatement p; p.name = "collations"; return ExecutePragma(p); }
  if (fname == "pragma_show" || fname == "pragma_show_tables") { ShowStatement s; s.kind = "TABLES"; return ExecuteShow(s); }
  if (fname == "pragma_user_agent") { PragmaStatement p; p.name = "user_agent"; return ExecutePragma(p); }
  if (fname == "current_schemas") { r.names = {"current_schemas"}; r.types = {V()}; return r; }
  if (fname == "duckdb_tables" || fname == "duckdb_views" || fname == "duckdb_columns" || fname == "duckdb_schemas" || fname == "duckdb_databases" || fname == "duckdb_sequences" || fname == "duckdb_indexes" || fname == "duckdb_constraints" || fname == "duckdb_types" || fname == "duckdb_functions" || fname == "duckdb_settings" || fname == "duckdb_extensions" || fname == "duckdb_keywords" || fname == "duckdb_dependencies" || fname == "duckdb_logs" || fname == "duckdb_memory" || fname == "duckdb_optimizers" || fname == "duckdb_secrets" || fname == "duckdb_temporary_files" || fname == "duckdb_variables" || fname == "duckdb_prepared_statements" || fname == "duckdb_log_contexts" || fname == "duckdb_external_file_cache" || fname == "duckdb_secret_types" || fname == "duckdb_which_secret" || fname == "pragma_database_list" || fname == "sqlite_master") {
    return SystemView("", "main", fname);
  }
  if (fname == "test_all_types") {
    throw NotImplementedException("test_all_types is not supported");
  }
  if (fname == "checkpoint" || fname == "force_checkpoint") { r.names = {"Success"}; r.types = {BO()}; return r; }
  if (fname == "summary" || fname == "summarize") { throw BinderException("summarize is a statement"); }
