static bool LooksLikeType(const std::string &s, const LogicalType &t) {
  Value r;
  if (t.id == TypeId::BIGINT) { int128_t v; if (s.find_first_of(".eE") != std::string::npos) return false; return ParseInt128(s, v) && v >= INT64_MIN && v <= INT64_MAX && !s.empty() && !isspace((unsigned char)s[0]) && !isspace((unsigned char)s.back()); }
