  char delim = ',', quote = '"';
  bool header = true;
  std::string nullstr = "";
  if (options.count("delim") && !options["delim"].empty()) delim = options["delim"][0].ToString()[0];
  if (options.count("delimiter") && !options["delimiter"].empty()) delim = options["delimiter"][0].ToString()[0];
  if (options.count("sep") && !options["sep"].empty()) delim = options["sep"][0].ToString()[0];
  if (options.count("quote") && !options["quote"].empty()) quote = options["quote"][0].ToString()[0];
  if (options.count("header") && !options["header"].empty()) header = options["header"][0].GetBool();
  if (options.count("nullstr") && !options["nullstr"].empty()) nullstr = options["nullstr"][0].ToString();
  if (options.count("null") && !options["null"].empty()) nullstr = options["null"][0].ToString();
  std::string out;
  if (header) {
    for (size_t i = 0; i < r.names.size(); i++) { if (i) out += delim; out += CsvEscape(r.names[i], delim, quote, false); }
    out += "\n";
  }
  for (auto &row : r.rows) {
    for (size_t i = 0; i < row.size(); i++) {
      if (i) out += delim;
      if (row[i].is_null) out += nullstr;
      else {
        bool is_str = row[i].type.id == TypeId::VARCHAR;
        std::string s = row[i].ToString();
        out += CsvEscape(s, delim, quote, is_str && (s == nullstr || s.empty()) && !nullstr.empty());
      }
    }
    out += "\n";
  }
  fwrite(out.data(), 1, out.size(), f);
  fclose(f);
}

QueryResult Executor::ExecuteCopy(CopyStatement &s) {
  QueryResult r; r.is_result = false;
  std::string fmt = s.format;
  std::string lower = ToLower(s.file);
  if (fmt.empty()) {
    if (EndsWith(lower, ".parquet")) fmt = "parquet";
    else if (EndsWith(lower, ".json") || EndsWith(lower, ".jsonl") || EndsWith(lower, ".ndjson")) fmt = "json";
    else fmt = "csv";
  }
  if (fmt == "parquet") throw NotImplementedException("Parquet is not supported in this build");
  if (fmt == "json") throw CatalogException("Copy Function with name json does not exist!\nDid you mean \"csv\"?");
  if (s.is_from) {
    auto table = catalog.FindTable("", s.schema, s.table);
    if (!table) throw CatalogException("Table with name " + s.table + " does not exist!");
    std::map<std::string, Value> opts;
    for (auto &o : s.options) if (!o.second.empty()) opts[o.first] = o.second[0];
    if (!opts.count("header")) opts["header"] = Value::Boolean(false);
    // when no header specified, DuckDB auto-detects; we use table types
    QueryResult csv;
    bool header_auto = !s.options.count("header");
    if (header_auto) opts.erase("header");
    opts["all_varchar"] = Value::Boolean(true);
    csv = ReadCSV(s.file, opts);
    std::vector<int> colmap;
    if (s.columns.empty()) for (size_t i = 0; i < table->columns.size(); i++) colmap.push_back((int)i);
    else for (auto &c : s.columns) { int ci = table->ColumnIndex(c); if (ci < 0) throw BinderException("Column \"" + c + "\" does not exist"); colmap.push_back(ci); }
    int64_t count = 0;
    for (auto &row : csv.rows) {
      Row nr;
      for (auto &c : table->columns) nr.push_back(c.default_value ? CastValue(EvaluateConstantExpression(*this, *c.default_value), c.type, false) : Value::Null(c.type));
      for (size_t i = 0; i < colmap.size() && i < row.size(); i++) {
        Value v = row[i];
        const LogicalType &t = table->columns[colmap[i]].type;
        if (v.is_null) v = Value::Null(t);
        else v = CastValue(v, t, false);
        nr[colmap[i]] = v;
      }
      CheckConstraints(*table, nr);
      table->rows.push_back(nr);
      count++;
    }
    r.changed_rows = count;
    ctx.rows_changed = count;
    return r;
  }
  QueryResult data;
  if (s.select) data = ExecuteSelect(*s.select);
  else {
    std::string sql = "SELECT " + (s.columns.empty() ? std::string("*") : [&]() { std::string c; for (size_t i = 0; i < s.columns.size(); i++) { if (i) c += ", "; c += QuoteIdentifierIfNeeded(s.columns[i]); } return c; }()) + " FROM " + (s.schema.empty() ? "" : QuoteIdentifierIfNeeded(s.schema) + ".") + QuoteIdentifierIfNeeded(s.table);
    auto stmt = Parser::ParseSelectFromString(sql);
    data = ExecuteSelect(*stmt);
  }
  WriteCSV(s.file, data, s.options);
  r.changed_rows = (int64_t)data.rows.size();
  ctx.rows_changed = r.changed_rows;
  return r;
}
