#include "shell.h"
#include <algorithm>
#include <cmath>

static const char *kBoxH = "\xe2\x94\x80";   // ─
static const char *kBoxV = "\xe2\x94\x82";   // │
static const char *kTL = "\xe2\x94\x8c", *kTR = "\xe2\x94\x90", *kBL = "\xe2\x94\x94", *kBR = "\xe2\x94\x98";
static const char *kTM = "\xe2\x94\xac", *kBM = "\xe2\x94\xb4", *kLM = "\xe2\x94\x9c", *kRM = "\xe2\x94\xa4", *kCM = "\xe2\x94\xbc";

static bool IsNumericType(const LogicalType &t) {
  return t.IsNumeric();
}

static std::string Repeat(const std::string &s, size_t n) { std::string r; for (size_t i = 0; i < n; i++) r += s; return r; }
static std::string Spaces(int n) { return n > 0 ? std::string((size_t)n, ' ') : std::string(); }

std::string ValueForOutput(const Value &v, const ShellState &st) {
  if (v.is_null) return st.null_value;
  return v.ToString();
}

static std::string EscapeForBox(const std::string &s) {
  std::string r;
  for (char c : s) {
    if (c == '\n') r += "\\n";
    else if (c == '\t') r += "\\t";
    else if (c == '\r') r += "\\r";
    else r += c;
  }
  return r;
}

// split a string into chunks of at most `width` display columns
static std::vector<std::string> SplitWidth(const std::string &s, size_t width) {
  std::vector<std::string> out;
  std::string cur;
  size_t cw = 0;
  for (size_t i = 0; i < s.size();) {
    int len = Utf8CharLen((unsigned char)s[i]);
    std::string ch = s.substr(i, len);
    size_t w = Utf8DisplayWidth(ch);
    if (cw + w > width && !cur.empty()) { out.push_back(cur); cur.clear(); cw = 0; }
    cur += ch; cw += w;
    i += len;
  }
  out.push_back(cur);
  return out;
}

// ---------------------------------------------------------------- duckbox
std::string RenderDuckBox(ShellState &st, const QueryResult &r, bool colors) {
  std::string ss;
  size_t column_count = r.names.size();
  size_t row_count = r.rows.size();
  int max_rows = st.max_rows;
  size_t max_width = st.max_width <= 0 ? 0 : (size_t)std::max(st.max_width, 80);
  if (st.max_width == 0 && st.is_terminal) {
    extern int TerminalWidth();
    int tw = TerminalWidth();
    max_width = tw > 0 ? (size_t)tw : 120;
  }
  if (column_count == 0) return "";
  // rows to render
  size_t rows_to_render = std::min<size_t>(row_count, (size_t)max_rows);
  if (row_count <= (size_t)max_rows + 3) rows_to_render = row_count;
  size_t top_rows, bottom_rows;
  if (rows_to_render == row_count) { top_rows = row_count; bottom_rows = 0; }
  else { top_rows = rows_to_render / 2 + (rows_to_render % 2 != 0 ? 1 : 0); bottom_rows = rows_to_render - top_rows; }
  std::string row_count_str = std::to_string(row_count) + " rows";
  std::string shown_str;
  bool has_hidden_rows = top_rows < row_count;
  if (has_hidden_rows) shown_str = "(" + std::to_string(top_rows + bottom_rows) + " shown)";
  size_t minimum_row_length = std::max(row_count_str.size(), shown_str.size()) + 4;
  // collect rendered values
  std::vector<size_t> render_rows;
  for (size_t i = 0; i < top_rows; i++) render_rows.push_back(i);
  for (size_t i = row_count - bottom_rows; i < row_count; i++) render_rows.push_back(i);
  std::vector<std::vector<std::string>> vals(render_rows.size(), std::vector<std::string>(column_count));
  std::vector<std::string> type_names(column_count);
  std::vector<size_t> widths(column_count), value_widths(column_count, 0);
  for (size_t c = 0; c < column_count; c++) {
    type_names[c] = r.types[c].ToStringLower();
    widths[c] = std::max(Utf8DisplayWidth(r.names[c]), Utf8DisplayWidth(type_names[c]));
  }
  for (size_t ri = 0; ri < render_rows.size(); ri++) {
    for (size_t c = 0; c < column_count; c++) {
      const Value &v = r.rows[render_rows[ri]][c];
      std::string s = v.is_null ? st.null_value : EscapeForBox(v.ToString());
      vals[ri][c] = s;
      size_t w = Utf8DisplayWidth(s);
      value_widths[c] = std::max(value_widths[c], w);
      widths[c] = std::max(widths[c], w);
    }
  }
  // total length
  size_t total_length = 1;
  for (size_t c = 0; c < column_count; c++) total_length += widths[c] + 3;
  if (has_hidden_rows && total_length < minimum_row_length) {
    widths[0] += minimum_row_length - total_length;
    total_length = minimum_row_length;
  }
  // column pruning / squeezing
  std::vector<bool> pruned(column_count, false);
  bool has_dots = false;
  const size_t max_col_width = 20;
  if (max_width > 0 && total_length > max_width) {
    std::vector<size_t> removal_order;
    size_t mid = column_count / 2;
    removal_order.push_back(mid);
    for (size_t k = 1; removal_order.size() < column_count; k++) {
      if (mid >= k) removal_order.push_back(mid - k);
      if (mid + k < column_count && removal_order.size() < column_count) removal_order.push_back(mid + k);
    }
    size_t ri = 0;
    while (total_length > max_width) {
      size_t needed = total_length - max_width;
      size_t available = 0;
      for (size_t c = 0; c < column_count; c++) if (!pruned[c] && widths[c] > max_col_width) available += widths[c] - max_col_width;
      if (available >= needed) {
        while (total_length > max_width) {
          size_t best = column_count; size_t bw = 0;
          for (size_t c = 0; c < column_count; c++) if (!pruned[c] && widths[c] > max_col_width && widths[c] > bw) { bw = widths[c]; best = c; }
          if (best == column_count) break;
          widths[best]--;
          total_length--;
        }
        break;
      }
      if (ri >= removal_order.size()) break;
      size_t col = removal_order[ri++];
      if (col >= column_count) continue;
      pruned[col] = true;
      total_length -= widths[col] + 3;
      if (!has_dots) { has_dots = true; total_length += 4; }
    }
  }
  // column map: indexes of columns to render, with -1 for dots
  std::vector<int> column_map;
  bool dots_inserted = false;
  for (size_t c = 0; c < column_count; c++) {
    if (pruned[c]) { if (!dots_inserted) { column_map.push_back(-1); dots_inserted = true; } continue; }
    column_map.push_back((int)c);
  }
  if (has_dots && !dots_inserted) column_map.push_back(-1);
  size_t shown_columns = 0;
  for (auto c : column_map) if (c >= 0) shown_columns++;
  bool has_hidden_columns = shown_columns < column_count;
  auto col_width = [&](int c) -> size_t { return c < 0 ? 1 : widths[c]; };
  // colors
  std::string gray = colors ? "\033[90m" : "", reset = colors ? "\033[00m" : "";
  auto V = [&]() { return gray + kBoxV + reset; };
  // top border
  auto border = [&](const char *left, const char *mid, const char *right) {
    std::string s = gray + left;
    for (size_t i = 0; i < column_map.size(); i++) {
      if (i) s += mid;
      s += Repeat(kBoxH, col_width(column_map[i]) + 2);
    }
    s += right;
    s += reset + "\n";
    return s;
  };
  ss += border(kTL, kTM, kTR);
  auto render_centered = [&](const std::string &text, size_t w) {
    size_t tw = Utf8DisplayWidth(text);
    size_t pc = (w >= tw ? w - tw : 0) + 2;
    size_t lp = pc / 2, rp = pc - lp;
    return Spaces((int)lp) + text + Spaces((int)rp);
  };
  auto render_aligned = [&](const std::string &text, size_t w, bool right) {
    size_t tw = Utf8DisplayWidth(text);
    size_t pc = (w >= tw ? w - tw : 0) + 2;
    if (right) return Spaces((int)(pc - 1)) + text + " ";
    return " " + text + Spaces((int)(pc - 1));
  };
  // header
  {
    std::string line = V();
    for (auto c : column_map) {
      if (c < 0) line += " " + std::string("\xe2\x80\xa6") + " " + V();
      else line += render_centered(r.names[c], widths[c]) + V();
    }
    ss += line + "\n";
    line = V();
    for (auto c : column_map) {
      if (c < 0) line += " " + std::string("\xe2\x80\xa6") + " " + V();
      else line += gray + render_centered(type_names[c], widths[c]) + reset + V();
    }
    ss += line + "\n";
  }
  if (row_count > 0) ss += border(kLM, kCM, kRM);
  // values
  std::vector<std::vector<std::vector<std::string>>> row_lines;  // per rendered row, per column, lines
  bool any_multiline = false;
  for (size_t ri = 0; ri < render_rows.size(); ri++) {
    std::vector<std::vector<std::string>> cols;
    size_t maxl = 1;
    for (auto c : column_map) {
      if (c < 0) { cols.push_back({"\xe2\x80\xa6"}); continue; }
      std::string &s = vals[ri][c];
      if (Utf8DisplayWidth(s) > widths[c]) { auto parts = SplitWidth(s, widths[c]); maxl = std::max(maxl, parts.size()); cols.push_back(parts); }
      else cols.push_back({s});
    }
    if (maxl > 1) any_multiline = true;
    row_lines.push_back(cols);
  }
  auto render_row = [&](size_t ri) {
    auto &cols = row_lines[ri];
    size_t maxl = 1;
    for (auto &c : cols) maxl = std::max(maxl, c.size());
    for (size_t l = 0; l < maxl; l++) {
      std::string line = V();
      for (size_t ci = 0; ci < column_map.size(); ci++) {
        int c = column_map[ci];
        std::string text = l < cols[ci].size() ? cols[ci][l] : "";
        if (c < 0) line += " " + text + Spaces(text.empty() ? 1 : 0) + " " + V();
        else {
          bool right = IsNumericType(r.types[c]);
          bool is_null = r.rows[render_rows[ri]][c].is_null;
          std::string cell = render_aligned(text, widths[c], right);
          if (colors && is_null) cell = gray + cell + reset;
          line += cell + V();
        }
      }
      ss += line + "\n";
    }
  };
  for (size_t ri = 0; ri < top_rows; ri++) {
    if (any_multiline && ri > 0) ss += border(kLM, kCM, kRM);
    render_row(ri);
  }
  if (bottom_rows > 0) {
    for (int k = 0; k < 3; k++) {
      std::string line = V();
      for (auto c : column_map) {
        if (c < 0) { line += " " + std::string("\xe2\x80\xa6") + " " + V(); continue; }
        size_t w = widths[c], vw = value_widths[c];
        if (vw > w) vw = w;
        bool right = IsNumericType(r.types[c]);
        size_t start = right ? w - vw : 0;
        size_t dot = start + vw / 2;
        if (dot >= w) dot = w - 1;
        line += " " + Spaces((int)dot) + "\xc2\xb7" + Spaces((int)(w - dot - 1)) + " " + V();
      }
      ss += line + "\n";
    }
    for (size_t ri = top_rows; ri < render_rows.size(); ri++) {
      if (any_multiline) ss += border(kLM, kCM, kRM);
      render_row(ri);
    }
  }
  // footer
  std::string column_count_str = std::to_string(column_count) + " columns";
  if (has_hidden_columns) column_count_str += " (" + std::to_string(shown_columns) + " shown)";
  bool display_shown_separately = has_hidden_rows;
  if (has_hidden_rows && total_length >= row_count_str.size() + shown_str.size() + 5) {
    row_count_str += " " + shown_str;
    shown_str.clear();
    display_shown_separately = false;
    minimum_row_length = row_count_str.size() + 4;
  }
  size_t minimum_length = row_count_str.size() + column_count_str.size() + 6;
  bool render_rows_and_columns = total_length >= minimum_length && ((has_hidden_columns && row_count > 0) || (row_count >= 10 && column_count > 1));
  bool render_rows = total_length >= minimum_row_length && (row_count == 0 || row_count >= 10);
  if (row_count == 0 && !render_rows) render_rows = true;
  ss += border(kBL, kBM, kBR);
  if (render_rows_and_columns) {
    std::string msg = "use .last to show entire result";
    bool show_msg = (has_hidden_rows || has_hidden_columns) && total_length >= 2 + row_count_str.size() + msg.size() + column_count_str.size() + 4;
    std::string line = gray + "  " + row_count_str;
    if (show_msg) {
      size_t rem = total_length - 2 - 2 - row_count_str.size() - msg.size() - column_count_str.size();
      size_t lp = rem / 2, rp = rem - lp;
      line += Spaces((int)lp) + msg + Spaces((int)rp) + column_count_str;
    } else {
      line += Spaces((int)(total_length - row_count_str.size() - column_count_str.size() - 4)) + column_count_str;
    }
    ss += line + reset + "\n";
  } else if (render_rows) {
    size_t w = total_length - 4;
    size_t rw = row_count_str.size();
    if (rw > w) ss += gray + "  " + row_count_str + reset + "\n";
    else {
      size_t pc = (w - rw) + 2;
      size_t lp = pc / 2, rp = pc - lp;
      ss += gray + " " + Spaces((int)lp) + row_count_str + Spaces((int)(rp - 1)) + reset + "\n";
    }
    if (display_shown_separately) {
      size_t sw = shown_str.size();
      size_t pc = (w >= sw ? w - sw : 0) + 2;
      size_t lp = pc / 2, rp = pc - lp;
      ss += gray + " " + Spaces((int)lp) + shown_str + Spaces((int)rp) + reset + "\n";
    }
  }
  return ss;
}

// ---------------------------------------------------------------- other modes
static void OutputCsv(std::string &out, const std::string &z, const ShellState &st, bool is_null) {
  if (is_null) { out += st.null_value; return; }
  bool need = false;
  for (unsigned char c : z) {
    if (c < 0x20 || c == '"' || c >= 0x80) { need = true; break; }
    if (!st.col_sep.empty() && c == (unsigned char)st.col_sep[0]) { need = true; break; }
  }
  if (!need && z.empty()) need = false;
  if (need) {
    out += '"';
    for (char c : z) { if (c == '"') out += "\"\""; else out += c; }
    out += '"';
  } else out += z;
}

static std::string HtmlEscape(const std::string &s) {
  std::string r;
  for (char c : s) {
    switch (c) {
    case '<': r += "&lt;"; break;
    case '>': r += "&gt;"; break;
    case '&': r += "&amp;"; break;
    case '"': r += "&quot;"; break;
    case '\'': r += "&#39;"; break;
    default: r += c;
    }
  }
  return r;
}

static std::string TclQuote(const std::string &s) {
  std::string r = "\"";
  for (unsigned char c : s) {
    if (c == '"' || c == '\\' || c == '[' || c == ']' || c == '$' || c == '{' || c == '}') { r += '\\'; r += (char)c; }
    else if (c == '\n') r += "\\n";
    else if (c == '\t') r += "\\t";
    else if (c == '\r') r += "\\r";
    else if (c < 0x20 || c >= 0x80) { char buf[8]; snprintf(buf, sizeof(buf), "\\%03o", c); r += buf; }
    else r += (char)c;
  }
  return r + "\"";
}

static std::string JsonQuote(const std::string &s) {
  std::string r = "\"";
  for (unsigned char c : s) {
    switch (c) {
    case '"': r += "\\\""; break;
    case '\\': r += "\\\\"; break;
    case '\n': r += "\\n"; break;
    case '\t': r += "\\t"; break;
    case '\r': r += "\\r"; break;
    case '\b': r += "\\b"; break;
    case '\f': r += "\\f"; break;
    default:
      if (c < 0x20) { char buf[8]; snprintf(buf, sizeof(buf), "\\u%04x", c); r += buf; }
      else r += (char)c;
    }
  }
  return r + "\"";
}

static std::string QuoteValue(const Value &v, const ShellState &st) {
  if (v.is_null) return "NULL";
  switch (v.type.id) {
  case TypeId::TINYINT: case TypeId::SMALLINT: case TypeId::INTEGER: case TypeId::BIGINT: case TypeId::HUGEINT: case TypeId::UTINYINT: case TypeId::USMALLINT: case TypeId::UINTEGER: case TypeId::UBIGINT: case TypeId::UHUGEINT:
  case TypeId::FLOAT: case TypeId::DOUBLE: case TypeId::DECIMAL: case TypeId::BOOLEAN:
    return v.ToString();
  default: return EscapeSQLString(v.ToString());
  }
}

static bool IsJsonRaw(const LogicalType &t) {
  return t.IsInteger() || t.IsFloating() || t.id == TypeId::LIST || t.id == TypeId::STRUCT || t.id == TypeId::MAP || t.id == TypeId::ARRAY;
}

void RenderResult(ShellState &st, const QueryResult &r, bool is_describe, bool describe_box) {
  FILE *out = st.out;
  std::string o;
  size_t nc = r.names.size();
  auto str_of = [&](const Value &v) { return ValueForOutput(v, st); };
  switch (st.mode) {
  case OutputMode::TRASH: return;
  case OutputMode::DUCKBOX: {
    bool colors = st.highlight_results && st.out == stdout && st.stdout_is_console;
    o = RenderDuckBox(st, r, colors);
    break;
  }
  case OutputMode::LIST: case OutputMode::TABS: {
    if (st.show_header) { for (size_t i = 0; i < nc; i++) { if (i) o += st.col_sep; o += r.names[i]; } o += st.row_sep; }
    for (auto &row : r.rows) { for (size_t i = 0; i < nc; i++) { if (i) o += st.col_sep; o += str_of(row[i]); } o += st.row_sep; }
    break;
  }
  case OutputMode::ASCII: {
    if (st.show_header) { for (size_t i = 0; i < nc; i++) { o += r.names[i]; o += "\n"; } }
    for (auto &row : r.rows) { for (size_t i = 0; i < nc; i++) { o += str_of(row[i]); o += "\n"; } }
    break;
  }
  case OutputMode::CSV: {
    if (st.show_header) { for (size_t i = 0; i < nc; i++) { if (i) o += st.col_sep; OutputCsv(o, r.names[i], st, false); } o += st.row_sep; }
    for (auto &row : r.rows) { for (size_t i = 0; i < nc; i++) { if (i) o += st.col_sep; OutputCsv(o, row[i].is_null ? "" : row[i].ToString(), st, row[i].is_null); } o += st.row_sep; }
    break;
  }
  case OutputMode::QUOTE: {
    if (st.show_header) { for (size_t i = 0; i < nc; i++) { if (i) o += st.col_sep; o += EscapeSQLString(r.names[i]); } o += st.row_sep; }
    for (auto &row : r.rows) { for (size_t i = 0; i < nc; i++) { if (i) o += st.col_sep; o += QuoteValue(row[i], st); } o += st.row_sep; }
    break;
  }
  case OutputMode::TCL: {
    if (st.show_header) { for (size_t i = 0; i < nc; i++) { if (i) o += st.col_sep; o += TclQuote(r.names[i]); } o += st.row_sep; }
    for (auto &row : r.rows) { for (size_t i = 0; i < nc; i++) { if (i) o += st.col_sep; o += TclQuote(str_of(row[i])); } o += st.row_sep; }
    break;
  }
  case OutputMode::HTML: {
    if (st.show_header) { o += "<tr>"; for (size_t i = 0; i < nc; i++) { o += "<th>" + HtmlEscape(r.names[i]) + "</th>\n"; } o += "</tr>\n"; }
    for (auto &row : r.rows) { o += "<tr>"; for (size_t i = 0; i < nc; i++) o += "<td>" + HtmlEscape(str_of(row[i])) + "</td>\n"; o += "</tr>\n"; }
    break;
  }
  case OutputMode::INSERT: {
    for (auto &row : r.rows) {
      o += "INSERT INTO " + st.insert_table;
      if (st.show_header) { o += "("; for (size_t i = 0; i < nc; i++) { if (i) o += ","; o += QuoteIdentifierIfNeeded(r.names[i]); } o += ")"; }
      o += " VALUES(";
      for (size_t i = 0; i < nc; i++) { if (i) o += ","; o += QuoteValue(row[i], st); }
      o += ");\n";
    }
    break;
  }
  case OutputMode::LINE: {
    size_t w = 5;
    for (auto &n : r.names) w = std::max(w, Utf8Length(n));
    bool first = true;
    for (auto &row : r.rows) {
      if (!first) o += "\n";
      first = false;
      for (size_t i = 0; i < nc; i++) { o += Spaces((int)(w - Utf8Length(r.names[i]))) + r.names[i] + " = " + str_of(row[i]) + "\n"; }
    }
    break;
  }
  case OutputMode::JSON: case OutputMode::JSONLINES: {
    bool arr = st.mode == OutputMode::JSON;
    if (arr) o += "[";
    for (size_t ri = 0; ri < r.rows.size(); ri++) {
      if (ri) o += arr ? ",\n" : "";
      o += "{";
      for (size_t i = 0; i < nc; i++) {
        if (i) o += ",";
        o += JsonQuote(r.names[i]) + ":";
        const Value &v = r.rows[ri][i];
        if (v.is_null) o += "null";
        else if (IsJsonRaw(v.type)) { std::string s = v.ToString(); if (v.type.IsFloating() && (s == "nan" || s == "inf" || s == "-inf")) o += JsonQuote(s); else o += s; }
        else o += JsonQuote(v.ToString());
      }
      o += "}";
      if (!arr) o += "\n";
    }
    if (arr) o += "]\n";
    if (arr && r.rows.empty()) { o = "[]\n"; }
    break;
  }
  case OutputMode::COLUMN: case OutputMode::TABLE: case OutputMode::BOX: case OutputMode::MARKDOWN: case OutputMode::LATEX: {
    std::vector<size_t> widths(nc, 0);
    std::vector<std::vector<std::string>> cells;
    for (size_t i = 0; i < nc; i++) widths[i] = Utf8DisplayWidth(r.names[i]);
    for (auto &row : r.rows) {
      std::vector<std::string> cr;
      for (size_t i = 0; i < nc; i++) { std::string s = str_of(row[i]); widths[i] = std::max(widths[i], Utf8DisplayWidth(s)); cr.push_back(s); }
      cells.push_back(cr);
    }
    std::vector<bool> right_just(nc, false);
    for (size_t i = 0; i < nc; i++) {
      if (i < st.col_widths.size() && st.col_widths[i] != 0) {
        size_t w = (size_t)std::abs(st.col_widths[i]);
        if (st.mode == OutputMode::COLUMN) widths[i] = std::max(widths[i], w);
        if (st.col_widths[i] < 0) right_just[i] = true;
      }
    }
    auto pad = [&](const std::string &s, size_t w, bool right) { size_t dw = Utf8DisplayWidth(s); if (dw >= w) return s; return right ? Spaces((int)(w - dw)) + s : s + Spaces((int)(w - dw)); };
    auto center = [&](const std::string &s, size_t w) { size_t dw = Utf8DisplayWidth(s); if (dw >= w) return s; size_t l = (w - dw) / 2; return Spaces((int)l) + s + Spaces((int)(w - dw - l)); };
    if (st.mode == OutputMode::COLUMN) {
