      for (size_t i = 0; i < nc; i++) o += IsNumericType(r.types[i]) ? "r" : "l";
      o += "|}\n\\hline\n";
      for (size_t i = 0; i < nc; i++) { if (i) o += " & "; o += center(r.names[i], widths[i]); }
      o += " \\\\\n\\hline\n";
      for (auto &cr : cells) { for (size_t i = 0; i < nc; i++) { if (i) o += " & "; o += pad(cr[i], widths[i], right_just[i]); } o += " \\\\\n"; }
      o += "\\hline\n\\end{tabular}\n";
    }
    break;
  }
  }
  fwrite(o.data(), 1, o.size(), out);
  fflush(out);
}
