    case OutputMode::DUCKBOX: return "duckbox"; case OutputMode::HTML: return "html"; case OutputMode::INSERT: return "insert"; case OutputMode::JSON: return "json";
    case OutputMode::JSONLINES: return "jsonlines"; case OutputMode::LATEX: return "latex"; case OutputMode::LINE: return "line"; case OutputMode::LIST: return "list";
    case OutputMode::MARKDOWN: return "markdown"; case OutputMode::QUOTE: return "quote"; case OutputMode::TABLE: return "table"; case OutputMode::TABS: return "tabs";
    case OutputMode::TCL: return "tcl"; case OutputMode::TRASH: return "trash";
    }
    return "";
  }

  bool SetMode(const std::string &m, const std::string &table, bool from_cli) {
    std::string n = ToLower(m);
    static const char *modes[] = {"ascii", "box", "column", "csv", "duckbox", "html", "insert", "json", "jsonlines", "latex", "line", "list", "markdown", "quote", "table", "tabs", "tcl", "trash"};
    // prefix matching like sqlite
    std::string match;
    int count = 0;
    for (auto md : modes) { if (std::string(md) == n) { match = md; count = 1; break; } if (StartsWith(md, n) && !n.empty()) { match = md; count++; } }
    if (count != 1) {
      fprintf(stderr, "Error: mode should be one of: ascii box column csv duckbox html insert json jsonlines latex line list markdown quote table tabs tcl trash \n");
      return false;
    }
    n = match;
    if (!table.empty() && n != "insert") { fprintf(stderr, "TABLE argument can only be used with .mode insert"); return false; }
    if (n == "ascii") { st.mode = OutputMode::ASCII; st.col_sep = "\x1f"; st.row_sep = "\x1e"; }
    else if (n == "box") st.mode = OutputMode::BOX;
    else if (n == "column") { st.mode = OutputMode::COLUMN; st.row_sep = "\n"; st.show_header = true; }
    else if (n == "csv") { st.mode = OutputMode::CSV; st.col_sep = ","; st.row_sep = from_cli ? "\n" : "\r\n"; }
    else if (n == "duckbox") st.mode = OutputMode::DUCKBOX;
    else if (n == "html") st.mode = OutputMode::HTML;
    else if (n == "insert") { st.mode = OutputMode::INSERT; st.insert_table = table.empty() ? "\"table\"" : table; }
    else if (n == "json") st.mode = OutputMode::JSON;
    else if (n == "jsonlines") st.mode = OutputMode::JSONLINES;
    else if (n == "latex") st.mode = OutputMode::LATEX;
    else if (n == "line") { st.mode = OutputMode::LINE; st.row_sep = "\n"; }
    else if (n == "list") { st.mode = OutputMode::LIST; st.col_sep = "|"; st.row_sep = "\n"; }
    else if (n == "markdown") st.mode = OutputMode::MARKDOWN;
    else if (n == "quote") { st.mode = OutputMode::QUOTE; if (!from_cli) { st.col_sep = ","; st.row_sep = "\n"; } }
    else if (n == "table") st.mode = OutputMode::TABLE;
    else if (n == "tabs") { st.mode = OutputMode::TABS; st.col_sep = "\t"; }
    else if (n == "tcl") { st.mode = OutputMode::TCL; st.col_sep = " "; st.row_sep = "\n"; }
    else if (n == "trash") st.mode = OutputMode::TRASH;
    return true;
  }

  void InvalidUsage(const std::string &cmd, const std::string &usage) {
    fprintf(stderr, "Invalid Command Error: Invalid usage of command '.%s'\n\nUsage: '.%s %s'\n", cmd.c_str(), cmd.c_str(), usage.c_str());
    rc = 1;
  }

  void OpenOutput(const std::string &file, bool once) {
    if (st.out != stdout && st.out) fclose(st.out);
    st.out = stdout;
    st.out_file.clear();
    st.once = false;
    if (file.empty() || file == "stdout") return;
    if (file == "stderr") { st.out = stderr; st.out_file = "stderr"; st.once = once; return; }
    if (file[0] == '|') {
      FILE *p = popen(file.c_str() + 1, "w");
      if (!p) { fprintf(stderr, "Error: cannot open pipe \"%s\"\n", file.c_str() + 1); rc = 1; return; }
      st.out = p; st.out_file = file; st.once = once; return;
    }
    FILE *f = fopen(file.c_str(), "wb");
    if (!f) { fprintf(stderr, "Error: cannot write to \"%s\"\n", file.c_str()); rc = 1; return; }
    st.out = f; st.out_file = file; st.once = once;
  }

  void DoHelp(std::vector<std::string> &args) {
    if (args.size() <= 1) { fputs(kHelpText, st.out); return; }
    std::string a = args[1];
    if (a == "--all" || a == "-all" || a == "-a" || a == "--a" || a == "all") { fputs(kHelpAllText, st.out); return; }
    if (a == "shortcuts") { fputs(kHelpShortcuts, st.out); return; }
    // pattern: find matching commands in full help
    std::string all = kHelpAllText;
    std::vector<std::string> lines = SplitString(all, '\n');
    std::vector<std::vector<std::string>> entries;
    for (auto &l : lines) {
      if (l.empty()) continue;
      if (StartsWith(l, "\033[32m.")) entries.push_back({l});
      else if (!entries.empty()) entries.back().push_back(l);
    }
    std::string lp = ToLower(a);
    std::vector<std::vector<std::string> *> matched;
    for (auto &e : entries) {
      size_t p = e[0].find("\033[00m");
      std::string cmd = e[0].substr(6, p == std::string::npos ? std::string::npos : p - 6);
      if (ToLower(cmd).find(lp) != std::string::npos) matched.push_back(&e);
    }
    if (matched.empty()) { fprintf(st.out, "Nothing matches '%s'\n", a.c_str()); return; }
    // compute widths: strip ANSI and measure first line's command+args
    auto strip = [](const std::string &s) { std::string r; for (size_t i = 0; i < s.size(); i++) { if (s[i] == '\033') { while (i < s.size() && s[i] != 'm') i++; continue; } r += s[i]; } return r; };
    size_t width = 0;
    for (auto *e : matched) {
      std::string plain = strip((*e)[0]);
      size_t two = plain.find("  ");
      std::string head = two == std::string::npos ? plain : plain.substr(0, two);
      width = std::max(width, head.size());
      for (size_t i = 1; i < e->size(); i++) {
        std::string pl = strip((*e)[i]);
        size_t t2 = pl.find("  ", 4);
        if (t2 != std::string::npos && pl.size() > 4 && pl[0] == ' ' && pl[1] == ' ' && pl[2] == ' ' && pl[3] == ' ') width = std::max(width, pl.substr(0, t2).size());
      }
    }
    width += 4;
    for (auto *e : matched) {
      for (size_t i = 0; i < e->size(); i++) {
        std::string &l = (*e)[i];
        std::string plain = strip(l);
        size_t two = plain.find("  ", i == 0 ? 0 : 4);
        if (two == std::string::npos) { fputs(l.c_str(), st.out); fputs("\n", st.out); continue; }
        // find description start
        size_t ds = two; while (ds < plain.size() && plain[ds] == ' ') ds++;
        std::string head_plain = plain.substr(0, two);
        std::string desc = plain.substr(ds);
        // reconstruct colored head: take from l up to the position after head
        // find in l the index where plain chars count reaches two
        size_t cnt = 0, li = 0;
        while (li < l.size() && cnt < two) { if (l[li] == '\033') { while (li < l.size() && l[li] != 'm') li++; li++; continue; } li++; cnt++; }
        // include trailing reset codes
        while (li < l.size() && l[li] == '\033') { while (li < l.size() && l[li] != 'm') li++; li++; }
        std::string head = l.substr(0, li);
        std::string pad(width > head_plain.size() ? width - head_plain.size() : 1, ' ');
        fputs((head + pad + desc + "\n").c_str(), st.out);
      }
    }
  }

  void DoShow() {
    fprintf(st.out, "%12.12s: %s\n", "echo", st.echo ? "on" : "off");
    fprintf(st.out, "%12.12s: %s\n", "headers", st.show_header ? "on" : "off");
    fprintf(st.out, "%12.12s: %s\n", "mode", ModeName(st.mode));
    fprintf(st.out, "%12.12s: %s\n", "nullvalue", ("\"" + EscapeSep(st.null_value) + "\"").c_str());
    fprintf(st.out, "%12.12s: %s\n", "output", st.out_file.empty() ? "stdout" : st.out_file.c_str());
    fprintf(st.out, "%12.12s: %s\n", "colseparator", ("\"" + EscapeSep(st.col_sep) + "\"").c_str());
    fprintf(st.out, "%12.12s: %s\n", "rowseparator", ("\"" + EscapeSep(st.row_sep) + "\"").c_str());
    std::string w;
    for (auto x : st.col_widths) w += std::to_string(x) + " ";
    fprintf(st.out, "%12.12s: %s\n", "width", w.c_str());
    fprintf(st.out, "%12.12s: %s\n", "filename", st.filename.c_str());
  }

  void DoSchema(std::vector<std::string> &args) {
    std::string pattern;
    for (size_t i = 1; i < args.size(); i++) { if (args[i] == "--indent") continue; pattern = args[i]; }
    for (auto &sc : catalog.AllSchemas()) {
      if (sc.first == "system") continue;
      std::vector<std::string> order = sc.second->creation_order;
      for (auto &t : sc.second->tables) if (std::find(order.begin(), order.end(), "table:" + t.first) == order.end()) order.push_back("table:" + t.first);
      for (auto &v : sc.second->views) if (std::find(order.begin(), order.end(), "view:" + v.first) == order.end()) order.push_back("view:" + v.first);
      for (auto &e : order) {
        std::string name = e.substr(e.find(':') + 1);
        if (!pattern.empty() && !LikeMatch(name, pattern, 0, true)) continue;
        if (StartsWith(e, "table:")) { auto it = sc.second->tables.find(name); if (it != sc.second->tables.end()) fprintf(st.out, "%s\n", it->second->CreateSQL().c_str()); }
        else if (StartsWith(e, "view:")) { auto it = sc.second->views.find(name); if (it != sc.second->views.end()) fprintf(st.out, "%s\n", it->second->create_sql.c_str()); }
      }
      for (auto &i : sc.second->indexes) if (pattern.empty() || LikeMatch(i.second->table, pattern, 0, true)) fprintf(st.out, "%s\n", i.second->sql.c_str());
    }
  }

  void DoDump(std::vector<std::string> &args) {
    std::vector<std::string> patterns;
    for (size_t i = 1; i < args.size(); i++) if (!StartsWith(args[i], "--")) patterns.push_back(args[i]);
    fprintf(st.out, "BEGIN TRANSACTION;\n");
    for (auto &sc : catalog.AllSchemas()) {
      if (sc.first == "system" || sc.first == "temp") continue;
      std::vector<std::string> order = sc.second->creation_order;
      for (auto &t : sc.second->tables) if (std::find(order.begin(), order.end(), "table:" + t.first) == order.end()) order.push_back("table:" + t.first);
      for (auto &v : sc.second->views) if (std::find(order.begin(), order.end(), "view:" + v.first) == order.end()) order.push_back("view:" + v.first);
      for (auto &e : order) {
        std::string name = e.substr(e.find(':') + 1);
        bool match = patterns.empty();
        for (auto &p : patterns) if (LikeMatch(name, p, 0, true)) match = true;
        if (!match) continue;
        if (StartsWith(e, "table:")) {
          auto it = sc.second->tables.find(name);
          if (it == sc.second->tables.end()) continue;
          fprintf(st.out, "%s;\n", it->second->CreateSQL().c_str());
          for (auto &row : it->second->rows) {
            std::string ins = "INSERT INTO " + sc.second->name + "." + QuoteIdentifierIfNeeded(name) + " VALUES(";
            for (size_t i = 0; i < row.size(); i++) { if (i) ins += ","; ShellState tmp = st; ins += row[i].is_null ? "NULL" : (row[i].type.IsNumeric() || row[i].type.id == TypeId::BOOLEAN ? row[i].ToString() : EscapeSQLString(row[i].ToString())); }
            ins += ");";
            fprintf(st.out, "%s\n", ins.c_str());
          }
        } else if (StartsWith(e, "view:")) {
          auto it = sc.second->views.find(name);
          if (it != sc.second->views.end()) fprintf(st.out, "%s;\n", it->second->create_sql.c_str());
        }
      }
    }
    fprintf(st.out, "COMMIT;\n");
  }

  void DoTables(std::vector<std::string> &args) {
    std::string pattern = args.size() > 1 ? args[1] : "";
    if (st.mode == OutputMode::DUCKBOX) {
      std::string o = RenderTablesBox(st, catalog, pattern);
      fwrite(o.data(), 1, o.size(), st.out);
      return;
    }
    std::vector<std::string> names;
    for (auto &sc : catalog.AllSchemas()) {
      if (sc.first == "system") continue;
      for (auto &t : sc.second->tables) if (pattern.empty() || LikeMatch(t.first, pattern, 0, true)) names.push_back(t.first);
      for (auto &v : sc.second->views) if (pattern.empty() || LikeMatch(v.first, pattern, 0, true)) names.push_back(v.first);
    }
    std::sort(names.begin(), names.end());
    // sqlite style: multiple columns
    size_t maxlen = 0;
    for (auto &n : names) maxlen = std::max(maxlen, n.size());
    size_t ncol = maxlen ? std::max<size_t>(1, 80 / (maxlen + 2)) : 1;
    size_t nrow = (names.size() + ncol - 1) / ncol;
    for (size_t r = 0; r < nrow; r++) {
      std::string line;
      for (size_t c = 0; c < ncol; c++) {
        size_t idx = c * nrow + r;
        if (idx >= names.size()) break;
        std::string n = names[idx];
        line += n;
        if (c + 1 < ncol && (c + 1) * nrow + r < names.size()) line += std::string(maxlen + 2 - n.size(), ' ');
      }
      fprintf(st.out, "%s\n", line.c_str());
    }
  }

  bool DotCommand(const std::string &line_in) {
    std::string line = Trim(line_in);
    std::vector<std::string> args = SplitArgs(line.substr(1));
    if (args.empty()) return true;
    std::string cmd = ToLower(args[0]);
    size_t n = args.size();
    auto arg = [&](size_t i) { return i < args.size() ? args[i] : std::string(); };
    if (cmd == "quit" || cmd == "q" || cmd == "exit") {
      exit_requested = true;
      if (cmd == "exit" && n > 1) exit_code = atoi(args[1].c_str()) & 0xFF;
      return true;
    }
    if (cmd == "help" || cmd == "h") { DoHelp(args); return true; }
    if (cmd == "mode" || cmd == "m") {
      if (n == 1) { fprintf(st.out, "current output mode: %s\n", ModeName(st.mode)); return true; }
      if (n > 3) { fprintf(stderr, "Usage: .mode MODE ?TABLE?\n"); rc = 1; return false; }
      if (!SetMode(args[1], arg(2), false)) { rc = 1; return false; }
      return true;
    }
    if (cmd == "headers" || cmd == "header") {
      if (n != 2) { InvalidUsage("headers", "on|off"); return false; }
      st.show_header = BooleanValue(args[1], cmd);
      return true;
    }
    if (cmd == "echo") { if (n != 2) { InvalidUsage("echo", "on|off"); return false; } st.echo = BooleanValue(args[1], cmd); return true; }
    if (cmd == "bail") { if (n != 2) { InvalidUsage("bail", "on|off"); return false; } st.bail = BooleanValue(args[1], cmd); return true; }
    if (cmd == "timer") { if (n != 2) { InvalidUsage("timer", "on|off"); return false; } st.timer = BooleanValue(args[1], cmd); return true; }
    if (cmd == "changes") { if (n != 2) { InvalidUsage("changes", "on|off"); return false; } st.changes = BooleanValue(args[1], cmd); return true; }
    if (cmd == "binary") { if (n != 2) { InvalidUsage("binary", "on|off"); return false; } return true; }
    if (cmd == "highlight" || cmd == "highlight_errors" || cmd == "render_errors" || cmd == "render_completion" || cmd == "auto_format") { if (n != 2) { InvalidUsage(cmd, "on|off"); return false; } BooleanValue(args[1], cmd); return true; }
    if (cmd == "highlight_results") { if (n != 2) { InvalidUsage(cmd, "on|off"); return false; } st.highlight_results = BooleanValue(args[1], cmd); return true; }
    if (cmd == "nullvalue") { if (n != 2) { InvalidUsage("nullvalue", "STRING"); return false; } st.null_value = args[1]; return true; }
    if (cmd == "separator") {
      if (n < 2 || n > 3) { InvalidUsage("separator", "COL ?ROW?"); return false; }
      st.col_sep = args[1];
      if (n == 3) st.row_sep = args[2];
      return true;
    }
    if (cmd == "width") {
      st.col_widths.clear();
      for (size_t i = 1; i < n; i++) st.col_widths.push_back(atoi(args[i].c_str()));
      return true;
    }
    if (cmd == "print") {
      std::string s;
      for (size_t i = 1; i < n; i++) { if (i > 1) s += " "; s += args[i]; }
      fprintf(st.out, "%s\n", s.c_str());
      return true;
    }
    if (cmd == "show") { DoShow(); return true; }
    if (cmd == "schema") { DoSchema(args); return true; }
    if (cmd == "dump") { DoDump(args); return true; }
    if (cmd == "tables") { DoTables(args); return true; }
    if (cmd == "indexes" || cmd == "indices") {
      for (auto &sc : catalog.AllSchemas()) for (auto &i : sc.second->indexes) if (n == 1 || LikeMatch(i.second->table, args[1], 0, true)) fprintf(st.out, "%s\n", i.first.c_str());
      return true;
    }
    if (cmd == "databases") {
      if (st.mode == OutputMode::DUCKBOX) { std::string o = RenderDatabasesBox(st, catalog); fwrite(o.data(), 1, o.size(), st.out); return true; }
      for (auto &nm : catalog.database_order) { auto db = catalog.FindDatabase(nm); fprintf(st.out, "%s: %s\n", nm.c_str(), db->path.empty() ? "" : db->path.c_str()); }
      return true;
    }
    if (cmd == "output" || cmd == "once") {
      std::string file;
      for (size_t i = 1; i < n; i++) { if (StartsWith(args[i], "-") && args[i] != "-") continue; file = args[i]; }
      OpenOutput(file, cmd == "once");
      return true;
    }
    if (cmd == "read") {
      if (n != 2) { InvalidUsage("read", "FILE"); return false; }
      FILE *f = fopen(args[1].c_str(), "rb");
      if (!f) { fprintf(stderr, "Error: cannot open \"%s\"\n", args[1].c_str()); rc = 1; return false; }
      ProcessInput(f, false);
      fclose(f);
      return true;
    }
    if (cmd == "shell" || cmd == "system") {
      std::string c;
      for (size_t i = 1; i < n; i++) { if (i > 1) c += " "; c += args[i]; }
      fflush(st.out);
      int r = system(c.c_str());
      if (r != 0) { fprintf(stderr, "System command returns %d\n", r); }
      return true;
    }
    if (cmd == "cd") {
      if (n != 2) { InvalidUsage("cd", "DIRECTORY"); return false; }
      if (chdir(args[1].c_str()) != 0) { fprintf(stderr, "Cannot change to directory \"%s\"\n", args[1].c_str()); rc = 1; return false; }
      return true;
    }
    if (cmd == "maxrows") {
      if (n != 2) { InvalidUsage("maxrows", "COUNT"); return false; }
      st.max_rows = atoi(args[1].c_str());
      if (st.max_rows <= 0) st.max_rows = 40;
      return true;
    }
    if (cmd == "maxwidth") {
      if (n != 2) { InvalidUsage("maxwidth", "COUNT"); return false; }
      st.max_width = atoi(args[1].c_str());
      return true;
    }
    if (cmd == "columns") { st.columns_mode = true; return true; }
    if (cmd == "rows") { st.columns_mode = false; return true; }
    if (cmd == "multiline" || cmd == "singleline" || cmd == "safe_mode" || cmd == "excel" || cmd == "edit" || cmd == "log" || cmd == "pager" || cmd == "progress_bar" || cmd == "ui_command" || cmd == "read_line_version" || cmd == "highlight_mode" || cmd == "highlight_colors" || cmd == "startup_text" || cmd == "display_colors" || cmd == "decimal_sep" || cmd == "thousand_sep" || cmd == "large_number_rendering") {
      if (cmd == "large_number_rendering" && n == 2) st.large_number_rendering = args[1];
      return true;
    }
    if (cmd == "prompt") { if (n > 1) st.prompt_main = args[1]; if (n > 2) st.prompt_continue = args[2]; return true; }
    if (cmd == "last") {
      if (has_last_result) { int saved = st.max_rows; int sw = st.max_width; st.max_rows = 1000000000; st.max_width = 0; RenderResult(st, last_result); st.max_rows = saved; st.max_width = sw; }
      return true;
    }
    if (cmd == "version") {
      fprintf(st.out, "DuckDB v0.0.1 (Unknown Version) 780a73962f\ngcc-11.4.0\n");
      return true;
    }
    if (cmd == "about") {
      fprintf(st.out, "DuckDB v0.0.1 (Unknown Version)\n\nDuckDB is an in-process analytical database management system designed for fast execution of complex SQL queries. It runs embedded within its host process with no external dependencies, and is optimized for OLAP workloads using a columnar, vectorized execution engine.\n\nDeveloped and maintained by the DuckDB Foundation, available under the MIT License.\nFor more information, visit https://duckdb.org or https://github.com/duckdb/duckdb.\n\n");
      return true;
    }
    if (cmd == "open") {
      std::string file;
      bool ro = false;
      for (size_t i = 1; i < n; i++) { if (args[i] == "--readonly") ro = true; else if (StartsWith(args[i], "--")) continue; else file = args[i]; }
      SaveAll();
      readonly = ro;
      try { OpenDatabase(file); } catch (DBException &e) { PrintError(e.Format()); rc = 1; return false; }
      return true;
    }
    if (cmd == "import") {
      std::string file, table;
      std::vector<std::string> rest;
      for (size_t i = 1; i < n; i++) { if (StartsWith(args[i], "--")) { if (args[i] == "--csv" || args[i] == "--json" || args[i] == "--parquet") continue; i++; continue; } rest.push_back(args[i]); }
      if (rest.size() < 2) { InvalidUsage("import", "FILE TABLE"); return false; }
      file = rest[0]; table = rest[1];
      std::string sql;
      if (catalog.FindTable("", "", table)) sql = "INSERT INTO " + QuoteIdentifierIfNeeded(table) + " SELECT * FROM read_csv(" + EscapeSQLString(file) + ")";
      else sql = "CREATE TABLE " + QuoteIdentifierIfNeeded(table) + " AS SELECT * FROM read_csv(" + EscapeSQLString(file) + ")";
      return RunSQL(sql);
    }
    // unknown command
    static const char *known[] = {".about", ".auto_format", ".bail", ".binary", ".cd", ".changes", ".columns", ".decimal_sep", ".databases", ".dump", ".display_colors", ".echo", ".edit", ".excel", ".exit", ".headers", ".help", ".highlight", ".highlight_colors", ".highlight_errors", ".highlight_mode", ".highlight_results", ".import", ".indexes", ".last", ".large_number_rendering", ".log", ".maxrows", ".maxwidth", ".mode", ".multiline", ".nullvalue", ".open", ".once", ".output", ".pager", ".print", ".progress_bar", ".prompt", ".quit", ".read", ".read_line_version", ".render_completion", ".render_errors", ".rows", ".safe_mode", ".separator", ".schema", ".shell", ".show", ".singleline", ".startup_text", ".system", ".tables", ".thousand_sep", ".timer", ".ui_command", ".version", ".width", ".comment", ".constant", ".cont", ".cont_sel", ".keyword", ".error", ".numeric_const", ".string_const", ".column_name", ".column_type", ".layout", ".none", ".bold", ".underline"};
    std::vector<std::string> cands(known, known + sizeof(known) / sizeof(known[0]));
    auto top = TopSimilar("." + cmd, cands, 5, 0.0);
    std::string sugg;
    for (size_t i = 0; i < top.size(); i++) { if (i) sugg += ", "; sugg += "\"" + top[i] + "\""; }
    fprintf(stderr, "Unknown Command Error: Unrecognized command '%s'\n\nDid you mean: %s\nRun '.help' for more information.\n", args[0].c_str(), sugg.c_str());
    rc = 1;
    return false;
  }

  // process one complete input chunk (sql or dot command)
  bool RunOne(const std::string &text) {
    std::string t = Trim(text);
    if (t.empty()) return true;
    if (t[0] == '.') {
      if (st.echo) fprintf(st.out, "%s\n", t.c_str());
      return DotCommand(t);
    }
    if (st.echo) fprintf(st.out, "%s\n", t.c_str());
    return RunSQL(text);
  }

  // process input stream line by line (non-interactive)
  void ProcessInput(FILE *in, bool is_stdin) {
    std::string buffer;
    char *line = nullptr;
    size_t cap = 0;
    ssize_t len;
    while (!exit_requested && (len = getline(&line, &cap, in)) >= 0) {
      std::string l(line, (size_t)len);
      while (!l.empty() && (l.back() == '\n' || l.back() == '\r')) l.pop_back();
      line_number++;
      std::string tl = Trim(l);
      if (buffer.empty()) {
        if (tl.empty()) continue;
        if (tl[0] == '.') {
          bool ok = RunOne(tl);
          if (!ok) { rc = 1; if (st.bail) break; }
          continue;
        }
      }
      buffer += l + "\n";
      if (SqlIsComplete(buffer)) {
        bool ok = RunOne(buffer);
        buffer.clear();
        if (!ok) { rc = 1; if (st.bail) break; }
      }
    }
    free(line);
    if (!exit_requested && !Trim(buffer).empty()) {
      bool ok = RunOne(buffer);
      if (!ok) rc = 1;
    }
  }

  void Interactive() {
    // simple line-based interactive mode
    printf("DuckDB v0.0.1 (Unknown Version)\nEnter \".help\" for usage hints.\n");
    if (st.filename == ":memory:") printf("Connected to a transient in-memory database.\nUse \".open FILENAME\" to reopen on a persistent database.\n");
    std::string buffer;
    while (!exit_requested) {
      std::string prompt = buffer.empty() ? (st.prompt_main.empty() ? "D " : st.prompt_main) : (st.prompt_continue.empty() ? "· " : st.prompt_continue);
      fputs(prompt.c_str(), stdout);
      fflush(stdout);
      char *line = nullptr; size_t cap = 0;
      ssize_t len = getline(&line, &cap, stdin);
      if (len < 0) { free(line); printf("\n"); break; }
      std::string l(line, (size_t)len); free(line);
      while (!l.empty() && (l.back() == '\n' || l.back() == '\r')) l.pop_back();
      std::string tl = Trim(l);
      if (buffer.empty()) {
        if (tl.empty()) continue;
        if (tl[0] == '.') { RunOne(tl); continue; }
      }
      buffer += l + "\n";
      if (SqlIsComplete(buffer)) { RunOne(buffer); buffer.clear(); }
    }
  }
};

static void UnknownOption(const char *prog, const std::string &opt) {
  static const char *opts[] = {"-ascii", "-bail", "-batch", "-box", "-column", "-cmd", "-csv", "-c", "-echo", "-f", "-format", "-format-file", "-init", "-header", "-h", "-help", "-html", "-interactive", "-json", "-jsonlines", "-line", "-list", "-markdown", "-newline", "-no-init", "-no-stdin", "-noheader", "-nullvalue", "-quote", "-readonly", "-s", "-safe", "-separator", "-storage-version", "-table", "-ui", "-unredacted", "-unsigned", "-version"};
  std::vector<std::string> cands(opts, opts + sizeof(opts) / sizeof(opts[0]));
  auto top = TopSimilar(opt, cands, 5, 0.0);
  std::string sugg;
  for (size_t i = 0; i < top.size(); i++) { if (i) sugg += ", "; sugg += "\"" + top[i] + "\""; }
  fprintf(stderr, "Unknown Option Error: Unrecognized option '%s'\n\nDid you mean: %s\nRun '%s -help' for a list of options.\n\n", opt.c_str(), sugg.c_str(), prog);
}

int main(int argc, char **argv) {
  Shell sh;
  sh.st.stdout_is_console = isatty(STDOUT_FILENO);
  sh.st.is_terminal = sh.st.stdout_is_console;
  bool stdin_is_tty = isatty(STDIN_FILENO);
  std::vector<std::pair<std::string, std::string>> cmds;  // (type, text) : "c" run and exit, "cmd" run before stdin
  std::string db_file;
  std::string positional_sql;
  bool no_stdin = false, interactive = false, batch = false, have_db = false;
  std::string prog = argv[0];
  auto need_arg = [&](int i, const char *opt, const char *desc) {
    if (i + 1 >= argc) {
      fprintf(stderr, "Missing Argument Error: Argument '%s' needs 1 arguments, but got 0\nOPTION:\n  %s\n\nRun '%s -help' for a list of options.\n\n", opt, desc, prog.c_str());
      exit(1);
    }
  };
  std::vector<std::string> format_files;
  for (int i = 1; i < argc; i++) {
    std::string a = argv[i];
    if (a.size() > 1 && a[0] == '-' && a[1] == '-') a = a.substr(1);
    if (a.empty() || a[0] != '-') {
      if (!have_db) { db_file = a; have_db = true; }
      else positional_sql += (positional_sql.empty() ? "" : "\n") + a;
      continue;
    }
    if (a == "-help" || a == "-h") { fputs(kUsageText, stdout); return 0; }
    if (a == "-version") { printf("v0.0.1 (Unknown Version) 780a73962f\n"); return 0; }
    if (a == "-ascii") sh.SetMode("ascii", "", true);
    else if (a == "-bail") sh.st.bail = true;
    else if (a == "-batch") batch = true;
    else if (a == "-box") sh.SetMode("box", "", true);
    else if (a == "-column") sh.SetMode("column", "", true);
    else if (a == "-csv") sh.SetMode("csv", "", true);
    else if (a == "-html") sh.SetMode("html", "", true);
    else if (a == "-json") sh.SetMode("json", "", true);
    else if (a == "-jsonlines") sh.SetMode("jsonlines", "", true);
    else if (a == "-line") sh.SetMode("line", "", true);
    else if (a == "-list") sh.SetMode("list", "", true);
    else if (a == "-markdown") sh.SetMode("markdown", "", true);
    else if (a == "-quote") sh.SetMode("quote", "", true);
    else if (a == "-table") sh.SetMode("table", "", true);
    else if (a == "-echo") sh.st.echo = true;
    else if (a == "-header") sh.st.show_header = true;
    else if (a == "-noheader") sh.st.show_header = false;
    else if (a == "-interactive") interactive = true;
    else if (a == "-no-init") sh.no_init = true;
    else if (a == "-no-stdin") no_stdin = true;
    else if (a == "-readonly") sh.readonly = true;
    else if (a == "-safe") sh.st.safe_mode = true;
    else if (a == "-unredacted" || a == "-unsigned" || a == "-ui") {}
    else if (a == "-cmd") { need_arg(i, "-cmd", "-cmd COMMAND    run \"COMMAND\" before reading stdin"); cmds.push_back({"cmd", argv[++i]}); }
    else if (a == "-c" || a == "-s") { need_arg(i, a.c_str(), a == "-c" ? "-c COMMAND    run \"COMMAND\" and exit" : "-s COMMAND    run \"COMMAND\" and exit"); cmds.push_back({"c", argv[++i]}); }
    else if (a == "-f") { need_arg(i, "-f", "-f FILENAME    read/process named file and exit"); cmds.push_back({"f", argv[++i]}); }
    else if (a == "-init") { need_arg(i, "-init", "-init FILENAME    read/process named file"); sh.init_files.push_back(argv[++i]); }
    else if (a == "-newline") { need_arg(i, "-newline", "-newline SEP    set output row separator. Default: '\\n'"); sh.st.row_sep = argv[++i]; }
    else if (a == "-separator") { need_arg(i, "-separator", "-separator SEP    set output column separator. Default: '|'"); sh.st.col_sep = argv[++i]; }
    else if (a == "-nullvalue") { need_arg(i, "-nullvalue", "-nullvalue TEXT    set text string for NULL values. Default 'NULL'"); sh.st.null_value = argv[++i]; }
    else if (a == "-storage-version") { need_arg(i, "-storage-version", "-storage-version VER    database storage compatibility version to use. Default: 'v0.10.0'"); i++; }
    else if (a == "-format") { cmds.push_back({"format", ""}); }
    else if (a == "-format-file") { need_arg(i, "-format-file", "-format-file FILENAME    format SQL in file, writing result to stdout"); cmds.push_back({"format-file", argv[++i]}); }
    else { UnknownOption(prog.c_str(), a); return 1; }
  }
  try {
    sh.OpenDatabase(db_file);
  } catch (DBException &e) {
    sh.PrintError(e.Format());
    return 1;
  }
  // init files (~/.duckdbrc)
  if (!sh.no_init) {
    const char *home = getenv("HOME");
    std::string rcfile = home ? std::string(home) + "/.duckdbrc" : "";
    if (!rcfile.empty()) {
      FILE *f = fopen(rcfile.c_str(), "rb");
      if (f) { sh.ProcessInput(f, false); fclose(f); }
    }
  }
  for (auto &init : sh.init_files) {
    FILE *f = fopen(init.c_str(), "rb");
    if (!f) { fprintf(stderr, "cannot open: \"%s\"\n", init.c_str()); return 1; }
    fprintf(stdout, "\033[90m-- Loading resources from %s\n\033[00m", init.c_str());
    int saved_rc = sh.rc;
    sh.rc = 0;
    sh.ProcessInput(f, false);
    fclose(f);
    if (sh.rc != 0) { fprintf(stderr, "Encountered errors while executing init file \"%s\". Exiting.\n", init.c_str()); return 1; }
    sh.rc = saved_rc;
  }
  bool ran_command = false;
  for (auto &c : cmds) {
    if (sh.exit_requested) break;
    if (c.first == "f") {
      FILE *f = fopen(c.second.c_str(), "rb");
      if (!f) { fprintf(stderr, "Error: cannot open \"%s\"\n", c.second.c_str()); return 1; }
      sh.ProcessInput(f, false);
      fclose(f);
      ran_command = true;
      if (sh.rc != 0) { sh.SaveAll(); return sh.rc; }
      continue;
    }
    if (c.first == "format" || c.first == "format-file") { ran_command = true; continue; }
    std::string text = c.second;
    bool ok;
    if (!Trim(text).empty() && Trim(text)[0] == '.') ok = sh.RunOne(Trim(text));
    else ok = sh.RunOne(text);
    if (!ok) { sh.rc = 1; sh.SaveAll(); return 1; }
    if (c.first == "c") ran_command = true;
  }
  if (!positional_sql.empty()) {
    bool ok = sh.RunOne(positional_sql);
    if (!ok) sh.rc = 1;
    ran_command = true;
  }
  if (sh.exit_requested) { sh.SaveAll(); return sh.exit_code ? sh.exit_code : sh.rc; }
  if (!ran_command && !no_stdin) {
    if ((stdin_is_tty || interactive) && !batch) sh.Interactive();
    else sh.ProcessInput(stdin, true);
  }
  sh.SaveAll();
  if (sh.st.out != stdout && sh.st.out != stderr && sh.st.out) fclose(sh.st.out);
  if (sh.exit_requested) return sh.exit_code ? sh.exit_code : sh.rc;
  return sh.rc;
}
