static std::string Under(const std::string &s) { return "\033[4m" + s + "\033[00m"; }

static std::string DescribeType(const std::string &t) {
  std::string l = ToLower(t);
  if (StartsWith(l, "decimal(")) return "decimal";
  return l;
}

struct DescRow { std::string name, type, attr; bool pk = false; };

static std::vector<std::string> BoxLines(const std::string &title, const std::vector<DescRow> &rows, const std::string &footer, bool gray_box, size_t &box_width) {
  auto G = [&](const std::string &s) { return gray_box ? Gray(s) : s; };
  size_t name_w = 0, type_w = 0, attr_w = 0;
  bool has_attr = false;
  for (auto &r : rows) { name_w = std::max(name_w, Utf8DisplayWidth(r.name)); type_w = std::max(type_w, Utf8DisplayWidth(r.type)); attr_w = std::max(attr_w, Utf8DisplayWidth(r.attr)); if (!r.attr.empty()) has_attr = true; }
  size_t inner = 1 + name_w + 1 + type_w + 1 + (has_attr ? attr_w + 1 : 0);
  size_t title_w = Utf8DisplayWidth(title);
  if (inner < title_w + 2) { name_w += title_w + 2 - inner; inner = title_w + 2; }
  if (!footer.empty() && inner < footer.size() + 2) { name_w += footer.size() + 2 - inner; inner = footer.size() + 2; }
  box_width = inner + 2;
  std::vector<std::string> lines;
  lines.push_back(G("\xe2\x94\x8c" + Rep(H, inner) + "\xe2\x94\x90"));
  size_t lp = (inner - title_w) / 2, rp = inner - title_w - lp;
  lines.push_back(G("\xe2\x94\x82" + Sp(lp)) + Bold(title) + G(Sp(rp) + "\xe2\x94\x82"));
  lines.push_back(G("\xe2\x94\x82" + Sp(inner) + "\xe2\x94\x82"));
  for (auto &r : rows) {
    std::string line = G("\xe2\x94\x82 ");
    line += r.pk ? Under(r.name) : r.name;
    line += G(Sp(name_w - Utf8DisplayWidth(r.name) + 1));
    line += Gray(r.type);
    line += G(Sp(type_w - Utf8DisplayWidth(r.type) + 1));
    if (has_attr) { line += Gray(r.attr); line += G(Sp(attr_w - Utf8DisplayWidth(r.attr) + 1)); }
    line += G("\xe2\x94\x82");
    lines.push_back(line);
  }
  if (!footer.empty()) {
    lines.push_back(G("\xe2\x94\x82" + Sp(inner) + "\xe2\x94\x82"));
    size_t fl = (inner - footer.size()) / 2, fr = inner - footer.size() - fl;
    lines.push_back(G("\xe2\x94\x82" + Sp(fl)) + Gray(footer) + G(Sp(fr) + "\xe2\x94\x82"));
  }
  lines.push_back(G("\xe2\x94\x94" + Rep(H, inner) + "\xe2\x94\x98"));
