}

static std::vector<DescRow> RowsFromDescribe(const QueryResult &r) {
  std::vector<DescRow> rows;
  for (auto &row : r.rows) {
    DescRow d;
    d.name = row[0].ToString();
    d.type = DescribeType(row[1].ToString());
    std::string key = row[3].is_null ? "" : row[3].ToString();
    bool notnull = row[2].ToString() == "NO";
    d.pk = key == "PRI";
    std::vector<std::string> attrs;
    if (notnull) attrs.push_back("not null");
    if (key == "UNI") attrs.push_back("unique");
