    DescRow d; d.name = n; d.type = "(" + (db->path.empty() ? std::string("memory") : db->path) + ")";
    rows.push_back(d);
  }
  size_t bw;
  auto lines = BoxLines("databases", rows, "", true, bw);
  std::string out;
  for (auto &l : lines) out += l + Gray("\n");
  return out;
}

std::string RenderTablesBox(ShellState &st, Catalog &cat, const std::string &pattern) {
  std::string out;
  size_t max_width = st.max_width > 0 ? (size_t)st.max_width : (st.is_terminal ? (size_t)[]() { extern int TerminalWidth(); return TerminalWidth(); }() : 80);
  struct BoxInfo { std::vector<std::string> lines; size_t width; };
  for (auto &dbname : cat.database_order) {
    auto db = cat.FindDatabase(dbname);
    if (!db) continue;
    for (auto &sc : db->schemas) {
      std::vector<BoxInfo> boxes;
      std::vector<std::string> names;
      for (auto &t : sc.second->tables) if (pattern.empty() || LikeMatch(t.first, pattern, 0, true)) names.push_back("t:" + t.first);
      for (auto &v : sc.second->views) if (pattern.empty() || LikeMatch(v.first, pattern, 0, true)) names.push_back("v:" + v.first);
      std::sort(names.begin(), names.end(), [](const std::string &a, const std::string &b) { return a.substr(2) < b.substr(2); });
      if (names.empty()) continue;
      for (auto &n : names) {
        std::vector<DescRow> rows;
        std::string footer;
        bool is_table = n[0] == 't';
        std::string name = n.substr(2);
        if (is_table) {
          auto &t = *sc.second->tables[name];
          auto pk = t.PrimaryKeyColumns();
          for (auto &c : t.columns) { DescRow d; d.name = c.name; d.type = DescribeType(c.type.ToString()); d.pk = std::find_if(pk.begin(), pk.end(), [&](const std::string &p) { return IEquals(p, c.name); }) != pk.end(); rows.push_back(d); }
          footer = std::to_string(t.rows.size()) + " rows";
        } else {
          auto &v = *sc.second->views[name];
          for (size_t i = 0; i < v.column_names.size(); i++) { DescRow d; d.name = v.column_names[i]; d.type = DescribeType(v.column_types[i].ToString()); rows.push_back(d); }
        }
        BoxInfo b;
        b.lines = BoxLines(name, rows, footer, is_table, b.width);
        boxes.push_back(b);
      }
      // layout rows of boxes
      size_t i = 0;
      while (i < boxes.size()) {
        size_t total = 0, j = i;
        while (j < boxes.size() && (j == i || total + boxes[j].width <= max_width)) { total += boxes[j].width; j++; }
        // header lines
        auto header = [&](const std::string &name, const char *color) {
          size_t dashes = total >= name.size() + 4 ? total - 4 - name.size() : 0;
          size_t l = dashes / 2, rr = dashes - l;
          return std::string("\033[38;5;") + color + "m " + Rep(H, l) + " " + name + " " + Rep(H, rr) + " \n\033[00m";
        };
        if (i == 0) { out += header(dbname, "172"); out += header(sc.first, "39"); }
        size_t maxl = 0;
        for (size_t k = i; k < j; k++) maxl = std::max(maxl, boxes[k].lines.size());
        for (size_t l = 0; l < maxl; l++) {
          std::string line;
          size_t last_active = i;
          for (size_t k = i; k < j; k++) if (l < boxes[k].lines.size()) last_active = k;
          for (size_t k = i; k <= last_active; k++) {
            if (l < boxes[k].lines.size()) line += boxes[k].lines[l];
            else line += Gray(Sp(boxes[k].width));
          }
          out += line + Gray("\n");
        }
        i = j;
      }
    }
  }
  return out;
}
