end = s.index("  // footer\n")
new_body = r'''  // colors: every box element is wrapped individually when colors are enabled
  auto G = [&](const std::string &x) { return colors ? "\033[90m" + x + "\033[00m" : x; };
  auto NL = [&]() { return G("\n"); };
  auto V = [&]() { return G(kBoxV); };
  auto border = [&](const char *left, const char *mid, const char *right) {
    std::string s = G(left);
    for (size_t i = 0; i < column_map.size(); i++) {
      if (i) s += G(mid);
      size_t w = col_width(column_map[i]) + 2;
      if (colors) { for (size_t k = 0; k < w; k++) s += G(kBoxH); }
      else s += Repeat(kBoxH, w);
    }
    s += G(right);
    s += NL();
    return s;
  };
  ss += border(kTL, kTM, kTR);
  auto render_centered = [&](const std::string &text, size_t w, bool gray_text) {
    size_t tw = Utf8DisplayWidth(text);
    size_t pc = (w >= tw ? w - tw : 0) + 2;
    size_t lp = pc / 2, rp = pc - lp;
    return G(Spaces((int)lp)) + (gray_text ? G(text) : text) + G(Spaces((int)rp));
  };
  auto render_aligned = [&](const std::string &text, size_t w, bool right, bool gray_text) {
    size_t tw = Utf8DisplayWidth(text);
    size_t pc = (w >= tw ? w - tw : 0) + 2;
    std::string t = gray_text ? G(text) : text;
    if (right) return G(Spaces((int)(pc - 1))) + t + G(" ");
    return G(" ") + t + G(Spaces((int)(pc - 1)));
  };
  // header
  {
    std::string line = V();
    for (auto c : column_map) {
      if (c < 0) line += G(" ") + G("\xe2\x80\xa6") + G(" ") + V();
      else line += render_centered(r.names[c], widths[c], false) + V();
    }
    ss += line + NL();
    line = V();
    for (auto c : column_map) {
      if (c < 0) line += G(" ") + G("\xe2\x80\xa6") + G(" ") + V();
      else line += render_centered(type_names[c], widths[c], true) + V();
    }
    ss += line + NL();
  }
  if (row_count > 0) ss += border(kLM, kCM, kRM);
  // values
  std::vector<std::vector<std::vector<std::string>>> row_lines;  // per rendered row, per column, lines
  bool any_multiline = false;
  for (size_t ri = 0; ri < rrows.size(); ri++) {
    std::vector<std::vector<std::string>> cols;
    size_t maxl = 1;
    for (auto c : column_map) {
      if (c < 0) { cols.push_back({"\xe2\x80\xa6"}); continue; }
