                  if (lid == 10) { if (sid == 1) { sc.int_bits = (int)r.readInt(st); return true; } if (sid == 2) { sc.int_signed = st == 1; return true; } return false; }
                  return false;
                });
                return true;
              }
              return false;
            });
            return true;
          }
          default: return false;
          }
        });
        meta.schema.push_back(sc);
      });
      return true;
    }
    if (id == 3) { meta.num_rows = r.readInt(type); return true; }
    if (id == 4 && type == 9) {
      r.readList([&](int et) {
        RowGroupMeta rg;
        r.readStruct([&](int16_t fid, int ft) {
          if (fid == 1 && ft == 9) {
            r.readList([&](int et2) {
              ColumnChunkMeta cc;
              r.readStruct([&](int16_t cid, int ct) {
                if (cid == 3 && ct == 12) {
                  r.readStruct([&](int16_t mid, int mt) {
                    switch (mid) {
                    case 1: cc.type = (int)r.readInt(mt); return true;
                    case 3: r.readList([&](int) { cc.path.push_back(r.binary()); }); return true;
                    case 4: cc.codec = (int)r.readInt(mt); return true;
                    case 5: cc.num_values = r.readInt(mt); return true;
                    case 7: cc.total_compressed_size = r.readInt(mt); return true;
                    case 9: cc.data_page_offset = r.readInt(mt); return true;
                    case 11: cc.dictionary_page_offset = r.readInt(mt); return true;
                    default: return false;
                    }
                  });
                  return true;
                }
                return false;
              });
              rg.columns.push_back(cc);
            });
            return true;
          }
          if (fid == 3) { rg.num_rows = r.readInt(ft); return true; }
          return false;
        });
        meta.row_groups.push_back(rg);
      });
      return true;
    }
    if (id == 6 && type == 8) { meta.created_by = r.binary(); return true; }
    return false;
  });
  return meta;
}

static LogicalType ParquetToLogical(const SchemaCol &sc) {
  switch (sc.type) {
  case 0: return LogicalType(TypeId::BOOLEAN);
  case 1:
    if (sc.logical == 6 || sc.converted == 6) return LogicalType(TypeId::DATE);
    if (sc.logical == 5 || sc.converted == 5) return LogicalType::Decimal(sc.precision, sc.scale);
    if (sc.logical == 7 || sc.converted == 7) return LogicalType(TypeId::TIME);
    if (sc.logical == 10) { if (sc.int_bits == 8) return LogicalType(sc.int_signed ? TypeId::TINYINT : TypeId::UTINYINT); if (sc.int_bits == 16) return LogicalType(sc.int_signed ? TypeId::SMALLINT : TypeId::USMALLINT); return LogicalType(sc.int_signed ? TypeId::INTEGER : TypeId::UINTEGER); }
    if (sc.converted == 15) return LogicalType(TypeId::TINYINT);
    if (sc.converted == 16) return LogicalType(TypeId::SMALLINT);
    if (sc.converted == 11) return LogicalType(TypeId::UTINYINT);
    if (sc.converted == 12) return LogicalType(TypeId::USMALLINT);
    if (sc.converted == 13) return LogicalType(TypeId::UINTEGER);
    return LogicalType(TypeId::INTEGER);
  case 2:
    if (sc.logical == 5 || sc.converted == 5) return LogicalType::Decimal(sc.precision, sc.scale);
    if (sc.logical == 8 || sc.converted == 9 || sc.converted == 10) {
      if (sc.adjusted_utc) return LogicalType(TypeId::TIMESTAMP_TZ);
      if (sc.converted == 9 || sc.time_unit == 1) return LogicalType(TypeId::TIMESTAMP_MS);
      if (sc.time_unit == 3) return LogicalType(TypeId::TIMESTAMP_NS);
      return LogicalType(TypeId::TIMESTAMP);
    }
    if (sc.logical == 7 || sc.converted == 8) return LogicalType(TypeId::TIME);
    if (sc.logical == 10 && !sc.int_signed) return LogicalType(TypeId::UBIGINT);
    if (sc.converted == 14) return LogicalType(TypeId::UBIGINT);
    return LogicalType(TypeId::BIGINT);
  case 3: return LogicalType(TypeId::TIMESTAMP);
  case 4: return LogicalType(TypeId::FLOAT);
  case 5: return LogicalType(TypeId::DOUBLE);
  case 6:
    if (sc.logical == 1 || sc.converted == 0 || sc.logical == 12 || sc.converted == 19 || sc.logical == 4 || sc.converted == 4) return LogicalType(TypeId::VARCHAR);
    if (sc.logical == 5 || sc.converted == 5) return LogicalType::Decimal(sc.precision, sc.scale);
    return LogicalType(TypeId::BLOB);
  case 7:
    if (sc.logical == 5 || sc.converted == 5) return LogicalType::Decimal(sc.precision, sc.scale);
    if (sc.logical == 14) return LogicalType(TypeId::UUID);
    if (sc.converted == 21) return LogicalType(TypeId::INTERVAL);
    return LogicalType(TypeId::BLOB);
  }
  return LogicalType(TypeId::VARCHAR);
}

static std::string Decompress(int codec, const uint8_t *p, size_t n, size_t uncompressed) {
  if (codec == 0) return std::string((const char *)p, n);
  std::string out;
  if (codec == 1) { if (!SnappyDecompress(p, n, out)) throw IOException("Parquet: snappy decompression failed"); return out; }
  if (codec == 2) { if (!GzipDecompress(p, n, uncompressed, out)) throw IOException("Parquet: gzip decompression failed"); return out; }
  throw NotImplementedException("Parquet: unsupported compression codec " + std::to_string(codec));
}

static Value DecodePlainValue(const SchemaCol &sc, const LogicalType &t, const uint8_t *&p, const uint8_t *end) {
  auto need = [&](size_t n) { if (p + n > end) throw IOException("Parquet: truncated data page"); };
  switch (sc.type) {
  case 1: { need(4); int32_t v; memcpy(&v, p, 4); p += 4; Value r(t); r.is_null = false; r.ival = v; if (t.id == TypeId::TIME && (sc.converted == 7 || sc.time_unit == 1)) r.ival = (int64_t)v * 1000; return r; }
  case 2: { need(8); int64_t v; memcpy(&v, p, 8); p += 8; Value r(t); r.is_null = false; r.ival = v; return r; }
  case 3: { need(12); int64_t nanos; memcpy(&nanos, p, 8); uint32_t jd; memcpy(&jd, p + 8, 4); p += 12; int64_t days = (int64_t)jd - 2440588; return Value::Timestamp(days * 86400000000LL + nanos / 1000); }
  case 4: { need(4); float f; memcpy(&f, p, 4); p += 4; return Value::Float(f); }
  case 5: { need(8); double d; memcpy(&d, p, 8); p += 8; return Value::Double(d); }
  case 6: {
    need(4); uint32_t len; memcpy(&len, p, 4); p += 4; need(len);
    std::string s((const char *)p, len); p += len;
    if (t.id == TypeId::DECIMAL) { int128_t v = 0; for (unsigned char c : s) v = (v << 8) | c; if (!s.empty() && (s[0] & 0x80)) v -= ((int128_t)1 << (8 * s.size())); return Value::Decimal(v, t.width, t.scale); }
    if (t.id == TypeId::VARCHAR) return Value::Varchar(s);
    return Value::Blob(s);
  }
  case 7: {
    size_t len = (size_t)sc.type_length; need(len);
    std::string s((const char *)p, len); p += len;
    if (t.id == TypeId::DECIMAL) { int128_t v = 0; for (unsigned char c : s) v = (v << 8) | c; if (!s.empty() && (s[0] & 0x80) && len < 16) v -= ((int128_t)1 << (8 * len)); return Value::Decimal(v, t.width, t.scale); }
    if (t.id == TypeId::UUID) { uint128_t v = 0; for (unsigned char c : s) v = (v << 8) | c; v ^= ((uint128_t)1 << 127); return Value::UUID((int128_t)v); }
    if (t.id == TypeId::INTERVAL) { uint32_t m, d, ms; memcpy(&m, s.data(), 4); memcpy(&d, s.data() + 4, 4); memcpy(&ms, s.data() + 8, 4); Interval iv; iv.months = (int32_t)m; iv.days = (int32_t)d; iv.micros = (int64_t)ms * 1000; return Value::IntervalV(iv); }
    return Value::Blob(s);
  }
  }
  throw IOException("Parquet: unsupported physical type");
}

static void ReadColumnChunk(const std::string &data, const SchemaCol &sc, const LogicalType &t, const ColumnChunkMeta &cc, std::vector<Value> &out) {
  int64_t offset = cc.dictionary_page_offset > 0 && cc.dictionary_page_offset < cc.data_page_offset ? cc.dictionary_page_offset : cc.data_page_offset;
  if (offset < 0 || (size_t)offset >= data.size()) throw IOException("Parquet: invalid column chunk offset");
  const uint8_t *p = (const uint8_t *)data.data() + offset;
  const uint8_t *fend = (const uint8_t *)data.data() + data.size();
  std::vector<Value> dict;
  bool has_dict = false;
  int64_t remaining = cc.num_values;
  bool optional = sc.repetition == 1;
  while (remaining > 0 && p < fend) {
    // page header
    TReader r(p, fend - p);
    int page_type = -1; int32_t usize = 0, csize = 0; int32_t num_values = 0; int encoding = 0; int def_enc = 3;
    int32_t v2_def_len = 0, v2_rep_len = 0; bool v2_compressed = true; bool is_v2 = false;
    r.readStruct([&](int16_t id, int type) {
      switch (id) {
      case 1: page_type = (int)r.readInt(type); return true;
      case 2: usize = (int32_t)r.readInt(type); return true;
      case 3: csize = (int32_t)r.readInt(type); return true;
      case 5: r.readStruct([&](int16_t fid, int ft) { if (fid == 1) { num_values = (int32_t)r.readInt(ft); return true; } if (fid == 2) { encoding = (int)r.readInt(ft); return true; } if (fid == 3) { def_enc = (int)r.readInt(ft); return true; } return false; }); return true;
      case 7: r.readStruct([&](int16_t fid, int ft) { if (fid == 1) { num_values = (int32_t)r.readInt(ft); return true; } if (fid == 2) { encoding = (int)r.readInt(ft); return true; } return false; }); return true;
      case 8: is_v2 = true; r.readStruct([&](int16_t fid, int ft) { if (fid == 1) { num_values = (int32_t)r.readInt(ft); return true; } if (fid == 4) { encoding = (int)r.readInt(ft); return true; } if (fid == 5) { v2_def_len = (int32_t)r.readInt(ft); return true; } if (fid == 6) { v2_rep_len = (int32_t)r.readInt(ft); return true; } if (fid == 7) { v2_compressed = ft == 1; return true; } return false; }); return true;
      default: return false;
      }
    });
    const uint8_t *page_data = r.p;
    if (page_data + csize > fend) throw IOException("Parquet: truncated page");
    std::string buf;
    const uint8_t *vp, *vend;
    if (is_v2) {
      // levels are uncompressed; values possibly compressed
      std::string levels((const char *)page_data, v2_rep_len + v2_def_len);
      std::string values = v2_compressed ? Decompress(cc.codec, page_data + v2_rep_len + v2_def_len, csize - v2_rep_len - v2_def_len, usize - v2_rep_len - v2_def_len) : std::string((const char *)page_data + v2_rep_len + v2_def_len, csize - v2_rep_len - v2_def_len);
      buf = levels + values;
    } else buf = Decompress(cc.codec, page_data, csize, usize);
    vp = (const uint8_t *)buf.data(); vend = vp + buf.size();
    p = page_data + csize;
    if (page_type == 2) {
      // dictionary page: PLAIN values
      dict.clear();
      for (int32_t i = 0; i < num_values; i++) dict.push_back(DecodePlainValue(sc, t, vp, vend));
      has_dict = true;
      continue;
    }
    if (page_type != 0 && page_type != 3) continue;
    // definition levels
    std::vector<uint32_t> defs;
    if (optional) {
      if (is_v2) { const uint8_t *dp = vp + v2_rep_len; const uint8_t *dend = dp + v2_def_len; DecodeHybrid(dp, dend, 1, num_values, defs); vp = vp + v2_rep_len + v2_def_len; }
      else {
        if (def_enc == 3) {
          if (vp + 4 > vend) throw IOException("Parquet: truncated levels");
          uint32_t len; memcpy(&len, vp, 4); vp += 4;
          const uint8_t *dp = vp; const uint8_t *dend = vp + len;
          DecodeHybrid(dp, dend, 1, num_values, defs);
          vp = dend;
        } else {
          // BIT_PACKED (deprecated): 1 bit per value, MSB first
          size_t nbytes = (num_values + 7) / 8;
          for (int32_t i = 0; i < num_values; i++) defs.push_back((vp[i / 8] >> (7 - (i % 8))) & 1);
          vp += nbytes;
        }
      }
    } else defs.assign(num_values, 1);
    size_t nonnull = 0;
    for (auto d : defs) if (d) nonnull++;
    std::vector<Value> vals;
    vals.reserve(nonnull);
    if (encoding == 0) {
      if (sc.type == 0) {
        // booleans bit-packed LSB first
        for (size_t i = 0; i < nonnull; i++) { if (vp + i / 8 >= vend) throw IOException("Parquet: truncated booleans"); vals.push_back(Value::Boolean((vp[i / 8] >> (i % 8)) & 1)); }
      } else for (size_t i = 0; i < nonnull; i++) vals.push_back(DecodePlainValue(sc, t, vp, vend));
    } else if (encoding == 2 || encoding == 8) {
      if (!has_dict) throw IOException("Parquet: dictionary encoding without dictionary page");
      if (vp >= vend) { for (size_t i = 0; i < nonnull; i++) vals.push_back(dict.empty() ? Value::Null(t) : dict[0]); }
      else {
        int bw = *vp++;
        std::vector<uint32_t> idx;
        DecodeHybrid(vp, vend, bw, nonnull, idx);
        for (size_t i = 0; i < nonnull; i++) { if (idx[i] >= dict.size()) throw IOException("Parquet: dictionary index out of range"); vals.push_back(dict[idx[i]]); }
      }
    } else if (encoding == 5 && (sc.type == 1 || sc.type == 2)) {
      // DELTA_BINARY_PACKED
      BitReader br(vp, vend);
      uint64_t block_size = br.varint(), miniblocks = br.varint(), total = br.varint();
      int64_t first = (int64_t)((br.varint() >> 1)) ; // zigzag
      { uint64_t z = 0; } 
      // re-read first value properly as zigzag: recompute
      (void)first;
      throw NotImplementedException("Parquet: DELTA_BINARY_PACKED encoding is not supported");
    } else {
      throw NotImplementedException("Parquet: unsupported encoding " + std::to_string(encoding));
    }
    size_t vi = 0;
    for (int32_t i = 0; i < num_values; i++) {
      if (defs[i]) out.push_back(vi < vals.size() ? vals[vi++] : Value::Null(t));
      else out.push_back(Value::Null(t));
    }
    remaining -= num_values;
  }
}

} // namespace

QueryResult ReadParquetFile(const std::string &path) {
  FILE *f = fopen(path.c_str(), "rb");
  if (!f) throw IOException("No files found that match the pattern \"" + path + "\"");
  std::string data; char buf[65536]; size_t n;
  while ((n = fread(buf, 1, sizeof(buf), f)) > 0) data.append(buf, n);
  fclose(f);
  if (data.size() < 8 || data.compare(0, 4, "PAR1") != 0) throw IOException("No magic bytes found at beginning of file '" + path + "'");
  FileMeta meta = ParseFooter(data);
  QueryResult r;
  // flat columns: schema[0] is root
  std::vector<SchemaCol> cols;
  for (size_t i = 1; i < meta.schema.size(); i++) {
    if (meta.schema[i].num_children > 0) throw NotImplementedException("Parquet: nested types are not supported in this build");
    cols.push_back(meta.schema[i]);
  }
  for (auto &c : cols) { r.names.push_back(c.name); r.types.push_back(ParquetToLogical(c)); }
  std::vector<std::vector<Value>> coldata(cols.size());
  for (auto &rg : meta.row_groups) {
    for (size_t ci = 0; ci < cols.size() && ci < rg.columns.size(); ci++) {
      ReadColumnChunk(data, cols[ci], r.types[ci], rg.columns[ci], coldata[ci]);
    }
  }
  size_t nrows = cols.empty() ? 0 : coldata[0].size();
  for (size_t i = 0; i < nrows; i++) {
    Row row;
    for (size_t ci = 0; ci < cols.size(); ci++) row.push_back(i < coldata[ci].size() ? coldata[ci][i] : Value::Null(r.types[ci]));
    r.rows.push_back(row);
  }
  return r;
}

// ---------------------------------------------------------------- writer
static void WriteI32(std::string &s, int32_t v) { s.append((const char *)&v, 4); }
static void WriteI64(std::string &s, int64_t v) { s.append((const char *)&v, 8); }

void WriteParquetFile(const std::string &path, const QueryResult &r) {
  std::string out = "PAR1";
  struct ColInfo { int ptype; int type_len; LogicalType t; };
  std::vector<ColInfo> infos;
  for (auto &t : r.types) {
    ColInfo ci; ci.t = t; ci.type_len = 0;
    switch (t.id) {
    case TypeId::BOOLEAN: ci.ptype = 0; break;
    case TypeId::TINYINT: case TypeId::SMALLINT: case TypeId::INTEGER: case TypeId::UTINYINT: case TypeId::USMALLINT: case TypeId::DATE: ci.ptype = 1; break;
    case TypeId::UINTEGER: case TypeId::BIGINT: case TypeId::UBIGINT: case TypeId::TIMESTAMP: case TypeId::TIMESTAMP_TZ: case TypeId::TIMESTAMP_MS: case TypeId::TIMESTAMP_S: case TypeId::TIMESTAMP_NS: case TypeId::TIME: case TypeId::TIME_TZ: ci.ptype = 2; break;
    case TypeId::FLOAT: ci.ptype = 4; break;
    case TypeId::DOUBLE: ci.ptype = 5; break;
    case TypeId::DECIMAL: ci.ptype = t.width <= 9 ? 1 : (t.width <= 18 ? 2 : 7); ci.type_len = ci.ptype == 7 ? 16 : 0; break;
    case TypeId::HUGEINT: case TypeId::UHUGEINT: ci.ptype = 7; ci.type_len = 16; break;
    case TypeId::UUID: ci.ptype = 7; ci.type_len = 16; break;
    case TypeId::INTERVAL: ci.ptype = 7; ci.type_len = 12; break;
    case TypeId::BLOB: case TypeId::BIT: ci.ptype = 6; break;
    default: ci.ptype = 6; break;  // varchar and others as strings
    }
    infos.push_back(ci);
  }
  struct ChunkMeta { int64_t offset; int64_t size; int64_t num_values; };
  std::vector<ChunkMeta> chunks;
  for (size_t ci = 0; ci < r.types.size(); ci++) {
    auto &info = infos[ci];
    std::string values;
    // definition levels: RLE hybrid, 1 bit
    std::string defs;
    {
      // bit-packed run of all values: use RLE runs for simplicity: group consecutive equal
      size_t i = 0, n = r.rows.size();
      while (i < n) {
        bool nul = r.rows[i][ci].is_null;
        size_t j = i; while (j < n && r.rows[j][ci].is_null == nul) j++;
        uint64_t header = ((uint64_t)(j - i) << 1);
        while (header >= 0x80) { defs.push_back((char)(header | 0x80)); header >>= 7; }
        defs.push_back((char)header);
        defs.push_back(nul ? 0 : 1);
        i = j;
      }
    }
    std::string page;
    WriteI32(page, (int32_t)defs.size());
    page += defs;
    // values
    size_t nonnull = 0;
    if (info.ptype == 0) {
      std::string bits; int bitpos = 0; unsigned char cur = 0;
      for (auto &row : r.rows) { if (row[ci].is_null) continue; nonnull++; if (row[ci].ival) cur |= (1 << bitpos); bitpos++; if (bitpos == 8) { bits.push_back((char)cur); cur = 0; bitpos = 0; } }
      if (bitpos) bits.push_back((char)cur);
      values = bits;
    } else {
      for (auto &row : r.rows) {
        const Value &v = row[ci];
        if (v.is_null) continue;
        nonnull++;
        switch (info.ptype) {
        case 1: { int32_t x = (int32_t)v.ival; WriteI32(values, x); break; }
        case 2: { int64_t x = (int64_t)v.ival; if (v.type.id == TypeId::TIMESTAMP_MS) x *= 1000; if (v.type.id == TypeId::TIMESTAMP_S) x *= 1000000; if (v.type.id == TypeId::TIMESTAMP_NS) x /= 1000; WriteI64(values, x); break; }
        case 4: { float f = (float)v.dval; values.append((const char *)&f, 4); break; }
        case 5: { double d = v.dval; values.append((const char *)&d, 8); break; }
        case 6: { std::string s = (v.type.id == TypeId::BLOB || v.type.id == TypeId::VARCHAR || v.type.id == TypeId::BIT) ? v.str : v.ToString(); WriteI32(values, (int32_t)s.size()); values += s; break; }
        case 7: {
          if (v.type.id == TypeId::INTERVAL) { uint32_t m = (uint32_t)v.interval.months, d = (uint32_t)v.interval.days, ms = (uint32_t)(v.interval.micros / 1000); values.append((const char *)&m, 4); values.append((const char *)&d, 4); values.append((const char *)&ms, 4); }
          else { uint128_t x = (uint128_t)v.ival; if (v.type.id == TypeId::UUID) x ^= ((uint128_t)1 << 127); for (int b = 15; b >= 0; b--) values.push_back((char)((x >> (8 * b)) & 0xFF)); }
          break;
        }
        }
      }
    }
    page += values;
    // page header (DATA_PAGE v1, PLAIN, uncompressed)
    TWriter hw;
    hw.structBegin();
    hw.i32(1, 0);
    hw.i32(2, (int32_t)page.size());
    hw.i32(3, (int32_t)page.size());
    hw.structField(5);
    hw.structBegin();
    hw.i32(1, (int32_t)r.rows.size());
    hw.i32(2, 0);
    hw.i32(3, 3);
    hw.i32(4, 3);
    hw.structEnd();
    hw.structEnd();
    ChunkMeta cm; cm.offset = (int64_t)out.size(); cm.num_values = (int64_t)r.rows.size();
    out += hw.out;
    out += page;
    cm.size = (int64_t)out.size() - cm.offset;
    chunks.push_back(cm);
    (void)nonnull;
  }
  // footer
  TWriter fw;
  fw.structBegin();
  fw.i32(1, 1);
  // schema
  fw.listBegin(2, 12, r.types.size() + 1);
  fw.structBegin(); fw.i32(3, 0); fw.binary(4, "duckdb_schema"); fw.i32(5, (int32_t)r.types.size()); fw.structEnd();
  for (size_t ci = 0; ci < r.types.size(); ci++) {
    auto &info = infos[ci];
    const LogicalType &t = r.types[ci];
    fw.structBegin();
    fw.i32(1, info.ptype);
    if (info.type_len) fw.i32(2, info.type_len);
    fw.i32(3, 1);
    fw.binary(4, r.names[ci]);
    // converted type
    int conv = -1;
    switch (t.id) {
    case TypeId::VARCHAR: case TypeId::ENUM: case TypeId::LIST: case TypeId::STRUCT: case TypeId::MAP: case TypeId::ARRAY: case TypeId::UNION: conv = 0; break;
    case TypeId::DATE: conv = 6; break;
    case TypeId::TIMESTAMP: case TypeId::TIMESTAMP_TZ: case TypeId::TIMESTAMP_MS: case TypeId::TIMESTAMP_S: case TypeId::TIMESTAMP_NS: conv = 10; break;
    case TypeId::TIME: case TypeId::TIME_TZ: conv = 8; break;
    case TypeId::DECIMAL: conv = 5; break;
    case TypeId::TINYINT: conv = 15; break; case TypeId::SMALLINT: conv = 16; break; case TypeId::UTINYINT: conv = 11; break; case TypeId::USMALLINT: conv = 12; break; case TypeId::UINTEGER: conv = 13; break; case TypeId::UBIGINT: conv = 14; break;
    case TypeId::INTERVAL: conv = 21; break;
    default: break;
    }
    if (conv >= 0) fw.i32(6, conv);
    if (t.id == TypeId::DECIMAL) { fw.i32(7, t.scale); fw.i32(8, t.width); }
    if (t.id == TypeId::HUGEINT || t.id == TypeId::UHUGEINT) { fw.i32(6, 5); fw.i32(7, 0); fw.i32(8, 38); }
    // logical type
    bool has_logical = true;
    fw.structField(10);
    fw.structBegin();
    switch (t.id) {
    case TypeId::VARCHAR: case TypeId::ENUM: case TypeId::LIST: case TypeId::STRUCT: case TypeId::MAP: case TypeId::ARRAY: case TypeId::UNION: fw.structField(1); fw.structBegin(); fw.structEnd(); break;
    case TypeId::DATE: fw.structField(6); fw.structBegin(); fw.structEnd(); break;
    case TypeId::DECIMAL: fw.structField(5); fw.structBegin(); fw.i32(1, t.scale); fw.i32(2, t.width); fw.structEnd(); break;
    case TypeId::HUGEINT: case TypeId::UHUGEINT: fw.structField(5); fw.structBegin(); fw.i32(1, 0); fw.i32(2, 38); fw.structEnd(); break;
    case TypeId::TIMESTAMP: case TypeId::TIMESTAMP_MS: case TypeId::TIMESTAMP_S: case TypeId::TIMESTAMP_NS: case TypeId::TIMESTAMP_TZ:
      fw.structField(8); fw.structBegin(); fw.boolean(1, t.id == TypeId::TIMESTAMP_TZ); fw.structField(2); fw.structBegin(); fw.structField(2); fw.structBegin(); fw.structEnd(); fw.structEnd(); fw.structEnd(); break;
    case TypeId::TIME: case TypeId::TIME_TZ:
      fw.structField(7); fw.structBegin(); fw.boolean(1, false); fw.structField(2); fw.structBegin(); fw.structField(2); fw.structBegin(); fw.structEnd(); fw.structEnd(); fw.structEnd(); break;
    case TypeId::TINYINT: case TypeId::SMALLINT: case TypeId::INTEGER: case TypeId::BIGINT: case TypeId::UTINYINT: case TypeId::USMALLINT: case TypeId::UINTEGER: case TypeId::UBIGINT: {
      int bits = t.id == TypeId::TINYINT || t.id == TypeId::UTINYINT ? 8 : t.id == TypeId::SMALLINT || t.id == TypeId::USMALLINT ? 16 : t.id == TypeId::INTEGER || t.id == TypeId::UINTEGER ? 32 : 64;
      fw.structField(10); fw.structBegin(); fw.fieldHeader(1, 3); fw.byte((uint8_t)bits); fw.boolean(2, t.IsSigned()); fw.structEnd(); break;
    }
    case TypeId::UUID: fw.structField(14); fw.structBegin(); fw.structEnd(); break;
    default: has_logical = false; break;
    }
    fw.structEnd();
    (void)has_logical;
    fw.structEnd();
  }
  fw.i64(3, (int64_t)r.rows.size());
  // row groups (single)
  fw.listBegin(4, 12, 1);
  fw.structBegin();
  fw.listBegin(1, 12, chunks.size());
  int64_t total = 0;
  for (size_t ci = 0; ci < chunks.size(); ci++) {
    fw.structBegin();
    fw.i64(2, chunks[ci].offset);
    fw.structField(3);
    fw.structBegin();
    fw.i32(1, infos[ci].ptype);
    fw.listBegin(2, 5, 2); fw.zigzag(0); fw.zigzag(3);
    fw.listBegin(3, 8, 1); fw.varint(r.names[ci].size()); fw.out += r.names[ci];
    fw.i32(4, 0);
    fw.i64(5, chunks[ci].num_values);
    fw.i64(6, chunks[ci].size);
    fw.i64(7, chunks[ci].size);
    fw.i64(9, chunks[ci].offset);
    fw.structEnd();
    fw.structEnd();
    total += chunks[ci].size;
  }
  fw.i64(2, total);
  fw.i64(3, (int64_t)r.rows.size());
  fw.structEnd();
  fw.binary(6, "DuckDB");
  fw.structEnd();
  out += fw.out;
  uint32_t flen = (uint32_t)fw.out.size();
  out.append((const char *)&flen, 4);
  out += "PAR1";
  FILE *f = fopen(path.c_str(), "wb");
  if (!f) throw IOException("Cannot open file \"" + path + "\" for writing");
  fwrite(out.data(), 1, out.size(), f);
  fclose(f);
}
